// [BGM]
let bgmAudio = null;
let bgmEnabled = (localStorage.getItem('kingsRoadBgmOn') !== 'false'); // 기본값: 켜짐

function initBgm() {
    bgmAudio = new Audio('assets/audio/bgm.mp3');
    bgmAudio.loop = true;
    bgmAudio.volume = 0.4;
    updateBgmIcon();
}

function updateBgmIcon() {
    const icon = document.getElementById('bgm-icon');
    if (icon) icon.textContent = bgmEnabled ? '🎵' : '🔇';
}

function toggleBgm() {
    bgmEnabled = !bgmEnabled;
    localStorage.setItem('kingsRoadBgmOn', bgmEnabled);
    if (bgmEnabled) {
        bgmAudio.play().catch(() => {});
    } else {
        bgmAudio.pause();
    }
    updateBgmIcon();
}

function startBgm() {
    if (bgmEnabled && bgmAudio) {
        bgmAudio.currentTime = 0;
        bgmAudio.play().catch(() => {});
    }
}

function stopBgm() {
    if (bgmAudio) bgmAudio.pause();
}

function stopActiveAudio() {
    if (_activeAudio) {
        _activeAudio.loop = false;
        _activeAudio.pause();
        _activeAudio.src = '';
        _activeAudio = null;
    }
}

