let missionData = {
    lastLoginDate: "",      // 일일 초기화용
    weekId: "",             // 주간 초기화용 (예: "2024-W05")

    // 일일 미션 진행도
    daily: {
        loginReward: 0,     // 매일 접속 시 자동 완료
        newClear: 0,        // 신규 훈련 횟수
        differentStages: 0, // 서로 다른 스테이지 클리어 횟수
        checkpointBoss: 0,  // 중보/보스 처치 횟수
        hardship: 0,        // 왕의 고난 완주 횟수
        claimed: [false, false, false, false, false] // 보상 수령 여부
    },

    // 주간 미션 진행도
    weekly: {
        attendance: 0,      // 주간 출석 일수
        attendanceLog: [],  // 이번 주 출석한 날짜들 ["Mon", "Tue"...] (중복 방지용)
        dragonKill: 0,      // 용/중보/보스 처치 횟수
        stageClear: 0,      // 스테이지 15개 완료 횟수
        hardship: 0,        // 왕의 고난 완주 횟수
        claimed: [false, false, false, false]
    },

    // 미션 포인트 (일일/주간 미션 클리어 시 적립, 오전 6시 기준 별도 리셋)
    points: {
        dailyKey: '',           // getMemoryQuizDate() 값 — 바뀌면 daily 리셋
        weeklyKey: '',          // getMissionPointWeekId() 값 — 바뀌면 weekly 리셋
        daily: 0,               // 오늘 누적 포인트
        weekly: 0,              // 이번 주 누적 포인트
        dailyClaimedTiers: [],  // 오늘 수령한 마일스톤 인덱스
        weeklyClaimedTiers: []  // 이번 주 수령한 마일스톤 인덱스
    }
};

// 미션 포인트: 클리어 1회당 고정 25점 (일일/주간 완전히 분리, 서로 영향 없음)
// 보스를 한 번도 못 깼을 땐 기본 미션 4개 = 100점 만점. 보스를 클리어해 고난 계열 미션이
// 열리면 그만큼 만점 자체가 확장된다 (일일: 100→200, 주간: 100→125).
const POINTS_PER_MISSION_CLEAR = 25;

// 포인트 마일스톤: 임계값 도달 시 1회씩 보석 추가 지급. *_EXPANDED는 보스 클리어로 만점이
// 늘어난 뒤에만 추가로 열리는 상위 티어.
const DAILY_POINT_MILESTONES_BASE = [
    { threshold: 40, reward: 100 },
    { threshold: 70, reward: 200 },
    { threshold: 100, reward: 400 },
];
const DAILY_POINT_MILESTONES_EXPANDED = [
    { threshold: 150, reward: 700 },
    { threshold: 200, reward: 1200 },
];
const WEEKLY_POINT_MILESTONES_BASE = [
    { threshold: 40, reward: 300 },
    { threshold: 70, reward: 600 },
    { threshold: 100, reward: 1200 },
];
const WEEKLY_POINT_MILESTONES_EXPANDED = [
    { threshold: 125, reward: 2000 },
];

// 보스(또는 중간점검)를 한 번이라도 클리어했는지 — 클리어 시 고난 계열 일일/주간 미션이 추가로 열림
function hasAnyBossCleared() {
    const _cm = [stageMastery, typeof kingsRoadData !== 'undefined' && kingsRoadData && kingsRoadData.mastery].filter(Boolean);
    return _cm.some(m => Object.keys(m).some(id => id.endsWith('-boss') && m[id] > 0));
}

// 보스 클리어 여부에 따라 현재 적용되는 마일스톤 목록/만점을 반환
function getDailyPointMilestones() {
    return hasAnyBossCleared() ? DAILY_POINT_MILESTONES_BASE.concat(DAILY_POINT_MILESTONES_EXPANDED) : DAILY_POINT_MILESTONES_BASE;
}
function getWeeklyPointMilestones() {
    return hasAnyBossCleared() ? WEEKLY_POINT_MILESTONES_BASE.concat(WEEKLY_POINT_MILESTONES_EXPANDED) : WEEKLY_POINT_MILESTONES_BASE;
}
function getDailyPointMax() {
    return hasAnyBossCleared() ? 200 : 100;
}
function getWeeklyPointMax() {
    return hasAnyBossCleared() ? 125 : 100;
}

// 주간 포인트 리셋 기준 주차 ID (오전 6시 경계로 날짜를 보정한 뒤 ISO 주차 계산)
function getMissionPointWeekId() {
    const now = new Date();
    const shifted = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    if (now.getHours() < 6) shifted.setDate(shifted.getDate() - 1);
    return getWeekId(shifted);
}

// 날짜/주차가 바뀌었으면 미션 포인트를 리셋 (오전 6시 기준)
function checkMissionPointsReset() {
    if (!missionData.points) {
        missionData.points = { dailyKey: '', weeklyKey: '', daily: 0, weekly: 0, dailyClaimedTiers: [], weeklyClaimedTiers: [] };
    }
    const todayKey = (typeof getMemoryQuizDate === 'function') ? getMemoryQuizDate() : new Date().toISOString().split('T')[0];
    if (missionData.points.dailyKey !== todayKey) {
        missionData.points.dailyKey = todayKey;
        missionData.points.daily = 0;
        missionData.points.dailyClaimedTiers = [];
    }
    const weekKey = getMissionPointWeekId();
    if (missionData.points.weeklyKey !== weekKey) {
        missionData.points.weeklyKey = weekKey;
        missionData.points.weekly = 0;
        missionData.points.weeklyClaimedTiers = [];
    }
}

// 미션 포인트 마일스톤 달성 여부 확인 후 보석 지급
// (인덱스 0~2 = 기본 티어, 그 뒤 = 보스 클리어 후 확장 티어 — concat 순서가 고정이라 인덱스로 중복 지급 방지 가능)
function checkMissionPointMilestones() {
    // 수령은 미션 포인트 바의 상자 클릭으로 처리 (claimMissionPointTier)
}

function claimMissionPointTier(type, idx, silent) {
    checkMissionPointsReset();
    const isDaily = type === 'daily';
    const claimedTiers = isDaily ? missionData.points.dailyClaimedTiers : missionData.points.weeklyClaimedTiers;
    if (claimedTiers.includes(idx)) return;
    const milestones = isDaily ? getDailyPointMilestones() : getWeeklyPointMilestones();
    const current = isDaily ? missionData.points.daily : missionData.points.weekly;
    const tier = milestones[idx];
    if (!tier || current < tier.threshold) return;
    claimedTiers.push(idx);
    myGems += tier.reward;
    updateGemDisplay();
    saveGameData();
    if (silent) return;
    showGemToast(tier.reward, t('mission_point_milestone_toast', { gem: tier.reward }));
    renderMissionList(currentMissionTab);
}

function buildMissionPointBarHtml(type) {
    if (!document.getElementById('mpp-style')) {
        const s = document.createElement('style');
        s.id = 'mpp-style';
        s.textContent = `
            @keyframes mppPulse {
                0%,100%{transform:translateX(-50%) scale(1);filter:drop-shadow(0 0 5px #f1c40f);}
                50%{transform:translateX(-50%) scale(1.18);filter:drop-shadow(0 0 12px #f1c40f) drop-shadow(0 0 22px rgba(241,196,15,0.55));}
            }
            @keyframes mppPulseLast {
                0%,100%{transform:translateX(-100%) scale(1);filter:drop-shadow(0 0 5px #f1c40f);}
                50%{transform:translateX(-100%) scale(1.18);filter:drop-shadow(0 0 12px #f1c40f) drop-shadow(0 0 22px rgba(241,196,15,0.55));}
            }
        `;
        document.head.appendChild(s);
    }
    const isDaily = type === 'daily';
    const current = isDaily ? missionData.points.daily : missionData.points.weekly;
    const milestones = isDaily ? getDailyPointMilestones() : getWeeklyPointMilestones();
    const claimedTiers = isDaily ? missionData.points.dailyClaimedTiers : missionData.points.weeklyClaimedTiers;
    const max = isDaily ? getDailyPointMax() : getWeeklyPointMax();
    const label = t(isDaily ? 'mission_point_daily_label' : 'mission_point_weekly_label');
    const pct = Math.min(100, Math.round((current / max) * 100));

    const chestsHtml = milestones.map((tier, i) => {
        const pos = Math.round((tier.threshold / max) * 100);
        const isLast = pos >= 100;
        const claimed = claimedTiers.includes(i);
        const ready = current >= tier.threshold && !claimed;

        let icon, bg, border, animStyle, cursor, onclickAttr;
        if (claimed) {
            icon = '📦'; bg = 'rgba(50,80,50,0.7)'; border = '1px solid rgba(80,160,80,0.35)';
            animStyle = ''; cursor = 'default'; onclickAttr = '';
        } else if (ready) {
            icon = '🎁'; bg = 'linear-gradient(135deg,#b8860b,#f1c40f)'; border = '2px solid #f1c40f';
            animStyle = `animation:${isLast ? 'mppPulseLast' : 'mppPulse'} 1.1s ease-in-out infinite;`;
            cursor = 'pointer'; onclickAttr = `onclick="claimMissionPointTier('${type}',${i})"`;
        } else {
            icon = '🔒'; bg = 'rgba(40,30,70,0.85)'; border = '1px solid rgba(100,70,180,0.25)';
            animStyle = ''; cursor = 'default'; onclickAttr = '';
        }
        const labelColor = claimed ? '#5a9' : ready ? '#f1c40f' : '#555';
        const posStyle = isLast
            ? `right:-2px;top:0;transform:translateX(-100%);`
            : `left:${pos}%;top:0;transform:translateX(-50%);`;

        return `<div style="position:absolute;${posStyle}cursor:${cursor};" ${onclickAttr}>
            <div style="width:34px;height:34px;background:${bg};border:${border};border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:17px;${animStyle}">${icon}</div>
            <div style="text-align:center;font-size:9px;color:${labelColor};margin-top:2px;white-space:nowrap;">💎${tier.reward >= 1000 ? (tier.reward/1000).toFixed(1).replace('.0','')+'k' : tier.reward}</div>
        </div>`;
    }).join('');

    return `<div style="margin-bottom:16px;padding:10px 12px 18px;background:rgba(70,30,130,0.18);border:1px solid rgba(130,80,220,0.28);border-radius:12px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
            <span style="font-size:0.82rem;font-weight:bold;color:#c0a0ff;">${label}</span>
            <span style="font-size:0.82rem;color:#ccc;">${current} / ${max}pt</span>
        </div>
        <div style="position:relative;height:44px;margin:0 4px;">
            <div style="position:absolute;top:10px;left:0;right:0;height:8px;background:rgba(255,255,255,0.08);border-radius:4px;overflow:hidden;">
                <div style="width:${pct}%;height:100%;background:linear-gradient(90deg,#5020a0,#a060f0);border-radius:4px;transition:width 0.5s ease;"></div>
            </div>
            ${chestsHtml}
        </div>
    </div>`;
}

/* [시스템: 미션 상태 확인 및 초기화] */
function checkMissions() {
    const today = getMemoryQuizDate();      // 오전 6시 기준 날짜 (YYYY-MM-DD)
    const currentWeekId = getMissionPointWeekId(); // 오전 6시 기준 주차
    let lastMissionDate = localStorage.getItem('lastMissionCheckDate');

    checkMissionPointsReset();

    // 1. 일일 미션 초기화 (날짜가 바뀌었으면)
    if (missionData.lastLoginDate !== today) {
        missionData.lastLoginDate = today;
        missionData.daily = {
            loginReward: 0,
            newClear: 0,
            differentStages: 0,
            checkpointBoss: 0,
            hardship: 0,
            hardshipAddress: 0,
            hardshipMemory: 0,
            hardshipEndurance: 0,
            hardshipVerse: 0,
            backup: 0,
            claimed: [false, false, false, false, false, false, false, false]
        };
        missionData.daily.loginReward = 1; // 접속 시 즉시 완료
        // 심화 일일 미션 리셋
        missionData.advanced = createEmptyAdvancedMissionData(today);
        console.log("📅 새로운 하루가 시작되어 일일 미션이 초기화되었습니다.");

        // 날짜 변경 시 초기화 (stageDailyAttempts 제거)

        // 주간 출석 체크 (하루에 한 번만)
        updateWeeklyAttendance(today, currentWeekId);
    }

    // 2. 주간 미션 초기화 — 리셋은 _resetWeeklyMissionsIfNeeded 한 곳에서만 (아래 주석)
    _resetWeeklyMissionsIfNeeded(today);

    // 기존 세이브 데이터에 loginReward 필드 없을 때 보정
    if (missionData.daily.loginReward === undefined) {
        missionData.daily.loginReward = 1;
    }

    updateMissionUI();
    // 로그인 미션 등 — 완료된 것은 바로 지급 (약간 뒤: 로드 직후 UI가 준비된 뒤에)
    setTimeout(() => { if (typeof _autoClaimMissions === 'function') _autoClaimMissions(); }, 1200);
}

/* ★ 주간 미션 리셋은 **여기 한 곳에서, 오전 6시 기준 주차로만** 한다 (2026-09-28).
   checkMissions()(월요일 6시)와 checkDailyLogin()(월요일 **자정**)이 서로 다른 경계로 각자 리셋해서,
   월요일 00~06시에 둘이 번갈아 missionData.weekId를 뒤집었다 — 자정에 한 번, 6시에 또 한 번.
   게다가 자정 쪽은 **일부만** 지웠다: claimed를 4칸으로 만들고(미션은 5개) dailyMissionClearCount를 남겨,
   지난주 「일일 미션 20회」가 새 주의 것처럼 다시 수령 가능해졌다(자동 수령이 2,000젬을 한 번 더 지급).
   출석도 0으로 두고 오늘을 안 넣었다. 저장본 7,086개 중 854개에 4칸 흔적이 남아 있었다.
   9/16에 일일 리셋에서 잡은 '두 함수가 따로 리셋' 버그의 주간판이다.
   승점(leagueData) 주간 리셋은 서버 랭킹 주차(월요일 0시)를 따르므로 checkDailyLogin에 그대로 둔다 — 그건 다른 시계다 */
function _resetWeeklyMissionsIfNeeded(today) {
    const wk = getMissionPointWeekId();
    if (missionData.weekId === wk) return false;
    missionData.weekId = wk;
    missionData.weekly = {
        attendance: 1,          // 새 주 첫 접속이므로 1일 출석
        attendanceLog: [today],
        dragonKill: 0,
        stageClear: 0,
        hardship: 0,
        dailyMissionClearCount: 0,
        claimed: [false, false, false, false, false]
    };
    console.log("📅 새로운 주가 시작되어 주간 미션이 초기화되었습니다.");
    return true;
}

// [보조] 주간 출석 체크 로직 (버그 수정됨)
function updateWeeklyAttendance(today, currentWeek) {
    // 주차가 맞는지 확인
    if (missionData.weekId === currentWeek) {
        // 이미 출석한 날짜인지 기록부(Log)에서 확인
        if (!missionData.weekly.attendanceLog.includes(today)) {
            missionData.weekly.attendanceLog.push(today); // 오늘 날짜 도장 쾅
            missionData.weekly.attendance++;              // 출석 일수 +1
            saveGameData();
        }
    }
}

/* [시스템: 미션 진행도 업데이트 (핵심 기능)] */
// type: 'new'(신규), 'review'(복습), 'dragon'(용)
/* 심화 미션 데이터 기본값 — 여러 곳에서 초기화하므로 한 곳에서 생성한다
   claimed 인덱스: [address, memory, endurance, verse, checkpointBoss, midBoss] */
function createEmptyAdvancedMissionData(lastResetDate = '') {
    return {
        hardshipAddressChapters: [],
        hardshipMemoryChapters: [],
        hardshipEnduranceChapters: [],
        hardshipVerseChapters: [],
        checkpointBossStages: [],
        midBossStages: [],
        claimed: [0, 0, 0, 0, 0, 0],
        lastResetDate
    };
}

function updateMissionProgress(type, extraData) {
    if (isFocusedTrainingSession()) return;
    if (type === 'training') type = 'new';
    if (type === 'dragonKill') type = 'dragon';
    _addGuildRaidDamage(type, extraData);
    if (type === 'review') return;

    // 모든 도감이 열렸는지 체크 (하루 1회만 인정)
    let allOpened = true;
    for (let ch = 1; ch <= 22; ch++) {
        if (bibleData[ch]) {
            for (let idx = 0; idx < bibleData[ch].length; idx++) {
                const sId = `${ch}-${idx + 1}`;
                if (!(stageMastery[sId] && stageMastery[sId] >= 1)) {
                    allOpened = false;
                    break;
                }
            }
            if (!allOpened) break;
        }
    }

    // 👉 저장하는 오늘 날짜 (내 기기의 현지 시간 기준 YYYY-MM-DD 만들기)
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0'); // 월은 0부터 시작하므로 1 더하기
    const day = String(now.getDate()).padStart(2, '0');
    const today = `${year}-${month}-${day}`;

    // 1. 일일 미션: 신규 훈련 or 모든 도감 오픈 시 아무 스테이지든 1회
    if (type === 'new') {
        if (allOpened) {
            if (missionData.daily.anyStageClearDate !== today) {
                missionData.daily.anyStageClearDate = today;
                missionData.daily.newClear = 1; // 하루 1회만 인정
            }
        } else {
            missionData.daily.newClear++;
        }
    }
    // 2. 일일 미션: 다양성 (오늘 처음 클리어하는 스테이지)
    else if (type === 'differentStage') {
        missionData.daily.differentStages = (missionData.daily.differentStages || 0) + 1;
    }
    // 3. 일일 미션: 중보/보스 처치
    else if (type === 'checkpointBoss') {
        missionData.daily.checkpointBoss = (missionData.daily.checkpointBoss || 0) + 1;
    }
    // 3-b. 일일/주간 미션: 왕의 고난 완주
    else if (type === 'hardship') {
        missionData.daily.hardship = (missionData.daily.hardship || 0) + 1;
        missionData.weekly.hardship = (missionData.weekly.hardship || 0) + 1;
    }
    else if (type === 'hardshipAddress') {
        missionData.daily.hardshipAddress = (missionData.daily.hardshipAddress || 0) + 1;
        missionData.weekly.hardship = (missionData.weekly.hardship || 0) + 1;
    }
    else if (type === 'hardshipMemory') {
        missionData.daily.hardshipMemory = (missionData.daily.hardshipMemory || 0) + 1;
        // Lv.4 완주 → 하위 고난(Lv.1~3) 미션 자동 달성
        if (!missionData.daily.hardshipEndurance) missionData.daily.hardshipEndurance = 1;
        if (!missionData.daily.hardshipVerse) missionData.daily.hardshipVerse = 1;
        if (!missionData.daily.hardshipAddress) missionData.daily.hardshipAddress = 1;
        missionData.weekly.hardship = (missionData.weekly.hardship || 0) + 1;
    }
    else if (type === 'hardshipEndurance') {
        missionData.daily.hardshipEndurance = (missionData.daily.hardshipEndurance || 0) + 1;
        // Lv.3 완주 → 하위 고난(Lv.1~2) 미션 자동 달성
        if (!missionData.daily.hardshipVerse) missionData.daily.hardshipVerse = 1;
        if (!missionData.daily.hardshipAddress) missionData.daily.hardshipAddress = 1;
        missionData.weekly.hardship = (missionData.weekly.hardship || 0) + 1;
    }
    else if (type === 'hardshipVerse') {
        missionData.daily.hardshipVerse = (missionData.daily.hardshipVerse || 0) + 1;
        // Lv.2 완주 → 하위 고난(Lv.1) 미션 자동 달성
        if (!missionData.daily.hardshipAddress) missionData.daily.hardshipAddress = 1;
        missionData.weekly.hardship = (missionData.weekly.hardship || 0) + 1;
    }
    // 심화 일일 미션: 서로 다른 장 추적 (chapter = 장 번호)
    else if (type === 'advancedAddress') {
        const ch = arguments[1];
        if (!missionData.advanced) missionData.advanced = createEmptyAdvancedMissionData();
        const _adv = missionData.advanced;
        if (!Array.isArray(_adv.hardshipAddressChapters)) _adv.hardshipAddressChapters = [];
        if (ch != null && !_adv.hardshipAddressChapters.includes(ch) && _adv.hardshipAddressChapters.length < 22) _adv.hardshipAddressChapters.push(ch);
    }
    else if (type === 'advancedMemory') {
        const ch = arguments[1];
        if (!missionData.advanced) missionData.advanced = createEmptyAdvancedMissionData();
        const _adv = missionData.advanced;
        if (!Array.isArray(_adv.hardshipMemoryChapters)) _adv.hardshipMemoryChapters = [];
        if (ch != null && !_adv.hardshipMemoryChapters.includes(ch) && _adv.hardshipMemoryChapters.length < 22) _adv.hardshipMemoryChapters.push(ch);
        // Cascade: Lv.4 → Lv.3, Lv.2, Lv.1
        if (!Array.isArray(_adv.hardshipEnduranceChapters)) _adv.hardshipEnduranceChapters = [];
        if (ch != null && !_adv.hardshipEnduranceChapters.includes(ch) && _adv.hardshipEnduranceChapters.length < 22) _adv.hardshipEnduranceChapters.push(ch);
        if (!Array.isArray(_adv.hardshipVerseChapters)) _adv.hardshipVerseChapters = [];
        if (ch != null && !_adv.hardshipVerseChapters.includes(ch) && _adv.hardshipVerseChapters.length < 22) _adv.hardshipVerseChapters.push(ch);
        if (!Array.isArray(_adv.hardshipAddressChapters)) _adv.hardshipAddressChapters = [];
        if (ch != null && !_adv.hardshipAddressChapters.includes(ch) && _adv.hardshipAddressChapters.length < 22) _adv.hardshipAddressChapters.push(ch);
    }
    else if (type === 'advancedEndurance') {
        const ch = arguments[1];
        if (!missionData.advanced) missionData.advanced = createEmptyAdvancedMissionData();
        const _adv = missionData.advanced;
        if (!Array.isArray(_adv.hardshipEnduranceChapters)) _adv.hardshipEnduranceChapters = [];
        if (ch != null && !_adv.hardshipEnduranceChapters.includes(ch) && _adv.hardshipEnduranceChapters.length < 22) _adv.hardshipEnduranceChapters.push(ch);
        // Cascade: Lv.3 → Lv.2, Lv.1
        if (!Array.isArray(_adv.hardshipVerseChapters)) _adv.hardshipVerseChapters = [];
        if (ch != null && !_adv.hardshipVerseChapters.includes(ch) && _adv.hardshipVerseChapters.length < 22) _adv.hardshipVerseChapters.push(ch);
        if (!Array.isArray(_adv.hardshipAddressChapters)) _adv.hardshipAddressChapters = [];
        if (ch != null && !_adv.hardshipAddressChapters.includes(ch) && _adv.hardshipAddressChapters.length < 22) _adv.hardshipAddressChapters.push(ch);
    }
    else if (type === 'advancedVerse') {
        const ch = arguments[1];
        if (!missionData.advanced) missionData.advanced = createEmptyAdvancedMissionData();
        const _adv = missionData.advanced;
        if (!Array.isArray(_adv.hardshipVerseChapters)) _adv.hardshipVerseChapters = [];
        if (ch != null && !_adv.hardshipVerseChapters.includes(ch) && _adv.hardshipVerseChapters.length < 22) _adv.hardshipVerseChapters.push(ch);
        // Cascade: Lv.2 → Lv.1
        if (!Array.isArray(_adv.hardshipAddressChapters)) _adv.hardshipAddressChapters = [];
        if (ch != null && !_adv.hardshipAddressChapters.includes(ch) && _adv.hardshipAddressChapters.length < 22) _adv.hardshipAddressChapters.push(ch);
    }
    // 심화 미션: 용 사냥 — 보스전 전용 (보스는 장당 1개라 상한 22 = 전체 장 수)
    else if (type === 'advancedCheckpointBoss') {
        const stageId = arguments[1];
        if (!missionData.advanced) missionData.advanced = createEmptyAdvancedMissionData();
        const _adv = missionData.advanced;
        if (!Array.isArray(_adv.checkpointBossStages)) _adv.checkpointBossStages = [];
        if (stageId != null && !_adv.checkpointBossStages.includes(stageId) && _adv.checkpointBossStages.length < 22) _adv.checkpointBossStages.push(stageId);
    }
    // 심화 미션: 중간점검 전용 — 상한은 실제 존재하는 중간점검 수
    else if (type === 'advancedMidBoss') {
        const stageId = arguments[1];
        if (!missionData.advanced) missionData.advanced = createEmptyAdvancedMissionData();
        const _adv = missionData.advanced;
        if (!Array.isArray(_adv.midBossStages)) _adv.midBossStages = [];
        if (stageId != null && !_adv.midBossStages.includes(stageId) && _adv.midBossStages.length < getTotalMidBossCount()) _adv.midBossStages.push(stageId);
    }
    // 4. 주간 미션: 중보/보스 처치 (용 사냥)
    else if (type === 'dragon') {
        missionData.weekly.dragonKill++;
    }

    // 5. 스테이지 클리어 총수 (일반 스테이지에서만)
    if (type === 'new') {
        missionData.weekly.stageClear++;
    }

    saveGameData();
    _autoClaimMissions();
    updateMissionUI();
    // 🌟 [추가 1] 카운트가 올랐으니 배지 상태도 즉시 새로고침!
    if (typeof updateNotificationBadges === 'function') updateNotificationBadges();
}

