// [보조] 미션 포인트 진행 요약 HTML 만들기
function buildMissionPointSummaryHtml(label, current, milestones, claimedTiers) {
    const nextIdx = milestones.findIndex((tier, i) => !claimedTiers.includes(i));
    const progressText = (nextIdx === -1)
        ? t('mission_point_maxed')
        : t('mission_point_next', { cur: Math.round(current), n: milestones[nextIdx].threshold, gem: milestones[nextIdx].reward });
    return `<div style="background:rgba(241,196,15,0.08); border:1px solid rgba(241,196,15,0.3); border-radius:8px; padding:8px 12px; margin-bottom:10px; font-size:0.8rem; color:#f1c40f; display:flex; justify-content:space-between; align-items:center; gap:10px;">
        <span style="font-weight:bold; white-space:nowrap;">${label}</span><span style="color:#eee;">${progressText}</span>
    </div>`;
}

// [보조] 미션 항목 HTML 만들기
function createMissionElement(parent, m) {
    const item = document.createElement('div');
    item.className = 'mission-item';
    // 스타일: 아이템 박스
    item.style.background = "rgba(255,255,255,0.05)";
    item.style.marginBottom = "8px";
    item.style.padding = "10px";
    item.style.borderRadius = "8px";
    item.style.display = "flex";
    item.style.justifyContent = "space-between";
    item.style.alignItems = "center";

    const isCompleted = m.current >= m.target;
    let btnHtml = "";

    // 버튼 상태 결정
    if (m.claimed) {
        btnHtml = `<button style="background:#7f8c8d; color:#bdc3c7; border:none; padding:5px 10px; border-radius:5px;" disabled>${t('mission_btn_done')}</button>`;
    } else if (isCompleted) {
        btnHtml = `<button id="btn-${m.type}-${m.index}" class="btn-claim-active" style="background:#f39c12; color:white; border:none; padding:5px 10px; border-radius:5px; cursor:pointer; font-weight:bold; animation: pulse 1s infinite;">${t('mission_btn_claim')}</button>`;
    } else {
        btnHtml = `<button style="background:transparent; color:#7f8c8d; border:1px solid #7f8c8d; padding:5px 10px; border-radius:5px;" disabled>${m.current}/${m.target}</button>`;
    }

    item.innerHTML = `
        <div class="mission-info">
            <div style="font-weight:bold; font-size:0.95rem;">${m.desc}</div>
            <div style="font-size:0.8rem; color:#f39c12; margin-top:3px;">🎁 ${m.rewardText}</div>
        </div>
        ${btnHtml}
    `;
    parent.appendChild(item);

    // 버튼에 클릭 이벤트 연결 (문자열로 넣으면 따옴표 문제가 생기므로 JS로 연결)
    if (isCompleted && !m.claimed) {
        const btn = document.getElementById(`btn-${m.type}-${m.index}`);
        if (btn) {
            btn.onclick = function () {
                claimReward(m.type, m.index, m.rewardType, m.val1, m.val2);
                // 🌟 [추가 2] 보상을 받았으니 배지 상태 새로고침! (빨간 점 끄기)
                if (typeof updateNotificationBadges === 'function') updateNotificationBadges();
            };
        }
    }
}

function showGemToast(count, customMsg, isInfo) {
    const existing = document.getElementById('gem-reward-toast');
    if (existing) existing.remove();
    const el = document.createElement('div');
    el.id = 'gem-reward-toast';
    el.className = 'gem-reward-toast' + (isInfo ? ' gem-toast-info' : '');
    el.textContent = customMsg || `💎 보석 ${count.toLocaleString()}개 획득`;
    document.body.appendChild(el);
    setTimeout(() => { if (el.parentNode) el.remove(); }, 2800);
}

/* [시스템: 보상 수령 처리 함수] */
/* ── 미션 자동 완료 (2026-09-14) ─────────────────────────────────────────────
   듀오링고처럼 미션은 **완료되는 순간 보상을 주고 알린다.** 미션 화면에 들어가 「받기」를 누를 필요가 없다.
   미션 화면은 어떤 미션이 있고 무엇을 끝냈는지 **보는 용도**로 남는다.
   알림은 모달이 아니라 **긴 토스트**(4초, 위로 쌓임) — 스테이지 결과 화면 직후에 완료되는데
   거기서 또 모달을 띄우면 확인 버튼이 두 번이고, 우리 규칙("알리기만 하는 건 막지 않는다")에도 맞다.
   진입점: updateMissionProgress 끝 / checkMissions(로그인) / 백업 미션 / 성경 읽기 / 심화 미션. */
function showMissionToast(title, rewardText) {
    let stack = document.getElementById('mission-toast-stack');
    if (!stack) {
        stack = document.createElement('div');
        stack.id = 'mission-toast-stack';
        document.body.appendChild(stack);
    }
    const el = document.createElement('div');
    el.className = 'mission-toast';
    el.innerHTML = `<span class="mission-toast-check">✅</span><span class="mission-toast-title">${title}</span><span class="mission-toast-reward">${rewardText}</span>`;
    stack.appendChild(el);
    if (typeof SoundEffect !== 'undefined' && SoundEffect.playCorrect) SoundEffect.playCorrect();
    setTimeout(() => el.classList.add('out'), 3600);
    setTimeout(() => { if (el.parentNode) el.remove(); if (stack.childElementCount === 0 && stack.parentNode) stack.remove(); }, 4000);
}

let _autoClaimBusy = false;
function _autoClaimMissions() {
    if (_autoClaimBusy) return;            // claimReward → renderMissionList 재진입 방지
    if (typeof missionData === 'undefined' || !missionData || !missionData.daily) return;
    _autoClaimBusy = true;
    try {
        // 1) 일일·주간 미션 — 화면과 같은 정의를 본다
        for (const tab of ['daily', 'weekly']) {
            const defs = (typeof _buildMissionDefs === 'function') ? _buildMissionDefs(tab) : [];
            for (const m of defs) {
                if (m.bibleRead || m.claimed) continue;
                if ((m.current || 0) < m.target) continue;
                claimReward(tab, m.id, m.rewardType, m.val1 || 0, m.val2 || 0, true);
                showMissionToast(m.title, m.reward);
            }
        }
        // 2) 포인트 상자 — 문턱을 넘은 것은 바로 연다
        for (const type of ['daily', 'weekly']) {
            const isDaily = type === 'daily';
            const milestones = isDaily ? getDailyPointMilestones() : getWeeklyPointMilestones();
            const claimedTiers = isDaily ? missionData.points.dailyClaimedTiers : missionData.points.weeklyClaimedTiers;
            const current = isDaily ? missionData.points.daily : missionData.points.weekly;
            milestones.forEach((tier, i) => {
                if (claimedTiers.includes(i) || current < tier.threshold) return;
                claimMissionPointTier(type, i, true);
                showMissionToast(t(isDaily ? 'mission_point_daily_label' : 'mission_point_weekly_label') + ' ' + tier.threshold + 'pt', `💎 ${tier.reward.toLocaleString()}`);
            });
        }
        // 3) 성경 읽기 (10절마다 100)
        if (typeof claimBibleReadReward === 'function') claimBibleReadReward(true);
        // 4) 심화 미션 — 새 장이 늘 때마다
        if (missionData.advanced && typeof claimAdvancedReward === 'function') {
            for (const key of ['address', 'memory', 'endurance', 'verse', 'checkpointBoss', 'midBoss']) {
                claimAdvancedReward(key, null, true);
            }
        }
    } finally {
        _autoClaimBusy = false;
    }
    // 미션 화면이 떠 있으면 한 번만 다시 그린다
    const listArea = document.getElementById('mission-list-area');
    const missionScreen = document.getElementById('mission-screen');
    if (listArea && missionScreen && missionScreen.classList.contains('active') && typeof renderMissionList === 'function') {
        renderMissionList(currentMissionTab);
    }
    if (typeof updateNotificationBadges === 'function') updateNotificationBadges();
}

function claimReward(type, index, rewardType, value1, value2, silent) {
    // 햇살 승격 검사 — 수령 처리 뒤에 돈다 (아래 setTimeout). 오늘 이미 한 절을 해서 promisedOn이 있을 때만 의미가 있다
    setTimeout(() => { if (typeof _promiseRain === 'function' && rain.promisedOn === _get6AMDayStr()) _promiseRain(); }, 0);
    // 1. 중복 수령 방지
    let isAlreadyClaimed = (type === 'daily') ? missionData.daily.claimed[index] : missionData.weekly.claimed[index];
    if (isAlreadyClaimed) return;

    // 2. 수령 상태 저장
    if (type === 'daily') {
        missionData.daily.claimed[index] = true;
        // 주간 미션: 일일미션 클리어 횟수 집계
        if (!missionData.weekly) missionData.weekly = {};
        missionData.weekly.dailyMissionClearCount = (missionData.weekly.dailyMissionClearCount || 0) + 1;
    } else {
        missionData.weekly.claimed[index] = true;
    }

    // 3. 보상 실제 지급 로직
    if (rewardType === 'gem') {
        // 보석 지급
        myGems += value1;
        updateGemDisplay();
        if (!silent) showGemToast(value1);
    }

    // 3-1. 미션 포인트 적립 + 마일스톤 확인 (일일/주간 완전히 별개로 누적 — 서로 영향 없음)
    checkMissionPointsReset();
    if (type === 'daily') {
        missionData.points.daily = Math.min(getDailyPointMax(), missionData.points.daily + POINTS_PER_MISSION_CLEAR);
    } else {
        missionData.points.weekly = Math.min(getWeeklyPointMax(), missionData.points.weekly + POINTS_PER_MISSION_CLEAR);
    }
    checkMissionPointMilestones();

    // 4. 저장 및 화면 갱신
    saveGameData();
    syncToFirestore(); // [Firestore] 미션 보상 청구
    if (silent) return; // 자동 완료: 호출한 쪽이 한 번에 그린다
    updateNotificationBadges();
    // ✅ [수정됨] 현재 보고 있는 탭의 화면을 다시 그립니다.
    if (typeof renderMissionList === 'function') {
        renderMissionList(currentMissionTab);
    } else {
        updateMissionUI(); // 혹시 모를 상황을 대비한 예비 코드
    }
}

/* =========================================
   [시스템: 사운드 효과 (Web Audio API)]
   용량 0KB로 효과음을 생성하는 신디사이저입니다.
   ★ 2026-09-28 음색 개편 — 8비트 삑소리(사각파·톱니파)를 둥근 종소리로.
     · 모든 음은 사인파 + 배음 2개(종·차임 느낌), 6ms 어택 → 지수 감쇠. 뚝 끊기는 딸깍 잡음 없음
     · 짧은 울림(에코 한 겹)과 압축기를 거쳐 한 공간에서 나는 소리처럼
     · 보상의 크기가 귀로 구분되게: 정답(2음) < 레벨업(4음 오름) < 백지레벨 오름(화음이 피어남+반짝) < 클리어(오름+긴 화음)
     · 틀림은 벌칙 버저가 아니라 낮고 부드러운 「툭」 — 백지에서 틀리는 건 흔하고, 틀려야 기억에 남는다
     · 아이폰: 잠든 오디오를 깨우는 동안 첫 소리가 씹히던 것 — 깨어나면 곧바로(0.25초 안) 재생
     · 효과음 버튼: 🔊 전부 → 🔉 타자음만 끔 → 🔇 전부 끔
   ========================================= */
const SoundEffect = {
    ctx: new (window.AudioContext || window.webkitAudioContext)(),

    // ★ [수정] 저장된 설정이 'true'이면 음소거(true), 아니면 기본값 해제(false)
    isMuted: localStorage.getItem('setting_sfx_mute') === 'true',
    // 타자음만 끔 (2026-09-28)
    keyMuted: localStorage.getItem('setting_key_sfx_off') === 'true',

    // iOS: ctx가 running 상태일 때만 true 반환. suspended면 resume 시도 후 false
    _ready: function() {
        if (this.ctx.state === 'running') return true;
        this.ctx.resume().catch(() => {});
        return false;
    },

    // 🔊 → 🔉(타자음 끔) → 🔇 → 🔊
    toggleMute: function () {
        if (this.isMuted) { this.isMuted = false; this.keyMuted = false; }
        else if (!this.keyMuted) { this.keyMuted = true; }
        else { this.isMuted = true; }
        localStorage.setItem('setting_sfx_mute', this.isMuted);
        localStorage.setItem('setting_key_sfx_off', this.keyMuted);
        return this.isMuted;
    },

    // 출력 버스: 음 → (마스터) → 압축기 → 스피커, 마스터에서 짧은 울림을 한 겹 곁들인다
    _out: null,
    _bus: function () {
        if (this._out) return this._out;
        const c = this.ctx;
        const master = c.createGain();
        master.gain.value = 0.9;
        const comp = c.createDynamicsCompressor();
        comp.threshold.value = -16; comp.knee.value = 12; comp.ratio.value = 4;
        comp.attack.value = 0.003; comp.release.value = 0.2;
        const dly = c.createDelay(0.5);
        dly.delayTime.value = 0.12;
        const fb = c.createGain(); fb.gain.value = 0.3;
        const lp = c.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 2400;
        const wet = c.createGain(); wet.gain.value = 0.22;
        master.connect(comp);
        master.connect(dly); dly.connect(lp); lp.connect(fb); fb.connect(dly); lp.connect(wet); wet.connect(comp);
        comp.connect(c.destination);
        this._out = master;
        return master;
    },

    // 잠들어 있으면 깨운 뒤 재생 (0.25초 안에 깨어날 때만 — 늦게 울리면 엉뚱한 순간에 들린다)
    _play: function (fn) {
        if (this.isMuted) return;
        const c = this.ctx;
        if (c.state === 'running') { try { fn(c.currentTime + 0.005); } catch (e) { } return; }
        const asked = Date.now();
        c.resume().then(() => {
            if (Date.now() - asked < 250) { try { fn(c.currentTime + 0.005); } catch (e) { } }
        }).catch(() => {});
    },

    // 종소리 한 음: partials = [[배수, 세기, 감쇠비율], ...]
    _BELL: [[1, 1, 1], [2, 0.32, 0.55], [3, 0.1, 0.3]],
    _PURE: [[1, 1, 1]],
    _note: function (freq, t, dur, vol, opt) {
        const c = this.ctx, out = this._bus();
        const o = opt || {};
        (o.partials || this._BELL).forEach(([m, a, dm]) => {
            const osc = c.createOscillator();
            const g = c.createGain();
            osc.type = o.wave || 'sine';
            osc.frequency.setValueAtTime(freq * m, t);
            if (o.glideTo) osc.frequency.exponentialRampToValueAtTime(o.glideTo * m, t + dur);
            const d = Math.max(0.02, dur * dm);
            const atk = Math.min(o.attack || 0.006, d * 0.5);
            g.gain.setValueAtTime(0.0001, t);
            g.gain.linearRampToValueAtTime(Math.max(0.0002, vol * a), t + atk);
            g.gain.exponentialRampToValueAtTime(0.0001, t + d);
            osc.connect(g); g.connect(out);
            osc.start(t); osc.stop(t + d + 0.03);
        });
    },

    // 짧은 바람 소리(잡음 + 대역 필터 훑기) — 공격
    _noise: null,
    _whoosh: function (t, dur, vol, from, to) {
        const c = this.ctx;
        if (!this._noise) {
            const len = Math.floor(c.sampleRate * 0.5);
            const buf = c.createBuffer(1, len, c.sampleRate);
            const d = buf.getChannelData(0);
            for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
            this._noise = buf;
        }
        const src = c.createBufferSource(); src.buffer = this._noise;
        const bp = c.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 1.2;
        bp.frequency.setValueAtTime(from, t);
        bp.frequency.exponentialRampToValueAtTime(to, t + dur);
        const g = c.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(vol, t + dur * 0.25);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        src.connect(bp); bp.connect(g); g.connect(this._bus());
        src.start(t); src.stop(t + dur + 0.02);
    },

    // 진동 (안드로이드만 — 아이폰 웹앱은 지원하지 않는다). 효과음을 끄면 진동도 끈다
    _buzz: function (pattern) {
        if (this.isMuted) return;
        try { if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate(pattern); } catch (e) { }
    },

    // 소리 재생의 기초 함수 (예전 호출부 호환 — 파형 인자는 무시하고 종소리로)
    playTone: function (freq, type, duration, vol = 0.1) {
        this._play(t => this._note(freq, t, Math.max(0.12, duration * 1.6), vol * 0.8));
    },

    // 내부용 (예전 호출부 호환)
    createOsc: function (freq, type, time, dur) {
        this._play(() => this._note(freq, Math.max(time, this.ctx.currentTime), Math.max(0.12, dur * 1.6), 0.08));
    },

    // 1. 블록 선택/클릭 소리 (톡)
    playClick: function () {
        this._play(t => this._note(1320, t, 0.05, 0.035, { partials: this._PURE }));
    },

    // 2. 정답 소리 (딩-동, 5도 위로)
    playCorrect: function () {
        this._play(t => {
            this._note(783.99, t, 0.45, 0.085);          // G5
            this._note(1046.50, t + 0.09, 0.7, 0.085);   // C6
        });
        this._buzz(12);
    },

    // 3. 오답 소리 (낮고 부드러운 「툭」 — 벌칙 버저가 아니다)
    playWrong: function () {
        this._play(t => {
            this._note(220, t, 0.26, 0.13, { glideTo: 174.6, partials: [[1, 1, 1], [2, 0.12, 0.4]] });
        });
        this._buzz([25, 40, 25]);
    },

    // 4. 공격 소리 (휙- 바람 + 낮은 울림)
    playAttack: function () {
        this._play(t => {
            this._whoosh(t, 0.2, 0.16, 2600, 500);
            this._note(146.8, t + 0.08, 0.3, 0.1, { partials: [[1, 1, 1], [2, 0.25, 0.5]] });
        });
    },

    // 5. 클리어 (도미솔도 오름 + 길게 울리는 화음 + 반짝)
    playClear: function () {
        this._play(t => {
            [523.25, 659.25, 783.99, 1046.50].forEach((f, i) => this._note(f, t + i * 0.1, 0.9, 0.075));
            [523.25, 659.25, 783.99, 1046.50].forEach(f => this._note(f, t + 0.48, 2.0, 0.05));
            this._note(2093.0, t + 0.62, 0.9, 0.025, { partials: this._PURE });
        });
        this._buzz([20, 40, 20, 40, 50]);
    },

    // 6. 레벨업/퍼펙트 (도미솔도 빠른 오름)
    playLevelUp: function () {
        this._play(t => {
            [523.25, 659.25, 783.99, 1046.50].forEach((f, i) =>
                this._note(f, t + i * 0.075, i === 3 ? 0.9 : 0.45, 0.075));
        });
        this._buzz(18);
    },

    // 6-1. 백지레벨 오름 (2026-09-28) — 따뜻한 화음이 천천히 피어나고 위에서 세 번 반짝
    playBlankLevelUp: function () {
        this._play(t => {
            [261.63, 392.00, 523.25, 659.25].forEach(f =>
                this._note(f, t, 1.6, 0.05, { attack: 0.14, partials: [[1, 1, 1], [2, 0.2, 0.6]] }));
            [1318.5, 1568.0, 2093.0].forEach((f, i) =>
                this._note(f, t + 0.22 + i * 0.12, 0.8, 0.04));
        });
        this._buzz([15, 30, 15, 30, 60]);
    },

    // 7. 보석 획득 소리 (찰랑)
    playGetGem: function () {
        this._play(t => {
            this._note(1318.5, t, 0.3, 0.05);
            this._note(1975.5, t + 0.05, 0.4, 0.045);
        });
    },

    // 8. 구절 공개 소리 - 인내의 고난 (부드러운 페이지 넘김)
    playReveal: function () {
        this._play(t => this._note(520, t, 0.18, 0.05, { glideTo: 700, attack: 0.03, partials: this._PURE }));
    },

    // 10. 힌트 사용 소리 - 망각의 고난 (작은 방울)
    playHint: function () {
        this._play(t => {
            this._note(880, t, 0.3, 0.055);
            this._note(1174.7, t + 0.07, 0.4, 0.055);
        });
    },

    // 11. 타이핑 소리 - 망각의 고난 (아주 작은 톡, 디바운스 15ms). 🔉에서는 이것만 꺼진다
    _lastKeystrokeTime: 0,
    playKeyStroke: function () {
        if (this.isMuted || this.keyMuted || !this._ready()) return;
        const now = Date.now();
        if (now - this._lastKeystrokeTime < 15) return;
        this._lastKeystrokeTime = now;
        this._note(1900, this.ctx.currentTime, 0.022, 0.02, { wave: 'triangle', partials: this._PURE });
    },

    // 새 예루살렘 3D — 물길을 걸을 때 참방 (잡음을 높은 데서 낮게 훑기 + 작은 물방울 톡). 발소리라 🔉에서도 꺼진다
    // big: 점프해서 물에 떨어질 때
    // 풀밭 발소리 — 잡음을 아래로 훑는다(예전 물소리였는데 "풀밭을 다니는 소리 같다"고 해서 풀밭으로 옮겼다, 9/30)
    playGrass: function (run) {
        if (this.keyMuted) return;
        this._play(t => {
            const j = 0.85 + Math.random() * 0.3;
            this._whoosh(t, run ? 0.09 : 0.11, run ? 0.07 : 0.05, 2600 * j, 700 * j);
        });
    },
    // 🐴 발굽 소리 — 나무를 두드리듯 짧은 두 번 '따각'(달릴 땐 더 빠르고 가볍게). 발소리라 🔉에서도 꺼진다
    playHoof: function (run) {
        if (this.keyMuted) return;
        this._play(t => {
            const j = 0.9 + Math.random() * 0.2;
            this._note(760 * j, t, 0.03, run ? 0.045 : 0.06, { glideTo: 420 * j, partials: this._PURE, attack: 0.001 });
            this._note(600 * j, t + (run ? 0.045 : 0.07), 0.03, run ? 0.035 : 0.05, { glideTo: 340 * j, partials: this._PURE, attack: 0.001 });
        });
    },
    // 🛝 생명수 미끄럼 (10/5) — 흐르는 물(잡음 고리 → 대역 필터) + 빠를수록 커지고 높아지는 바람(고역 잡음). 손잡이 { set(0~1), stop() }
    _noiseLong: null,
    slideLoop: function () {
        if (this.isMuted || this.keyMuted) return null;
        const c = this.ctx;
        try {
            if (c.state !== 'running') c.resume();
            if (!this._noiseLong) {   // 2초짜리 — 0.5초 고리는 되풀이가 들렸다
                const len = Math.floor(c.sampleRate * 2), buf = c.createBuffer(1, len, c.sampleRate), d = buf.getChannelData(0);
                for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
                this._noiseLong = buf;
            }
            const src = c.createBufferSource(); src.buffer = this._noiseLong; src.loop = true;
            const water = c.createBiquadFilter(); water.type = 'bandpass'; water.frequency.value = 800; water.Q.value = 0.7;
            const wg = c.createGain(); wg.gain.value = 0.0001;
            const wind = c.createBiquadFilter(); wind.type = 'highpass'; wind.frequency.value = 2200;
            const ng = c.createGain(); ng.gain.value = 0.0001;
            src.connect(water); water.connect(wg); wg.connect(this._bus());
            src.connect(wind); wind.connect(ng); ng.connect(this._bus());
            const t0 = c.currentTime; src.start(t0); wg.gain.setTargetAtTime(0.05, t0, 0.15);
            let done = false;
            return {
                set: (k) => { if (done) return; const t = c.currentTime;
                    wg.gain.setTargetAtTime(0.045 + 0.06 * k, t, 0.12); water.frequency.setTargetAtTime(650 + 1000 * k, t, 0.12);
                    ng.gain.setTargetAtTime(0.0001 + 0.07 * k * k, t, 0.12); wind.frequency.setTargetAtTime(1800 + 2800 * k, t, 0.15); },
                stop: () => { if (done) return; done = true; const t = c.currentTime;
                    wg.gain.setTargetAtTime(0.0001, t, 0.08); ng.gain.setTargetAtTime(0.0001, t, 0.08); try { src.stop(t + 0.6); } catch (e) { } }
            };
        } catch (e) { return null; }
    },
    // 🛝 바다에 풍덩 (10/5) — 묵직한 '풍'(낮게 떨어짐) + 물 갈라지는 소리 + '덩' + 보글보글 올라오는 거품
    playPlunge: function () {
        if (this.keyMuted) return;
        this._play(t => {
            this._note(120, t, 0.4, 0.17, { glideTo: 52, partials: this._PURE, attack: 0.003 });
            this._whoosh(t, 0.28, 0.12, 3200, 380);
            this._note(270, t + 0.03, 0.14, 0.09, { glideTo: 760, partials: this._PURE, attack: 0.002 });
            for (let k = 0; k < 8; k++) {
                const tt = t + 0.28 + k * (0.07 + Math.random() * 0.07), f = 300 + Math.random() * 520;
                this._note(f, tt, 0.05, 0.055 * (1 - k / 9), { glideTo: f * 2.3, partials: this._PURE, attack: 0.002 });
            }
        });
    },
    // 🛝 출발 — "슝~" 올라가는 휘파람 + 바람
    playWhee: function () {
        if (this.keyMuted) return;
        this._play(t => {
            this._note(480, t, 0.45, 0.07, { glideTo: 1150, partials: this._PURE, wave: 'triangle', attack: 0.03 });
            this._whoosh(t, 0.5, 0.06, 700, 3200);
        });
    },
    playSplash: function (big) {
        if (this.keyMuted) return;
        this._play(t => {
            // 물소리 = 물방울이 '퐁' 하고 올라가는 음(거품이 울리는 소리). 전엔 잡음을 아래로 훑어 풀밭을 헤치는 소리 같았다(9/30 사용자)
            const j = 0.85 + Math.random() * 0.3, n = big ? 3 : 1 + (Math.random() < 0.4 ? 1 : 0);
            for (let k = 0; k < n; k++) {
                const tt = t + k * (0.04 + Math.random() * 0.03), f = (big ? 380 : 560) * j * (1 + k * 0.3 + Math.random() * 0.15);
                this._note(f, tt, 0.06, (big ? 0.11 : 0.06) * (k ? 0.6 : 1), { glideTo: f * 2.6, partials: this._PURE, attack: 0.002 });
            }
            this._whoosh(t, big ? 0.06 : 0.035, big ? 0.07 : 0.03, 6000 * j, 4200 * j);   // 튀는 물 — 아주 짧고 높게
            if (big) this._note(140 * j, t, 0.12, 0.08, { glideTo: 70 * j, partials: this._PURE, attack: 0.002 });   // 떨어질 때 '풍덩' 무게
        });
    },

    // 방패 막기 소리 (퉁! 금속 충격 + 짧은 울림)
    playShield: function () {
        this._play(t => {
            this._note(320, t, 0.25, 0.14, { glideTo: 180, wave: 'triangle', partials: this._PURE });
            this._note(860, t, 0.2, 0.05, { partials: this._PURE });
        });
    }
};

/* =========================================
   [시스템: 음성 파일 음량 정규화]
   음성 MP3 파일을 Web Audio API를 통해 라우팅하여
   파일 간 음량 차이를 균등화하고 효과음과 비슷한
   수준으로 맞춥니다 (DynamicsCompressor 사용).
   ========================================= */
function connectVoiceToAudioContext(audioElem) {
    if (!audioElem || audioElem._voiceConnected) return;
    audioElem._voiceConnected = true;

    try {
        const ctx = SoundEffect.ctx;
        if (ctx.state === 'suspended') ctx.resume();

        const source = ctx.createMediaElementSource(audioElem);

        // 다이나믹 컴프레서: 파일 간 음량 차이 균등화
        const compressor = ctx.createDynamicsCompressor();
        compressor.threshold.setValueAtTime(-24, ctx.currentTime); // -24dBFS 이상 압축
        compressor.knee.setValueAtTime(5, ctx.currentTime);
        compressor.ratio.setValueAtTime(10, ctx.currentTime);      // 압축 비율 10:1
        compressor.attack.setValueAtTime(0.003, ctx.currentTime);  // 3ms
        compressor.release.setValueAtTime(0.2, ctx.currentTime);   // 200ms

        // 압축 후 음량 조정 (효과음 gain 0.1과 유사한 수준으로)
        const gainNode = ctx.createGain();
        gainNode.gain.setValueAtTime(1.2, ctx.currentTime);

        source.connect(compressor);
        compressor.connect(gainNode);
        gainNode.connect(ctx.destination);
    } catch (e) {
        console.warn('음성 정규화 연결 오류:', e);
    }
}

// 이어폰 뽑기 등 오디오 장치 변경 시 AudioContext를 자동으로 resume
if (navigator.mediaDevices && navigator.mediaDevices.addEventListener) {
    navigator.mediaDevices.addEventListener('devicechange', () => {
        const ctx = SoundEffect.ctx;
        if (ctx && ctx.state === 'suspended') ctx.resume();
    });
}

// iOS: 첫 터치/클릭에서 AudioContext를 즉시 unlock (suspended → running)
// iOS Safari는 유저 인터랙션 없이 생성된 AudioContext를 suspended 상태로 유지하며,
// resume 하지 않으면 예약된 소리가 큐에 쌓였다가 나중에 한꺼번에 재생됨
(function _iosAudioUnlock() {
    const ctx = SoundEffect.ctx;
    if (!ctx) return;
    const unlock = () => {
        if (ctx.state === 'suspended') ctx.resume().catch(() => {});
        document.removeEventListener('touchstart', unlock);
        document.removeEventListener('touchend', unlock);
        document.removeEventListener('click', unlock);
    };
    document.addEventListener('touchstart', unlock, { passive: true });
    document.addEventListener('touchend', unlock, { passive: true });
    document.addEventListener('click', unlock, { passive: true });
}());

