// 🌟 1. 현재 선택된 단어를 기억할 전역 변수 추가
window.selectedAdj = "";
window.selectedNoun = "";

/* [기능] 랜덤 닉네임 추출 및 드롭다운 세팅 */
function generateRandomNickname() {
    const adjArr = currentLang === 'en' ? NICK_ADJECTIVES_EN : NICK_ADJECTIVES;
    const nounArr = currentLang === 'en' ? NICK_NOUNS_EN : NICK_NOUNS;
    window.selectedAdj = adjArr[Math.floor(Math.random() * adjArr.length)];
    window.selectedNoun = nounArr[Math.floor(Math.random() * nounArr.length)];

    // 이 함수가 실행되면 드롭다운의 값도 같이 바꿔줍니다.
    const adjSelect = document.getElementById('adj-select');
    const nounSelect = document.getElementById('noun-select');
    if (adjSelect) adjSelect.value = window.selectedAdj;
    if (nounSelect) nounSelect.value = window.selectedNoun;

    updateNicknamePreview(); // 프리뷰 즉시 갱신
}

/* [기능] 실시간 프리뷰 업데이트 */
function updateNicknamePreview() {
    const adjSelect = document.getElementById('adj-select');
    const nounSelect = document.getElementById('noun-select');

    if (adjSelect && nounSelect) {
        window.selectedAdj = adjSelect.value;
        window.selectedNoun = nounSelect.value;

        // ★ [버그 픽스] 부서/지파 선택 함수가 찾는 변수에도 이름을 쥐여줍니다!
        window.tempNickname = window.selectedAdj + " " + window.selectedNoun;
        window.tempName = window.tempNickname;
    }

    // 화면 상단의 까만색 프리뷰 박스 갱신
    const previewBox = document.getElementById('preview-full');
    if (previewBox) {
        previewBox.innerHTML = `${getTribeIcon(window.tempTribe)}${getDeptTag(window.tempDept)} ${window.tempNickname}`;
    }
}

/* 도감 점수 계산 — 구절별 누적 클리어 횟수에 따라 10/20/30/50점.
   예전에는 이 계산이 renderLifeBook() 안에 인라인으로 박혀 있어서 도감 화면을 열어야만 값이 생겼고,
   그 변수는 함수 지역(let)이라 recalculateMaxHearts()에서는 스코프상 아예 보이지 않았다.
   → 도감 15,000점 +3 체력 보너스가 한 번도 발동한 적이 없다. 2026-09-08 수정. */
function getCollectionScoreOf(mastery) {
    if (!mastery || typeof bibleData === 'undefined') return 0;
    let total = 0;
    for (let ch = 1; ch <= 22; ch++) {
        if (!bibleData[ch]) continue;
        bibleData[ch].forEach((v, idx) => {
            const count = mastery[`${ch}-${idx + 1}`] || 0;
            if (count >= 20) total += 50;
            else if (count >= 10) total += 30;
            else if (count >= 5) total += 20;
            else if (count >= 1) total += 10;
        });
    }
    return total;
}

/* 체력 보너스 판정용. 예전엔 자유여행 + 왕의 길 합산이었다.
   2026-10-02부터 두 여정이 진도 한 벌을 쓰므로 한 번만 센다 — 다만 합치기 전 점수(collectionLegacy)가 더 크면 그것을 쓴다.
   (합치면 15,000 아래로 내려가는 사람이 3명 있었다: 두 여정에서 같은 절을 따로 쌓아 온 가장 열심인 사람들) */
function getTotalCollectionScore() {
    return Math.max(collectionLegacy || 0, getCollectionScoreOf(stageMastery));
}

/* ★ 기억은 하나 — 두 여정의 진도(클리어 횟수·첫 클리어 날·마지막 클리어·복습 단계·다음 복습)를 한 벌로 합친다 (2026-10-02).
   예전엔 여정마다 따로라 같은 절에 복습 시계가 둘(+ 백지레벨) 돌았고, 왕의 길에서 7일 단계까지 온 절도 자유여행에선 10분부터였다.
   여정은 이제 「길」(무엇이 열리고 어떤 순서로 가는가)만 정하고, 「기억」은 절마다 하나다.
   - 절마다 **마지막으로 복습한 쪽**을 통째로(_mergeProgressSet — 동기화와 같은 규칙), 클리어 횟수만 큰 쪽, 첫 클리어 날은 이른 쪽
     (첫 배포(10/2 21:16)는 스텝이 높은 쪽을 골라 멈춘 기록이 이겼다 — 그날 밤 서버 스냅샷으로 되돌림)
   - 몇 번 불러도 결과가 같다(멱등) — 옛 앱이 두 벌을 따로 써 보내도 다음 불러오기에서 다시 합쳐진다
   - 저장본은 예전 모양 그대로(최상위·kingsMode 둘 다) 같은 내용을 쓴다 → 옛 앱도 그대로 읽는다
   - 처음 합칠 때 그 전 도감 점수(두 여정 합)를 collectionLegacy로 한 번 남긴다 */
function _unifyJourneyMemory() {
    if (typeof kingsRoadData === 'undefined' || !kingsRoadData) return;
    const free = { mastery: stageMastery, clearDate: stageClearDate, lastClear: stageLastClear, reviewStep: stageReviewStep, nextReviewTime: stageNextReviewTime };
    const kings = { mastery: kingsRoadData.mastery, clearDate: kingsRoadData.clearDate, lastClear: kingsRoadData.lastClear, reviewStep: kingsRoadData.reviewStep, nextReviewTime: kingsRoadData.nextReviewTime };
    if (collectionLegacy === null) {
        // 두 벌이 이미 같은 내용이면(합친 뒤 옛 앱이 이 필드를 빼고 저장한 경우) 한 번만 센다 — 두 번 세면 점수가 부풀어 오른다
        const fm0 = free.mastery || {}, km0 = kings.mastery || {};
        const same = Object.keys(fm0).length === Object.keys(km0).length && Object.keys(fm0).every(id => fm0[id] === km0[id]);
        collectionLegacy = getCollectionScoreOf(fm0) + (same ? 0 : getCollectionScoreOf(km0));
    }
    if (free.mastery === kings.mastery && free.reviewStep === kings.reviewStep) return;   // 이미 한 벌
    const r = _mergeProgressSet(free, kings).merged;   // 절마다 마지막으로 복습한 쪽 · 클리어 횟수는 큰 쪽
    stageMastery = kingsRoadData.mastery = r.mastery;
    stageClearDate = kingsRoadData.clearDate = r.clearDate;
    stageLastClear = kingsRoadData.lastClear = r.lastClear;
    stageReviewStep = kingsRoadData.reviewStep = r.reviewStep;
    stageNextReviewTime = kingsRoadData.nextReviewTime = r.nextReviewTime;
}

/* [추가] 최종 체력 계산 함수 (버프 적용용) */
function recalculateMaxHearts() {
    // 1. 도감 점수 확인 (자유여행 + 왕의 길 합산 15,000점 이상이면 +3 보너스)
    let bonus = 0;

    if (getTotalCollectionScore() >= 15000) {
        bonus = 3;
    }

    // 2. 최종 체력 = 구매한 체력 + 보너스
    maxPlayerHearts = purchasedMaxHearts + bonus;

    // 3. UI 갱신 (playerHearts가 초기화된 이후에만 호출)
    if (typeof updateBattleUI !== 'undefined' && typeof playerHearts !== 'undefined') updateBattleUI();
}

// 1. 리그 및 부스터 데이터 초기화
let leagueData = {
    weekId: getWeekId(),
    monthId: getMonthId(),
    myScore: 0,
    myMonthlyScore: 0,
    totalScore: 0,
    yearlyScore: 0, // 🌟 [추가] 올해의 지파 대항전 기여도
    stageLog: {},
};

// ============================================================
// ★ [v1.1.0] 직렬 복습 시스템 핵심 함수
// ============================================================

// step(1-based)에 해당하는 기본 보석 보상 반환
function getReviewBaseGem(step) {
    if (step <= 0) return 0;
    const idx = step - 1;
    if (idx < REVIEW_SEQUENCE.length) return REVIEW_SEQUENCE[idx].baseGem;
    return 90 + (step - 7) * 10; // step 7+
}

// step이 해금되기까지 이전 step으로부터 기다려야 할 시간(ms) 반환
// step 7+: 167 → 355 → 671 → 1343시간 (약 2배씩 증가)
function getReviewWaitMs(step) {
    if (step <= 1) return 0;
    const idx = step - 1; // step 2 → index 1
    if (idx < REVIEW_SEQUENCE.length) return REVIEW_SEQUENCE[idx].waitMs;
    // step 10 이후 대기 시간 (사용자 원안 기준)
    const longWaits = [167, 355, 671, 1343]; // step 7~10
    const n = step - 7; // step 7 → n=0
    const hours = n < longWaits.length
        ? longWaits[n]
        : Math.round(longWaits[longWaits.length - 1] * Math.pow(2, n - (longWaits.length - 1)));
    return hours * 60 * 60 * 1000;
}

// 현재 복습 상태를 통합 반환 (checkMemoryStatus + peekTimedBonus 역할)
// 반환: { step, nextReviewTime, isEligible, remainMs, baseGem, isFirstClear }
function getReviewStatus(stageId) {
    const step = stageReviewStep[stageId] || 1;
    const nextTime = stageNextReviewTime[stageId] || 0;
    const now = Date.now();
    const isFirstClear = (step === 1 && nextTime === 0);
    const isEligible = (now >= nextTime); // nextTime=0이면 항상 가능
    const remainMs = isEligible ? 0 : nextTime - now;
    const baseGem = isEligible ? getReviewBaseGem(step) : 0;
    return { step, nextReviewTime: nextTime, isEligible, remainMs, baseGem, isFirstClear };
}

// 클리어 시 step을 올리고 다음 타이머를 설정. 획득한 보석 수를 반환.
function advanceReviewStep(stageId) {
    const currentStep = stageReviewStep[stageId] || 1;
    const baseGem = getReviewBaseGem(currentStep);

    const strength = currentStep > 1 ? getMemoryStrength(stageId) : null;
    const outcome = (strength === null || strength >= 0.8) ? 'perfect'
                  : strength >= 0.4 ? 'good'
                  : 'miss';

    const nextStep = currentStep + 1;
    stageReviewStep[stageId] = nextStep;
    const waitMs = getReviewWaitMs(nextStep);
    stageNextReviewTime[stageId] = waitMs > 0 ? Date.now() + waitMs : 0;

    const earnedGem = outcome === 'perfect' ? baseGem
                    : outcome === 'good'    ? Math.round(baseGem * 0.5)
                    :                        Math.round(baseGem * 0.2);

    return { earnedGem, outcome };
}

/* 단계별 기억 안정성 S(시간) — getMemoryStrength와 「보너스 선」 초기화(_resetLongUnstudied)가 함께 쓴다 */
function _stabilityHours(step) {
    // S값 기준: 대복습 완료 직후 안정성이 약 2배 증가한다는 FSRS 이론 적용
    // step 1 10분 후 · 2 1시간 · 3 6시간 · 4 23시간 · 5 대복습(23hr) 완료 → S ×2 (R=80%: 46시간 후) · 6 대복습(71hr) 완료 → S ×2 (R=80%: 142시간 후)
    const STABILITY_HOURS = [0.747, 4.48, 26.9, 103.1, 206.0, 637.0];
    const idx = step - 1;
    if (idx < STABILITY_HOURS.length) return STABILITY_HOURS[idx];
    return (getReviewWaitMs(step + 1) / 3600000) / 0.2231;   // step 7+: 다음 복습 대기시간으로 동적 산출
}
// ★ [에빙하우스] 현재 기억 강도 계산 (0~1)
// 공식: R = e^(-t/S), t=경과시간(hr), S=안정성(hr, 스텝별 증가)
function getMemoryStrength(stageId) {
    const lastClear = stageLastClear[stageId] || 0;
    if (lastClear === 0) return null;

    const step = stageReviewStep[stageId] || 1;
    const S = _stabilityHours(step);
    const elapsedHr = (Date.now() - lastClear) / 3600000;
    return Math.max(0, Math.min(1, Math.exp(-elapsedHr / S)));
}


// 중간점검 스테이지에 속한 서브스테이지 목록 반환 (앞쪽 normal 스테이지들)
function getSubStagesOfMidBoss(chData, midBossStage) {
    const idx = chData.stages.findIndex(s => s.id === midBossStage.id);
    const subs = [];
    for (let i = idx - 1; i >= 0; i--) {
        const s = chData.stages[i];
        if (s.type === 'boss' || s.type === 'mid-boss') break;
        subs.push(s);
    }
    return subs;
}

// 중간점검 소속 서브스테이지들의 평균 기억 강도(0~1) 반환
function getMidBossAvgStrength(chData, midBossStage) {
    const subs = getSubStagesOfMidBoss(chData, midBossStage);
    const cleared = subs.filter(s => stageLastClear[s.id]);
    if (cleared.length === 0) return null;
    const sum = cleared.reduce((acc, s) => acc + (getMemoryStrength(s.id) || 0), 0);
    return sum / cleared.length;
}

// step → 통계/배지 표시용 레벨(0~5) 변환 (getTotalMemoryLevel, mem-badge 호환용)
function getMemoryLevelFromStep(step) {
    if (step <= 1) return 0;
    if (step <= 4) return 1;  // 1단계 진행 중
    if (step <= 5) return 2;  // 2단계
    if (step <= 6) return 3;  // 3단계
    if (step <= 9) return 4;
    return 5;
}

// 구버전(v1.0.0) 데이터를 신규 step 시스템으로 마이그레이션
function migrateToSerialReview(parsed) {
    const oldLevels = parsed.memoryLevels || {};
    const oldBonus  = parsed.timedBonus || {};
    const oldNextTime = parsed.nextEligibleTime || {};
    const newStep = {};
    const newNextTime = {};

    Object.keys(oldLevels).forEach(id => {
        const level = oldLevels[id] || 0;
        const bonus = oldBonus[id] || { remaining: 3, lastClear: 0 };

        let mappedStep;
        if (level === 0) {
            if (bonus.lastClear === 0) {
                mappedStep = 1; // 미클리어
            } else if (bonus.remaining === 3) {
                mappedStep = 1; // 클리어 직후, 10분 대기
            } else if (bonus.remaining === 2) {
                mappedStep = 2; // 10분 완료, 1시간 대기
            } else if (bonus.remaining === 1) {
                mappedStep = 3; // 1시간 완료, 6시간 대기
            } else {
                mappedStep = 4; // 6시간 완료, 23시간 대기
            }
        } else if (level === 1) {
            mappedStep = 5;
        } else if (level === 2) {
            mappedStep = 8;
        } else if (level === 3) {
            mappedStep = 10;
        } else {
            mappedStep = 10 + (level - 3) * 2;
        }

        newStep[id] = mappedStep;

        // 기존 nextEligibleTime이 아직 유효하면 그대로 사용
        if (oldNextTime[id] && oldNextTime[id] > Date.now()) {
            newNextTime[id] = oldNextTime[id];
        } else {
            newNextTime[id] = 0; // 만료됐으면 즉시 가능
        }
    });

    stageReviewStep = newStep;
    stageNextReviewTime = newNextTime;
    console.log(`✅ 마이그레이션 완료: ${Object.keys(newStep).length}개 스테이지 변환됨`);
}

// 스테이지 버튼에 표시할 복습 단계 배지 HTML 생성
function buildReviewBadgeHtml(stageId) {
    const status = getReviewStatus(stageId);
    const step = status.step;

    // 단계 그룹 및 표시할 step strip 정의
    let stepDefs;
    if (step <= 4) {
        stepDefs = [
            { label: t('review_dot_start'), step: 1 },
            { label: t('review_dot_10m'), step: 2 },
            { label: t('review_dot_1h'), step: 3 },
            { label: t('review_dot_6h'), step: 4 },
        ];
    } else if (step <= 5) {
        stepDefs = [
            { label: t('review_dot_1d'), step: 5 },
        ];
    } else if (step <= 6) {
        stepDefs = [
            { label: t('review_dot_3d'), step: 6 },
        ];
    } else {
        // step 7+: 대기 시간 표시
        const waitMs = getReviewWaitMs(step);
        const waitHr = Math.round(waitMs / 3600000);
        const waitLabel = waitHr >= 24 ? t('review_dot_days', { n: Math.round(waitHr / 24) }) : t('review_dot_hours', { n: waitHr });
        stepDefs = [{ label: waitLabel, step }];
    }

    const dotsHtml = stepDefs.map((s, i) => {
        const isDone = s.step < step;
        const isCurrent = s.step === step;
        const cls = isDone ? 'review-dot done' : isCurrent ? 'review-dot current' : 'review-dot future';
        const sep = i > 0 ? '<span class="review-dot-sep">→</span>' : '';
        return `${sep}<span class="${cls}">${s.label}</span>`;
    }).join('');

    // 타이머 or 보상 표시
    let statusHtml;
    if (!status.isEligible) {
        statusHtml = `<span class="review-timer live-timer-review" data-unlock="${status.nextReviewTime}">${t('review_status_calculating')}</span>`;
    } else if (step === 1) {
        statusHtml = `<span class="review-ready">${t('review_status_first', { gem: status.baseGem })}</span>`;
    } else {
        statusHtml = `<span class="review-ready">${status.baseGem}💎 ${t('status_review_now')}</span>`;
    }

    return `<div class="review-badge-strip"><div class="review-dots">${dotsHtml}</div><div class="review-status">${statusHtml}</div></div>`;
}

// ============================================================
// [Forgetting-Curve 냉각 시간 계산] (구버전 호환용, 직접 호출 금지)
// ============================================================
function getNextEligibleTime(memoryLevel) {
    // 메모리 레벨에 따른 냉각 시간 (시간 단위)
    const cooldownHours = {
        0: 23,   // Level 0: 1일 (23시간)
        1: 71,   // Level 1: 3일 (71시간)
        2: 167,  // Level 2: 7일 (167시간)
        3: 335,  // Level 3: 14일 (335시간)
        4: 719,  // Level 4+: 30일 (719시간)
        5: 719
    };

    const hours = cooldownHours[memoryLevel] || 719;
    return Date.now() + (hours * 60 * 60 * 1000);
}

// ============================================================
// [때를 따른 양식 보너스 시스템]
// ============================================================
function getTimedBonus(stageId) {
    // 보너스 데이터 초기화
    if (!stageTimedBonus[stageId]) {
        stageTimedBonus[stageId] = { remaining: 3, lastClear: 0 };
    }

    const bonus = stageTimedBonus[stageId];

    // 각인 주기 체크
    const memStatus = checkMemoryStatus(stageId);

    // 각인 주기 도래 시 자동 리셋 (숙련도에 따라 시작 배율 차등)
    // level 0→1 (1회차): 1.5x에서 시작 (remaining=3)
    // level 1→2 (2회차): 2x에서 시작 (remaining=2)
    // level 2+ (3회차+): 5x에서 시작 (remaining=1)
    if (memStatus.isForgotten) {
        const startRemaining = memStatus.level === 0 ? 3 : memStatus.level === 1 ? 2 : 1;
        if (bonus.remaining < startRemaining) {
            bonus.remaining = startRemaining;
        }
    }

    return bonus;
}

// 소진 없이 현재 받을 수 있는 보너스 레벨 미리 확인 (UI 표시용)
// 반환값: 4=최초(×1), 3=×1.5가능, 2=×2가능, 1=×5가능, 0=대기중/쿨타임
function peekTimedBonus(stageId) {
    const bonus = getTimedBonus(stageId);
    if (bonus.lastClear === 0) return 4;
    if (bonus.remaining === 0) return 0;
    const THRESHOLDS = { 3: 600000, 2: 3600000, 1: 21600000 };
    const elapsed = Date.now() - bonus.lastClear;
    return elapsed >= THRESHOLDS[bonus.remaining] ? bonus.remaining : 0;
}

function consumeTimedBonus(stageId) {
    const bonus = getTimedBonus(stageId);
    const now = Date.now();

    // 최초 클리어 (lastClear=0)
    if (bonus.lastClear === 0) {
        bonus.lastClear = now;
        return 4; // ×1, 10분 후 알림 예약
    }

    // 쿨타임 (모든 보너스 소진)
    if (bonus.remaining === 0) return 0;

    const THRESHOLDS = {
        3: 10 * 60 * 1000,       // remaining=3: 10분 대기 후 ×1.5
        2: 60 * 60 * 1000,       // remaining=2: 1시간 대기 후 ×2
        1: 6 * 60 * 60 * 1000,   // remaining=1: 6시간 대기 후 ×5
    };

    const elapsed = now - bonus.lastClear;
    const threshold = THRESHOLDS[bonus.remaining];

    if (elapsed >= threshold) {
        // 타이밍 OK → 보너스 지급, 단계 소진
        const level = bonus.remaining;
        bonus.remaining--;
        bonus.lastClear = now;
        return level; // 3→×1.5, 2→×2, 1→×5
    } else {
        // 너무 일찍 → ×1, 단계 유지 (lastClear 갱신 안 함)
        return 0;
    }
}

/* [시스템: 미션 및 부스터 데이터] */
let boosterData = {
    active: false,
    endTime: 0,
    multiplier: 1
};

/* ── 단비 (2026-09-13 베타) ─────────────────────────────────────────────────
   **오늘 한 절이라도 하면, 내일 단비가 내린다.** 20분간 승점 ×2. 그게 전부다.
   듀오링고의 '오늘 하면 내일 부스터'를 그대로 가져왔다 — 조건이 없어야 배울 것이 없다.
   원래 B 설계(미션 보상으로 받기·로그인 화면·햇살 구매·소멸 규칙)는 전부 뺐고, 부스터 구매도 없앤다.
   하루에 많이 할 사람은 부스터 없이도 많이 하고, 암송은 몰아서보다 매일이 중요하다.

   하는 일: ① 돌아오게 한다("어제 했으니 오늘 비"는 안 오면 아까운 것 — 스트릭의 힘, 벌은 없음)
           ② 내일이 곧 제때다 — 오늘 배운 구절의 23시간 복습이 내일 돌아오고, 비가 그때 와 있다
           ③ 복습이 없는 완주자도 매일 하니 매일 비

   연장 장치: RAIN_TIERS[2] = 햇살(×3). 그날 일일 미션을 SUN_DAILY_MISSIONS(4)개 완료하면 내일 햇살이 된다 —
   듀오링고의 "미션 N개 → 내일 3배"("적어도 이만큼은"). 기본 4개는 보스전 전이라도 완료할 수 있다.

   타이머는 기존 boosterData(active/multiplier/endTime)를 그대로 쓴다 — 승점 계산이 이미 그걸 본다. */
const ITEM_REFUND_GEM = 50;   // 떡·방패 환급 단가 (상점가와 같다)
let itemRefund = null;        // { at, bread, shield, gems } — 환급했으면 존재

const RAIN_MINUTES = 20;
const RAIN_TIERS = { 1: { mult: 2, icon: '🌧️', nameKey: 'rain_name' }, 2: { mult: 3, icon: '☀️', nameKey: 'sun_name' } };
const SUN_DAILY_MISSIONS = 4; // 그날 일일 미션을 이만큼 완료하면 내일 햇살(×3). 0 = 꺼짐

/* ── 햇살 사기 — 이정표의 쓸모 (2026-09-14) ─────────────────────────────────
   밭 30 → 하루 1회, 60 → 2회, 100 → 3회. 2,000젬에 20분 ×3 (이미 켜져 있으면 ×3으로 올리고 20분 더).
   이정표가 처음으로 기능을 갖고, 밭 100 뒤에도 보석 쓸 곳이 생긴다.
   "부스터 구매를 없앤다"와 어긋나 보이지만 대상이 다르다 — 그때 없앤 건 누구나 사는 부스터,
   이건 백만 젬 넘게 심은 사람의 혜택이다. 승점 랭킹은 원래 '투자' 판이고 실시간 암송왕은 영향이 없다. */
const SUN_BUY_GEM = 2000;
let sunBuy = { day: '', count: 0 };   // 오늘(6시 경계) 몇 번 샀나
function _sunBuySlots(level) {
    if (level >= 144) return 4;   // 열둘의 열둘 (10/4)
    if (level >= 100) return 3;
    if (level >= 60) return 2;
    if (level >= 30) return 1;
    return 0;
}
function _sunBuyUsedToday() {
    return sunBuy.day === _get6AMDayStr() ? (sunBuy.count || 0) : 0;
}
/* 지금 켜진 날씨 — 배율로 판단한다 (미션 햇살이든 산 햇살이든 ×3이면 ☀️) */
function _activeWeatherTier() {
    return (boosterData.active && boosterData.multiplier >= 3) ? RAIN_TIERS[2] : RAIN_TIERS[1];
}
function buySun() {
    const slots = _sunBuySlots(maxPlayerHearts);
    const used = _sunBuyUsedToday();
    if (slots <= 0 || used >= slots) return;
    if (myGems < SUN_BUY_GEM) { showGemToast(0, t('alert_buy_hearts_no_gems', { cost: SUN_BUY_GEM }), true); return; }
    myGems -= SUN_BUY_GEM;
    sunBuy = { day: _get6AMDayStr(), count: used + 1 };
    const now = Date.now();
    const dur = RAIN_MINUTES * 60 * 1000;
    if (boosterData.active && now < boosterData.endTime) {
        boosterData.multiplier = Math.max(3, boosterData.multiplier);
        boosterData.endTime += dur;
    } else {
        boosterData.active = true;
        boosterData.multiplier = 3;
        boosterData.endTime = now + dur;
    }
    updateGemDisplay();
    saveGameData();
    if (typeof startBoosterTimer === 'function') startBoosterTimer();
    if (typeof SoundEffect !== 'undefined' && SoundEffect.playLevelUp) SoundEffect.playLevelUp();
    showToast(t('sun_bought', { min: RAIN_MINUTES }));
    if (typeof updateHeaderToday === 'function') updateHeaderToday();
    openFieldScreen();
}
function _dailyMissionsDone() {
    if (typeof missionData === 'undefined' || !missionData || !missionData.daily) return 0;
    const c = missionData.daily.claimed || [];
    let n = 0;
    for (let i = 0; i < c.length; i++) if (c[i]) n++;
    return n;
}
let rain = { earnedFor: '', tier: 0, promisedOn: '', startedOn: '' };   // 날짜는 전부 오전 6시 경계 키
let dailySeeds = {};    // 6시 경계 날짜 → 오늘 뿌린 씨 (최근 7일). "어제에 비해 얼마나 했나"
/* 씨 = 승점 ÷ 밭 (단비 배율 전). 구절 수로 세면 주소의 고난 22절(1분)과 망각의 고난 22절(12분)이 같은 22가 되는데,
   씨는 난도가 곧 무게라 1 : 10 — 실측 시간비(구절당 3초 : 30초)와 거의 같다. 새 가중치 표 없이 승점 체계를 그대로 쓴다.
   알고 둘 것: 초학습도 1이다(승점 체계가 초학습을 승점이 아니라 보석으로 쳐주는 구조). 자기 비교라 그대로 둔다. */

function _shift6AMDayStr(base, days) {
    const [y, m, d] = String(base).split('-').map(Number);
    return _getLocalDateStr(new Date(y, m - 1, d + days));
}
function _noteDailySeeds(seeds) {
    if (!seeds || seeds <= 0) return;
    const k = _get6AMDayStr();
    dailySeeds[k] = (dailySeeds[k] || 0) + seeds;
    const keys = Object.keys(dailySeeds).sort();
    while (keys.length > 7) delete dailySeeds[keys.shift()];
    _promiseRain();
    if (typeof _guideNoteDay === 'function') _guideNoteDay();   // 동행 — 오늘 암송한 날
    if (typeof updateHeaderToday === 'function') updateHeaderToday();
}
/* 오늘 첫 구절 → 내일 비를 예약. 하루 한 번만 말한다 */
function _promiseRain() {
    const today = _get6AMDayStr();
    if (rain.promisedOn !== today) {
        rain.promisedOn = today;
        rain.earnedFor = _shift6AMDayStr(today, 1);
        rain.tier = 1;
        if (typeof showToast === 'function') showToast(t('rain_promise'));
    }
    // 연장 장치 — 햇살. 기본 4개(로그인·새 구절·중간점검·백업)는 보스전 전이라도 완료할 수 있다 ("적어도 이만큼은")
    if (SUN_DAILY_MISSIONS > 0 && rain.tier < 2 && rain.earnedFor === _shift6AMDayStr(today, 1) &&
        _dailyMissionsDone() >= SUN_DAILY_MISSIONS) {
        rain.tier = 2;
        if (typeof showToast === 'function') showToast(t('sun_promise'));
        if (typeof updateHeaderToday === 'function') updateHeaderToday();
    }
}
/* 오늘 첫 스테이지에 들어가는 순간 켠다. 버튼 없음. 랭킹만 보고 나가면 안 켜지고 남는다 */
function _maybeStartRain() {
    const today = _get6AMDayStr();
    if (rain.earnedFor !== today || rain.startedOn === today) return;
    rain.startedOn = today;
    const tier = RAIN_TIERS[rain.tier] || RAIN_TIERS[1];
    const now = Date.now();
    const dur = RAIN_MINUTES * 60 * 1000;
    // ★ 이미 날씨가 켜져 있으면(첫 스테이지 전에 햇살을 산 경우) 덮어쓰지 않고 buySun과 같은 규칙으로 얹는다 —
    //   배율은 큰 쪽, 시간은 20분 연장. 예전엔 무조건 ×2·20분으로 덮어써서 2,000젬 햇살이 단비로 내려갔다 (2026-09-22)
    if (boosterData.active && now < boosterData.endTime) {
        boosterData.multiplier = Math.max(boosterData.multiplier || 1, tier.mult);
        boosterData.endTime += dur;
    } else {
        boosterData.active = true;
        boosterData.multiplier = tier.mult;
        boosterData.endTime = now + dur;
    }
    saveGameData();
    if (typeof startBoosterTimer === 'function') startBoosterTimer();
    if (typeof showToast === 'function') {
        // 단비가 · 햇살이 — 받침에 따라 (10/5까지 「단비이 내립니다」였다)
        const nm = t(tier.nameKey), lc = nm.charCodeAt(nm.length - 1) - 44032;
        const ig = (lc >= 0 && lc < 11172) ? (lc % 28 ? '이' : '가') : '이';
        showToast(t('rain_started', { icon: tier.icon, name: nm, ig, min: RAIN_MINUTES, multi: tier.mult }));
    }
    if (typeof updateHeaderToday === 'function') updateHeaderToday();
}
/* 서버 시각 보정(clock.js)이 기기 시계와 1시간 넘게 어긋난 것을 알아채면 한 번 알린다.
   '오늘'이 폰 날짜와 다르게 보일 수 있으니 이유를 말해준다. 보정 자체는 clock.js가 이미 끝냈다 */
/* 잡히지 않은 오류를 화면 위에 띄운다 (2026-09-17). 아이폰은 콘솔을 볼 수 없어 "모달이 그냥 닫혀요"로만 전해진다.
   세션당 첫 오류 하나, 우리 파일(game.js·index.html)에서 난 것만. 스크린샷으로 원인을 받기 위한 것 */
let _errShown = false;
function _showUncaughtError(msg, src, line) {
    if (_errShown) return;
    if (src && !/kingsload|game\.js|index\.html|clock\.js/.test(String(src))) return;
    _errShown = true;
    try {
        const el = document.createElement('div');
        el.style.cssText = 'position:fixed;top:12px;left:50%;transform:translateX(-50%);z-index:99999;max-width:92vw;background:#7b1e1e;color:#fff;padding:10px 14px;border-radius:10px;font-size:12px;line-height:1.5;word-break:break-all;pointer-events:none;box-shadow:0 4px 16px rgba(0,0,0,.4);';
        el.textContent = `⚠️ 오류: ${String(msg).slice(0, 160)}${line ? ` (${String(src || '').split('/').pop().split('?')[0]}:${line})` : ''}`;
        document.body.appendChild(el);
        setTimeout(() => el.remove(), 12000);
    } catch (e) {}
}
window.addEventListener('error', (ev) => _showUncaughtError(ev.message || (ev.error && ev.error.message) || 'error', ev.filename, ev.lineno));
window.addEventListener('unhandledrejection', (ev) => { const r = ev.reason; _showUncaughtError((r && (r.message || r.code)) || String(r), 'game.js', 0); });

function _onClockChanged(detail) {
    const off = (detail && detail.offset) || 0;
    if (Math.abs(off) < 3600000) return;
    const h = Math.round(Math.abs(off) / 3600000);
    console.warn('[clock] device clock off by', off, 'ms');
    if (typeof showToast === 'function') showToast(t('clock_adjusted', { h }));
}
document.addEventListener('kr-clock-changed', (e) => _onClockChanged(e.detail));
// HEAD 응답이 game.js 파싱보다 먼저 올 수 있다(1MB) — 그때는 이벤트를 놓치므로 기록을 본다
if (window._krClock && window._krClock.lastChange) setTimeout(() => _onClockChanged(window._krClock.lastChange), 3000);

/* 지도 헤더 셋째 줄 — 📖 오늘 5절 · 어제 9절 · 🌧️ 내일 단비 */
function updateHeaderToday() {
    const row2 = document.querySelector('.map-header-row2');
    if (!row2) return;
    let row3 = document.getElementById('header-today');
    if (!row3) {
        row3 = document.createElement('div');
        row3.id = 'header-today';
        row3.className = 'map-header-row3';
        row2.insertAdjacentElement('afterend', row3);
    }
    const today = _get6AMDayStr();
    const yday = _shift6AMDayStr(today, -1);
    const tCnt = Math.round(dailySeeds[today] || 0);
    const yCnt = Math.round(dailySeeds[yday] || 0);
    let rainTxt;
    if (boosterData.active && Date.now() < boosterData.endTime) {
        const tier = _activeWeatherTier();
        rainTxt = t('header_rain_now', { icon: tier.icon, name: t(tier.nameKey) });
    } else if (rain.earnedFor === today && rain.startedOn !== today) {
        const tier = RAIN_TIERS[rain.tier] || RAIN_TIERS[1];
        rainTxt = t('header_rain_ready', { icon: tier.icon, name: t(tier.nameKey) });
    } else if (rain.promisedOn === today) {
        const tier = RAIN_TIERS[rain.tier] || RAIN_TIERS[1];
        const left = SUN_DAILY_MISSIONS - _dailyMissionsDone();
        rainTxt = (rain.tier < 2 && SUN_DAILY_MISSIONS > 0 && left > 0)
            ? t('header_rain_tomorrow_sun_hint', { icon: tier.icon, name: t(tier.nameKey), left })
            : t('header_rain_tomorrow', { icon: tier.icon, name: t(tier.nameKey) });
    } else {
        rainTxt = t('header_rain_hint');
    }
    row3.innerHTML = `<span>${t('header_today', { today: tCnt, yday: yCnt })}</span><span class="header-today-sep">·</span><span>${rainTxt}</span>`;
}

