// [시스템: 성과 측정 변수]
let stageStartTime = 0; // 시작 시간
let bossStartTime = 0;  // 보스전 시작 시간
let wrongCount = 0;     // 틀린 횟수
let battleHintCount = 0; // 보스전/훈련 중 힌트 사용 횟수
let bossHintCount = 0;   // 보스전 전용 힌트 사용 횟수

/* [시스템: 화면 이동] */
/* [수정] 게임 시작 함수 (사운드 설정 불러오기 적용) */
// ============================================================
// ★ [왕의 길 모드] 핵심 로직
// ============================================================

// 전역 변수 스왑으로 모드 전환 (기존 함수들이 변경 없이 올바른 데이터를 참조하게 됨)
function switchMode(mode) {
    if (mode === activeMode) return;

    if (mode === 'kings') {
        // 현재 자유여행 데이터를 백업
        _freeStageMastery = stageMastery;
        _freeStageClearDate = stageClearDate;
        _freeStageLastClear = stageLastClear;
        _freeStageReviewStep = stageReviewStep;
        _freeStageNextReviewTime = stageNextReviewTime;
        // 왕의 길 데이터로 스왑
        stageMastery = kingsRoadData.mastery;
        stageClearDate = kingsRoadData.clearDate;
        stageLastClear = kingsRoadData.lastClear;
        stageReviewStep = kingsRoadData.reviewStep;
        stageNextReviewTime = kingsRoadData.nextReviewTime;
    } else {
        // 자유여행 데이터로 복원
        stageMastery = _freeStageMastery;
        stageClearDate = _freeStageClearDate;
        stageLastClear = _freeStageLastClear;
        stageReviewStep = _freeStageReviewStep;
        stageNextReviewTime = _freeStageNextReviewTime;
        // 왕의 길 데이터 백업
        kingsRoadData.mastery = kingsRoadData.mastery; // 이미 같은 참조
    }

    activeMode = mode;
    // 맵의 스테이지 클리어 상태 반영
    gameData.forEach(chapter => {
        chapter.stages.forEach(stage => {
            stage.cleared = (stageMastery[stage.id] || 0) > 0;
            stage.locked = false;
        });
    });
    saveGameData();
}

// 왕의 길 단계 설정 (최초 선택 or 변경)
function setKingsRoadStep(newStep) {
    if (kingsRoadData.stepHistory.length === 0) {
        // 최초 설정
        const now = Date.now();
        kingsRoadData.startTimestamp = now;
        kingsRoadData.stepHistory = [{ step: newStep, timestamp: now, isInitial: true }];
    } else {
        // 단계 변경: 현재 날짜 시작 시점을 기록하고 새 항목 추가 (이력 보존)
        const oldLast = kingsRoadData.stepHistory[kingsRoadData.stepHistory.length - 1];
        const daysElapsed = Math.floor((Date.now() - oldLast.timestamp) / 86400000);
        const preservedTimestamp = oldLast.timestamp + daysElapsed * 86400000;
        kingsRoadData.stepHistory.push({ step: newStep, timestamp: preservedTimestamp, isInitial: false });
    }
    updateKingsStepBtn();
    saveGameData();
}

// 왕의 길 단계 순환 (메뉴 버튼) — 1초 쿨다운으로 연타 방지
let _kingsStepChangeCooldown = false;
function cycleKingsStep() {
    if (kingsRoadData.stepHistory.length === 0) return;
    if (_kingsStepChangeCooldown) return; // 연타 차단
    _kingsStepChangeCooldown = true;
    setTimeout(() => { _kingsStepChangeCooldown = false; }, 1000);

    const currentStep = kingsRoadData.stepHistory[kingsRoadData.stepHistory.length - 1].step;
    const nextStep = currentStep >= 3 ? 1 : currentStep + 1;
    setKingsRoadStep(nextStep);
    alert(t('alert_kings_step_changed', { step: nextStep }));
}

// 메뉴의 왕의 길 단계 버튼 텍스트 갱신
function updateKingsStepBtn() {
    const btn = document.getElementById('kings-step-btn');
    if (!btn) return;
    if (kingsRoadData.stepHistory.length === 0) {
        btn.style.display = 'none';
    } else {
        const step = kingsRoadData.stepHistory[kingsRoadData.stepHistory.length - 1].step;
        btn.style.display = 'flex';
        btn.textContent = t('label_kings_step_btn', { step });
    }
}

/* 지도 헤더 첫 줄의 「👑 N단계」 칩 — 왕의 길에서만. 누르면 단계 선택.
   예전의 지도 위 카드(D+N일 · M구절 해금)를 대신한다: D+일은 행동으로 이어지지 않고, 해금 수는 지도가 이미 보여준다 (2026-09-17) */
function updateKingsStepChip() {
    const row1 = document.querySelector('#map-screen .map-header-row1');
    if (!row1) return;
    let chip = document.getElementById('kings-step-chip');
    const show = activeMode === 'kings' && kingsRoadData.stepHistory.length > 0;
    if (!show) { if (chip) chip.style.display = 'none'; return; }
    if (!chip) {
        chip = document.createElement('span');
        chip.id = 'kings-step-chip';
        chip.className = 'kings-step-chip';
        chip.onclick = openKingsStepSelectFromMap;
        const name = document.getElementById('sub-profile-name');
        if (name) name.insertAdjacentElement('afterend', chip); else row1.appendChild(chip);
    }
    const step = kingsRoadData.stepHistory[kingsRoadData.stepHistory.length - 1].step;
    chip.textContent = t('kings_step_chip', { step });
    chip.style.display = '';
}
function openKingsStepSelectFromMap() {
    window._kingsStepFromMap = true;
    const el = document.getElementById('kings-step-select-overlay');
    if (!el) return;
    const back = el.querySelector('.mode-back-btn');
    if (back) back.style.display = 'none';   // 지도에서 열었으니 '돌아가기'(모드 선택)는 없다
    el.style.display = 'flex';
}

// startTs ~ endTs 사이에 오전 6시(로컬) 경계가 몇 번 지났는지 반환
function count6AMBoundaries(startTs, endTs) {
    function to6AMDay(ts) {
        const d = new Date(ts);
        if (d.getHours() < 6) d.setDate(d.getDate() - 1);
        d.setHours(6, 0, 0, 0);
        return d.getTime();
    }
    return Math.max(0, Math.round((to6AMDay(endTs) - to6AMDay(startTs)) / 86400000));
}

// 현재 해금된 일반 스테이지 수 반환
function getKingsRoadUnlockedCount() {
    const history = kingsRoadData.stepHistory;
    if (!history || history.length === 0) return 0;

    const now = Date.now();
    let total = 0;
    for (let i = 0; i < history.length; i++) {
        const entry = history[i];
        // 구버전 호환: baseCount 필드가 있으면 해당 구간 이전 누적분을 직접 사용
        // (단계 변경 이력이 없는 저장 데이터)
        if (entry.baseCount !== undefined && i === 0 && history.length === 1) {
            const daysElapsed = count6AMBoundaries(entry.timestamp, now);
            const bonus = entry.isInitial
                ? (daysElapsed + 1) * entry.step
                : daysElapsed * entry.step;
            total = entry.baseCount + bonus;
            break;
        }
        // 이 구간이 끝나는 시점: 다음 항목의 timestamp, 없으면 현재
        const endTs = i + 1 < history.length ? history[i + 1].timestamp : now;
        const daysInPeriod = count6AMBoundaries(entry.timestamp, endTs);
        // 최초 설정: 첫날 즉시 1×step 해금 → (days + 1) * step
        // 단계 변경: 변경 당일 보너스 없고 내일부터 → days * step
        total += entry.isInitial
            ? (daysInPeriod + 1) * entry.step
            : daysInPeriod * entry.step;
    }
    total += (kingsRoadData.manualBonus || 0);
    return Math.min(total, getTotalNormalStageCount());
}

// 다음으로 수동 해금 가능한 일반 스테이지 id 반환 (없으면 null)
function getNextKingsRoadStageId() {
    const unlockedCount = getKingsRoadUnlockedCount();
    let normalIdx = 0;
    for (const chapter of gameData) {
        for (const stage of chapter.stages) {
            if (stage.type !== 'normal') continue;
            if (normalIdx === unlockedCount) return stage.id;
            normalIdx++;
        }
    }
    return null;
}

// 전체 일반 스테이지 수 반환 (캐시)
let _totalNormalStageCount = 0;
function getTotalNormalStageCount() {
    if (_totalNormalStageCount > 0) return _totalNormalStageCount;
    let count = 0;
    gameData.forEach(ch => ch.stages.forEach(s => { if (s.type === 'normal') count++; }));
    _totalNormalStageCount = count;
    return count;
}

// 왕의 길에서 해금된 stage id Set 반환 (normal + 관련 mid-boss/boss 포함)
function getKingsRoadUnlockedSet() {
    const unlockedCount = getKingsRoadUnlockedCount();
    const result = new Set();
    let normalIdx = 0;

    // 각 챕터별 해금 상태를 추적
    const chapterNormalUnlocked = {}; // chapterId → {total: N, unlocked: N}

    gameData.forEach(chapter => {
        const chId = chapter.id;
        const normals = chapter.stages.filter(s => s.type === 'normal');
        chapterNormalUnlocked[chId] = { total: normals.length, unlocked: 0 };

        chapter.stages.forEach(stage => {
            if (stage.type === 'normal') {
                if (normalIdx < unlockedCount) {
                    result.add(stage.id);
                    chapterNormalUnlocked[chId].unlocked++;
                }
                normalIdx++;
            }
        });
    });

    // mid-boss: 구성 절이 모두 해금이면 해금
    gameData.forEach(chapter => {
        chapter.stages.forEach(stage => {
            if (stage.type === 'mid-boss') {
                // id 형식: "X-mid-Y" (1~Y절이 구성 절)
                const match = stage.id.match(/^(\d+)-mid-(\d+)$/);
                if (match) {
                    const chId = parseInt(match[1]);
                    const endVerse = parseInt(match[2]);
                    // 해당 챕터에서 절 번호 1~endVerse 인 일반 스테이지가 모두 해금인지 확인
                    const chData = gameData.find(c => c.id === chId);
                    if (chData) {
                        const componentNormals = chData.stages.filter(s => {
                            if (s.type !== 'normal') return false;
                            const vMatch = s.id.match(/^\d+-(\d+)$/);
                            if (!vMatch) return false;
                            const vNum = parseInt(vMatch[1]);
                            // 이 mid-boss가 어떤 절 범위를 커버하는지 계산
                            // mid-boss 이전의 마지막 mid-boss 끝 절 + 1 부터 endVerse 까지
                            return vNum <= endVerse;
                        });
                        // 이 mid-boss에 속하는 구간만 추출 (이전 mid-boss 이후부터)
                        // 더 간단하게: endVerse까지의 모든 일반 스테이지가 해금이면 해금
                        const allUnlocked = componentNormals.every(s => result.has(s.id));
                        if (allUnlocked && componentNormals.length > 0) result.add(stage.id);
                    }
                }
            } else if (stage.type === 'boss') {
                // boss: 해당 챕터 모든 일반 스테이지가 해금이면 해금
                const chId = chapter.id;
                const info = chapterNormalUnlocked[chId];
                if (info && info.unlocked >= info.total && info.total > 0) {
                    result.add(stage.id);
                }
            }
        });
    });

    return result;
}

// 왕의 길 모드에서 스테이지가 잠금인지 여부
function isKingsRoadLocked(stageId) {
    if (activeMode !== 'kings') return false;
    const unlocked = getKingsRoadUnlockedSet();
    return !unlocked.has(stageId);
}

// === 왕의 길 해금 정보 UI ===

// 다음 해금까지 남은 ms 반환 (전부 해금됐으면 -1)
// 해금은 매일 오전 6시에 발생
function getKingsRoadNextUnlockMs() {
    const history = kingsRoadData.stepHistory;
    if (!history || history.length === 0) return -1;
    const total = getTotalNormalStageCount();
    const current = getKingsRoadUnlockedCount();
    if (current >= total) return -1;
    const now = new Date();
    const next6AM = new Date(now);
    next6AM.setHours(6, 0, 0, 0);
    if (next6AM.getTime() <= Date.now()) next6AM.setDate(next6AM.getDate() + 1);
    return next6AM.getTime() - Date.now();
}

// 해금됐지만 한 번도 클리어하지 않은 일반 스테이지 수 반환
function getKingsRoadNewStageCount() {
    if (!kingsRoadData.stepHistory || kingsRoadData.stepHistory.length === 0) return 0;
    const mastery = kingsRoadData.mastery || {};
    const unlocked = getKingsRoadUnlockedSet();
    let count = 0;
    unlocked.forEach(id => {
        // 일반 스테이지만 확인 (mid-boss, boss 제외)
        if (!id.includes('boss') && !id.includes('mid')) {
            if (!(mastery[id] > 0)) count++;
        }
    });
    return count;
}

let _kingsRoadInfoInterval = null;

function updateKingsRoadHomeInfo() {
    if (window.isGamePlaying) return;
    const history = kingsRoadData.stepHistory;
    if (!history || history.length === 0) {
        _updateKingsOverlayBtnInfo(0, -1, false);
        return;
    }

    const newCount = getKingsRoadNewStageCount();
    const msLeft = getKingsRoadNextUnlockMs();

    _updateKingsOverlayBtnInfo(newCount, msLeft, true);
}

function _updateKingsOverlayBtnInfo(newCount, msLeft, hasHistory) {
    const overlayInfoEl = document.getElementById('kings-overlay-info');
    if (!overlayInfoEl) return;

    if (!hasHistory) {
        overlayInfoEl.style.display = 'none';
        return;
    }

    overlayInfoEl.style.display = 'flex';

    const overlayBadgeEl = document.getElementById('kings-overlay-badge');
    if (overlayBadgeEl) {
        if (newCount > 0) {
            overlayBadgeEl.textContent = t('status_new_verses', { count: newCount });
            overlayBadgeEl.style.display = '';
        } else {
            overlayBadgeEl.style.display = 'none';
        }
    }

    const overlayTimerEl = document.getElementById('kings-overlay-timer');
    if (overlayTimerEl) {
        if (msLeft < 0) {
            overlayTimerEl.textContent = '🎉 ' + t('status_all_unlocked');
        } else {
            const h = Math.floor(msLeft / 3600000);
            const m = Math.floor((msLeft % 3600000) / 60000);
            const s = Math.floor((msLeft % 60000) / 1000);
            const pad = n => String(n).padStart(2, '0');
            overlayTimerEl.textContent = t('label_unlock_timer', { time: `${pad(h)}:${pad(m)}:${pad(s)}` });
        }
    }
}

function updateModeSelectReviewCounts() {
    const kingsCount = getReviewCountForMode('kings');
    const freeCount = getReviewCountForMode('free');

    const kingsEl = document.getElementById('kings-btn-review-count');
    if (kingsEl) {
        if (kingsCount > 0) {
            kingsEl.textContent = `📖 ${t('status_review_now')} ${kingsCount}`;
            kingsEl.style.display = '';
        } else {
            kingsEl.style.display = 'none';
        }
    }

    const freeEl = document.getElementById('free-btn-review-count');
    if (freeEl) {
        if (freeCount > 0) {
            freeEl.textContent = `📖 ${t('status_review_now')} ${freeCount}`;
            freeEl.style.display = '';
        } else {
            freeEl.style.display = 'none';
        }
    }

    // 다음 복습 대기시간 표시
    function fmtWaitMs(ms) {
        if (ms === null) return null;
        const totalMin = Math.ceil(ms / 60000);
        if (totalMin < 60) return `${totalMin}분 후`;
        const h = Math.floor(totalMin / 60);
        const m = totalMin % 60;
        return m > 0 ? `${h}시간 ${m}분 후` : `${h}시간 후`;
    }

    const kingsMap = kingsRoadData.nextReviewTime;
    const freeMap = activeMode === 'kings' ? _freeStageNextReviewTime : stageNextReviewTime;

    const kingsTxt = fmtWaitMs(getNearestWaitingMs(kingsMap));
    const freeTxt  = fmtWaitMs(getNearestWaitingMs(freeMap));

    const kingsWaitEl = document.getElementById('kings-btn-review-wait');
    const kingsWaitTime = document.getElementById('kings-btn-review-wait-time');
    if (kingsWaitEl && kingsWaitTime) {
        if (kingsTxt && kingsCount === 0) {
            kingsWaitTime.textContent = kingsTxt;
            kingsWaitEl.style.display = '';
        } else {
            kingsWaitEl.style.display = 'none';
        }
    }

    const freeWaitEl = document.getElementById('free-btn-review-wait');
    const freeWaitTime = document.getElementById('free-btn-review-wait-time');
    if (freeWaitEl && freeWaitTime) {
        if (freeTxt && freeCount === 0) {
            freeWaitTime.textContent = freeTxt;
            freeWaitEl.style.display = '';
        } else {
            freeWaitEl.style.display = 'none';
        }
    }
}

function startKingsRoadInfoTimer() {
    if (_kingsRoadInfoInterval) clearInterval(_kingsRoadInfoInterval);
    updateKingsRoadHomeInfo();
    _kingsRoadInfoInterval = setInterval(updateKingsRoadHomeInfo, 1000);
}

// 왕의 길 모드 선택 오버레이 열기
function openModeSelectOverlay() {
    const el = document.getElementById('mode-select-overlay');
    if (el) el.style.display = 'flex';
    updateKingsRoadHomeInfo();
    updateModeSelectReviewCounts();
    _renderModeSelectEventBtn();
}

/* 「여정을 선택하세요」에 이벤트 기간 동안만 세 번째 버튼 — 기간 한정 스테이지 (2026-09-16).
   모두가 반드시 거치는 화면이라 캐러셀·홈 띠보다 세고, 홈 공간을 안 건드린다. 시험이 왕의 길·자유여행과 같은 급의 목적지가 된다 */
function _renderModeSelectEventBtn() {
    const card = document.querySelector('#mode-select-overlay .mode-select-card');
    if (!card) return;
    _renderModeSelectDailyBtn(card);
    const old = document.getElementById('mode-event-btn');
    const ev = (typeof _activeEvents === 'function') ? (_activeEvents()[0] || null) : null;
    if (!ev) { if (old) old.remove(); return; }
    const dd = _eventDday(ev);
    const r = _eventReadiness(ev);
    const html = `<span class="mode-btn-icon">📝</span>
        <div class="mode-btn-text">
            <span class="mode-btn-label">${t('event_mode_btn_label')} <span class="mode-event-dday">${dd > 0 ? 'D-' + dd : dd === 0 ? 'D-Day' : ''}</span></span>
            <span class="mode-btn-desc">${escapeHtml(ev.title || t('event_default_title'))} · ${t('event_ready', { done: r.done, total: r.total })}</span>
        </div>`;
    if (old) { old.innerHTML = html; return; }
    const btn = document.createElement('button');
    btn.id = 'mode-event-btn';
    btn.className = 'mode-journey-btn event-btn';
    btn.onclick = () => { closeModeSelectOverlay(); openEventScreen(ev.id); };
    btn.innerHTML = html;
    card.appendChild(btn);
}

/* 「여정을 선택하세요」의 「📅 오늘의 암송」 — 달력이 있고 쉬는 날이 아닐 때만 */
function _renderModeSelectDailyBtn(card) {
    const old = document.getElementById('mode-daily-btn');
    const dev = (typeof _dailyEvent === 'function') ? _dailyEvent() : null;
    if (!dev || dev.rest) { if (old) old.remove(); return; }
    const ids = _eventVerseIds(dev);
    const done = _dailyDoneToday();
    const html = `<span class="mode-btn-icon">📅</span>
        <div class="mode-btn-text">
            <span class="mode-btn-label">${t('daily_mode_btn_label')} ${done ? '<span class="mode-event-dday">✅ ' + t('daily_done_short') + '</span>' : ''}</span>
            <span class="mode-btn-desc">${t(dev.mine ? 'daily_mode_btn_desc_mine' : 'daily_mode_btn_desc_church', { label: escapeHtml(_dailyLabel(ids)) })}</span>
        </div>`;
    if (old) { old.innerHTML = html; return; }
    const btn = document.createElement('button');
    btn.id = 'mode-daily-btn';
    btn.className = 'mode-journey-btn event-btn daily-btn';
    btn.onclick = () => { closeModeSelectOverlay(); openDailyScreen(); };
    btn.innerHTML = html;
    // 왕의 길·자유여행 다음, 시험 버튼 앞
    const evBtn = document.getElementById('mode-event-btn');
    if (evBtn) card.insertBefore(btn, evBtn); else card.appendChild(btn);
}

// 왕의 길 모드 선택 오버레이 닫기
function closeModeSelectOverlay() {
    const el = document.getElementById('mode-select-overlay');
    if (el) el.style.display = 'none';
}

// 왕의 길 단계 선택 오버레이 열기
function openKingsStepSelectOverlay() {
    closeModeSelectOverlay();
    const el = document.getElementById('kings-step-select-overlay');
    if (el) el.style.display = 'flex';
}

// 왕의 길 단계 선택 오버레이 닫기
function closeKingsStepSelectOverlay() {
    const el = document.getElementById('kings-step-select-overlay');
    if (el) {
        el.style.display = 'none';
        const back = el.querySelector('.mode-back-btn');
        if (back) back.style.display = '';
    }
    window._kingsStepFromMap = false;
}

// '왕의 길' 버튼 클릭 시
function onClickKingsRoad() {
    closeModeSelectOverlay();
    if (kingsRoadData.stepHistory.length === 0) {
        // 단계 미설정: 단계 선택 화면으로
        openKingsStepSelectOverlay();
    } else {
        // 단계 기설정: 바로 여정 시작
        switchMode('kings');
        proceedToJourneyOverlay();
    }
}

// 단계 선택 완료 후
function onSelectKingsStep(step) {
    closeKingsStepSelectOverlay();
    setKingsRoadStep(step);
    if (window._kingsStepFromMap) {
        // 지도의 칩에서 바꾼 것 — 여정 연출 없이 지도만 다시 그린다
        window._kingsStepFromMap = false;
        if (typeof renderChapterMap === 'function') renderChapterMap();
        if (typeof showToast === 'function') showToast(t('kings_step_changed_toast', { step }));
        return;
    }
    switchMode('kings');
    proceedToJourneyOverlay();
}

// '자유여행' 버튼 클릭 시
function onClickFreeJourney() {
    closeModeSelectOverlay();
    switchMode('free');
    proceedToJourneyOverlay();
}

// 기존 여정 오버레이 + amen 버튼 흐름 진행
function proceedToJourneyOverlay() {
    if (!localStorage.getItem('kingsRoad_introSeen')) {
        showIntroSlides(() => {
            localStorage.setItem('kingsRoad_introSeen', '1');
            _showJourneyOverlay();
        });
        return;
    }
    // 오늘 이미 아멘 했으면 여정 오버레이 스킵하고 바로 진입
    if (localStorage.getItem('kingsRoad_lastAmenDate') === getMemoryQuizDate()) {
        amenAndStartGame();
        return;
    }
    _showJourneyOverlay();
}

function _showJourneyOverlay() {
    const overlay = document.getElementById('journey-overlay');
    const amenBtn = document.getElementById('amen-btn');
    if (overlay) overlay.style.display = 'flex';
    if (amenBtn) {
        amenBtn.style.display = 'block';
        amenBtn.style.opacity = '0';
        amenBtn.style.pointerEvents = 'none';
        // 페이드인만 남기고 대기를 없앤다 — 1초 동안 아무것도 누를 수 없는 구간이
        // 온보딩에서 특히 길게 느껴진다. 연출은 CSS 트랜지션이 이어받는다.
        setTimeout(() => {
            amenBtn.style.opacity = '1';
            amenBtn.style.pointerEvents = 'auto';
        }, 120);
        amenBtn.onclick = amenAndStartGame;
    }
}

function showIntroSlides(onDone) {
    const SLIDES = [
        {
            icon: '📖',
            title: '말씀을 배워요',
            body: '계시록 말씀을 구절 단위로 배웁니다.\n초성 힌트로 시작해, 점점 혼자서\n완성해 나가는 방식이에요.',
        },
        {
            icon: '🧠',
            title: '잊기 전에 복습해요',
            body: '처음엔 10분 후, 그 다음은 1시간,\n6시간, 하루, 3일…\n간격을 늘리며 장기 기억으로 만들어요.',
        },
        {
            icon: '⚔️',
            title: '구역과 함께 용 사냥',
            body: '스테이지를 클리어할 때마다\n구역의 용 사냥에 기여합니다.\n함께 말씀을 완성해 나가요.',
        },
    ];

    // CSS (한 번만 주입)
    if (!document.getElementById('intro-slides-style')) {
        const s = document.createElement('style');
        s.id = 'intro-slides-style';
        s.textContent = `
#intro-slides-overlay {
    position:fixed;z-index:10000;inset:0;
    background:rgba(15,22,35,0.98);
    display:flex;flex-direction:column;
    align-items:center;justify-content:center;
    padding:32px 24px 40px;box-sizing:border-box;
}
#intro-slides-overlay .is-icon {
    font-size:3.2rem;margin-bottom:18px;
    animation:is-pop .32s cubic-bezier(.34,1.56,.64,1) both;
}
#intro-slides-overlay .is-title {
    font-size:1.3rem;font-weight:700;
    color:#f1c40f;margin-bottom:14px;text-align:center;
    animation:is-pop .32s cubic-bezier(.34,1.56,.64,1) .05s both;
}
#intro-slides-overlay .is-body {
    font-size:0.93rem;color:#dce8f5;line-height:1.85;
    text-align:center;white-space:pre-line;max-width:280px;
    animation:is-pop .32s cubic-bezier(.34,1.56,.64,1) .1s both;
}
#intro-slides-overlay .is-dots {
    display:flex;gap:8px;margin:28px 0 0;
}
#intro-slides-overlay .is-dot {
    width:8px;height:8px;border-radius:50%;
    background:rgba(255,255,255,0.25);transition:background .25s;
}
#intro-slides-overlay .is-dot.active { background:#f1c40f; }
#intro-slides-overlay .is-btn {
    margin-top:20px;background:#f1c40f;color:#2c3e50;
    font-size:1rem;font-weight:700;
    padding:12px 44px;border-radius:30px;border:none;cursor:pointer;
    box-shadow:0 4px 18px rgba(241,196,15,.3);
}
@keyframes is-pop {
    from{opacity:0;transform:translateY(14px);}
    to{opacity:1;transform:none;}
}`;
        document.head.appendChild(s);
    }

    let current = 0;

    const el = document.createElement('div');
    el.id = 'intro-slides-overlay';
    document.body.appendChild(el);

    function render(idx) {
        const slide = SLIDES[idx];
        const isLast = idx === SLIDES.length - 1;
        el.innerHTML = `
            <div class="is-icon">${slide.icon}</div>
            <div class="is-title">${slide.title}</div>
            <div class="is-body">${slide.body}</div>
            <div class="is-dots">${SLIDES.map((_, i) => `<div class="is-dot${i === idx ? ' active' : ''}"></div>`).join('')}</div>
            <button class="is-btn">${isLast ? '시작하기' : '다음'}</button>`;
        el.querySelector('.is-btn').onclick = () => {
            if (isLast) {
                el.remove();
                onDone();
            } else {
                current++;
                render(current);
            }
        };
    }

    render(0);
}

// ============================================================

function startGame() {
    // 모드 선택 오버레이를 먼저 표시
    openModeSelectOverlay();
}

function amenAndStartGame() {
    // 오늘 아멘 완료 기록 (하루 1회 자동 스킵용, 오전 6시 경계 기준)
    localStorage.setItem('kingsRoad_lastAmenDate', getMemoryQuizDate());

    // ★ 여정 진입 시 1회 복습 타이밍 팝업 체크 예약 (goMap()에서 소비됨)
    window._pendingReviewPopupCheck = true;
    // ★ 신규 유저 첫 구절 안내 예약 (goMap()에서 소비, 조건은 _shouldGuideFirstStage)
    window._pendingFirstStageStart = true;

    const overlay = document.getElementById('journey-overlay');
    const amenBtn = document.getElementById('amen-btn');
    // 시각적 피드백만 즉시 처리 (INP 개선: 브라우저가 먼저 페인트할 수 있도록)
    if (overlay) overlay.style.display = 'none';
    if (amenBtn) amenBtn.style.display = 'none';

    // 1. 오디오 권한 획득 (동기 but 빠름)
    if (typeof SoundEffect !== 'undefined' && SoundEffect.ctx.state === 'suspended') {
        SoundEffect.ctx.resume();
    }

    // 3. 효과음 버튼 상태 동기화
    syncSfxButtons();

    // 무거운 작업은 다음 태스크로 미뤄 브라우저가 먼저 페인트하게 함
    setTimeout(() => {
        // 🌟 4. 보류 중인 보상 — 맵 진입 후 자동 팝업 예약
        window._pendingRewardAutoPopup = true;

        // 5. 기억 퀴즈 시도 후 맵 화면으로 이동
        //    홈 📖 복습으로 들어왔으면 퀴즈를 건너뛴다 — 복습하러 왔는데 퀴즈가 먼저 뜨면 엉뚱하다 (2026-10-03)
        if (!window._forceReviewPopup && typeof showMemoryQuizOverlay === 'function') showMemoryQuizOverlay();
        else if (typeof goMap === 'function') goMap();

        // 6. 새 공지 자동 노출 (한 번만)
        setTimeout(() => {
            if (typeof checkAndShowNewNotice === 'function') checkAndShowNewNotice();
        }, 800);
    }, 0);
}

/* =====================================================
   [지난 주 보상] pendingReward 확인 → 홈 버튼 표시
   ===================================================== */
function checkPendingReward() {
    if (typeof loadKrEvents === 'function') loadKrEvents();   // 이벤트도 같은 시점(인증 뒤)에 한 번
    if (typeof db === 'undefined' || !db || !myTag) return;

    // enablePersistence 캐시 우회: 다른 기기의 수령 여부를 항상 서버에서 확인
    db.collection('leaderboard').doc(myTag).get({ source: 'server' }).then(doc => {
        if (!doc.exists) return;
        // 내 암송왕 칭호 — 프로필 표시용 (같은 조회에서 얻는다)
        _myRecallTitle = doc.data().recallTitle || null;
        _myReadTitle = doc.data().readTitle || null;
        if ((_myRecallTitle || _myReadTitle) && typeof updateProfileUI === 'function') updateProfileUI();
        const reward = doc.data().pendingReward;
        if (!reward || !reward.weekId) return;

        // 버튼 표시
        const btn = document.getElementById('last-week-reward-btn');
        if (btn) btn.style.display = 'flex';
    }).catch(err => console.warn('pendingReward 확인 실패:', err));
}

/* 보상 모달 열기 */
function openLastWeekRewardModal() {
    if (typeof db === 'undefined' || !db || !myTag) return;

    db.collection('leaderboard').doc(myTag).get({ source: 'server' }).then(doc => {
        if (!doc.exists) return;
        const reward = doc.data().pendingReward;
        if (!reward) return;

        _showLastWeekRewardModal(reward);
    }).catch(err => console.warn('보상 조회 실패:', err));
}

function _showLastWeekRewardModal(reward) {
    // 기존 모달 제거
    const old = document.getElementById('last-week-reward-modal');
    if (old) old.remove();

    const zionRank   = reward.zionRank;
    const tribeRank  = reward.tribeRank;
    const zionGems   = reward.zionGems  || 0;
    const tribeGems  = reward.tribeGems || 0;
    const totalGems  = reward.totalGems || 0;
    const score      = reward.score     || 0;
    const weekId     = reward.weekId    || '';
    const zionQ      = reward.zionQualified;
    const tribeQ     = reward.tribeQualified;

    // 순위 텍스트 생성
    function rankTxt(rank) {
        if (!rank) return null;
        return `${rank}위`;
    }

    // 보상 행 HTML
    function rewardRow(label, rank, gems, qualified) {
        if (!rank) return '';
        const gemText = qualified
            ? `<span style="color:#f1c40f; font-weight:bold;">+${gems}💎</span>`
            : `<span style="color:#95a5a6; font-size:0.85rem;">인원 미달 (보상 없음)</span>`;
        return `
            <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid rgba(255,255,255,0.08);">
                <div>
                    <div style="font-size:0.8rem; color:#95a5a6;">${label}</div>
                    <div style="font-size:1.5rem; font-weight:bold; color:white;">${rankTxt(rank)}</div>
                </div>
                <div style="text-align:right;">${gemText}</div>
            </div>`;
    }

    const noReward = totalGems === 0;
    const noRewardMsg = noReward ? `
        <div style="margin-top:12px; padding:10px; background:rgba(231,76,60,0.15); border-radius:8px; font-size:0.85rem; color:#e74c3c; text-align:center; line-height:1.5;">
            ${t('reward_no_reward_msg')}
        </div>` : '';

    const claimSection = noReward
        ? `<button onclick="closeLastWeekRewardModal()" style="margin-top:18px; width:100%; padding:12px; background:#7f8c8d; border:none; border-radius:10px; color:white; font-size:1rem; font-weight:bold; cursor:pointer;">${t('reward_confirm_btn')}</button>`
        : `<button onclick="claimWeeklyReward()" style="margin-top:18px; width:100%; padding:12px; background:linear-gradient(135deg,#f39c12,#e67e22); border:none; border-radius:10px; color:white; font-size:1rem; font-weight:bold; cursor:pointer;">${t('reward_claim_btn', { count: totalGems })}</button>`;

    const modal = document.createElement('div');
    modal.id = 'last-week-reward-modal';
    modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);z-index:10000;display:flex;justify-content:center;align-items:center;padding:20px;box-sizing:border-box;';
    modal.innerHTML = `
        <div style="background:#2c3e50;border:2px solid #f39c12;border-radius:18px;width:100%;max-width:360px;padding:24px;box-shadow:0 10px 40px rgba(0,0,0,0.9);">
            <div style="text-align:center; margin-bottom:16px;">
                <div style="font-size:2rem;">🏆</div>
                <div style="font-size:1.1rem; color:#f1c40f; font-weight:bold; margin-top:4px;">${t('reward_last_week_title')}</div>
                <div style="font-size:0.8rem; color:#95a5a6; margin-top:2px;">${weekId}</div>
                <div style="margin-top:8px; font-size:0.9rem; color:#bdc3c7;">${t('reward_score_label')} <strong style="color:white;">${score.toLocaleString()}</strong> pts</div>
            </div>
            ${rewardRow(t('label_zion_ranking'), zionRank, zionGems, zionQ)}
            ${rewardRow(t('label_my_tribe_ranking'), tribeRank, tribeGems, tribeQ)}
            ${(reward.readZionRank || reward.readTribeRank) ? `
            <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid rgba(255,255,255,0.08);">
                <div>
                    <div style="font-size:0.8rem; color:#95a5a6;">📖 ${t('ranking_tab_read')} · ${t('ranking_recall_unit', { n: (reward.readCount || 0).toLocaleString() })}</div>
                    <div style="font-size:1.05rem; font-weight:bold; color:white;">${reward.readTribeRank ? t('recall_reward_tribe', { rank: reward.readTribeRank }) : ''}${reward.readTribeRank && reward.readZionRank ? ' · ' : ''}${reward.readZionRank ? t('recall_reward_zion', { rank: reward.readZionRank }) : ''}</div>
                </div>
                <div style="text-align:right;"><span style="color:#f1c40f; font-weight:bold;">+${(reward.readGems || 0).toLocaleString()}💎</span></div>
            </div>` : ''}
            ${(reward.recallZionRank || reward.recallTribeRank) ? `
            <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid rgba(255,255,255,0.08);">
                <div>
                    <div style="font-size:0.8rem; color:#95a5a6;">🖊️ ${t('ranking_tab_recall')} · ${t('ranking_recall_unit', { n: (reward.recallCount || 0).toLocaleString() })}</div>
                    <div style="font-size:1.05rem; font-weight:bold; color:white;">${reward.recallTribeRank ? t('recall_reward_tribe', { rank: reward.recallTribeRank }) : ''}${reward.recallTribeRank && reward.recallZionRank ? ' · ' : ''}${reward.recallZionRank ? t('recall_reward_zion', { rank: reward.recallZionRank }) : ''}</div>
                </div>
                <div style="text-align:right;"><span style="color:#f1c40f; font-weight:bold;">+${(reward.recallGems || 0).toLocaleString()}💎</span></div>
            </div>` : ''}
            ${noRewardMsg}
            ${claimSection}
        </div>`;

    document.body.appendChild(modal);

    // 팡파레
    triggerConfetti();
    if (typeof SoundEffect !== 'undefined' && SoundEffect.playLevelUp) SoundEffect.playLevelUp();
}

function closeLastWeekRewardModal() {
    // 보상 없는 경우(확인 버튼) — pendingReward는 서버에서 삭제해 버튼도 숨김
    if (typeof db !== 'undefined' && db && myTag) {
        db.collection('leaderboard').doc(myTag).update({
            pendingReward: firebase.firestore.FieldValue.delete()
        }).catch(() => {});
    }
    const btn = document.getElementById('last-week-reward-btn');
    if (btn) btn.style.display = 'none';
    const modal = document.getElementById('last-week-reward-modal');
    if (modal) modal.remove();
}

function claimWeeklyReward() {
    if (typeof db === 'undefined' || !db || !myTag) return;

    // 서버에서 pendingReward 읽어 최종 확인 후 보석 지급 (캐시 우회)
    db.collection('leaderboard').doc(myTag).get({ source: 'server' }).then(doc => {
        if (!doc.exists) return;
        const reward = doc.data().pendingReward;
        if (!reward) return;

        const totalGems = reward.totalGems || 0;

        // 1. 서버 필드 삭제 먼저 (중복 수령 방지)
        return db.collection('leaderboard').doc(myTag).update({
            pendingReward: firebase.firestore.FieldValue.delete()
        }).then(() => {
            // 2. 보석 지급
            if (totalGems > 0) addGems(totalGems);

            // 3. UI 정리
            const btn = document.getElementById('last-week-reward-btn');
            if (btn) btn.style.display = 'none';
            const modal = document.getElementById('last-week-reward-modal');
            if (modal) modal.remove();
        });
    }).catch(err => {
        console.error('보상 수령 실패:', err);
        alert(t('alert_reward_error'));
    });
}

function goHome() {
    // 1. 모든 화면 숨기기
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));

    // 2. 홈 화면 켜기
    const homeScreen = document.getElementById('home-screen');
    if (homeScreen) {
        homeScreen.style.display = '';
        homeScreen.classList.add('active');
    }

    // 3. 성전 모습 업데이트
    updateCastleView();
    if (typeof renderHomeTodo === 'function') renderHomeTodo();   // 오늘 할 일 (9/30)


    // ★ [추가] 중요! 혹시 열려있을지 모르는 스테이지 시트(하얀 박스)를 닫아줌
    closeStageSheet();
    // 백버튼 표시 상태 갱신 (홈에서는 숨김)
    if (typeof updateBackButtonVisibility === 'function') updateBackButtonVisibility();
    // BGM 재생
    startBgm();
}

function goMap() {
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));

    const homeScreen = document.getElementById('home-screen');
    if (homeScreen) {
        homeScreen.style.display = '';
    }

    // ★ [수정] 동적으로 생성된 화면(도감 등) 제거
    const lifeBookScreen = document.getElementById('life-book-screen');
    if (lifeBookScreen) lifeBookScreen.remove();

    document.getElementById('map-screen').classList.add('active');
    if (typeof seasonTimerInterval !== 'undefined' && seasonTimerInterval) {
        clearInterval(seasonTimerInterval);
    }
    // ★ [추가] 맵으로 돌아올 때 맵 재렌더링 (보스 클리어 후 풀밭 배경 즉시 반영)
    if (typeof renderChapterMap === 'function') {
        renderChapterMap();
    }
    setTimeout(drawRiver, 50);
    // 백버튼 표시 상태 갱신 (맵에서는 숨김)
    if (typeof updateBackButtonVisibility === 'function') updateBackButtonVisibility();
    // ★ [추가] 맵으로 돌아올 때 리소스 UI 업데이트 (만나 수령 시 보석 반영)
    if (typeof updateResourceUI === 'function') updateResourceUI();
    // BGM 정지
    stopBgm();

    // ★ 여정 진입 직후라면(amenAndStartGame에서 예약됨) 복습 타이밍 팝업 1회 체크
    if (typeof maybeAutoShowReviewPopup === 'function') maybeAutoShowReviewPopup();

    // ★ 아멘 진입 직후라면 주간 랭킹 보상 자동 팝업 (복습 팝업보다 늦게)
    if (window._pendingRewardAutoPopup) {
        window._pendingRewardAutoPopup = false;
        setTimeout(() => {
            if (typeof openLastWeekRewardModal === 'function') openLastWeekRewardModal();
        }, 1500);
    }

    markOnboardStep('map');
    if (onboardPromise && !onboardPromise.shown) setTimeout(() => { if (document.getElementById('map-screen').classList.contains('active')) _showPromiseCard(); }, 900);   // 🌅 내일의 약속(첫 절 뒤 한 번)

    // ★ 첫 구절 안내 — 아직 아무것도 클리어하지 않은 신규 유저는 지도에서 헤매지 않도록
    // 1장 1절로 바로 데려간다. 한 번만 하고, 이후에는 평소처럼 지도가 나온다.
    if (window._pendingFirstStageStart) {
        window._pendingFirstStageStart = false;
        if (_shouldGuideFirstStage()) {
            try { localStorage.setItem('kingsRoad_firstStageGuided', '1'); } catch (e) {}
            setTimeout(() => {
                if (typeof startTraining === 'function') startTraining('1-1', 'full-new');
            }, 500); // 지도를 한 번 보여주고 넘어간다 (어디에 있는지 인지시키기)
        }
    }
}

/* 아직 첫 스테이지를 한 번도 깨지 않은 상태인가.
   기존 사용자에게 영향이 가지 않도록 온보딩 표식이 아니라 '클리어 기록이 전무한가'로 판단한다
   (표식은 이번 배포부터 쌓이므로, 그것만 보면 기존 사용자도 세션 초반에 걸린다). */
function _isPreFirstClear() {
    if (onboardStep === 'cleared') return false;
    const freeCount = Object.keys(stageMastery || {}).length;
    const kingsCount = Object.keys((typeof kingsRoadData !== 'undefined' && kingsRoadData.mastery) || {}).length;
    return freeCount === 0 && kingsCount === 0;
}

/* 첫 구절 안내 대상인가 — 자유여행이고, 클리어 기록이 전무하고, 아직 안내한 적 없을 때만 */
function _shouldGuideFirstStage() {
    if (activeMode !== 'free' && !(activeMode === 'kings' && kingsRoadData.stepHistory.length)) return false; // 왕의 길은 stepHistory 설정이 선행되어야 함(10/6 — 정해져 있으면 왕의 길도)
    try { if (localStorage.getItem('kingsRoad_firstStageGuided')) return false; } catch (e) {}
    const freeCount = Object.keys(stageMastery || {}).length;
    const kingsCount = Object.keys((typeof kingsRoadData !== 'undefined' && kingsRoadData.mastery) || {}).length;
    return freeCount === 0 && kingsCount === 0;
}

// 백버튼(돌아가기) 표시를 현재 활성 화면에 따라 제어
function updateBackButtonVisibility() {
    // 1) 우선 모든 btn-back 숨김 처리
    document.querySelectorAll('.btn-back').forEach(b => b.style.display = 'none');

    // 2) 현재 활성화된 화면 내부의 btn-back 만 보이게 함
    const active = document.querySelector('.screen.active');
    if (!active) return;
    active.querySelectorAll('.btn-back').forEach(b => b.style.display = 'inline-block');
}

// 화면에 돌아가기 버튼이 없으면 생성
function ensureBackButton(screen) {
    if (!screen) return;

    let footer = screen.querySelector('.button-area-static');
    if (!footer) {
        footer = document.createElement('div');
        footer.className = 'button-area-static';
        screen.appendChild(footer);
    }

    let btn = footer.querySelector('.btn-back');
    if (!btn) {
        btn = document.createElement('button');
        btn.className = 'btn-gray btn-back';
        btn.type = 'button';
        btn.textContent = t('btn_go_back');
        btn.onclick = goMap;
        footer.appendChild(btn);
    } else {
        btn.classList.add('btn-gray', 'btn-back');
        if (!btn.textContent || btn.textContent.trim() === '') {
            btn.textContent = t('btn_go_back');
        }
    }
}

/* ══════════════════════════════════════════════════════════════════════════
   새 예루살렘 — 보석으로 짓는 성 (2026-09-29, 설계: docs/새-예루살렘.md)
   지도 맨 위, 강의 근원. 위에서 내려다본 네모반듯한 성(21:16) · 벽옥 성곽(21:18) · 네 면에 셋씩 진주 문(21:13, 21) ·
   성곽을 받치는 열두 기초석(21:14, 19) — 놓기 전엔 평범한 돌, 놓으면 보석. 12시(북쪽 가운데)부터 시계 방향.
   보좌에서 강이 사방으로(22:1) — 남쪽 물줄기가 지도의 강이 되어 1장으로 이어진다(drawRiver의 시작점).
   기초석 = 보석 + 백지레벨 조건(그 레벨 이상인 절의 수). 보상 없음(승점·칭호 없이 짓는 것 자체) — 사용자 결정 9/29
   ══════════════════════════════════════════════════════════════════════════ */
const NJ_STONES = [
    // 색 = 지파 보석 색(TRIBE_DATA.glow) — 벽옥=베드로, 남보석=부산야고보 … 같은 보석은 앱 어디서나 같은 색 (9/29)
    { ko: '벽옥',   en: 'Jasper',       color: '#00a0e9' },
    { ko: '남보석', en: 'Sapphire',     color: '#1d2088' },
    { ko: '옥수',   en: 'Chalcedony',   color: '#59c3e1' },
    { ko: '녹보석', en: 'Emerald',      color: '#009651' },
    { ko: '홍마노', en: 'Sardonyx',     color: '#eb6120' },
    { ko: '홍보석', en: 'Carnelian',    color: '#d7005b' },
    { ko: '황옥',   en: 'Chrysolite',   color: '#fdd000' },
    { ko: '녹옥',   en: 'Beryl',        color: '#86cab6' },
    { ko: '담황옥', en: 'Topaz',        color: '#e39300' },
    { ko: '비취옥', en: 'Chrysoprase',  color: '#6FBA2C' },
    { ko: '청옥',   en: 'Jacinth',      color: '#005dac' },
    { ko: '자수정', en: 'Amethyst',     color: '#7f1084' },
];
// [백지레벨, 절 수, 보석] — 404절을 12등분, 앞 넷 Lv3 · 가운데 넷 Lv4 · 끝 넷 Lv5. 합계 900만
const NJ_REQ = [
    [3, 34, 200000], [3, 68, 300000], [3, 101, 400000], [3, 135, 500000],
    [4, 168, 600000], [4, 202, 700000], [4, 236, 800000], [4, 269, 900000],
    [5, 303, 1000000], [5, 337, 1100000], [5, 370, 1200000], [5, 404, 1300000],
];
const NJ_ORD_KO = ['첫째', '둘째', '셋째', '넷째', '다섯째', '여섯째', '일곱째', '여덟째', '아홉째', '열째', '열한째', '열두째'];
const NJ_ZONE_H = 330;

function _njName(k) { return currentLang === 'en' ? NJ_STONES[k].en : NJ_STONES[k].ko; }
function _njOrd(k) { return currentLang === 'en' ? `#${k + 1}` : NJ_ORD_KO[k]; }
/* 백지레벨이 lv 이상인 절의 수 */
function _njCount(lv) {
    if (typeof verseRecall === 'undefined' || !verseRecall) return 0;
    let n = 0;
    _allVerseIds().forEach(id => { const r = verseRecall[id]; if (r && (r.bx || 0) >= lv) n++; });
    return n;
}

/* 진주 — 연속 출석처럼 (2026-09-29 개정)
   한 주(월~일)에 백지로 한 절이라도 통과한 날이 5일 이상이면 진주 +1 (최대 12).
   5일을 못 채운 주가 지나면 -1 (0 아래로는 안 내려간다). 12개가 된 뒤에도 같다 — 지키는 만큼 문이 빛난다.
   진주 수는 저장하지 않고 njBlankDays에서 매번 계산한다(기기 병합이 날짜 합집합만으로 맞는다). 처음 기록한 주부터 센다 */
const NJ_PEARL_DAYS = 5;
function _njMonday(ds) {
    const [y, m, d] = ds.split('-').map(Number);
    const dt = new Date(y, m - 1, d);
    dt.setDate(dt.getDate() - ((dt.getDay() + 6) % 7));
    return dt;
}
function _njPearlCalc(days) {
    const today = _get6AMDayStr();
    const cnt = {}; let first = null;
    new Set(days || []).forEach(ds => {
        if (typeof ds !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(ds) || ds > today) return;
        const k = _getLocalDateStr(_njMonday(ds));
        cnt[k] = (cnt[k] || 0) + 1;
        if (!first || k < first) first = k;
    });
    const cur = _getLocalDateStr(_njMonday(today));
    const curDays = cnt[cur] || 0;
    if (!first) return { n: 0, curDays, curDone: false };
    let n = 0;
    const w = _njMonday(first);
    for (let i = 0; i < 2000; i++) {
        const k = _getLocalDateStr(w), c = cnt[k] || 0;
        if (k >= cur) { if (c >= NJ_PEARL_DAYS) n = Math.min(12, n + 1); break; }   // 이번 주는 채웠을 때만 센다(아직 안 끝났다)
        n = c >= NJ_PEARL_DAYS ? Math.min(12, n + 1) : Math.max(0, n - 1);
        w.setDate(w.getDate() + 7);
    }
    return { n, curDays, curDone: curDays >= NJ_PEARL_DAYS };
}
/* 날짜로 다시 계산. notify면 줄어든 것을 알린다(지난주를 못 채우고 돌아왔을 때) */
function _njRefreshPearls(notify) {
    const before = njPearls;
    const st = _njPearlCalc(njBlankDays);
    njPearls = st.n;
    if (st.n !== before) {
        if (notify && st.n < before) setTimeout(() => { if (typeof showMissionToast === 'function') showMissionToast(t('nj_pearl_lost'), `${njPearls} / 12`); }, 1500);
        try { saveGameData(); } catch (e) { }
    }
    return st;
}
function _njNoteBlankDay() {
    try {
        const day = _get6AMDayStr();
        if (!Array.isArray(njBlankDays)) njBlankDays = [];
        if (njBlankDays.includes(day)) return;
        njBlankDays.push(day);
        const before = njPearls;
        _njRefreshPearls(false);
        if (njPearls > before) {
            (njPearlLog = Array.isArray(njPearlLog) ? njPearlLog : []).push({ k: njPearls - 1, week: _getLocalDateStr(_njMonday(day)), at: Date.now() });
            setTimeout(() => {
                if (typeof showMissionToast === 'function') showMissionToast(t('nj_pearl_got'), `${njPearls} / 12`);
                if (document.getElementById('nj-zone') && typeof drawRiver === 'function') drawRiver();
            }, 1200);
        }
    } catch (e) { }
}

/* ══ 생명나무 열매 (2026-09-29) — docs/새-예루살렘.md 「생명나무 열매」 ══
   그달에 백지로 통과한 절 하나 = 열매 하나. 7일 뒤 익고, 익은 열매를 눌러 그 절을 백지로 써내면 먹는다 → 🍃 잎사귀 1장.
   못 쓰면 열매가 남고 하루 뒤 다시. 익은 뒤 30일이 지나면 떨어진다(벌 없음).
   먹기는 7일 이상 간격을 둔 백지 떠올리기라 연구 기록으로도 깨끗하다(일지 ctx 'fruit') */
const NJ_FRUIT_RIPE_MS = 7 * 86400000, NJ_FRUIT_FALL_MS = 37 * 86400000, NJ_FRUIT_RETRY_MS = 86400000;
// 열두 가지 열매 — 달마다 바뀐다(모양만 다르고 서열 없음). 첫 열매가 열린 2026년 9월 = 석류부터
const NJ_FRUIT_KINDS = [
    { ko: '석류', en: 'Pomegranate', color: '#d0383a' }, { ko: '무화과', en: 'Fig', color: '#9b4f8a' },
    { ko: '포도', en: 'Grape', color: '#5e3aa6' }, { ko: '감람', en: 'Olive', color: '#7a8c2e' },
    { ko: '대추야자', en: 'Date', color: '#a0522d' }, { ko: '금사과', en: 'Golden apple', color: '#ffc21a' },
    { ko: '살구', en: 'Almond', color: '#f7a58c' }, { ko: '뽕', en: 'Mulberry', color: '#4a1f45' },
    { ko: '합환채', en: 'Mandrake', color: '#ff8c42' }, { ko: '쥐엄', en: 'Carob', color: '#6b4423' },
    { ko: '참외', en: 'Melon', color: '#e3d35f' }, { ko: '호두', en: 'Walnut', color: '#b08a5a' },
];
// 나무 12그루 자리(3D 단위, 성 한 변 12) — 물길마다 보좌 가까이 오른쪽 둑 한 그루 + 문 쪽 양쪽 둑 한 쌍. nj3d.js도 이것을 쓴다
function _njTreeSpots() {
    const out = [];
    [[0, -1], [1, 0], [0, 1], [-1, 0]].forEach(([dx, dz]) => {
        const px = -dz, pz = dx;
        [[2.0, 1], [4.1, 1], [4.1, -1]].forEach(([d, sd]) => out.push([dx * d + px * 1.45 * sd, dz * d + pz * 1.45 * sd]));
    });
    return out;
}
function _njMonthKey(ts) { return (ts ? _tsTo6AMDateStr(ts) : _get6AMDayStr()).slice(0, 7); }
function _njFruitKind(m) { const [y, mo] = m.split('-').map(Number); const n = (y - 2026) * 12 + (mo - 9); return ((n % 12) + 12) % 12; }
function _njFruitName(kind) { const k = NJ_FRUIT_KINDS[kind] || NJ_FRUIT_KINDS[0]; return currentLang === 'en' ? k.en : k.ko; }
function _njVerseRef(id) { const [c, v] = String(id).split('-'); return t('nj_fruit_ref', { c, v }); }
/* 두 달보다 오래된 달은 잎사귀 수만 남기고 접는다(그 달 열매는 모두 떨어졌다 — 열린 뒤 37일) */
function _njFruitPrune() {
    const [y, mo] = _njMonthKey().split('-').map(Number);
    const cut = new Date(y, mo - 3, 1), cutKey = `${cut.getFullYear()}-${String(cut.getMonth() + 1).padStart(2, '0')}`;
    Object.keys(njFruits || {}).forEach(m => {
        if (m >= cutKey) return;
        let n = 0; Object.values(njFruits[m] || {}).forEach(f => { if (Array.isArray(f) && f[1]) n++; });
        njLeafArch[m] = Math.max(njLeafArch[m] | 0, n);
        delete njFruits[m];
    });
}
/* 잎사귀 = 먹은 열매 수 (달마다 접은 수와 남은 기록 중 큰 쪽 — 병합 뒤 겹쳐도 두 번 세지 않는다). 쓰는 곳(만국 소성)은 다음 단계 */
function _njLeaves() {
    const months = new Set([...Object.keys(njLeafArch || {}), ...Object.keys(njFruits || {})]);
    let n = 0;
    months.forEach(m => {
        let live = 0; Object.values((njFruits || {})[m] || {}).forEach(f => { if (Array.isArray(f) && f[1]) live++; });
        n += Math.max((njLeafArch || {})[m] | 0, live);
    });
    return n + (njGiftLeaves | 0);   // 🎁 나눔 열매로 받은 잎사귀 (서버 seaLeavesEarned도 같이)
}
function _njGrowFruit(id, now) {
    if (!/^\d+-\d+$/.test(String(id))) return;
    const m = _njMonthKey(now);
    if (!njFruits || typeof njFruits !== 'object') njFruits = {};
    const mm = njFruits[m] || (njFruits[m] = {});
    if (mm[id]) return;
    mm[id] = [now, 0, 0];
    _njFruitPrune();
}
/* 달린 열매(먹지 않았고 떨어지지 않은 것) — 달·절 순서. 3D·건축 창·지도가 함께 쓴다 */
function _njFruitList(now) {
    const n = now || Date.now(), out = [];
    const cmp = (a, b) => { const [a1, a2] = a.split('-').map(Number), [b1, b2] = b.split('-').map(Number); return a1 - b1 || a2 - b2; };
    Object.keys(njFruits || {}).sort().forEach(m => {
        const kind = _njFruitKind(m);
        Object.keys(njFruits[m] || {}).sort(cmp).forEach(id => {
            const f = njFruits[m][id];
            if (!Array.isArray(f) || f[1] || n >= f[0] + NJ_FRUIT_FALL_MS) return;
            const ripeAt = f[0] + NJ_FRUIT_RIPE_MS;
            out.push({ key: m + '|' + id, id, m, kind, ripe: n >= ripeAt, ripeAt, retryAt: f[2] ? f[2] + NJ_FRUIT_RETRY_MS : 0 });
        });
    });
    return out.slice(0, 408);
}
/* 먹기 — 3D·건축 창을 닫고 그 절 하나로 백지 세션을 연다 (결과 화면 '빈칸으로 확인해보기'와 같은 엔진, 단 이쪽은 진짜 백지) */
function njEatFruit(key) {
    const f = _njFruitList().find(x => x.key === key);
    if (!f || !f.ripe || (f.retryAt && Date.now() < f.retryAt)) return;
    if (typeof closeNJ3D === 'function') closeNJ3D();
    closeNewJerusalem();
    window.currentStageId = f.id;
    window.hardshipOrigin = 'map';
    selectedHardshipOrderType = 'sequential';
    selectedHardshipUltimate = true;
    _pendingHardshipEmbed = { label: t('nj_fruit_embed', { name: _njFruitName(f.kind) }), fruitKey: key };
    startHardshipSession('memory', [f.id]);
}
/* recordVerseRecall에서 — 열매 세션이면 먹었는지 판정 */
function _njFruitResult(key, id, ok, now) {
    const i = key.indexOf('|'), m = key.slice(0, i), fid = key.slice(i + 1);
    if (fid !== String(id)) return;
    const f = njFruits[m] && njFruits[m][fid];
    if (!Array.isArray(f) || f[1]) return;
    if (ok) {
        f[1] = now;
        setTimeout(() => { if (typeof showMissionToast === 'function') showMissionToast(t('nj_fruit_eaten'), `🍃 ${_njLeaves()}`); }, 1200);
    } else {
        f[2] = now;
        setTimeout(() => { if (typeof showToast === 'function') showToast(t('nj_fruit_fail')); }, 1200);
    }
}

/* ══ 생명수의 바다와 만국 (2026-09-30) — docs/새-예루살렘.md 「바다」 ══
   모두의 바다 하나(서버 sea/world). 💎 보석은 강 어귀에서부터 물칸을 맑히고(에스겔 47:3~5 발목·무릎·허리·헤엄칠 물),
   🍃 잎사귀는 해안의 70 나라(창 10장)를 소성한다. 나라는 바다가 차오른 단계까지만 자란다.
   드리기는 kingsroad 함수 seaGive만(규칙이 직접 쓰기를 막는다). 화면엔 단계마다 함께한 길드 이름(없으면 사람 이름) — 양·순위 없음 */
const SEA_CELL_COST = 200000, SEA_STAGES = [194, 929, 2000], SEA_LEAF_PER_LV = 50;   // 물가 · 얕은 바다 · 깊은 바다(누적 칸 수, 서버와 같게) — 10/5 전엔 250·500·1,000·2,000
