    const isl = _seaIsles().filter(s => vis(s.x)); if (isl.length) { const s = isl.reduce((a, b) => Math.abs(b.x - (x0 + F.span / 2)) < Math.abs(a.x - (x0 + F.span / 2)) ? b : a); lab(en ? 'Japheth' : '야벳', s.x, s.z + s.r + 4.5); }
    // 넘길 수 있다는 표시 — 양 끝 화살표
