function _seaGiftId() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 10); }
async function _seaGive(kind, amount, nation) {
    if (_seaBusy) return;
    if (kind === 'gem') {
        if ((myGems || 0) < amount) { showGemToast(0, t('sea_need_gems'), true); return; }
        if (!confirm(t('sea_confirm_gem', { n: amount.toLocaleString() }))) return;
    } else if (_njLeavesAvail() < 1) { showGemToast(0, t('sea_no_leaves'), true); return; }
    _seaBusy = kind + ':' + amount; _seaRender();   // 누른 버튼에 스피너 — 저장 올리기 + 서버 요청 두 번 왕복이라 1~3초 걸린다
    try {
        // 서버가 저장본의 보석·먹은 열매로 확인하므로 먼저 올린다
        saveGameData();
        try { await syncToFirestore(); } catch (e) { }
        const res = await _callGuildFn('seaGive', { kind, amount, nation: kind === 'leaf' ? nation : null, giftId: _seaGiftId() });
        if (kind === 'gem' && !res.dup) { myGems -= res.used; if (typeof updateGemDisplay === 'function') updateGemDisplay(); }
        seaGemsGiven = Math.max(seaGemsGiven, res.givenGems || 0);
        njLeafSpent = Math.max(njLeafSpent, res.spentLeaves || 0);
        saveGameData();
        if (typeof syncToFirestore === 'function') syncToFirestore();
        if (typeof SoundEffect !== 'undefined' && SoundEffect.playClear && (res.lvUp || res.stageUp != null)) SoundEffect.playClear();
        if (res.stageUp != null) showMissionToast(t('sea_stage_up', { name: SEA_STAGE_NAMES[currentLang === 'en' ? 'en' : 'ko'][res.stageUp] }), '🌊');
        else if (res.lvUp) showMissionToast(t('sea_nat_up', { name: currentLang === 'en' ? SEA_NATIONS[nation][2] : SEA_NATIONS[nation][0], lv: SEA_LV_NAMES[currentLang === 'en' ? 'en' : 'ko'][res.lvUp] }), '🍃');
        else showGemToast(0, kind === 'gem' ? t('sea_gave_gem') : t('sea_gave_leaf', { n: res.used, name: currentLang === 'en' ? SEA_NATIONS[nation][2] : SEA_NATIONS[nation][0] }));
        await _seaFetch(true);
        _seaBusy = ''; return res;
    } catch (e) {
        const msg = (e && e.message) ? e.message : '';
        showGemToast(0, msg || t('sea_fail'), true);
    } finally {
        _seaBusy = ''; _seaRender();
    }
}

/* 성을 그린다. 반환: 남쪽 가운데 문(지도의 강이 시작하는 곳)의 캔버스 좌표 */
/* opts.flow: 지도 — 물결은 따로 흐르는 SVG가 그리므로 캔버스엔 고정 물결을 그리지 않는다
   opts.south: 건축 창 — 지도의 큰 강이 없으니 남쪽 물줄기도 그린다 */
function _njDraw(cv, W, H, built, pearls, opts) {
    const O = opts || {};
    const dpr = Math.min(3, window.devicePixelRatio || 2);
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr); cv.style.width = W + 'px'; cv.style.height = H + 'px';
    const g = cv.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0);
    const lin = (x0, y0, x1, y1, st) => { const gr = g.createLinearGradient(x0, y0, x1, y1); st.forEach(([o, c]) => gr.addColorStop(o, c)); return gr; };
    const rad = (x, y, r, st) => { const gr = g.createRadialGradient(x, y, 0, x, y, r); st.forEach(([o, c]) => gr.addColorStop(o, c)); return gr; };
    const hex = (c, a) => { const n = parseInt(c.slice(1), 16); return `rgba(${n >> 16},${(n >> 8) & 255},${n & 255},${a})`; };
    const S = Math.min(W - 70, H - 46), cx = W / 2, cy = H / 2 - 4, h = S / 2;
    const FB = 14, WW = 8;
    const x0 = cx - h, y0 = cy - h, x1 = cx + h, y1 = cy + h;
    // 풀밭 + 성에서 번지는 은은한 빛
    g.fillStyle = '#27ae60'; g.fillRect(0, 0, W, H);
    g.fillStyle = rad(W * 0.2, H * 0.3, W * 0.45, [[0, 'rgba(46,204,113,0.9)'], [1, 'rgba(46,204,113,0)']]); g.fillRect(0, 0, W, H);
    g.fillStyle = rad(W * 0.8, H * 0.75, W * 0.45, [[0, 'rgba(30,132,73,0.9)'], [1, 'rgba(30,132,73,0)']]); g.fillRect(0, 0, W, H);
    g.fillStyle = rad(cx, cy, W * 0.62, [[0, 'rgba(255,246,215,0.55)'], [0.5, 'rgba(255,240,190,0.18)'], [1, 'rgba(255,240,190,0)']]); g.fillRect(0, 0, W, H);
    // 성 밖 물줄기 — 북·동·서 (남쪽은 지도의 강이 이어받는다)
    const outRiver = (ax, ay, bx, by) => {
        g.lineCap = 'butt';
        g.strokeStyle = 'rgba(93,64,55,0.35)'; g.lineWidth = 34; g.beginPath(); g.moveTo(ax, ay); g.lineTo(bx, by); g.stroke();
        g.strokeStyle = 'rgba(0,188,212,0.88)'; g.lineWidth = 22; g.beginPath(); g.moveTo(ax, ay); g.lineTo(bx, by); g.stroke();
        if (!O.flow) {
            g.strokeStyle = 'rgba(210,248,255,0.55)'; g.lineWidth = 1.6; g.setLineDash([14, 12]);
            [-5, 4].forEach(o => { const vx = ax === bx; g.beginPath(); g.moveTo(ax + (vx ? o : 0), ay + (vx ? 0 : o)); g.lineTo(bx + (vx ? o : 0), by + (vx ? 0 : o)); g.stroke(); });
            g.setLineDash([]);
        }
    };
    outRiver(cx, y0, cx, 0); outRiver(x1, cy, W, cy); outRiver(x0, cy, 0, cy);
    if (O.south) outRiver(cx, y1, cx, H);
    // 기초석 열두 조각 — 12시부터 시계 방향. 놓기 전엔 빈 터(점선), 놓으면 보석 돌이 새로 놓인다 (3D 시안과 같게, 9/29)
    const seq = [['N', 1], ['N', 2], ['E', 0], ['E', 1], ['E', 2], ['S', 2], ['S', 1], ['S', 0], ['W', 2], ['W', 1], ['W', 0], ['N', 0]];
    const L = S / 3;
    // 북쪽 면 기준 조각 모양(모서리는 액자처럼 45도로 잘라 이웃과 반씩) → 면마다 돌린다. 화면 좌표(아래가 +y)
    const segPoly = (side, i) => {
        const idx = (side === 'S' || side === 'W') ? 2 - i : i;
        const ox0 = -h + idx * L, ox1 = ox0 + L, gap = 0.8;
        const a = idx === 0 ? -h + gap : ox0 + gap, b = idx === 2 ? h - gap : ox1 - gap;
        const ai = idx === 0 ? -h + FB + gap : ox0 + gap, bi = idx === 2 ? h - FB - gap : ox1 - gap;
        const pts = [[a, -h], [b, -h], [bi, -h + FB], [ai, -h + FB]];
        const rot = side === 'N' ? (p) => p : side === 'E' ? ([x, y]) => [-y, x] : side === 'S' ? ([x, y]) => [-x, -y] : ([x, y]) => [y, -x];
        return pts.map(p => { const [rx, ry] = rot(p); return [cx + rx, cy + ry]; });
    };
    const path = (pts) => { g.beginPath(); g.moveTo(pts[0][0], pts[0][1]); pts.slice(1).forEach(([px, py]) => g.lineTo(px, py)); g.closePath(); };
    // 성 안 — 맑은 유리 같은 정금, 문과 문을 잇는 정금 길 (성곽은 다음 단계라 아직 없다)
    const ix0 = x0 + FB, iy0 = y0 + FB, ix1 = x1 - FB, iy1 = y1 - FB;
    g.fillStyle = lin(ix0, iy0, ix1, iy1, [[0, 'rgba(255,226,140,0.95)'], [0.5, 'rgba(255,240,190,0.95)'], [1, 'rgba(245,205,110,0.95)']]); g.fillRect(ix0, iy0, ix1 - ix0, iy1 - iy0);
    g.strokeStyle = 'rgba(255,255,255,0.5)'; g.lineWidth = 3;
    [0.25, 0.75].forEach(tt => { const a = x0 + S * tt, b = y0 + S * tt;
        g.beginPath(); g.moveTo(a, iy0); g.lineTo(a, iy1); g.stroke(); g.beginPath(); g.moveTo(ix0, b); g.lineTo(ix1, b); g.stroke(); });
    g.fillStyle = rad(cx, cy, S * 0.42, [[0, 'rgba(255,255,255,1)'], [0.18, 'rgba(255,252,235,0.95)'], [0.5, 'rgba(255,240,190,0.4)'], [1, 'rgba(255,240,190,0)']]); g.fillRect(ix0, iy0, ix1 - ix0, iy1 - iy0);
    // 기초석
    seq.forEach(([side, i], k) => {
        const pts = segPoly(side, i);
        if (k < built) {
            const col = NJ_STONES[k].color;
            const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]);
            g.fillStyle = lin(Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys), [[0, hex(col, 1)], [1, hex(col, 0.78)]]);
            path(pts); g.fill();
            g.strokeStyle = 'rgba(255,255,255,0.55)'; g.lineWidth = 1; g.beginPath(); g.moveTo(pts[0][0], pts[0][1]); g.lineTo(pts[1][0], pts[1][1]); g.stroke();   // 윤기
        } else {
            g.strokeStyle = 'rgba(255,255,255,0.55)'; g.lineWidth = 1; g.setLineDash([3, 3]); path(pts); g.stroke(); g.setLineDash([]);
        }
    });
    // 보좌에서 사방으로 흐르는 강 — 네 면의 가운데 문으로 나간다
    const rw = 18;
    [[cx, y1], [cx, y0], [x1, cy], [x0, cy]].forEach(([tx, ty]) => {
        const vx = tx === cx, a = rw * 0.3, b = rw / 2;
        g.fillStyle = lin(cx, cy, tx, ty, [[0, 'rgba(160,240,255,0.95)'], [1, 'rgba(0,188,212,0.95)']]);
        g.beginPath();
        if (vx) { g.moveTo(cx - a, cy); g.lineTo(cx + a, cy); g.lineTo(tx + b, ty); g.lineTo(tx - b, ty); }
        else { g.moveTo(cx, cy - a); g.lineTo(cx, cy + a); g.lineTo(tx, ty + b); g.lineTo(tx, ty - b); }
        g.closePath(); g.fill();
    });
    g.fillStyle = 'rgba(255,255,255,0.95)'; g.beginPath(); g.arc(cx, cy, 7, 0, Math.PI * 2); g.fill();   // 보좌
    // 생명나무 12그루 (22:2) — 익은 열매가 있으면 그달 열매 색 점
    {
        const U = S / 12, FL = _njFruitList(), ripeCol = FL.some(f => f.ripe) ? NJ_FRUIT_KINDS[FL.find(f => f.ripe).kind].color : null;
        const green = FL.length && !ripeCol, redN = (typeof guideInfo !== 'undefined' && guideInfo && guideInfo.grads) || 0;
        _njTreeSpots().forEach(([tx, tz], ti) => {
            const px = cx + tx * U, py = cy + tz * U, r = Math.max(3, 0.55 * U);
            g.fillStyle = 'rgba(0,0,0,0.18)'; g.beginPath(); g.arc(px + 1, py + 1.5, r, 0, Math.PI * 2); g.fill();
            g.fillStyle = '#2f8f4e'; g.beginPath(); g.arc(px, py, r, 0, Math.PI * 2); g.fill();
            g.fillStyle = 'rgba(255,255,255,0.18)'; g.beginPath(); g.arc(px - r * 0.3, py - r * 0.3, r * 0.45, 0, Math.PI * 2); g.fill();
            if (ripeCol || green) {
                g.fillStyle = ripeCol || '#b5e07a';
                [[0.35, -0.2], [-0.3, 0.3], [0.1, 0.45]].forEach(([ox, oy]) => { g.beginPath(); g.arc(px + ox * r, py + oy * r, Math.max(1.2, r * 0.2), 0, Math.PI * 2); g.fill(); });
            }
            // 🍎 함께 정착한 사람 — 빨간 열매(달마다 바뀌지 않는다). 12그루에 돌아가며, 한 나무에 3개까지 보인다
            const RN = Math.min(3, Math.floor(redN / 12) + (ti < redN % 12 ? 1 : 0)), rr = Math.max(2.2, r * 0.36);
            [[-0.5, -0.3], [0.52, 0.22], [-0.05, -0.68]].slice(0, RN).forEach(([ox, oy]) => {
                const fx = px + ox * r, fy = py + oy * r;
                g.fillStyle = '#5a0a10'; g.beginPath(); g.arc(fx, fy, rr + 0.9, 0, Math.PI * 2); g.fill();   // 잎에 묻히지 않게 짙은 테
                g.fillStyle = '#e0202c'; g.beginPath(); g.arc(fx, fy, rr, 0, Math.PI * 2); g.fill();
                g.fillStyle = 'rgba(255,255,255,0.7)'; g.beginPath(); g.arc(fx - rr * 0.35, fy - rr * 0.35, rr * 0.32, 0, Math.PI * 2); g.fill();
            });
        });
    }
    // 진주 문 — 한 면에 1/4 · 1/2 · 3/4 (모서리에 몰리지 않게). 얻은 진주만큼 12시부터 시계 방향으로 얹힌다
    const gateAt = (side, i) => { const tt = [0.25, 0.5, 0.75][i], m = FB / 2;
        return side === 'N' ? [x0 + S * tt, y0 + m] : side === 'S' ? [x0 + S * tt, y1 - m] : side === 'W' ? [x0 + m, y0 + S * tt] : [x1 - m, y0 + S * tt]; };
    seq.forEach(([side, i], k) => {
        const [gx, gy] = gateAt(side, i);
        if (k < (pearls || 0)) {
            g.strokeStyle = 'rgba(255,255,255,0.97)'; g.lineWidth = 3.6; g.beginPath(); g.arc(gx, gy, 8.5, 0, Math.PI * 2); g.stroke();
            g.strokeStyle = 'rgba(190,178,225,0.9)'; g.lineWidth = 0.9; g.beginPath(); g.arc(gx, gy, 10.4, 0, Math.PI * 2); g.stroke();
            g.fillStyle = 'rgba(255,255,255,1)'; g.beginPath(); g.arc(gx - 5, gy - 5, 1.6, 0, Math.PI * 2); g.fill();
        } else {   // 진주가 얹힐 자리
            g.strokeStyle = 'rgba(255,255,255,0.5)'; g.lineWidth = 1; g.setLineDash([2.5, 2.5]);
            g.beginPath(); g.arc(gx, gy, 8.5, 0, Math.PI * 2); g.stroke(); g.setLineDash([]);
        }
    });
    return { x: cx, y: y1, cx, cy, x0, x1, y0, y1 };
}

/* 지도 맨 위 성 구역. 누르면 건축 창 */
function _njZoneEl() {
    const zone = document.createElement('div');
    zone.className = 'zone-wrapper nj-zone';
    zone.id = 'nj-zone';
    zone.innerHTML = '<canvas class="nj-map-canvas"></canvas>';
    // 성(가로 15~85%, 세로 7~93%) 바깥에만 — 성 안에 꽃이 겹쳐 진주를 가렸다
    [[5, 9, '🌸'], [92, 8, '🌼'], [4, 30, '🌿'], [94, 28, '🌷'], [4, 72, '🌺'], [94, 74, '🌷'], [7, 90, '🌻'], [91, 90, '🌹'], [16, 97, '🌸'], [82, 97, '🌼']]
        .forEach(([x, y, e], i) => { const f = document.createElement('span'); f.className = 'garden-flower'; f.textContent = e;
            f.style.cssText = `left:${x}%;top:${y}%;font-size:${0.85 + (i % 3) * 0.15}rem;animation-delay:${(i * 0.37) % 2}s`; zone.appendChild(f); });
    zone.onclick = () => openNewJerusalem();
    return zone;
}
/* 성을 다시 그리고, 지도 강이 시작할 점을 컨테이너 좌표로 돌려준다 (drawRiver가 부른다) */
function _njRiverStart(containerRect, scrollTop) {
    const zone = document.getElementById('nj-zone');
    const cv = zone && zone.querySelector('canvas');
    if (!zone || !cv) return null;
    const W = zone.clientWidth || containerRect.width;
    if (!W) return null;
    _njRefreshPearls(true);
    const gate = _njDraw(cv, W, NJ_ZONE_H, njBuilt, njPearls, { flow: true });
    _njFlowSvg(zone, W, NJ_ZONE_H, gate);
    const zr = zone.getBoundingClientRect();
    return { x: (zr.left - containerRect.left) + gate.x, y: (zr.top - containerRect.top) + scrollTop + gate.y };
}

/* 성 둘레·성 안 물결이 흐른다 (2026-09-29) — 지도 큰 강과 같은 물결 가닥(RIVER_STRANDS)·같은 시계(_riverFlowTick).
   캔버스를 다시 그리지 않고 얇은 SVG 선만 옮긴다. _buildRiverFlow가 관찰을 붙여 보이는 동안만 흐른다 */
function _njFlowSvg(zone, W, H, gm) {
    const old = zone.querySelector('.nj-flow'); if (old) old.remove();
    const NS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('class', 'nj-flow');
    svg.setAttribute('width', W); svg.setAttribute('height', H);
    svg._paths = [];
    const add = (ax, ay, bx, by, scale, strands) => {
        const vert = ax === bx;
        strands.forEach(k => {
            const st = RIVER_STRANDS[k], o = st.ox * scale;
            const p = document.createElementNS(NS, 'path');
            p.setAttribute('class', `river-hl river-hl-${k + 1}`);
            p.setAttribute('d', vert ? `M ${ax + o} ${ay} L ${bx + o} ${by}` : `M ${ax} ${ay + o} L ${bx} ${by + o}`);
            svg.appendChild(p);
            svg._paths.push({ el: p, base: 0, st });
        });
    };
    const { cx, cy, x0, x1, y0, y1 } = gm;
    // 성 밖 — 북·동·서로 흘러 나간다 (남쪽은 지도의 큰 강)
    add(cx, y0, cx, 0, 0.62, [0, 1, 2, 3]); add(x1, cy, W, cy, 0.62, [0, 1, 2, 3]); add(x0, cy, 0, cy, 0.62, [0, 1, 2, 3]);
    // 성 안 — 보좌에서 네 문으로
    [[cx, y1], [cx, y0], [x1, cy], [x0, cy]].forEach(([tx, ty]) => add(cx, cy, tx, ty, 0.3, [1, 2]));
    const zc = zone.querySelector('canvas'); zc.after(svg);
}

function openNewJerusalem() {
    const old = document.getElementById('nj-modal'); if (old) old.remove();
    const m = document.createElement('div');
    m.id = 'nj-modal';
    m.onclick = (e) => { if (e.target === m) closeNewJerusalem(); };
    m.innerHTML = `<div class="nj-card">
        <div class="nj-head"><b>${t('nj_title')}</b><button class="nj-x" onclick="closeNewJerusalem()">✕</button></div>
        <div class="nj-verse">${t('nj_verse')}</div>
        <canvas id="nj-canvas"></canvas>
        <button class="nj-3d-btn" onclick="openNJ3DView()">${t('nj3d_btn')}</button>
        <div class="nj-sub">${t('nj_hint')}</div>
        <div class="nj-gems">💎 ${Number(myGems || 0).toLocaleString()} · 🍃 ${_njLeavesAvail()}</div>
        <div class="nj-go" id="nj-go"></div>
        <div class="nj-pearl" id="nj-pearl"></div>
        <div class="nj-pearl nj-fruit" id="nj-fruit"></div>
        <div class="nj-list" id="nj-list"></div>
    </div>`;
    document.body.appendChild(m);
    _njRenderModal();
}
/* 3D 보기 — nj3d.js를 처음 누를 때만 불러온다(three.js도 그때). 캐시 번호는 game.js와 같게 */
let _nj3dLoading = false;
function openNJ3DView(opts) {
    if (typeof window.openNJ3D === 'function') { window.openNJ3D(opts); return; }
    if (_nj3dLoading) return;
    _nj3dLoading = true;
    const gs = document.querySelector('script[src*="game.js"]');
    const ver = gs && /[?&]v=([^&]+)/.test(gs.src) ? RegExp.$1 : String(Date.now());
    const sc = document.createElement('script');
    sc.src = `nj3d.js?v=${ver}`;
    sc.onload = () => { _nj3dLoading = false; if (typeof window.openNJ3D === 'function') window.openNJ3D(opts); };
    sc.onerror = () => { _nj3dLoading = false; showGemToast(0, t('nj3d_fail'), true); };
    document.head.appendChild(sc);
}
function closeNewJerusalem() { const m = document.getElementById('nj-modal'); if (m) m.remove(); }
function _njRenderModal() {
    const cv = document.getElementById('nj-canvas'), list = document.getElementById('nj-list');
    if (!cv || !list) return;
    const par = cv.parentElement, pcs = getComputedStyle(par);
    const W = Math.floor(par.clientWidth - parseFloat(pcs.paddingLeft) - parseFloat(pcs.paddingRight));   // 창 안쪽 여백을 뺀 폭
    _njDraw(cv, W, Math.round(W * 0.82), njBuilt, njPearls, { south: true });
    const gemsEl = document.querySelector('#nj-modal .nj-gems'); if (gemsEl) gemsEl.textContent = `💎 ${Number(myGems || 0).toLocaleString()} · 🍃 ${_njLeavesAvail()}${guideInfo && guideInfo.grads ? ` · 🍎 ${guideInfo.grads}` : ''}`;   // 잎사귀도 여기서 쓴다(바다와 만국)
    const pst = _njRefreshPearls(false);
    const ge = document.getElementById('nj-go');
    if (ge) ge.innerHTML = _njGoHtml(pst);
    const pe = document.getElementById('nj-pearl');
    if (pe) {
        const d = Math.min(NJ_PEARL_DAYS, pst.curDays);
        const dots = Array.from({ length: NJ_PEARL_DAYS }, (_, i) => `<span class="nj-pd${i < d ? ' on' : ''}"></span>`).join('');
        pe.innerHTML = `<div class="nj-pearl-head">${t('nj_pearl_title', { n: njPearls })}</div>
            <div class="nj-pearl-week">${pst.curDone ? t('nj_pearl_done_week') : `${t('nj_pearl_week', { d })} ${dots}`}</div>
            <div class="nj-pearl-rule">${t('nj_pearl_rule')}</div>`;
    }
    const fe = document.getElementById('nj-fruit');
    if (fe) {
        const L = _njFruitList(), ripe = L.filter(f => f.ripe).length;
        fe.innerHTML = `<div class="nj-pearl-head">${t('nj_fruit_title', { leaves: _njLeaves() })}</div>
            <div class="nj-pearl-week">${t('nj_fruit_now', { name: _njFruitName(_njFruitKind(_njMonthKey())), n: L.length, ripe })}</div>
            ${ripe ? `<button class="nj-go-btn" onclick="openNJ3DView()">${t('nj_fruit_go', { n: ripe })}</button>` : ''}
            <button class="nj-go-btn sub" onclick="closeNewJerusalem(); openSea()">${t('sea_open_from_nj', { n: _njLeavesAvail() })}</button>
            <div class="nj-pearl-rule">${t('nj_fruit_rule')}</div>`;
    }
    const counts = {}; [3, 4, 5].forEach(lv => { counts[lv] = _njCount(lv); });
    list.innerHTML = NJ_STONES.map((st, k) => {
        const [lv, need, cost] = NJ_REQ[k];
        const head = `<span class="nj-dot" style="background:${k < njBuilt ? st.color : '#a0957f'}"></span><span class="nj-name">${_njOrd(k)} · ${_njName(k)}</span>`;
        if (k < njBuilt) {
            const rec = (njLog || []).find(e => e && e.k === k);
            const d = rec && rec.at ? _tsTo6AMDateStr(rec.at).slice(5).replace('-', '/') : '';
            return `<div class="nj-row built">${head}<span class="nj-state">${d ? t('nj_built_on', { date: d }) : '✓'}</span></div>`;
        }
        const have = counts[lv], okV = have >= need, okG = (myGems || 0) >= cost;
        const cond = t('nj_cond', { lv, have: Math.min(have, need), need });
        if (k === njBuilt) {
            let why = !okV ? t('nj_need_verses', { n: need - have }) : (!okG ? t('nj_need_gems', { n: (cost - myGems).toLocaleString() }) : '');
            if (!okV) {   // 한 칸 아래에서 차례를 기다리는 절 — 기다림이 고장처럼 보이지 않게
                let soon = 0, first = Infinity;
                _allVerseIds().forEach(id => { const r = verseRecall[id]; if (r && r.bx === lv - 1) { soon++; if (r.bxDue && r.bxDue < first) first = r.bxDue; } });
                if (soon) why += `<br>${t('nj_soon', { from: lv - 1, lv, n: soon, date: first <= Date.now() ? t('nj_today') : _njDayLabel(first) })}`;
            }
            return `<div class="nj-row next">${head}
                <div class="nj-detail"><span class="${okV ? 'ok' : ''}">${cond}</span><span class="${okG ? 'ok' : ''}">💎 ${cost.toLocaleString()}</span></div>
                <button class="nj-place" ${okV && okG ? '' : 'disabled'} onclick="_njPlace(${k})">${t('nj_place')}</button>
                ${why ? `<div class="nj-why">${why}</div>` : ''}</div>`;
        }
        return `<div class="nj-row locked">${head}<span class="nj-state">${cond} · 💎 ${cost.toLocaleString()}</span></div>`;
    }).join('') + (njBuilt >= 12 ? `<div class="nj-done">${t('nj_all_done')}</div>` : '');
}
/* 건축 창 바로 가기 — ① 오늘 백지 차례가 있으면 그 장으로 ② 없으면 다음 차례 날짜(+오늘 진주 날을 아직 안 채웠으면 쓰러 가기) ③ 백지 기록이 없으면 첫 백지로 */
function _njDayLabel(ts) {
    const ds = _tsTo6AMDateStr(ts), [y, m, d] = ds.split('-').map(Number);
    const wd = new Date(y, m - 1, d).getDay();
    return currentLang === 'en' ? `${m}/${d} (${['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][wd]})` : `${m}/${d}(${'일월화수목금토'[wd]})`;
}
function _njGoHtml(pst) {
    const due = _blankDueIds();
    if (due.length) {
        const ch = Math.min(...due.map(id => parseInt(id.split('-')[0], 10)));
        return `<button class="nj-go-btn" onclick="closeNewJerusalem(); openBlankDueScreen()">${t('nj_go_due', { n: due.length })}</button>`;
    }
    const lastCh = parseInt(String(lastPlayedStageId || '1').split('-')[0], 10) || 1;
    const write = `<button class="nj-go-btn sub" onclick="_njGo(${lastCh})">${t('nj_go_write')}</button>`;
    let next = Infinity;
    for (const id in (verseRecall || {})) { const r = verseRecall[id]; if (r && r.bx && r.bxDue && r.bxDue < next) next = r.bxDue; }
    if (next === Infinity) return `<div class="nj-go-note">${t('nj_go_first')}</div>${write}`;
    const nd = _tsTo6AMDateStr(next);
    let n = 0;
    for (const id in verseRecall) { const r = verseRecall[id]; if (r && r.bx && r.bxDue && _tsTo6AMDateStr(r.bxDue) === nd) n++; }
    const today = (njBlankDays || []).includes(_get6AMDayStr());
    return `<div class="nj-go-note">${t('nj_go_none', { date: _njDayLabel(next), n })}</div>${today ? '' : write}`;
}
function _njGo(ch) {
    closeNewJerusalem();
    if (typeof openStageSheetForStageId === 'function') openStageSheetForStageId(`${ch}-1`);
}
function _njPlace(k) {
    if (k !== njBuilt || k >= 12) return;
    const [lv, need, cost] = NJ_REQ[k];
    const have = _njCount(lv);
    if (have < need || (myGems || 0) < cost) { _njRenderModal(); return; }
    if (!confirm(t('nj_confirm', { cost: cost.toLocaleString(), name: _njName(k) }))) return;
    myGems -= cost;
    njBuilt = k + 1;
    // 연구 기록 — 놓는 순간의 백지레벨 분포와 백지로 써낸 절 수
    const dist = [0, 0, 0, 0, 0, 0]; let blank = 0;
    _allVerseIds().forEach(id => { const r = verseRecall[id]; if (!r) return; dist[Math.min(5, r.bx || 0)]++; if (r.blankPass > 0 || r.bx > 0) blank++; });
    (njLog = Array.isArray(njLog) ? njLog : []).push({ k, at: Date.now(), gems: cost, bx: dist, blank });
    if (typeof updateGemDisplay === 'function') updateGemDisplay();
    saveGameData();
    if (typeof syncToFirestore === 'function') syncToFirestore();
    if (typeof SoundEffect !== 'undefined' && SoundEffect.playClear) SoundEffect.playClear();
    if (typeof showMissionToast === 'function') showMissionToast(t('nj_placed_toast', { name: _njName(k) }), njBuilt >= 12 ? t('nj_all_done') : `${njBuilt} / 12`);
    _njRenderModal();
    if (document.getElementById('nj-zone') && typeof drawRiver === 'function') drawRiver();
}

/* [시스템: 맵 렌더링 (레이어 완벽 분리 버전)] */
function renderChapterMap() {
    const container = document.getElementById('chapter-list-area');

    // ★ 왕의 길이면 헤더 첫 줄에 「👑 N단계」 칩 (2026-09-17 — 지도 위 카드를 없애고 이 칩 하나로)
    updateKingsStepChip();

    // 마지막 플레이 챕터 (진입 시점 기록 기준)
    let lastPlayedChapterId = null;
    if (lastPlayedStageId) {
        const m = String(lastPlayedStageId).match(/^(\d+)/);
        if (m) lastPlayedChapterId = parseInt(m[1]);
    }

    // 1. 컨테이너 초기화
    container.className = 'river-map-container';
    container.innerHTML = `
        <div id="map-land-area"></div> <svg id="river-svg">
            <path id="river-bank"  class="river-bank"  d="" />
            <path id="river-path"  class="river-path"  d="" />
        </svg>
        <div id="river-flow-layer"></div>
    `;

    const landArea = document.getElementById('map-land-area');

    // 화면에 들어온 장만 꽃·풀·열매가 흔들린다 (2026-09-28) — 다시 그릴 때마다 옛 관찰자는 끊는다
    if (window._mapSwayObserver) { try { window._mapSwayObserver.disconnect(); } catch (e) { } }
    window._mapSwayObserver = (typeof IntersectionObserver !== 'undefined')
        ? new IntersectionObserver(entries => {
            entries.forEach(en => en.target.classList.toggle('in-view', en.isIntersecting));
        }, { rootMargin: '40px 0px' })
        : null;

    // 새 예루살렘 — 지도 맨 위, 강의 근원 (2026-09-29)
    {
        const nz = _njZoneEl();
        landArea.appendChild(nz);
        if (window._mapSwayObserver) window._mapSwayObserver.observe(nz);
    }

    // 2. 챕터별 구역 생성
    gameData.forEach((chapter, index) => {
        // A. 상태 확인
        const bossId = `${chapter.id}-boss`;
        const isChapterClear = stageMastery[bossId] > 0;

        const lastTime = stageLastClear[`chapter-${chapter.id}`] || 0;

        // B. 껍데기 (Wrapper) 생성
        const wrapper = document.createElement('div');
        wrapper.className = 'zone-wrapper';
        if (index % 2 === 0) wrapper.classList.add('left');
        else wrapper.classList.add('right');

        // C. 배경 (Land Background) 생성
        const bg = document.createElement('div');
        let bgClass = 'land-bg barren';
        if (isChapterClear) {
            bgClass = 'land-bg garden';
        }
        bg.className = bgClass;

        // 황무지 마른 풀 장식 (장별 산발 배치)
        if (!isChapterClear) {
            const grassBase = [
                { x: 10, y: 10, s: 1.0, d: 0.0 },
                { x: 72, y: 20, s: 0.8, d: 1.2 },
                { x: 38, y: 15, s: 0.9, d: 0.5 },
                { x: 85, y: 60, s: 0.75,d: 1.8 },
                { x: 20, y: 70, s: 0.85,d: 0.9 },
                { x: 55, y: 75, s: 1.0, d: 2.1 },
                { x: 88, y: 82, s: 0.8, d: 0.3 },
            ];
            const seed = chapter.id;
            grassBase.forEach((f, i) => {
                const ox = ((seed * 17 + i * 31) % 22) - 11; // -11~+11
                const oy = ((seed * 13 + i * 23) % 18) - 9;  // -9~+9
                const x = Math.max(5, Math.min(90, f.x + ox));
                const y = Math.max(5, Math.min(85, f.y + oy));
                const span = document.createElement('span');
                span.className = 'barren-grass';
                span.textContent = '🌾';
                span.style.cssText = `left:${x}%;top:${y}%;font-size:${f.s}rem;animation-delay:${f.d}s`;
                bg.appendChild(span);
            });
        }

        // 풀밭 꽃 장식 (장별 산발 배치)
        if (isChapterClear) {
            const flowerBase = [
                { e: '🌸', x:  8, y: 12, s: 1.1, d: 0.0 },
                { e: '🌼', x: 78, y: 18, s: 0.9, d: 0.7 },
                { e: '🌺', x: 42, y:  8, s: 1.0, d: 1.4 },
                { e: '🌿', x: 15, y: 62, s: 0.85,d: 0.3 },
                { e: '🌷', x: 85, y: 55, s: 1.0, d: 1.8 },
                { e: '🌻', x: 58, y: 72, s: 0.95,d: 0.9 },
                { e: '🌹', x: 28, y: 80, s: 0.8, d: 2.2 },
                { e: '🌸', x: 90, y: 80, s: 0.9, d: 1.1 },
            ];
            const seed = chapter.id;
            flowerBase.forEach((f, i) => {
                const ox = ((seed * 19 + i * 37) % 22) - 11; // -11~+11
                const oy = ((seed * 11 + i * 29) % 18) - 9;  // -9~+9
                const x = Math.max(5, Math.min(90, f.x + ox));
                const y = Math.max(5, Math.min(85, f.y + oy));
                const span = document.createElement('span');
                span.className = 'garden-flower';
                span.textContent = f.e;
                span.style.cssText = `left:${x}%;top:${y}%;font-size:${f.s}rem;animation-delay:${f.d}s`;
                bg.appendChild(span);
            });
        }

        // D. 나무 버튼 (Node) 생성
        const node = document.createElement('div');
        let statusClass = chapter.locked ? 'locked' : 'unlocked';
        if (isChapterClear) statusClass = 'completed';

        node.className = `stage-node ${statusClass}`;
        node.id = `node-${index}`;
        const isLastPlayedChapter = lastPlayedChapterId !== null && chapter.id === lastPlayedChapterId;
        if (isLastPlayedChapter) node.classList.add('last-played-chapter');

        // 아이콘 결정
        let iconChar = "🌱";
        let fruitHTML = "";

        if (!chapter.locked) iconChar = "🌳";

        if (isChapterClear) {
            iconChar = "🌳";
            fruitHTML = `
                <div class="fruit-cluster">
                    <span class="fruit f1">🍎</span>
                    <span class="fruit f2">🍒</span>
                    <span class="fruit f3">🍎</span>
                    <span class="fruit f4">✨</span>
                </div>
            `;
        }

        node.innerHTML = `
            ${_mapBlankRingHtml(chapter)}
            <div class="tree-icon">
                ${iconChar}
                ${fruitHTML}
            </div>
            <div class="stage-label">${t('label_chapter_header', { num: chapter.id })}</div>
            ${isLastPlayedChapter ? '<span class="chapter-last-badge">👣 마지막 완료</span>' : ''}
        `;

        node.onclick = () => {
            if (!chapter.locked) openStageSheet(chapter);
            else alert(t('alert_chapter_locked'));
        };

        const isLeft = (index % 2 === 0);

        // ★ 핵심: 배경과 나무 노드를 wrapper에 추가
        wrapper.appendChild(bg);   // 1층 (배경)
        wrapper.appendChild(node); // 2층 (나무 노드)

        // ★ 클리어한 장에만 '심화 훈련' 버튼을 나무 반대편에 배치
        // zone-wrapper(position:relative, width:100%) 기준 absolute
        // → 나무가 왼쪽(left zone)이면 버튼은 오른쪽, 나무가 오른쪽(right zone)이면 버튼은 왼쪽
        if (isChapterClear) {
            const hardshipBtn = document.createElement('button');
            try {
                const _doneSet = new Set(['endurance', 'address', 'memory', 'verse'].filter(m => isHardshipChapterDoneToday(m, chapter.id)));
                if (_doneSet.has('memory'))    { _doneSet.add('endurance'); _doneSet.add('verse'); _doneSet.add('address'); }
                if (_doneSet.has('endurance')) { _doneSet.add('verse'); _doneSet.add('address'); }
                if (_doneSet.has('verse'))     { _doneSet.add('address'); }
                const _doneModes = [..._doneSet];
                const _allDone = _doneModes.length === 4;
                const _anyDone = _doneModes.length > 0;
                hardshipBtn.className = 'chapter-hardship-btn' + (_allDone ? ' hardship-btn-all-done' : _anyDone ? ' hardship-btn-partial-done' : '');
                hardshipBtn.innerHTML = t('hardship_kings_btn') + (_allDone ? ' ✅✅' : _anyDone ? ` ✅(${_doneModes.length}/4)` : '');
            } catch(e) {
                hardshipBtn.className = 'chapter-hardship-btn';
                hardshipBtn.innerHTML = t('hardship_kings_btn');
            }
            hardshipBtn.style.cssText = isLeft
                ? 'right: 12%; top: 50%; transform: translateY(-50%);'
                : 'left: 12%; top: 50%; transform: translateY(-50%);';
            hardshipBtn.onclick = (e) => {
                e.stopPropagation();
                openChapterHardship(chapter.id);
            };
            wrapper.appendChild(hardshipBtn);
        }

        landArea.appendChild(wrapper);
        if (window._mapSwayObserver) window._mapSwayObserver.observe(wrapper);
    });

    // 생명수의 바다 — 지도 맨 아래, 강이 들어가는 곳 (2026-09-30)
    landArea.appendChild(_seaZoneEl());


    // 3. 강물 그리기 (디바운스 150ms, 이전 리스너 제거 후 재등록)
    if (renderChapterMap._resizeHandler) {
        window.removeEventListener('resize', renderChapterMap._resizeHandler);
    }
    let _resizeTimer;
    renderChapterMap._resizeHandler = function() {
        clearTimeout(_resizeTimer);
        _resizeTimer = setTimeout(drawRiver, 150);
    };
    window.addEventListener('resize', renderChapterMap._resizeHandler);
    setTimeout(drawRiver, 100);
}

/* [시스템: S자 강물 그리기 (Zone 대응 버전)] */
function drawRiver() {
    const svg = document.getElementById('river-svg');
    const path = document.getElementById('river-path');
    const nodes = document.querySelectorAll('.stage-node');
    const container = document.querySelector('.river-map-container');

    if (nodes.length === 0 || !svg || !path || !container || container.offsetParent === null) return;

    // 1. 모든 DOM 읽기를 먼저 수행 (레이아웃 스래싱 방지)
    const scrollH = container.scrollHeight;
    const containerRect = container.getBoundingClientRect();
    const scrollTop = container.scrollTop;
    const nodeRects = Array.from(nodes).map(n => n.getBoundingClientRect());

    // 2. SVG 높이 설정 (읽기 이후 쓰기)
    svg.style.height = `${scrollH}px`;

    // 3. 좌표 수집
    const points = nodeRects.map(rect => ({
        x: (rect.left - containerRect.left) + (rect.width / 2),
        y: (rect.top - containerRect.top) + scrollTop + (rect.height / 2),
    }));

    if (points.length < 2) return;

    // 새 예루살렘 남쪽 문 — 있으면 강이 거기서 시작한다
    const njStart = _njRiverStart(containerRect, scrollTop);
    // 생명수의 바다 어귀 — 있으면 강이 거기로 들어간다
    const seaEnd = _seaRiverEnd(containerRect, scrollTop);

    // 4. x 오프셋을 적용한 경로 빌더
    function buildPath(ox) {
        let d;
        if (njStart) {
            const my = (njStart.y + points[0].y) / 2;
            d = `M ${njStart.x + ox} ${njStart.y} C ${njStart.x + ox} ${my}, ${points[0].x + ox} ${my}, ${points[0].x + ox} ${points[0].y} `;
        } else d = `M ${points[0].x + ox} 0 `;
        for (let i = 0; i < points.length - 1; i++) {
            const p1 = points[i];
            const p2 = points[i + 1];
            const midY = (p1.y + p2.y) / 2;
            if (i === 0 && !njStart) d += `L ${p1.x + ox} ${p1.y} `;
            d += `C ${p1.x + ox} ${midY}, ${p2.x + ox} ${midY}, ${p2.x + ox} ${p2.y} `;
        }
        const lp = points[points.length - 1];
        if (seaEnd) { const my = (lp.y + seaEnd.y) / 2; d += `C ${lp.x + ox} ${my}, ${seaEnd.x + ox} ${my}, ${seaEnd.x + ox} ${seaEnd.y}`; }
        else d += `L ${lp.x + ox} ${scrollH}`;
        return d;
    }

    // 5. 경로 적용 (bank와 path는 동일 경로 — 한 번만 빌드)
    const basePath = buildPath(0);
    const bank = document.getElementById('river-bank');
    if (bank) bank.setAttribute('d', basePath);
    path.setAttribute('d', basePath);

    _buildRiverFlow(points, scrollH, njStart, seaEnd);
}

/* [강물 흐름 (2026-09-28 부활)]
   3월엔 물결 4가닥을 지도 전체 높이(≈5,000px) 한 SVG에서 점선 밀기(stroke-dashoffset)로 움직여,
   빛 번짐(drop-shadow)이 걸린 강 전체를 매 프레임 다시 그렸다 → 렉으로 중단(5e2f7b9).
   이제: 번짐 있는 강 바탕(#river-svg)은 멈춰 있고, 물결은 **장 사이 구간마다 작은 SVG 조각**으로 나눠
   번짐 없이 그리며, **화면에 들어온 조각만** 흐른다(IntersectionObserver). 흐르는 조각은 자기 레이어라 아래 번짐을 다시 그리지 않는다.
   조각 경계에서 물결이 끊겨 보이지 않게, 가닥마다 앞 조각까지의 길이만큼 점선 위상을 이어 붙이고 모든 조각이 같은 시계(startTime 0)를 쓴다. */
const RIVER_STRANDS = [
    { ox: -13, period: 50, ms: 3200 },
    { ox: -5,  period: 50, ms: 5500 },
    { ox: +5,  period: 40, ms: 4100 },
    { ox: +13, period: 52, ms: 6800 },
];
function _buildRiverFlow(points, scrollH, start, end) {
    const layer = document.getElementById('river-flow-layer');
    if (!layer) return;
    if (window._riverFlowObserver) { try { window._riverFlowObserver.disconnect(); } catch (e) { } }
    layer.querySelectorAll('.river-flow-tile').forEach(t => (t._anims || []).forEach(a => a.cancel()));
    layer.innerHTML = '';

    // 구간: [맨 위 → 첫 나무], [나무 i → 나무 i+1] …, [마지막 나무 → 맨 아래]
    const segs = [];
    const first = points[0], last = points[points.length - 1];
    if (start) {   // 새 예루살렘 남쪽 문에서 1장까지 굽이
        const my = (start.y + first.y) / 2;
        segs.push({ top: Math.min(start.y, first.y), bottom: first.y,
            d: (ox, y0) => `M ${start.x + ox} ${start.y - y0} C ${start.x + ox} ${my - y0}, ${first.x + ox} ${my - y0}, ${first.x + ox} ${first.y - y0}` });
    } else {
        segs.push({ top: 0, bottom: first.y, d: (ox, y0) => `M ${first.x + ox} ${0 - y0} L ${first.x + ox} ${first.y - y0}` });
    }
    for (let i = 0; i < points.length - 1; i++) {
        const p1 = points[i], p2 = points[i + 1], midY = (p1.y + p2.y) / 2;
        segs.push({ top: Math.min(p1.y, p2.y), bottom: Math.max(p1.y, p2.y),
            d: (ox, y0) => `M ${p1.x + ox} ${p1.y - y0} C ${p1.x + ox} ${midY - y0}, ${p2.x + ox} ${midY - y0}, ${p2.x + ox} ${p2.y - y0}` });
    }
    if (end) {   // 22장에서 바다 어귀까지 굽이
        const my = (last.y + end.y) / 2;
        segs.push({ top: last.y, bottom: end.y, d: (ox, y0) => `M ${last.x + ox} ${last.y - y0} C ${last.x + ox} ${my - y0}, ${end.x + ox} ${my - y0}, ${end.x + ox} ${end.y - y0}` });
    } else {
        segs.push({ top: last.y, bottom: scrollH, d: (ox, y0) => `M ${last.x + ox} ${last.y - y0} L ${last.x + ox} ${scrollH - y0}` });
    }

    const NS = 'http://www.w3.org/2000/svg';
    const cum = RIVER_STRANDS.map(() => 0);   // 가닥별로 지금까지 흘러온 길이
    let cumC = 0;                              // 한가운데 선(빛줄기) 누적 길이
    const order = [];                          // 위→아래 순서의 조각
    segs.forEach(seg => {
        if (seg.bottom - seg.top < 1) return;
        const y0 = seg.top - 3;
        const svg = document.createElementNS(NS, 'svg');
        svg.setAttribute('class', 'river-flow-tile');
        svg.style.top = `${y0}px`;
        svg.style.height = `${seg.bottom - seg.top + 6}px`;
        svg._paths = [];
        RIVER_STRANDS.forEach((st, k) => {
            const p = document.createElementNS(NS, 'path');
            p.setAttribute('class', `river-hl river-hl-${k + 1}`);
            p.setAttribute('d', seg.d(st.ox, y0));
            svg.appendChild(p);
            svg._paths.push({ el: p, base: cum[k] % st.period, st });
        });
        // 빛줄기 자리 2개(한 조각에 두 줄기가 동시에 지날 수 있다) — 평소엔 숨김, 지나갈 때만 점선 한 토막을 보인다
        svg._glints = [0, 1].map(() => ['halo', 'core'].map(kind => {
            const g = document.createElementNS(NS, 'path');
            g.setAttribute('class', `river-glint river-glint-${kind}`);
            g.setAttribute('d', seg.d(0, y0));
            g.setAttribute('stroke-dasharray', `${RIVER_GLINT[kind]} 100000`);
            g.setAttribute('visibility', 'hidden');
            svg.appendChild(g);
            return g;
        }));
        svg._glintOn = [false, false];
        layer.appendChild(svg);
        svg._paths.forEach((o, k) => { try { cum[k] += o.el.getTotalLength(); } catch (e) { } });
        svg._start = cumC;   // 강 한가운데 선을 따라 이 조각이 시작하는 거리
        try { svg._len = svg._glints[0][1].getTotalLength(); } catch (e) { svg._len = seg.bottom - seg.top; }
        cumC += svg._len;
        order.push(svg);
    });
    _riverFlowTick.order = order;
    _riverFlowTick.streaks = [];
    _riverFlowTick.nextGlint = 0;

    const reduce = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce || typeof IntersectionObserver === 'undefined') return;
    const flowing = _riverFlowTick.tiles;
    flowing.clear();
    window._riverFlowObserver = new IntersectionObserver(entries => {
        entries.forEach(en => {
            if (en.isIntersecting) { flowing.add(en.target); en.target.classList.add('flowing'); }
            else { flowing.delete(en.target); en.target.classList.remove('flowing'); }
        });
        if (flowing.size && !_riverFlowTick.raf) _riverFlowTick.raf = requestAnimationFrame(_riverFlowTick);
    }, { rootMargin: '60px 0px' });
    layer.querySelectorAll('.river-flow-tile').forEach(t => window._riverFlowObserver.observe(t));
    document.querySelectorAll('#nj-zone .nj-flow').forEach(t => window._riverFlowObserver.observe(t));   // 새 예루살렘 둘레 물결
}

// 점선 밀기는 폰 그래픽 칩이 대신 못 해 매 프레임 스타일·그리기 비용이 든다(PC 6배 감속 실측: 60fps면 4초 중 2~3초가 일).
// 물결은 초당 10~15px로 느려서 초당 15번만 옮겨도 한 번에 1px 안팎 — 눈엔 똑같이 매끄럽다. 보이는 조각이 없으면 루프가 선다
function _riverFlowTick(now) {
    const self = _riverFlowTick;
    if (!self.tiles.size) { self.raf = 0; return; }
    self.raf = requestAnimationFrame(self);
    _riverGlintStep(now);   // 빛줄기는 빨라서 지나가는 동안만 매 프레임
    if (now - self.last < 66) return;
    self.last = now;
    self.tiles.forEach(tile => tile._paths.forEach(o => {
        // 모든 조각이 같은 시계(now)를 쓰고, 점선 위상은 앞 조각에서 이어받는다 — 줄어드는 방향이 하류(아래)로 흐르는 방향
        const phase = (now % o.st.ms) / o.st.ms;
        o.el.setAttribute('stroke-dashoffset', (o.base + o.st.period * (1 - phase)).toFixed(1));
    }));
}
_riverFlowTick.tiles = new Set();
_riverFlowTick.raf = 0;
_riverFlowTick.last = 0;
_riverFlowTick.order = [];
_riverFlowTick.streaks = [];
_riverFlowTick.nextGlint = 0;

/* [강을 따라 흐르는 빛줄기 (2026-09-28)]
   3~6초마다 화면에 보이는 강의 윗끝에서 빛줄기 하나(가끔 둘)가 하류로 달려 내려간다.
   조각마다 숨겨 둔 점선 한 토막(dasharray "길이 100000")의 위치만 옮긴다 — 지나가는 2~3초 동안만, 한두 줄만 움직인다 */
const RIVER_GLINT = { core: 34, halo: 62, speed: 260, gapMin: 3000, gapMax: 6000 };
function _riverGlintStep(now) {
    const self = _riverFlowTick;
    const order = self.order;
    if (!order.length) return;
    let lo = Infinity, hi = -Infinity;
    self.tiles.forEach(t => { if (t._len == null) return; lo = Math.min(lo, t._start); hi = Math.max(hi, t._start + t._len); });   // 새 예루살렘 둘레 물결(_len 없음)은 빛줄기 범위에서 뺀다
    if (!self.nextGlint) self.nextGlint = now + 1500;
    if (now >= self.nextGlint && self.streaks.length === 0 && isFinite(lo)) {
        self.streaks.push({ t0: now, s0: lo - 20 });
        if (Math.random() < 0.45) self.streaks.push({ t0: now + 380, s0: lo - 20 });   // 가끔 한 줄기가 뒤따른다
        self.nextGlint = now + RIVER_GLINT.gapMin + Math.random() * (RIVER_GLINT.gapMax - RIVER_GLINT.gapMin);
    }
    // 빛줄기 머리 위치(한가운데 선을 따른 거리). 화면 아래로 빠지면 끝
    const heads = self.streaks.map(st => now < st.t0 ? null : st.s0 + (now - st.t0) / 1000 * RIVER_GLINT.speed);
    self.streaks = self.streaks.filter((st, i) => heads[i] === null || heads[i] - RIVER_GLINT.halo < hi + 40);
    const live = heads.filter(h => h !== null && h - RIVER_GLINT.halo < hi + 40);
    if (!live.length && !order.some(t => t._glintOn[0] || t._glintOn[1])) return;
    order.forEach(tile => {
        [0, 1].forEach(slot => {
            const h = live[slot];
            const local = h === undefined ? null : h - tile._start;
            const on = local !== null && local > 0 && local - RIVER_GLINT.halo < tile._len;
            if (on !== tile._glintOn[slot]) {
                tile._glints[slot].forEach(g => g.setAttribute('visibility', on ? 'visible' : 'hidden'));
                tile._glintOn[slot] = on;
            }
            if (!on) return;
            // 점선 한 토막이 [local - 길이, local]에 오도록: offset = 길이 - local
            tile._glints[slot].forEach((g, i) => {
                const len = i === 0 ? RIVER_GLINT.halo : RIVER_GLINT.core;
                g.setAttribute('stroke-dashoffset', (len - local).toFixed(1));
            });
        });
    });
}

// 전역 변수로 타이머 관리 (창 닫을 때 끄기 위해)
var stageSheetTimer = null;

// 남은 시간을 어댑티브 형식으로 변환 (diff: ms)
function formatAdaptiveTime(diff) {
    if (diff >= 60 * 60 * 1000) {
        const h = Math.floor(diff / (60 * 60 * 1000));
        const m = Math.floor((diff % (60 * 60 * 1000)) / 60000);
        return m > 0 ? `${h}시간 ${m}분` : `${h}시간`;
    } else if (diff >= 10 * 60 * 1000) {
        return `${Math.floor(diff / 60000)}분`;
    } else {
        const mm = Math.floor(diff / 60000);
        const ss = Math.floor((diff % 60000) / 1000).toString().padStart(2, '0');
        return `${mm}:${ss}`;
    }
}

// [도우미] 스테이지가 속한 챕터 데이터 조회
function getChapterDataByStageId(stageId) {
    const chNum = parseInt(String(stageId).split('-')[0]);
    if (isNaN(chNum)) return null;
    return gameData.find(c => c.id === chNum) || null;
}

// [도우미] 해당 스테이지 구간의 체크포인트(중간점검/보스) ID 찾기
function getSegmentCheckpointStageId(chapterData, stageId) {
    if (!chapterData || !chapterData.stages) return null;
    const idx = chapterData.stages.findIndex(s => s.id === stageId);
    if (idx === -1) return null;

    for (let i = idx + 1; i < chapterData.stages.length; i++) {
        const stage = chapterData.stages[i];
        if (!stage) continue;
        if (stage.type === 'mid-boss' || stage.type === 'boss') return stage.id;
    }

    return null;
}

// [도우미] 중간점검/보스 클리어 시 전체학습 허용 여부
function isFullLearningUnlockedByCheckpoint(stageId) {
    const chapterData = getChapterDataByStageId(stageId);
    if (!chapterData) return false;

    const stage = chapterData.stages.find(s => s.id === stageId);
    if (!stage || stage.type !== 'normal') return false;

    const checkpointId = getSegmentCheckpointStageId(chapterData, stageId);
    if (!checkpointId) return false;

    return (stageMastery[checkpointId] || 0) > 0;
}

// [도우미] 한 번도 진행하지 않은 스테이지인지 확인
function isUnplayedStage(stageId) {
    return !missionData.stageProgress || !missionData.stageProgress[stageId];
}

// [도우미] 스테이지 진행도 스냅샷
function getStageProgressSnapshot(stageId) {
    if (!missionData || !missionData.stageProgress) return null;
    return missionData.stageProgress[stageId] || null;
}

// [도우미] Step 1~5 완료 처리 여부
function isStageFullyLearned(stageId, stageData) {
    const progress = getStageProgressSnapshot(stageId);
    const phase = progress ? progress.phase : 0;
    const hasMastery = (stageMastery && stageMastery[stageId] && stageMastery[stageId] > 0);
    const isCleared = stageData && stageData.cleared;

    if (hasMastery || isCleared || phase >= 3) return true;
    return isFullLearningUnlockedByCheckpoint(stageId);
}

// ★ [도우미] 해당 장의 아직 초회를 받지 않은 mid-boss의 총 절수
function getUnreceivedMidBossVerses(chapterNum) {
    const chData = gameData.find(c => c.id === chapterNum);
    if (!chData) return 0;

    let unreceived = 0;
    chData.stages.forEach(stage => {
        if (stage.type === 'mid-boss') {
            const lastTime = stageLastClear[stage.id] || 0;
            const isClearedToday = lastTime && _tsTo6AMDateStr(lastTime) === _get6AMDayStr();
            // 초회를 못 받은 mid-boss = 아직 오늘 클리어하지 않은 것
            if (!isClearedToday) {
                unreceived += stage.targetVerseCount || 0;
            }
        }
    });
    return unreceived;
}

// ★ [도우미] 해당 장의 모든 mid-boss 스테이지 ID 목록
function getChapterMidBossIds(chapterNum) {
    const chData = gameData.find(c => c.id === chapterNum);
    if (!chData) return [];
    return chData.stages
        .filter(s => s.type === 'mid-boss')
        .map(s => s.id);
}

let currentOpenChapterData = null;

/* ─── 말씀 읽기 오버레이 ─────────────────────────────────────────────────── */
function openBibleReadingOverlay() {
    const chapterNum = currentOpenChapterData && currentOpenChapterData.id;
    if (!chapterNum) return;
    const verses = bibleData[chapterNum];
    if (!verses || verses.length === 0) return;

    const existing = document.getElementById('bible-reading-overlay');
    if (existing) existing.remove();

    const today = _get6AMDayStr();
    const todayRead = (bibleReadLog[today] && bibleReadLog[today][chapterNum]) || [];

    const versesHtml = verses.map((v, idx) => {
        const verseNum = idx + 1;
        const stageId = `${chapterNum}-${verseNum}`;
        const mastery = stageMastery[stageId] || 0;
        let dotColor = '#5d6d7e';
        if (mastery > 0) {
            const s = getMemoryStrength(stageId);
            dotColor = s >= 0.8 ? '#2ecc71' : s >= 0.6 ? '#f1c40f' : s >= 0.4 ? '#e67e22' : '#e74c3c';
        }
        const text = (currentLang === 'en' && typeof bibleDataEn !== 'undefined' && bibleDataEn[chapterNum] && bibleDataEn[chapterNum][idx])
            ? bibleDataEn[chapterNum][idx].text : v.text;
        const alreadyRead = todayRead.includes(verseNum);
        const btnHtml = alreadyRead
            ? `<button class="bible-read-btn bible-read-done" data-v="${verseNum}" onclick="markVerseAsRead(${chapterNum},${verseNum},this)" disabled>완료</button>`
            : `<button class="bible-read-btn" data-v="${verseNum}" onclick="markVerseAsRead(${chapterNum},${verseNum},this)">읽음</button>`;
        return `<div class="bible-reading-verse">
            <span class="bible-reading-verse-num">${verseNum}</span>
            <span class="bible-reading-verse-text">${_hintTraceTextHtml(stageId, text) || text}</span>
            <span class="bible-reading-verse-dot" style="background:${dotColor};"></span>
            ${btnHtml}
        </div>`;
    }).join('');

    const overlay = document.createElement('div');
    overlay.id = 'bible-reading-overlay';
    overlay.innerHTML = `
        <div class="bible-reading-header">
            <span class="bible-reading-title">${t('label_chapter_header', { num: chapterNum })}</span>
            <button class="bible-reading-close-btn" onclick="closeBibleReadingOverlay()">✕</button>
        </div>
        <div id="bible-read-toast" class="bible-read-toast" style="display:none;">정독해주세요</div>
        <div id="bible-read-pass" class="bible-read-pass">${_bibleReadPassLabel(chapterNum)}</div>
        <div class="bible-reading-body">${versesHtml}</div>
    `;
    document.body.appendChild(overlay);
}

/* 한 절의 보석 = 글자 수(공백 제외) ÷ 5, 최소 3 — 46자 절은 9젬, 13자 절은 3젬, 119자 절은 24젬. 404절 한 바퀴 ≈ 3,900젬.
   기다리는 시간은 글자 수 ÷ 7(분당 420자, 묵독 속도), 최소 2초 — 119자 절이면 17초. (2026-09-21: 처음엔 둘 다 ÷5였는데
   "긴 절일수록 너무 길다"는 체감이 있어 간격만 낮췄다. 묵독은 분당 400~600자라 5자/초는 낭독 속도였다.)
   회독마다 같은 규칙이라 "읽었다"를 버튼이 아니라 시간이 증명한다. (2026-09-16) */
const BIBLE_READ_GEM_CPS = 5;
const BIBLE_READ_WAIT_CPS = 7;
function _verseReadLen(chapterNum, verseNum) {
    const v = (bibleData[chapterNum] || [])[verseNum - 1];
    const en = (currentLang === 'en' && typeof bibleDataEn !== 'undefined' && bibleDataEn[chapterNum] && bibleDataEn[chapterNum][verseNum - 1]) ? bibleDataEn[chapterNum][verseNum - 1].text : '';
    const text = en || (v && v.text) || '';
    return text.replace(/\s+/g, '').length;
}
function _verseReadGems(chapterNum, verseNum) { return Math.max(3, Math.ceil(_verseReadLen(chapterNum, verseNum) / BIBLE_READ_GEM_CPS)); }
function _verseReadSeconds(chapterNum, verseNum) { return Math.max(2, Math.ceil(_verseReadLen(chapterNum, verseNum) / BIBLE_READ_WAIT_CPS)); }

function markVerseAsRead(chapterNum, verseNum, btnEl) {
    const now = Date.now();
    const needSec = _verseReadSeconds(chapterNum, verseNum);
    if (now - _lastBibleReadClickTime < needSec * 1000) {
        const toast = document.getElementById('bible-read-toast');
        if (toast) {
            const left = Math.ceil((needSec * 1000 - (now - _lastBibleReadClickTime)) / 1000);
            toast.textContent = t('bible_read_wait', { n: left });
            toast.style.display = 'block';
            clearTimeout(toast._hideTimer);
            toast._hideTimer = setTimeout(() => { toast.style.display = 'none'; }, 2000);
        }
        return;
    }
    _lastBibleReadClickTime = now;

    const today = _get6AMDayStr();
    if (!bibleReadLog[today]) bibleReadLog[today] = {};
    if (!bibleReadLog[today][chapterNum]) bibleReadLog[today][chapterNum] = [];
    if (bibleReadLog[today][chapterNum].includes(verseNum)) return;

    bibleReadLog[today][chapterNum].push(verseNum);
    if (!bibleReadPasses[today]) bibleReadPasses[today] = {};
    const passes = bibleReadPasses[today][chapterNum] || 0;
    const gem = _verseReadGems(chapterNum, verseNum);   // 글자 수 기준. 회독마다 같다
    myGems += gem;
    bibleReadTotal[today] = (bibleReadTotal[today] || 0) + 1;
    _noteReadForWeek();
    // 「이번 주 통독 N절」은 절마다 바로 갱신 — 예전엔 한 장을 다 읽은 뒤에만 다시 그렸다 (2026-09-21)
    const passLabelEl = document.getElementById('bible-read-pass');
    if (passLabelEl) passLabelEl.textContent = _bibleReadPassLabel(chapterNum);
    updateGemDisplay();
    saveGameData();
    if (typeof claimBibleReadReward === 'function') claimBibleReadReward(true);

    if (btnEl) {
        btnEl.textContent = '완료';
        btnEl.classList.add('bible-read-done');
        btnEl.disabled = true;
        const rect = btnEl.getBoundingClientRect();
        const tip = document.createElement('div');
        tip.className = 'bible-gem-tip';
        tip.textContent = `+💎${gem}`;
        tip.style.left = (rect.left + rect.width / 2) + 'px';
        tip.style.top = (rect.top + window.scrollY) + 'px';
        document.body.appendChild(tip);
        setTimeout(() => { if (tip.parentNode) tip.remove(); }, 900);
    }

    // 한 장을 다 읽었으면 → 회독 +1, 버튼 초기화. 다시 읽을 수 있다
    const total = (bibleData[chapterNum] || []).length;
    if (total > 0 && bibleReadLog[today][chapterNum].length >= total) {
        bibleReadPasses[today][chapterNum] = passes + 1;
        bibleReadLog[today][chapterNum] = [];
        saveGameData();
        setTimeout(() => {
            document.querySelectorAll('#bible-reading-overlay .bible-read-btn').forEach(b => {
                b.disabled = false; b.textContent = '읽음'; b.classList.remove('bible-read-done');
            });
            const passEl = document.getElementById('bible-read-pass');
            if (passEl) passEl.textContent = _bibleReadPassLabel(chapterNum);
            if (typeof showToast === 'function') showToast(t('bible_read_pass_done', { ch: chapterNum, n: passes + 1 }));
        }, 600);
    }
}

function _bibleReadPassLabel(chapterNum) {
    const today = _get6AMDayStr();
    const passes = (bibleReadPasses[today] && bibleReadPasses[today][chapterNum]) || 0;
    const wk = (readWeek.weekId === getWeekId()) ? (readWeek.count || 0) : 0;
    return (passes > 0 ? t('bible_read_pass_n', { n: passes }) + ' · ' : '') + t('bible_read_week_count', { n: wk.toLocaleString() });
}

function claimBibleReadReward(silent) {
    const today = _get6AMDayStr();
    // 회독으로 장 목록이 비워져도 오늘 읽은 수는 bibleReadTotal에 남는다 (없으면 옛 방식으로 합산)
    const totalRead = (bibleReadTotal[today] != null) ? bibleReadTotal[today]
        : Object.values(bibleReadLog[today] || {}).reduce((s, a) => s + a.length, 0);
    const milestone = Math.min(40, Math.floor(totalRead / 10));
    const prevClaimed = missionData.daily.bibleReadClaimed || 0;
    if (milestone <= prevClaimed) return;
    const bonus = (milestone - prevClaimed) * 100;
    myGems += bonus;
    missionData.daily.bibleReadClaimed = milestone;
    updateGemDisplay();
    saveGameData();
    if (silent) { showMissionToast(t('mission_daily_bible_read_title') + ` ${milestone * 10}절`, `💎 ${bonus.toLocaleString()}`); return; }
    showGemToast(bonus);
    openMission();
}

function closeBibleReadingOverlay() {
    const el = document.getElementById('bible-reading-overlay');
    if (el) el.remove();
    // 실시간 통독왕 — 읽기를 마치면 한 번 올린다 (값이 같으면 안 보낸다)
    if (typeof saveMyScoreToServer === 'function') setTimeout(saveMyScoreToServer, 0);
}

/* ─── 챕터 오디오 플레이어 ───────────────────────────────────────────────── */
let _chapAudio = null;
let _chapAudioRaf = null;

function openChapterAudioPlayer() {
    const chapterNum = currentOpenChapterData && currentOpenChapterData.id;
    if (!chapterNum) return;

    const existing = document.getElementById('chapter-audio-modal');
    if (existing) return; // 이미 열림

    const mp3Url = `https://kyu12k.github.io/bjtest/bjtest${chapterNum}/mp3/${chapterNum}.mp3`;

    if (_chapAudio) { _chapAudio.pause(); _chapAudio = null; }
    _chapAudio = new Audio(mp3Url);
    _chapAudio.loop = false;

    const modal = document.createElement('div');
    modal.id = 'chapter-audio-modal';
    modal.innerHTML = `
        <div class="chap-audio-card">
            <div class="chap-audio-header">
                <span class="chap-audio-title">🎧 계시록 ${chapterNum}장</span>
                <button class="chap-audio-close-btn" onclick="closeChapterAudioPlayer()">✕</button>
            </div>
            <div class="chap-audio-time-row">
                <span id="chap-audio-cur">0:00</span>
                <span id="chap-audio-dur">-:--</span>
            </div>
            <div class="chap-audio-progress-wrap" id="chap-audio-prog" onclick="seekChapterAudio(event,this)">
                <div class="chap-audio-progress-fill" id="chap-audio-fill"></div>
                <div class="chap-audio-progress-thumb" id="chap-audio-thumb"></div>
            </div>
            <div class="chap-audio-btns">
                <button class="chap-audio-skip" onclick="skipChapterAudio(-10)">-10s</button>
                <button class="chap-audio-play-btn" id="chap-audio-play" onclick="toggleChapterAudio()">▶</button>
                <button class="chap-audio-skip" onclick="skipChapterAudio(10)">+10s</button>
            </div>
            <div class="chap-audio-options">
                <div class="chap-audio-speed-group" id="chap-audio-speed-group">
                    <button class="chap-speed-btn" data-rate="0.75" onclick="setChapterAudioSpeed(0.75)">0.75×</button>
                    <button class="chap-speed-btn active" data-rate="1" onclick="setChapterAudioSpeed(1)">1×</button>
                    <button class="chap-speed-btn" data-rate="1.25" onclick="setChapterAudioSpeed(1.25)">1.25×</button>
                    <button class="chap-speed-btn" data-rate="1.5" onclick="setChapterAudioSpeed(1.5)">1.5×</button>
                    <button class="chap-speed-btn" data-rate="2" onclick="setChapterAudioSpeed(2)">2×</button>
                </div>
                <button class="chap-audio-repeat-btn" id="chap-audio-repeat" onclick="toggleChapterAudioRepeat()">🔁 반복</button>
            </div>
            <div id="chap-audio-error" style="display:none; color:#e74c3c; font-size:0.85rem; text-align:center; padding:8px 0;"></div>
        </div>
    `;
    document.body.appendChild(modal);

    const audio = _chapAudio;

    audio.addEventListener('loadedmetadata', _chapAudioUpdateUI);
    audio.addEventListener('timeupdate', _chapAudioUpdateUI);
    audio.addEventListener('ended', () => {
        const btn = document.getElementById('chap-audio-play');
        if (btn) btn.textContent = '▶';
    });
    audio.addEventListener('error', () => {
        const err = document.getElementById('chap-audio-error');
        if (err) { err.style.display = 'block'; err.textContent = '오디오 파일을 불러올 수 없습니다.'; }
    });

    audio.play().then(() => {
        const btn = document.getElementById('chap-audio-play');
        if (btn) btn.textContent = '⏸';
    }).catch(() => {});
}

function _chapAudioFmtTime(sec) {
    if (!isFinite(sec) || sec < 0) return '-:--';
    const m = Math.floor(sec / 60), s = Math.floor(sec % 60);
    return `${m}:${s.toString().padStart(2, '0')}`;
}

function _chapAudioUpdateUI() {
    const audio = _chapAudio;
    if (!audio) return;
    const cur = document.getElementById('chap-audio-cur');
    const dur = document.getElementById('chap-audio-dur');
    const fill = document.getElementById('chap-audio-fill');
    const thumb = document.getElementById('chap-audio-thumb');
    if (cur) cur.textContent = _chapAudioFmtTime(audio.currentTime);
    if (dur) dur.textContent = _chapAudioFmtTime(audio.duration);
    const pct = audio.duration ? (audio.currentTime / audio.duration) * 100 : 0;
    if (fill) fill.style.width = pct + '%';
    if (thumb) thumb.style.left = pct + '%';
}

function toggleChapterAudio() {
    if (!_chapAudio) return;
    const btn = document.getElementById('chap-audio-play');
    if (_chapAudio.paused) {
        _chapAudio.play().catch(() => {});
        if (btn) btn.textContent = '⏸';
    } else {
        _chapAudio.pause();
        if (btn) btn.textContent = '▶';
    }
}

function skipChapterAudio(sec) {
    if (!_chapAudio) return;
    _chapAudio.currentTime = Math.max(0, Math.min(_chapAudio.duration || 0, _chapAudio.currentTime + sec));
}

function seekChapterAudio(e, el) {
    if (!_chapAudio || !_chapAudio.duration) return;
    const rect = el.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    _chapAudio.currentTime = ratio * _chapAudio.duration;
}

function setChapterAudioSpeed(rate) {
    if (_chapAudio) _chapAudio.playbackRate = rate;
    document.querySelectorAll('.chap-speed-btn').forEach(b => {
        b.classList.toggle('active', parseFloat(b.dataset.rate) === rate);
    });
}

function toggleChapterAudioRepeat() {
    if (!_chapAudio) return;
    _chapAudio.loop = !_chapAudio.loop;
    const btn = document.getElementById('chap-audio-repeat');
    if (btn) btn.classList.toggle('active', _chapAudio.loop);
}

function closeChapterAudioPlayer() {
    if (_chapAudio) { _chapAudio.pause(); _chapAudio = null; }
    const modal = document.getElementById('chapter-audio-modal');
    if (modal) modal.remove();
}

/* ─── 스테이지 아이템 엘리먼트 빌더 (accordion/flat 공용) ───────────────── */
function buildStageItemEl(stage, chData, kingsUnlockedSet, lastPlayedId) {
    const item = document.createElement('div');
    const isCleared = (stageMastery[stage.id] || 0) > 0;
    const chNum = parseInt(stage.id.split('-')[0]);
    let itemClass = `stage-item ${stage.type === 'boss' ? 'boss' : ''}`;
    if (isCleared) itemClass += ' cleared';
    const lastTime = stageLastClear[stage.id] || 0;
    const isTodayClear = lastTime && _tsTo6AMDateStr(lastTime) === _get6AMDayStr();
    const stageReviewStatusUI = getReviewStatus(stage.id);
    let statusBadgeHtml = '';
    if (isTodayClear) {
        itemClass += ' today-clear';
        statusBadgeHtml = `<div class="today-badge">${t('status_today_done')}</div>`;
    }
    const isLastPlayed = lastPlayedId && stage.id === lastPlayedId;
    let lastPlayedBadgeHtml = '';
    if (isLastPlayed) {
        itemClass += ' last-played';
        lastPlayedBadgeHtml = `<div class="last-played-badge">👣 마지막 완료</div>`;
    }
    const isNormalStage = (stage.type !== 'boss' && stage.type !== 'mid-boss');
    const memLevelUI = getMemoryLevelFromStep(stageReviewStatusUI.step);
    let levelBadgeHtml = '';
    if (memLevelUI > 0 && isNormalStage) {
        const colorClass = memLevelUI >= 5 ? 'mem-lv-high' : memLevelUI >= 3 ? 'mem-lv-mid' : 'mem-lv-low';
        levelBadgeHtml = `<span class="mem-badge ${colorClass}">Lv.${memLevelUI}</span>`;
    }
    item.className = itemClass;
    let iconChar = '🌱';
    if (stage.type === 'boss') iconChar = '🐲';
    else if (stage.type === 'mid-boss') iconChar = '📜';
    if (isCleared) iconChar = '🌳';
    const progress = getStageProgressSnapshot(stage.id);
    const isFullStepsComplete = isStageFullyLearned(stage.id, stage);
    const isCoolingDown = !isFullStepsComplete && progress && progress.unlockTime > Date.now();
    const canChooseReviewMode = isNormalStage;
    let rightSideContent = '';
    if (canChooseReviewMode) {
        rightSideContent = `<div style="font-size:1.2rem; color:#bdc3c7;">⚙️</div>`;
    } else if (isCoolingDown) {
        rightSideContent = `<div class="live-timer" data-unlock="${progress.unlockTime}" style="font-size:0.9rem; color:#e74c3c; font-weight:bold; background:#fff0f0; padding:4px 8px; border-radius:12px; border:1px solid #e74c3c;">⏳ 계산중</div>`;
    } else {
        rightSideContent = `<div style="font-size:1.2rem; color:#f1c40f;">▶</div>`;
    }
    let rewardInfo = isNormalStage ? (buildReviewBadgeHtml(stage.id) + _blankLvBadgeHtml(stage.id)) : '';
    if (stage.type === 'boss' && !isCleared) {
        const firstClearGem = (stage.targetVerseCount || 0) * 50;
        rewardInfo = `<div class="boss-first-clear-gem">💎 최초 클리어 시 보석 ${firstClearGem}개 지급</div>`;
    }
    let memoryBarHtml = '';
    if (isCleared && isNormalStage) {
        const strength = getMemoryStrength(stage.id);
        if (strength !== null) {
            const pct = Math.round(strength * 100);
            const colorClass = pct >= 80 ? 'mem-strength-green' : pct >= 60 ? 'mem-strength-yellow' : pct >= 40 ? 'mem-strength-orange' : 'mem-strength-red';
            const flameIcon = pct >= 60 ? '🔥' : pct >= 40 ? '🕯️' : '💀';
            const flameClass = pct >= 80 ? 'flame-alive' : pct >= 60 ? 'flame-dim' : pct >= 40 ? 'flame-low' : 'flame-ash';
            memoryBarHtml = `<div class="mem-strength-bar-wrap" data-stage-id="${stage.id}"><div class="mem-strength-label"><span class="flame-icon ${flameClass}">${flameIcon}</span> <span class="mem-strength-pct">${pct}%</span></div><div class="mem-strength-track"><div class="mem-strength-fill ${colorClass}" style="width:${pct}%"></div></div></div>`;
        }
    } else if (stage.type === 'mid-boss') {
        const avgStrength = getMidBossAvgStrength(chData, stage);
        if (avgStrength !== null) {
            const pct = Math.round(avgStrength * 100);
            const colorClass = pct >= 80 ? 'mem-strength-green' : pct >= 60 ? 'mem-strength-yellow' : pct >= 40 ? 'mem-strength-orange' : 'mem-strength-red';
            const flameIcon = pct >= 60 ? '🔥' : pct >= 40 ? '🕯️' : '💀';
            const flameClass = pct >= 80 ? 'flame-alive' : pct >= 60 ? 'flame-dim' : pct >= 40 ? 'flame-low' : 'flame-ash';
            memoryBarHtml = `<div class="mem-strength-bar-wrap" data-mid-boss-id="${stage.id}"><div class="mem-strength-label"><span class="flame-icon ${flameClass}">${flameIcon}</span> 평균 <span class="mem-strength-pct">${pct}%</span></div><div class="mem-strength-track"><div class="mem-strength-fill ${colorClass}" style="width:${pct}%"></div></div></div>`;
        }
    }
    item.innerHTML = `
    ${statusBadgeHtml}
    ${lastPlayedBadgeHtml}
    <div class="stage-icon">${iconChar}</div>
    <div class="stage-info">
        <div class="stage-title">${levelBadgeHtml} ${getStageTitle(stage)}</div>
        <div class="stage-desc">${getStageDesc(stage)}</div>
        ${rewardInfo}
        ${memoryBarHtml}
    </div>
    ${rightSideContent}
    `;
    if (isLastPlayed) item.dataset.lastPlayed = 'true';
    if (kingsUnlockedSet && !kingsUnlockedSet.has(stage.id)) {
        item.classList.add('kings-locked');
        item.innerHTML += `<span class="kings-locked-badge">🔒</span>`;
        if (stage.type === 'normal') {
            item.onclick = () => {
                const nextId = getNextKingsRoadStageId();
                if (stage.id !== nextId) { alert(t('alert_kings_unlock_order')); return; }
                if (confirm(t('alert_kings_unlock_next_confirm'))) {
                    kingsRoadData.manualBonus = (kingsRoadData.manualBonus || 0) + 1;
                    saveGameData();
                    openStageSheet(currentOpenChapterData);
                }
            };
        } else {
            item.onclick = () => alert(t('alert_verse_locked'));
        }
        return item;
    }
    item.onclick = () => {
        window.currentStageId = stage.id;
        if (stage.type !== 'boss' && stage.type !== 'mid-boss') {
            const _m = String(stage.id).match(/^(\d+)(?:-(\d+))?/);
            const _cn = _m ? parseInt(_m[1], 10) : 0;
            const _vn = (_m && _m[2]) ? parseInt(_m[2], 10) : 1;
            const _preload = new Audio(getAudioUrl(_cn, _vn));
            _preload.preload = 'auto';
            _preload.load();
            connectVoiceToAudioContext(_preload);
            window._preloadedStageAudio = _preload;
            window._preloadedStageAudioVoice = selectedVoice;
        }
        if (stage.type === 'boss' || stage.type === 'mid-boss') {
            openBossSetupModal(stage);
        } else if (canChooseReviewMode) {
            openModeSelect(stage.id);
        } else {
            startTraining(stage.id, 'full-new');
        }
    };
    return item;
}

/* ─── 중간점검 범위 기준으로 스테이지 그루핑 ─────────────────────────────── */
function groupStagesByMidBoss(chData) {
    const stages = chData.stages;
    const midBosses = stages.filter(s => s.type === 'mid-boss')
        .sort((a, b) => (a.rangeStart || 0) - (b.rangeStart || 0));
    if (midBosses.length === 0) return null;

    const boss = stages.find(s => s.type === 'boss');
    const normalStages = stages.filter(s => s.type === 'normal');

    const covered = new Set();
    midBosses.forEach(mb => {
        for (let v = mb.rangeStart; v <= mb.rangeEnd; v++) covered.add(v);
    });

    const groups = [];

    // 첫 번째 중간점검 이전 절 (예: 1~8절)
    const before = normalStages.filter(s => {
        const v = parseInt(s.id.split('-')[1]);
        return !covered.has(v) && v < midBosses[0].rangeStart;
    });
    if (before.length > 0) {
        const vs = before.map(s => parseInt(s.id.split('-')[1]));
        groups.push({ rangeStart: Math.min(...vs), rangeEnd: Math.max(...vs), subtitle: null, stages: before, midBoss: null });
    }

    // 중간점검별 그룹
    midBosses.forEach(mb => {
        const inRange = normalStages.filter(s => {
            const v = parseInt(s.id.split('-')[1]);
            return v >= mb.rangeStart && v <= mb.rangeEnd;
        });
        groups.push({ rangeStart: mb.rangeStart, rangeEnd: mb.rangeEnd, subtitle: mb.subtitle || null, stages: inRange, midBoss: mb });
    });

    return { groups, boss };
}

/* [수정] 스테이지 시트 열기 (각 버튼별 타이머 적용) */
/* ── 장 헤더의 백지 증거 한 줄 (2026-09-27) ───────────────────────────────────
   **복습 레벨과 "진짜 외웠는가"는 다른 것을 잰다.** 레벨은 '몇 번, 얼마나 규칙적으로 복습했나'이고
   Step 2/5의 단어 버튼은 답이 화면에 다 있는 재구성이라 단서 없이 나오는지를 증명하지 못한다(Bjork: 인출 강도 ≠ 저장 강도).
   실측(2026-09-27): 기억레벨 5인 스테이지 3,144개 중 **56%가 백지로 써낸 적이 없다.**
   16장 21절을 11~13회씩 깨고 레벨 5를 찍었는데 백지는 0절인 실제 사례가 이 표시의 계기다.
   → 난이도 모달에만 있던 증거를 **매일 지나는 자리**로 끌어낸다. verseRecall은 모드로 나뉘지 않으므로
     자유여행·왕의 길 어느 쪽에서 써냈든 같은 증거로 센다. */
// 장 하나의 백지 증거 집계 — 시트 헤더 한 줄과 지도 고리가 같이 쓴다
function _chapterBlankStats(chapterData) {
    const ids = ((chapterData && chapterData.stages) || []).map(s => String(s.id)).filter(id => /^\d+-\d+$/.test(id));
    let blank = 0, typed = 0, top = 0, due = 0;
    if (typeof verseRecall === 'undefined') return { total: ids.length, blank, typed, top, due, ids };
    const now = Date.now();
    ids.forEach(id => {
        const r = verseRecall[id];
        if (!r) return;
        if (r.blankPass > 0 || r.bx > 0) blank += 1;
        else if (r.typedPass > 0) typed += 1;   // 빈칸까지만 써본 절
        if (r.bx === 5) top += 1;
        if (r.bx && r.bxDue && r.bxDue <= now) due += 1;
    });
    return { total: ids.length, blank, typed, top, due, ids };
}

// 지도 나무 둘레의 백지 고리 — 백지로 써낸 절의 비율만큼 차오른다 (2026-09-28)
function _mapBlankRingHtml(chapter) {
    if (!chapter || chapter.locked) return '';
    const s = _chapterBlankStats(chapter);
    if (!s.total) return '';
    const pct = Math.round(s.blank / s.total * 100);
    const cls = 'map-blank-ring' + (s.blank >= s.total ? ' all' : '');
    const tip = `백지로 써낸 절 ${s.blank} / ${s.total}` + (s.due ? ` · 오늘 차례 ${s.due}개 절` : '');
    return `<div class="${cls}" style="--p:${pct}" aria-hidden="true"></div>` +
        (s.blank > 0 ? `<span class="map-blank-count${s.blank >= s.total ? ' all' : ''}${s.due ? ' due' : ''}" title="${tip}">✍️${s.blank}/${s.total}</span>` : '');
}

function _renderSheetBlankEvidence(chapterData) {
    const el = document.getElementById('sheet-blank-evidence');
    if (!el) return;
    const { ids, blank, typed, top, due } = _chapterBlankStats(chapterData);
    if (!ids.length || typeof verseRecall === 'undefined') { el.style.display = 'none'; return; }
    const all = blank >= ids.length;
    el.className = 'sheet-blank-evidence' + (all ? ' all-done' : (blank > 0 ? ' partial' : ' none'));
    el.setAttribute('data-tip', '복습 레벨은 「몇 번 복습했나」, 백지레벨은 「간격을 두고 단서 없이 꺼냈나」입니다. 1일·3일·1주·2주·한 달 간격으로 백지로 써낼 때마다 오릅니다');
    el.innerHTML = (all
        ? `✍️ 이 장 ${ids.length}절을 <b>모두 백지로</b> 써냈어요`
        : `✍️ 백지로 써낸 절 <b>${blank}</b> / ${ids.length}` +
          (typed > 0 ? ` <span class="sbe-sub">· 빈칸까지 ${typed}개 절</span>` : '')) +
        (top > 0 ? ` <span class="sbe-sub">· Lv5 ${top}개 절</span>` : '') +
        (due > 0 ? ` <span class="sbe-due">· 오늘 차례 ${due}개 절</span>` : '');   // 「3절」은 3절(구절 번호)로 읽힌다 → 「3개 절」
    el.style.display = '';
    _renderSheetBlankDue(chapterData);
}
/* ✍️ 이 장의 오늘 백지 차례 — 어느 절인지 + 바로 쓰기 (2026-10-05)
   지도 「✍️n/m」의 빨간 점이 무엇인지 알려면 1~4절·5~8절 묶음을 하나씩 펼쳐야 했다(사용자).
   증거 줄(data-tip 말풍선)은 누르면 말풍선이 클릭을 가로채므로 버튼은 따로 둔다 */
function _renderSheetBlankDue(chapterData) {
    const ev = document.getElementById('sheet-blank-evidence');
    if (!ev) return;
    let el = document.getElementById('sheet-blank-due');
    if (!el) { el = document.createElement('div'); el.id = 'sheet-blank-due'; el.className = 'sheet-blank-due'; ev.parentNode.insertBefore(el, ev.nextSibling); }
    const ch = chapterData && chapterData.id, now = Date.now();
    const vs = (_chapterBlankStats(chapterData).ids || []).filter(id => { const r = verseRecall[id]; return r && r.bx && r.bxDue && r.bxDue <= now; })
        .map(id => parseInt(id.split('-')[1], 10));
    if (!vs.length || typeof ch !== 'number') { el.style.display = 'none'; el.innerHTML = ''; return; }
    el.innerHTML = `<div class="sbd-text"><b>${t('sbd_title', { n: vs.length })}</b><span class="sbd-vs">${t('bd_range', { r: _verseRangeText(vs) })}</span></div>` +
        `<button class="sbd-go" onclick="_startBlankDue(${ch}, 'map')">${t('sbd_go')}</button>`;
    el.style.display = '';
}
// 묶음(중간점검) 안에서 오늘 백지 차례인 절 수
function _groupBlankDue(stages) {
    if (typeof verseRecall === 'undefined' || !verseRecall) return 0;
    const now = Date.now();
    return stages.filter(s => { const r = verseRecall[String(s.id)]; return r && r.bx && r.bxDue && r.bxDue <= now; }).length;
}

function openStageSheet(chapterData) {
    currentOpenChapterData = chapterData;
    const sheet = document.getElementById('stage-sheet');
    document.getElementById('sheet-chapter-title').innerText = t('label_chapter_header', { num: chapterData.id });
    _renderSheetBlankEvidence(chapterData);

    const list = document.getElementById('stage-list-area');
    list.innerHTML = "";

    // 보스 클리어 멘트 배너 (보류 멘트가 있으면 시트 상단에 표시)
    let quoteBanner = document.getElementById('sheet-quote-banner');
    if (!quoteBanner) {
        quoteBanner = document.createElement('p');
        quoteBanner.id = 'sheet-quote-banner';
        quoteBanner.style.cssText = 'font-style:italic; color:var(--primary-color,#f1c40f); font-size:0.9rem; text-align:center; padding:10px 16px 0; margin:0; line-height:1.6; display:none;';
        list.parentNode.insertBefore(quoteBanner, list);
    }
    if (window._pendingResultQuote) {
        quoteBanner.textContent = window._pendingResultQuote;
        quoteBanner.style.display = 'block';
        window._pendingResultQuote = null;
    } else {
        quoteBanner.textContent = '';
        quoteBanner.style.display = 'none';
    }

    // 이전에 돌아가던 타이머가 있다면 정지 (중복 방지)
    if (stageSheetTimer) clearInterval(stageSheetTimer);

    // ★ 왕의 길 모드: 해금 set 미리 계산
    const kingsUnlockedSet = (activeMode === 'kings') ? getKingsRoadUnlockedSet() : null;

    // 마지막으로 직접 플레이한 스테이지 (진입 시점 기록 기준)
    const chNum = chapterData.id;
    const lastPlayedId = (lastPlayedStageId &&
        String(lastPlayedStageId).match(/^(\d+)/) &&
        parseInt(String(lastPlayedStageId).match(/^(\d+)/)[1]) === chNum)
        ? lastPlayedStageId : null;

    const grouped = groupStagesByMidBoss(chapterData);
    if (grouped) {
        grouped.groups.forEach(group => {
            const rangeLabel = `${group.rangeStart}~${group.rangeEnd}절`;
            const subtitleHtml = group.subtitle
                ? `<span class="stage-group-subtitle">${group.subtitle}</span>` : '';
            const hasReview = group.stages.some(s => {
                const rs = getReviewStatus(s.id);
                return rs.isEligible && rs.step > 1;
            });
            const reviewDotHtml = hasReview ? `<span class="stage-group-review-dot"></span>` : '';
            const blankDue = _groupBlankDue(group.stages);
            const blankDueHtml = blankDue ? `<span class="stage-group-blank-due" title="${t('sbd_group_tip', { n: blankDue })}">✍️${blankDue}</span>` : '';
            const hasNewVerse = kingsUnlockedSet && group.stages.some(s =>
                kingsUnlockedSet.has(s.id) && (stageMastery[s.id] || 0) === 0
            );
            const newBadgeHtml = hasNewVerse ? `<span class="stage-group-new-badge">새 구절</span>` : '';
            const hasLastPlayed = lastPlayedId && (
                group.stages.some(s => s.id === lastPlayedId) ||
                (group.midBoss && group.midBoss.id === lastPlayedId)
            );

            const groupEl = document.createElement('div');
            groupEl.className = 'stage-group';
            if (hasNewVerse || hasLastPlayed || blankDue) groupEl.classList.add('open');   // 백지 차례가 있는 묶음은 펼쳐 둔다
            const headerEl = document.createElement('div');
            headerEl.className = 'stage-group-header';
            headerEl.innerHTML = `
                <div class="stage-group-header-left">
                    <span class="stage-group-range">${rangeLabel}</span>
                    ${subtitleHtml}
                </div>
                <div class="stage-group-header-right">
                    ${newBadgeHtml}
                    ${blankDueHtml}
                    ${reviewDotHtml}
                    <span class="stage-group-arrow">›</span>
                </div>
            `;
            headerEl.onclick = () => groupEl.classList.toggle('open');

            const contentEl = document.createElement('div');
            contentEl.className = 'stage-group-content';
            group.stages.forEach(s => contentEl.appendChild(buildStageItemEl(s, chapterData, kingsUnlockedSet, lastPlayedId)));
            if (group.midBoss) contentEl.appendChild(buildStageItemEl(group.midBoss, chapterData, kingsUnlockedSet, lastPlayedId));

            groupEl.appendChild(headerEl);
            groupEl.appendChild(contentEl);
            list.appendChild(groupEl);
        });
        if (grouped.boss) list.appendChild(buildStageItemEl(grouped.boss, chapterData, kingsUnlockedSet, lastPlayedId));
    } else {
        chapterData.stages.forEach(stage => {
            list.appendChild(buildStageItemEl(stage, chapterData, kingsUnlockedSet, lastPlayedId));
        });
    }

    sheet.classList.add('open');

    // 마지막 플레이 스테이지로 스크롤
    if (lastPlayedId) {
        setTimeout(() => {
            const lastEl = list.querySelector('[data-last-played="true"]');
            if (lastEl) lastEl.scrollIntoView({ block: 'center', behavior: 'smooth' });
        }, 80);
    }

    // ★ 6. 타이머 작동 시작 (즉시 1회 실행 후 1분마다 갱신) ★
    function updateSheetTimers() {
        const now = Date.now();

        // 숙성 쿨타임 타이머 (live-timer)
        document.querySelectorAll('.live-timer').forEach(el => {
            const unlockTime = parseInt(el.dataset.unlock);
            const diff = unlockTime - now;

            if (diff <= 0) {
                el.innerText = "🔓 OPEN";
                el.style.color = "#2ecc71";
                el.style.borderColor = "#2ecc71";
                el.style.background = "#eafaf1";
            } else {
                const totalMins = Math.floor(diff / 60000);
                const timeStr = totalMins >= 60
                    ? `${Math.floor(totalMins / 60)}시간 ${totalMins % 60 > 0 ? (totalMins % 60) + '분' : ''}`.trim()
                    : (totalMins > 0 ? totalMins + '분' : '1분 미만');
                el.innerText = t('status_review_later', { time: timeStr });
            }
        });

        // 보너스 대기 타이머 (live-timer-bonus) - 구버전 호환용
        document.querySelectorAll('.live-timer-bonus').forEach(el => {
            const unlockTime = parseInt(el.dataset.unlock);
            const diff = unlockTime - now;
            if (diff <= 0) {
                el.innerText = t('status_review_now');
            } else {
                const totalMins = Math.floor(diff / 60000);
                const timeStr = totalMins >= 60
                    ? `${Math.floor(totalMins / 60)}시간 ${totalMins % 60 > 0 ? (totalMins % 60) + '분' : ''}`.trim()
                    : (totalMins > 0 ? totalMins + '분' : '1분 미만');
                el.innerText = t('status_review_later', { time: timeStr });
            }
        });

        // ★ [v1.1.0] 복습 단계 배지 타이머 (live-timer-review)
        document.querySelectorAll('.live-timer-review').forEach(el => {
            const unlockTime = parseInt(el.dataset.unlock);
            const diff = unlockTime - now;
            if (diff <= 0) {
                el.textContent = t('status_review_now');
                el.className = 'review-ready';
            } else {
                const totalMins = Math.floor(diff / 60000);
                const d = Math.floor(totalMins / 1440);
                const h = Math.floor((totalMins % 1440) / 60);
                const m = totalMins % 60;
                let timeStr = '';
                if (d > 0) timeStr += `${d}일 `;
                if (h > 0) timeStr += `${h}시간 `;
                if (m > 0 || timeStr === '') timeStr += `${m}분`;
                el.textContent = t('status_review_bonus', { time: timeStr.trim() });
            }
        });

        // ★ [에빙하우스] 기억 강도 바 업데이트 (일반 스테이지)
        document.querySelectorAll('.mem-strength-bar-wrap[data-stage-id]').forEach(wrap => {
            const sid = wrap.dataset.stageId;
            const strength = getMemoryStrength(sid);
            if (strength === null) return;
            const pct = Math.round(strength * 100);
            const colorClass = pct >= 80 ? 'mem-strength-green'
                             : pct >= 60 ? 'mem-strength-yellow'
                             : pct >= 40 ? 'mem-strength-orange'
                             : 'mem-strength-red';
            const flameIcon  = pct >= 60 ? '🔥' : pct >= 40 ? '🕯️' : '💀';
            const flameClass = pct >= 80 ? 'flame-alive' : pct >= 60 ? 'flame-dim' : pct >= 40 ? 'flame-low' : 'flame-ash';
            const fill = wrap.querySelector('.mem-strength-fill');
            const pctEl = wrap.querySelector('.mem-strength-pct');
            const flameEl = wrap.querySelector('.flame-icon');
            if (fill) { fill.style.width = pct + '%'; fill.className = `mem-strength-fill ${colorClass}`; }
            if (pctEl) pctEl.textContent = pct + '%';
            if (flameEl) { flameEl.textContent = flameIcon; flameEl.className = `flame-icon ${flameClass}`; }
        });

        // ★ [에빙하우스] 기억 강도 바 업데이트 (중간점검 — 서브스테이지 평균)
        document.querySelectorAll('.mem-strength-bar-wrap[data-mid-boss-id]').forEach(wrap => {
            const midBossId = wrap.dataset.midBossId;
            const chNum = parseInt(midBossId.split('-')[0]);
            const chData = gameData.find(c => c.id === chNum);
            if (!chData) return;
            const midBossStage = chData.stages.find(s => s.id === midBossId);
            if (!midBossStage) return;
            const avgStrength = getMidBossAvgStrength(chData, midBossStage);
            if (avgStrength === null) return;
            const pct = Math.round(avgStrength * 100);
            const colorClass = pct >= 80 ? 'mem-strength-green'
                             : pct >= 60 ? 'mem-strength-yellow'
                             : pct >= 40 ? 'mem-strength-orange'
                             : 'mem-strength-red';
            const fill = wrap.querySelector('.mem-strength-fill');
            const pctEl = wrap.querySelector('.mem-strength-pct');
            if (fill) { fill.style.width = pct + '%'; fill.className = `mem-strength-fill ${colorClass}`; }
            if (pctEl) pctEl.textContent = pct + '%';
        });
    }

    updateSheetTimers();
    stageSheetTimer = setInterval(updateSheetTimers, 60000);
}


let selectedStageForMode = null;

/* [수정] 복습 모드 선택 팝업 (Step 6 클리어 후 전용) */
function openModeSelect(stageId) {
    if (studyModePreference === 'quick') {
        startTraining(stageId, 'quick');
        return;
    }
    if (studyModePreference === 'full') {
        startTraining(stageId, 'full');
        return;
    }
    const modal = document.getElementById('mode-select-modal');
    const container = modal.querySelector('.result-card');

    // 팝업 내용 재구성
    container.innerHTML = `
        <div style="text-align: right;">
            <button onclick="closeModeSelect()" style="background:none; border:none; font-size:1.5rem; color:#95a5a6; cursor:pointer;">✕</button>
        </div>
        <div style="text-align: center; margin-bottom: 20px;">
            <h2 style="margin:0; color:#2c3e50;">${t('review_mode_title')}</h2>
        </div>

        <button class="mode-btn" onclick="confirmMode('quick')" style="background:#fff9c4; border:2px solid #f1c40f; color:#d35400; box-shadow: 0 4px 0 #f39c12;">
            <div class="mode-icon">⚡</div>
            <div class="mode-info">
                <div class="mode-tag" style="background:#f1c40f; color:#d35400;">${t('review_mode_quick_tag')}</div>
                <div class="mode-title">${t('review_mode_quick_title')}</div>
                <div class="mode-desc">${t('review_mode_quick_desc')}</div>
            </div>
        </button>

        <button class="mode-btn" onclick="confirmMode('full')" style="background:white; border:2px solid #bdc3c7; color:#7f8c8d; box-shadow: 0 4px 0 #95a5a6;">
            <div class="mode-icon">📖</div>
            <div class="mode-info">
                <div class="mode-title">${t('review_mode_full_title')}</div>
                <div class="mode-desc">${t('review_mode_full_desc')}</div>
            </div>
        </button>
    `;

    window.selectedStageForMode = stageId;
    modal.style.display = 'flex';
}
// =========================================
// [추가] 기억 다지기 스테이지 오버레이 및 추적 함수
// =========================================

// 기억 다지기 스테이지 리스트를 수집하는 함수
function getForgottenStages() {
    const forgottenList = [];
    for (let chapter of gameData) {
        if (!chapter.stages) continue;
        for (let stage of chapter.stages) {
            // 중간점검/보스전 제외
            if (stage.type === 'boss' || stage.type === 'mid-boss') continue;
            const stageId = stage.id;
            const revStatus = getReviewStatus(stageId);
            if (revStatus.step > 1 && revStatus.isEligible) {
                const m = String(stageId).match(/^(\d+)-(\d+)$/);
                const label = m ? t('stage_title_normal', { ch: m[1], v: m[2] }) : stageId;
                forgottenList.push({
                    stageId,
                    label,
                    step: revStatus.step,
                });
            }
        }
    }
    return forgottenList;
}

// "오늘은 보지 않기" 체크 여부 (오전 6시 기준 날짜 경계)
function isReviewPopupHiddenToday() {
    const today = (typeof getMemoryQuizDate === 'function') ? getMemoryQuizDate() : new Date().toISOString().split('T')[0];
    return localStorage.getItem('kingsRoad_hideReviewPopupDate') === today;
}

function toggleHideReviewPopupToday(checked) {
    if (checked) {
        const today = (typeof getMemoryQuizDate === 'function') ? getMemoryQuizDate() : new Date().toISOString().split('T')[0];
        localStorage.setItem('kingsRoad_hideReviewPopupDate', today);
    } else {
        localStorage.removeItem('kingsRoad_hideReviewPopupDate');
    }
}

// 왕의 길/자유여행 진입 시 1회 자동으로 복습 타이밍 팝업을 띄움 (amenAndStartGame에서 예약, goMap()에서 소비)
function maybeAutoShowReviewPopup() {
    if (!window._pendingReviewPopupCheck) return;
    window._pendingReviewPopupCheck = false;
    const forced = window._forceReviewPopup; window._forceReviewPopup = false;
    if (!forced && isReviewPopupHiddenToday()) return;
    if (getForgottenStages().length === 0 && _blankDueIds().length === 0) return;
    openForgottenStagesOverlay();
}

// 특정 모드의 복습 대기 구절 수를 반환 (모드 전환 없이 조회)
function getReviewCountForMode(mode) {
    let reviewStepMap, nextReviewTimeMap;
    if (mode === activeMode) {
        reviewStepMap = stageReviewStep;
        nextReviewTimeMap = stageNextReviewTime;
    } else if (mode === 'kings') {
        reviewStepMap = kingsRoadData.reviewStep;
        nextReviewTimeMap = kingsRoadData.nextReviewTime;
    } else {
        reviewStepMap = _freeStageReviewStep;
        nextReviewTimeMap = _freeStageNextReviewTime;
    }
    const now = Date.now();
    let count = 0;
    for (const chapter of gameData) {
        if (!chapter.stages) continue;
        for (const stage of chapter.stages) {
            if (stage.type === 'boss' || stage.type === 'mid-boss') continue;
            const step = reviewStepMap[stage.id] || 1;
            const nextTime = nextReviewTimeMap[stage.id] || 0;
            if (step > 1 && now >= nextTime) count++;
        }
    }
    return count;
}

// 기억 다지기 스테이지 오버레이 표시 함수
// 보너스 대기 중인 스테이지 목록 반환 (remaining > 0 이고 아직 대기 시간이 남은 스테이지)
function formatTimeLeft(ms) {
    const min = Math.ceil(ms / 60000);
    if (min < 60) return `${min}분 후`;
    const h = Math.floor(min / 60);
    const m = min % 60;
    return m > 0 ? `${h}시간 ${m}분 후` : `${h}시간 후`;
}

function openForgottenStagesOverlay() {
    let overlay = document.getElementById('forgotten-stages-overlay');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.id = 'forgotten-stages-overlay';
        overlay.style = 'display:flex; position:fixed; z-index:9999; top:0; left:0; width:100vw; height:100vh; background:rgba(44,62,80,0.97); color:#f1c40f; flex-direction:column; align-items:center; justify-content:center; font-size:1.2rem; text-align:center;';
        overlay.innerHTML = `
                <div style="max-width:90vw; font-size:1.1em; line-height:1.5; font-weight:bold; color:#fff; text-shadow:0 2px 8px #222; margin-bottom:18px; flex-shrink: 0;">
                    ${t('forgotten_overlay_title')}<br><span style="font-size:0.72em; font-weight:600; color:#cfd8dc;">${t('forgotten_overlay_subtitle')}</span>
                </div>
                <div id="forgotten-stages-list" style="background:rgba(0,0,0,0.3); padding:16px; border-radius:15px; width:90vw; max-width:600px; min-width:220px; margin-bottom:22px; max-height:60vh; overflow-y:auto; flex-shrink: 0;">
                </div>
                <label style="display:flex; align-items:center; gap:8px; color:#bdc3c7; font-size:0.9rem; margin-bottom:20px; cursor:pointer; flex-shrink: 0;">
                    <input type="checkbox" id="forgotten-hide-today-checkbox" onchange="toggleHideReviewPopupToday(this.checked)" style="width:18px; height:18px; cursor:pointer;">
                    ${t('forgotten_overlay_hide_today')}
                </label>
                <button onclick="closeForgottenStagesOverlay()" style="background: #f1c40f; color: #2c3e50; font-size:1.1rem; font-weight:bold; padding: 10px 32px; border-radius: 30px; border:none; box-shadow:0 2px 10px #2224; cursor:pointer; margin-top:0; flex-shrink: 0;">${t('forgotten_overlay_close')}</button>
            `;
        document.body.appendChild(overlay);
    } else {
        overlay.style.display = 'flex';
    }
    const hideCheckbox = document.getElementById('forgotten-hide-today-checkbox');
    if (hideCheckbox) hideCheckbox.checked = isReviewPopupHiddenToday();
    // 리스트 렌더링
    const listDiv = document.getElementById('forgotten-stages-list');
    const forgottenList = getForgottenStages();
    const headHtml = _reviewOverlayHeadHtml(forgottenList);
    if (forgottenList.length === 0) {
        listDiv.innerHTML = headHtml || `<div style="color:#bdc3c7;">${t('forgotten_empty')}</div>`;
        return;
    }
    // 구절 목록은 차분한 줄로 — 맨 위 백지 차례만 상자로 강조한다 (2026-09-28)
    listDiv.innerHTML = headHtml + `<div class="rv-sec">${t('rv_list_title', { n: forgottenList.length })}</div>`;
    for (const item of forgottenList) {
        const btn = document.createElement('button');
        btn.className = 'rv-verse-row';
        btn.innerHTML = `<span class="rv-verse-label">${item.label}</span><span class="rv-verse-step">${t('forgotten_review_step', { step: item.step })}${item.step >= BLANK_FIRST_STEP ? ` <span class="rv-verse-blank">${t('rv_row_blank')}</span>` : ''}</span><span class="rv-verse-go">›</span>`;
        btn.onclick = function () {
            closeForgottenStagesOverlay();
            openModeSelect(item.stageId);
        };
        listDiv.appendChild(btn);
    }
}

/* 복습 목록 맨 위 — ① 오늘 백지 차례(장별로 묶어) ② 복습을 한 번에 끝내는 길 (2026-09-28).
   ② 판단: 한 장에 복습 차례가 2절 이상이면, 차례인 절이 걸친 중간점검 구간들의 절 수를 더해
   **장 전체의 80% 미만이면 중간점검, 이상이면 보스전**. 보스전은 차례가 6절이어도 장 전체를 써야 하고,
   중간점검은 걸친 구간(3~4절)만 쓰면 된다 — 대개 중간점검이 이긴다. 둘 다 클리어하면 차례인 절의 복습이 한꺼번에 처리된다. */
function _reviewOverlayHeadHtml(forgottenList) {
    let html = '';
    const chLabel = (c) => currentLang === 'en' ? `Ch.${c}` : `${c}장`;
    // ① 백지 차례
    const dueIds = _blankDueIds();
    if (dueIds.length) {
        const byCh = {};
        dueIds.forEach(id => { const c = parseInt(id.split('-')[0], 10); byCh[c] = (byCh[c] || 0) + 1; });
        const chips = Object.keys(byCh).map(Number).sort((a, b) => a - b)
            .map(c => `<button class="rv-chip" onclick="closeForgottenStagesOverlay(); openBlankDueScreen()">${t('bd_chip', { ch: c, n: byCh[c] })}</button>`).join('');
        html += `<div class="rv-head rv-blank"><div class="rv-head-title">${t('rv_blank_title')}</div><div class="rv-chips">${chips}</div><div class="rv-head-sub">${t('rv_blank_sub')}</div></div>`;
    }
    // ② 복습을 한 번에
    const byChRev = {};
    (forgottenList || []).forEach(it => {
        const m = String(it.stageId).match(/^(\d+)-(\d+)$/);
        if (m) (byChRev[m[1]] = byChRev[m[1]] || []).push(parseInt(m[2], 10));
    });
    const rows = [];
    Object.keys(byChRev).map(Number).sort((a, b) => a - b).forEach(c => {
        const vs = byChRev[c];
        if (vs.length < 2) return;
        const chData = (typeof gameData !== 'undefined') ? gameData.find(x => x.id === c) : null;
        if (!chData || !chData.stages) return;
        const total = chData.stages.filter(s => /^\d+-\d+$/.test(String(s.id))).length;
        const mids = chData.stages.filter(s => s.type === 'mid-boss' && s.rangeStart && s.rangeEnd);
        const covered = mids.filter(mb => vs.some(v => v >= mb.rangeStart && v <= mb.rangeEnd));
        const sum = covered.reduce((a, mb) => a + (mb.rangeEnd - mb.rangeStart + 1), 0);
        const how = (covered.length && sum < total * 0.8)
            ? t('rv_route_mid', { n: covered.length, ranges: covered.map(mb => `${mb.rangeStart}~${mb.rangeEnd}`).join(', ') })
            : t('rv_route_boss', { total });
        const needBlank = vs.some(v => _blankFirstDue(`${c}-${v}`));   // 간격 3일 된 절은 백지로 깨야 처리된다(10/4)
        rows.push(`<button class="rv-route-row" onclick="closeForgottenStagesOverlay(); openStageSheetForStageId('${c}-1')"><b>${chLabel(c)}</b> ${t('rv_route_due', { n: vs.length })} → ${how}${needBlank ? t('rv_route_blank') : ''}</button>`);
    });
    if (rows.length) html += `<div class="rv-sec">${t('rv_route_title')}</div><div class="rv-route">${rows.join('')}</div>`;
    return html;
}

function closeForgottenStagesOverlay() {
    const overlay = document.getElementById('forgotten-stages-overlay');
    if (overlay) overlay.style.display = 'none';
}

// 오버레이를 열 수 있는 버튼을 홈 화면에 추가하려면 아래 함수를 호출하세요:
