    const mc = _camSeg.maskCv;
    if (mc.width !== w || mc.height !== h) { mc.width = w; mc.height = h; }
    const mctx = mc.getContext('2d', { willReadFrequently: true });
    mctx.clearRect(0, 0, w, h);
    mctx.drawImage(img, 0, 0, w, h);
