    const d = mctx.createImageData(w, h), px = d.data;
    for (let i = 0, j = 0; i < arr.length; i++, j += 4) { px[j] = px[j + 1] = px[j + 2] = 255; px[j + 3] = _camMaskLUT[Math.max(0, Math.min(255, Math.round(arr[i] * 255)))]; }
    mctx.putImageData(d, 0, 0);
