            const t = rnd(), y = hz + (h - hz) * Math.pow(t, 1.6), len = (8 + 60 * t) * M / 720;
            const x = rnd() * w;
            g.strokeStyle = `rgba(255,255,255,${0.25 + rnd() * 0.45})`; g.lineWidth = (0.6 + 1.6 * t) * M / 720;
