        const bands = ['rgba(46,204,113,0.55)', 'rgba(26,188,156,0.5)', 'rgba(130,230,170,0.45)', 'rgba(22,160,133,0.45)', 'rgba(180,255,210,0.35)'];
        g.lineWidth = M * 0.028;
