    // 위 띠
    const topH = 74 * S;
    ctx.fillStyle = '#0d0d12'; ctx.fillRect(0, 0, w, topH);
    ctx.fillStyle = '#f1c40f'; ctx.font = `800 ${30 * S}px "Gowun Dodum", sans-serif`; ctx.textBaseline = 'middle'; ctx.textAlign = 'left';
    ctx.fillText(`📅 ${_cam.label}`, pad, topH / 2);
