const GUILD_DRAGON_HEAD_START = 11; // 머리 시작 레벨 (1-10: 뿔, 11-17: 머리)
const _HORN_NAMES = ['첫째','둘째','셋째','넷째','다섯째','여섯째','일곱째','여덟째','아홉째','열째'];
const _HEAD_NAMES = ['첫째','둘째','셋째','넷째','다섯째','여섯째','일곱째'];
function getDragonLevelName(level) {
    if (!level || level < 1) return '첫째 뿔';
    if (level < GUILD_DRAGON_HEAD_START) return `${_HORN_NAMES[level - 1] || level + '째'} 뿔`;
    return `${_HEAD_NAMES[level - GUILD_DRAGON_HEAD_START] || (level - 10) + '째'} 머리`;
}

// 개인 장비 (에베소서 6장) — index = 성(0=망가진, 1~5)
const PERSONAL_EQUIP_DEFS = {
    sword:       { name: '성령의 검',         icon: '⚔️',  type: 'all' },
    breastplate: { name: '의의 흉배',          icon: '🛡️',  type: 'new' },
    helmet:      { name: '구원의 투구',         icon: '⛑️',  type: 'review' },
    shield:      { name: '믿음의 방패',         icon: '🔰',  type: 'boss' },
    belt:        { name: '진리의 허리띠',       icon: '📿',  type: 'hardship' },
    shoes:       { name: '평안의 복음의 신',    icon: '👟',  type: 'attend' },
};
const PERSONAL_EQUIP_TYPE_DESC = {
    all: '모든 레이드 대미지 · 모든 젬',
    new: '첫 학습 대미지 · 첫 학습 젬',
    review: '복습 대미지 · 복습 젬',
    boss: '보스전·중간점검 대미지 · 보스전·중간점검 젬',
    hardship: '고난 길 대미지',
    attend: '출석한 날 당일 모든 대미지 · 모든 젬',
};
const PERSONAL_EQUIP_EFFECT = [0, 2, 5, 10, 17, 26]; // 성별 효과(%)
const PERSONAL_EQUIP_COST   = [0, 4, 8, 24, 72, 216]; // 해당 성에 도달하는 증분 비늘

// 길드 장비 (계시록) — index = 레벨(0~5)
const GUILD_EQUIP_DEFS = {
    chain:     { name: '큰 쇠사슬',               icon: '⛓️',  desc: '용 최대 HP 감소' },
    blade:     { name: '이한 검',                  icon: '🗡️',  desc: '길드원 전체 대미지 증가' },
    judgment:  { name: '심판하는 권세',             icon: '⚖️',  desc: '주간 비늘 보상 증가' },
    winepress: { name: '맹렬한 진노의 포도주 틀',   icon: '🍇',  desc: '용 처치당 추가 비늘' },
};
const GUILD_EQUIP_CHAIN_REDUCTION = [0, 3, 6, 10, 15, 20];      // 용 HP 감소(%)
const GUILD_EQUIP_BLADE_BONUS     = [0, 3, 6, 10, 15, 20];      // 전체 대미지 증가(%)
const GUILD_EQUIP_JUDGMENT_BONUS  = [0, 10, 20, 30, 40, 50];    // 주간 비늘 보상 증가(%)
const GUILD_EQUIP_WINEPRESS_BONUS = [0, 1, 2, 3, 4, 5];         // 처치당 추가 비늘
const GUILD_EQUIP_CLAW_COST       = [0, 1, 2, 4, 7, 12];        // 해당 레벨 도달 증분 발톱

/* 레이드 HP 표시값 계산
   큰 쇠사슬은 용 HP를 미리 깎아두지 않고, 서버가 대미지를 넣는 시점에 곱해서 적용한다.
   그래서 raidDragonMaxHp에는 '원본'이, raidDragonCurrentHp에는 '감소가 반영된 값'이 저장된다.
   이 둘을 그대로 나누면 아무도 때리지 않은 용이 "20% 피해"로 보이므로,
   서버(kingsroad/index.js의 effectiveMaxHp)와 같은 식으로 실질 최대 HP를 구해 기준을 맞춘다. */
function _getRaidHpView(guild) {
    const maxHp = guild.raidDragonMaxHp || 0;
    const rawCur = guild.raidDragonCurrentHp != null ? guild.raidDragonCurrentHp : maxHp;
    const chainLv = (guild.guildEquipment && guild.guildEquipment.chain) || 0;
    const reductionPct = GUILD_EQUIP_CHAIN_REDUCTION[chainLv] || 0;
    const effectiveMax = Math.round(maxHp * (1 - reductionPct / 100));
    const cur = Math.max(0, Math.min(rawCur, effectiveMax)); // 서버의 Math.min 클램프와 동일
    const remainPct = effectiveMax > 0 ? Math.max(0, Math.round((cur / effectiveMax) * 100)) : 0;
    return { originalMax: maxHp, effectiveMax, cur, remainPct, dealtPct: 100 - remainPct, chainLv, reductionPct };
}

let myPersonalEquipment = {}; // { sword:0, breastplate:0, ... }

let _guildRaidPendingDmg = 0;
let _guildRaidFlushTimer = null;

function _addGuildRaidDamage(type, dedupId) {
    if (!myGuildId) return;

    /* ★ 보스전·중간점검은 **미션 때문에** `checkpointBoss`(일일)와 `dragon`(주간)을 둘 다 부른다.
       그런데 레이드 대미지는 한 번의 클리어에 **한 항목만** 나가야 한다.
       그대로 두면 22절 장의 보스를 잡을 때 (5+7)×22 = 264가 들어갔다 — 의도는 7×22 = 154다.
       (2026-09-11 수정. 이전 CLAUDE.md는 이 이중 발동을 '의도된 구조'로 적어뒀으나 잘못이었다.)

       → `checkpointBoss`는 대미지를 내지 않고, **`dragon` 한 곳에서 스테이지 종류로 갈라 쓴다.**
         중간점검 = 5 × 구간 절수 / 보스전 = 7 × 장 절수.

       왜 `dragon`에 매다는가: 이쪽은 **조건 없이 항상** 호출된다.
       `checkpointBoss`는 `!isAlreadyClearedToday`(자정 경계)일 때만 불리는데
       레이드 중복 제거는 오전 6시 경계라, 그 사이 구간에서 대미지가 통째로 누락된다. */
    let effType = type;
    if (type === 'checkpointBoss') return; // 미션 전용 — 대미지는 dragon 쪽에서 한 번만
    if (type === 'dragon' && typeof dedupId === 'string' && dedupId.includes('-mid-')) {
        effType = 'checkpointBoss'; // 중간점검 몫 (5 × 구간 절수)
    }
    type = effType;

    const base = GUILD_RAID_DAMAGE[type];
    if (!base) return;

    if (dedupId != null) {
        const today = new Date(Date.now() - 6 * 3600000).toLocaleDateString('sv');
        let log;
        try { log = JSON.parse(localStorage.getItem('kingsRoad_raidDailyDmg') || '{}'); } catch(e) { log = {}; }
        if (log.date !== today) log = { date: today, done: [] };
        const key = `${dedupId}:${type}`;
        if (log.done.includes(key)) return;
        log.done.push(key);
        localStorage.setItem('kingsRoad_raidDailyDmg', JSON.stringify(log));
    }

    // 구절 수 기반 배율 적용
    let dmg = base;
    if (GUILD_RAID_DAMAGE_PER_VERSE.has(type) && dedupId != null) {
        let verseCount = null;
        // 스테이지 ID면 그 스테이지가 실제로 다루는 절 수를 사용
        // (중간점검 = 자기 구간, 보스전 = 장 전체 → targetVerseCount가 둘 다 올바른 값을 가짐)
        if (typeof dedupId !== 'number') {
            const sid = String(dedupId);
            const cNum = parseInt(sid.split('-')[0]);
            const chData = (typeof gameData !== 'undefined') ? gameData.find(c => c.id === cNum) : null;
            const stage = (chData && chData.stages) ? chData.stages.find(s => s.id === sid) : null;
            if (stage && stage.targetVerseCount) verseCount = stage.targetVerseCount;
        }
        // 고난 길 등 장 단위 호출(dedupId가 장 번호)은 장 전체 절 수
        if (verseCount == null) {
            const chNum = typeof dedupId === 'number' ? dedupId : parseInt(String(dedupId).split('-')[0]);
            verseCount = (typeof bibleData !== 'undefined' && bibleData[chNum]) ? bibleData[chNum].length : 20;
        }
        dmg = base * verseCount;
    }

    const eq = myPersonalEquipment;

    // 성령의 검: 모든 대미지
    dmg *= (1 + PERSONAL_EQUIP_EFFECT[eq.sword || 0] / 100);

    // 유형별 장비
    if (type === 'new')
        dmg *= (1 + PERSONAL_EQUIP_EFFECT[eq.breastplate || 0] / 100);
    else if (type === 'review')
        dmg *= (1 + PERSONAL_EQUIP_EFFECT[eq.helmet || 0] / 100);
    else if (type === 'dragon' || type === 'checkpointBoss')
        dmg *= (1 + PERSONAL_EQUIP_EFFECT[eq.shield || 0] / 100);
    else if (type.startsWith('hardship'))
        dmg *= (1 + PERSONAL_EQUIP_EFFECT[eq.belt || 0] / 100);

    // 평안의 복음의 신: 출석한 날 당일
    if (_myGuildStatus.attendedToday)
        dmg *= (1 + PERSONAL_EQUIP_EFFECT[eq.shoes || 0] / 100);

    _guildRaidPendingDmg += Math.round(dmg);
    if (_guildRaidFlushTimer) clearTimeout(_guildRaidFlushTimer);
    _guildRaidFlushTimer = setTimeout(_flushGuildRaidDamage, 5000);
}

async function _flushGuildRaidDamage() {
    _guildRaidFlushTimer = null;
    if (!myGuildId || _guildRaidPendingDmg <= 0) return;
    if (!myTag) return;
    const dmg = _guildRaidPendingDmg;
    _guildRaidPendingDmg = 0;
    try {
        await _callGuildFn('reportRaidDamage', { damage: dmg });
    } catch (e) {
        _guildRaidPendingDmg += dmg; // 실패 시 복구
    }
}

async function _callGuildFn(fnName, data) {
    const fn = firebase.app().functions('asia-northeast3').httpsCallable(fnName);
    const res = await _callWithSaveDocRetry(() => fn({ ...data, myTag }));
    return res.data;
}

/* Cloud Function 호출처럼 지연이 있는 버튼에 로딩 상태를 씌운다.
   버튼을 비활성화하므로 응답 대기 중 중복 클릭도 함께 막힌다.
   성공 시에는 대개 화면을 다시 그려 버튼이 사라지므로, 아직 DOM에 붙어 있을 때만 원래 상태로 되돌린다. */
async function _withButtonLoading(btn, loadingLabel, task) {
    const prevHtml = btn ? btn.innerHTML : null;
    const prevDisabled = btn ? btn.disabled : false;
    const prevMinWidth = btn ? btn.style.minWidth : '';
    // 같은 줄의 형제 버튼(수락/거절 등)도 함께 잠가 이중 실행을 막는다.
    // 원래 비활성이던 버튼은 제외해야 복원 시 되살아나지 않는다.
    const siblings = (btn && btn.parentElement)
        ? Array.from(btn.parentElement.querySelectorAll('button')).filter(b => b !== btn && !b.disabled)
        : [];
    if (btn) {
        // 원래 폭을 유지해 로딩 중 줄 배치가 흔들리지 않게 한다
        const w = btn.offsetWidth;
        if (w) btn.style.minWidth = w + 'px';
        btn.disabled = true;
        // 라벨이 비면 스피너만 — 폭이 좁은 버튼(추방·수락·거절)용
        btn.innerHTML = loadingLabel
            ? `<span class="kr-spinner-btn"></span>${loadingLabel}`
            : `<span class="kr-spinner-btn" style="margin-right:0;"></span>`;
    }
    siblings.forEach(b => { b.disabled = true; });
    try {
        return await task();
    } finally {
        if (btn && btn.isConnected) {
            btn.disabled = prevDisabled;
            btn.innerHTML = prevHtml;
            btn.style.minWidth = prevMinWidth;
        }
        siblings.forEach(b => { if (b.isConnected) b.disabled = false; });
    }
}

function openGuildScreen() {
    closeMoreMenu();
    if (!myTag || myTag === '0000') { showGemToast(0, '닉네임을 먼저 설정해주세요.', true); return; }
    let overlay = document.getElementById('guild-screen-overlay');
    if (overlay) { overlay.style.display = 'flex'; _renderGuildScreen(); return; }

    overlay = document.createElement('div');
    overlay.id = 'guild-screen-overlay';
    overlay.innerHTML = `
        <div class="guild-screen-card">
            <div class="guild-screen-header">
                <span class="guild-screen-title">⚔️ 길드</span>
                <button class="guild-screen-close" onclick="closeGuildScreen()">✕</button>
            </div>
            <div id="guild-screen-body" class="guild-screen-body"></div>
        </div>`;
    document.body.appendChild(overlay);
    _renderGuildScreen();
}

function closeGuildScreen() {
    const overlay = document.getElementById('guild-screen-overlay');
    if (overlay) overlay.style.display = 'none';
}

async function _renderGuildScreen() {
    const body = document.getElementById('guild-screen-body');
    if (!body) return;
    body.innerHTML = '<div class="guild-loading">불러오는 중…</div>';

    try {
        if (!db || !myTag) { body.innerHTML = '<div class="guild-error">서버 연결이 필요합니다.</div>'; return; }

        // 내 길드 ID + 개인 상태 확인
        const prevGuildId = myGuildId;
        const myDoc = await db.collection('leaderboard').doc(myTag).get();
        const myLbData = myDoc.exists ? myDoc.data() : {};
        myGuildId = myLbData.guildId || null;
        myPersonalEquipment = myLbData.personalEquipment || {};
        myDragonScales        = myLbData.dragonScales        || 0;
        myDragonHornFragments = myLbData.dragonHornFragments || 0;
        myDragonHeadSkins     = myLbData.dragonHeadSkins     || 0;

        if (!myGuildId) {
            if (prevGuildId) showGemToast(0, '길드에서 추방되었거나 길드가 해산되었습니다.', true);
            _renderGuildNoGuild(body, myLbData.pendingInvites || []);
            return;
        }

        const guildDoc = await db.collection('guilds').doc(myGuildId).get();
        if (!guildDoc.exists) {
            myGuildId = null;
            if (prevGuildId) showGemToast(0, '길드가 해산되었습니다.', true);
            _renderGuildNoGuild(body, myLbData.pendingInvites || []);
            return;
        }
        _guildData = { id: myGuildId, ...guildDoc.data() };
        const todayStr = _getLocalDateStr();
        const donateInfo = myLbData.guildDonateInfo || { date: '', count: 0 };
        const donateCountToday = donateInfo.date === todayStr ? donateInfo.count : 0;
        _myGuildStatus = {
            pendingReward: myLbData.pendingRaidReward || null,
            attendedToday: myLbData.lastGuildAttend === _get6AMDayStr(),
            donateCountToday,
        };
        _todoFromLb(myLbData); _syncSocialBadges();
        _renderGuildHome(body, _guildData, _myGuildStatus);
    } catch (e) {
        body.innerHTML = `<div class="guild-error">오류가 발생했습니다.<br>${e.message || ''}</div>`;
    }
}

function _renderGuildNoGuild(body, pendingInvites) {
    let inviteHtml = '';
    if (pendingInvites && pendingInvites.length > 0) {
        const cards = pendingInvites.map(inv => {
            const elapsed = Math.floor((Date.now() - inv.sentAt) / 3600000);
            const timeStr = elapsed < 1 ? '방금' : `${elapsed}시간 전`;
            const gid = inv.guildId.replace(/'/g, '');
            return `
            <div class="guild-invite-card">
                <div class="guild-invite-card-name">⚔️ ${escapeHtml(inv.guildName)}</div>
                <div class="guild-invite-card-from">${inv.invitedBy}번 길드장이 초대 · ${timeStr}</div>
                <div class="guild-invite-card-actions">
                    <button class="guild-btn-primary" onclick="_respondGuildInvite(true,'${gid}',this)">수락</button>
                    <button class="guild-btn-secondary" onclick="_respondGuildInvite(false,'${gid}',this)">거절</button>
                </div>
            </div>`;
        }).join('');
        inviteHtml = `<div class="guild-section-title" style="margin-top:0;">📨 길드 초대</div>${cards}`;
    }
    body.innerHTML = `
        <div class="guild-no-guild">
            <div class="guild-no-guild-icon">⚔️</div>
            <div class="guild-no-guild-msg">소속된 길드가 없습니다.</div>
        </div>
        ${inviteHtml}
        <div class="guild-section-title" style="margin-top:${inviteHtml ? 18 : 0}px;">길드 만들기</div>
        <div class="guild-create-wrap">
            <input id="guild-name-input" class="guild-input" type="text" maxlength="12" placeholder="길드 이름 (2~12자)">
            <button class="guild-btn-primary" onclick="_submitCreateGuild(this)">만들기</button>
        </div>
        <div class="guild-section-title" style="margin-top:18px;">코드로 가입 신청</div>
        <div class="guild-create-wrap">
            <input id="guild-code-input" class="guild-input" type="text" maxlength="6" placeholder="가입 코드 6자리" style="text-transform:uppercase;">
            <button class="guild-btn-secondary" onclick="_submitJoinGuild(this)">신청</button>
        </div>`;
}

async function _respondGuildInvite(accept, guildId, btn) {
    await _withButtonLoading(btn, '처리 중…', async () => {
        try {
            const res = await _callGuildFn('respondInvite', { accept, guildId });
            if (accept) {
                myGuildId = res.guildId;
                showGemToast(0, `"${res.guildName}" 길드에 가입되었습니다! 🎉`);
            } else {
                showGemToast(0, '초대를 거절했습니다.');
            }
            _renderGuildScreen();
        } catch (e) {
            showGemToast(0, e.message || '처리 실패', true);
        }
    });
}

async function _buyPersonalEquipment(itemKey, btn) {
    await _withButtonLoading(btn, '처리 중…', async () => {
        try {
            const level = myPersonalEquipment[itemKey] || 0;
            const cost = PERSONAL_EQUIP_COST[level + 1];
            const actionLabel = level === 0 ? '수리' : '강화';
            await _callGuildFn('buyPersonalEquipment', { itemKey });
            myPersonalEquipment[itemKey] = level + 1;
            myDragonScales -= cost;
            showGemToast(0, `${PERSONAL_EQUIP_DEFS[itemKey].name} ${actionLabel} 완료! (🪨${myDragonScales} 남음)`);
            _renderGuildScreen();
        } catch (e) {
            showGemToast(0, e.message || '구매 실패', true);
        }
    });
}

async function _contributeGuildEquipment(itemKey, btn) {
    const guildEquipLevel = (_guildData?.guildEquipment?.[itemKey]) || 0;
    if (guildEquipLevel >= 5) return;
    const cost = GUILD_EQUIP_CLAW_COST[guildEquipLevel + 1];
    const fund = (_guildData?.guildEquipmentFund?.[itemKey]) || 0;
    const amount = Math.min(myDragonHornFragments, cost - fund);
    if (amount <= 0) return;
    await _withButtonLoading(btn, '기여 중…', async () => {
        try {
            const def = GUILD_EQUIP_DEFS[itemKey];
            const res = await _callGuildFn('contributeGuildEquipment', { itemKey, amount });
            myDragonHornFragments = res.newHornFragments;
            if (res.upgraded) {
                showGemToast(0, `${def.name} Lv.${res.newLevel} 달성! (🦷${res.newHornFragments} 남음)`);
            } else {
                showGemToast(0, `🦷${amount} 기여 완료! (${res.newFund}/${cost} 적립)`);
            }
            _renderGuildScreen();
        } catch (e) {
            showGemToast(0, e.message || '기여 실패', true);
        }
    });
}

function _renderGuildHome(body, guild, myStatus = {}) {
    const isLeader = guild.leaderId === myTag;
    const maxMembers = [0, 5, 10, 15, 20, 25][guild.level] || 5;
    const levelXpNeeded = [0, 300, 1000, 3000, 8000][guild.level] || 9999;
    const xpPct = guild.level >= 5 ? 100 : Math.min(100, Math.round((guild.xp / levelXpNeeded) * 100));
    const dragonLevel = guild.raidCurrentDragonLevel || guild.raidDragonLevel || 1;
    const clearedCount = guild.raidClearedCount || 0;
    // 쇠사슬 감소를 반영한 실질 HP 기준 (원본 HP로 나누면 안 때린 용도 피해 입은 것처럼 보인다)
    const hpView = _getRaidHpView(guild);
    const dragonPct = hpView.remainPct;
    const hpDealtPct = hpView.dealtPct;

    const pendingReqs = guild.pendingRequests || [];
    const nicknames = guild.memberNicknames || {};

    // 보상 수령 버튼
    const pr = myStatus.pendingReward;
    const rewardHtml = pr ? (() => {
        const parts = [];
        if (pr.scales)        parts.push(`🪨 비늘 ×${pr.scales}`);
        if (pr.hornFragments) parts.push(`🦷 뿔조각 ×${pr.hornFragments}`);
        if (pr.headSkins)     parts.push(`🐉 머릿가죽 ×${pr.headSkins}`);
        return `
        <div class="guild-section-title">🎁 보상 수령 가능</div>
        <div class="guild-reward-row">
            <span>${parts.join(' &nbsp; ')}</span>
            <button class="guild-btn-primary" onclick="_claimRaidReward(this)">수령</button>
        </div>`;
    })() : '';

    // 일일 활동 버튼
    const donateLeft = 5 - (myStatus.donateCountToday || 0);   // 저장 단위는 그대로(100 = 1) — 500 한 번이 5를 채운다
    const attendBtn = myStatus.attendedToday
        ? `<button class="guild-btn-secondary" disabled>출석 완료 ✓</button>`
        : `<button id="guild-attend-btn" class="guild-btn-secondary" onclick="_guildAttend(this)">출석 체크</button>`;
    const donateBtn = donateLeft <= 0
        ? `<button class="guild-btn-secondary" disabled>기부 완료 ✓</button>`
        : `<button id="guild-donate-btn" class="guild-btn-secondary" onclick="_guildDonate(this)">기부 💎500</button>`;

    // 길드 이름 변경 버튼 (길드장 전용)
    let renameBtn = '';
    if (isLeader) {
        const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
        const lastChangeMs = guild.lastNameChangeAt ? guild.lastNameChangeAt.toMillis() : 0;
        const cooldownRemain = sevenDaysMs - (Date.now() - lastChangeMs);
        if (cooldownRemain > 0) {
            const remainDays = Math.ceil(cooldownRemain / 86400000);
            renameBtn = `<button class="guild-rename-btn" disabled title="${remainDays}일 후 변경 가능" style="opacity:0.4;">✏️</button>`;
        } else {
            renameBtn = `<button class="guild-rename-btn" onclick="_openRenameGuildModal()">✏️</button>`;
        }
    }

    let html = `
        <div class="guild-home-header">
            <div class="guild-home-name">${escapeHtml(guild.name)}${renameBtn}</div>
            <div class="guild-home-meta">Lv.${guild.level} · ${guild.members.length}/${maxMembers}명 · 코드: <strong>${guild.code}</strong></div>
        </div>
        <div class="guild-currency-row">
            <span class="guild-currency-item">🪨 비늘 <strong>${myDragonScales}</strong></span>
            <span class="guild-currency-item">🦷 뿔조각 <strong>${myDragonHornFragments}</strong></span>
            <span class="guild-currency-item">🐉 머릿가죽 <strong>${myDragonHeadSkins}</strong></span>
        </div>
        <div class="guild-xp-wrap">
            <div class="guild-xp-label">${guild.level >= 5 ? 'MAX' : `${guild.xp} / ${levelXpNeeded} XP`}</div>
            <div class="guild-xp-bar"><div class="guild-xp-fill" style="width:${xpPct}%"></div></div>
        </div>

        <div class="guild-section-title">📅 일일 활동</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;padding:0 4px;">
            ${attendBtn}
            ${donateBtn}
        </div>

        ${rewardHtml}

        <div class="guild-section-title">🐉 레이드 · ${getDragonLevelName(dragonLevel)} &nbsp;<span style="font-weight:400;font-size:12px;color:#a080c0;">이번 주 ${clearedCount}마리 처치</span></div>
        <div class="guild-raid-hp-wrap">
            <div class="guild-raid-hp-label">${hpView.cur.toLocaleString()} / ${hpView.effectiveMax.toLocaleString()} HP (${hpDealtPct}% 피해)</div>
            <div class="guild-raid-hp-bar"><div class="guild-raid-hp-fill" style="width:${dragonPct}%"></div></div>
            ${hpView.reductionPct > 0 ? `<div class="guild-raid-chain-note">⛓️ 큰 쇠사슬 -${hpView.reductionPct}% · 원본 ${hpView.originalMax.toLocaleString()} HP</div>` : ''}
        </div>
        <button onclick="_showRaidDamageTable()" style="margin-top:6px;background:none;border:1px solid #6040a0;border-radius:6px;color:#b090e0;font-size:12px;padding:4px 12px;cursor:pointer;width:100%;">대미지 📊</button>`;

    // 기여도 상위 표시
    const contribs = guild.raidContributions || {};
    const contribList = Object.entries(contribs).sort((a, b) => b[1] - a[1]);
    if (contribList.length > 0) {
        html += `<div class="guild-section-title">⚔️ 레이드 기여도</div>`;
        html += `<div class="guild-contrib-wrap">`;
        contribList.slice(0, 5).forEach(([tag, dmg], i) => {
            const nick = nicknames[tag] || tag;
            html += `<div class="guild-contrib-row">
                <span class="guild-contrib-rank">${i + 1}</span>
                <span class="guild-contrib-name">${escapeHtml(nick)}<span class="guild-contrib-tag"> #${tag}</span></span>
                <span class="guild-contrib-dmg">${dmg.toLocaleString()} dmg</span>
            </div>`;
        });
        html += `</div>`;
    }

    // 개인 장비
    html += `<div class="guild-section-title">🧰 개인 장비</div>`;
    html += `<div class="guild-equip-grid">`;
    Object.entries(PERSONAL_EQUIP_DEFS).forEach(([key, def]) => {
        const level = (myPersonalEquipment[key] || 0);
        const isBroken = level === 0;
        const isMax = level >= 5;
        const effect = PERSONAL_EQUIP_EFFECT[level];
        const nextCost = isMax ? null : PERSONAL_EQUIP_COST[level + 1];
        const canAfford = nextCost !== null && myDragonScales >= nextCost;
        const levelLabel = isBroken ? '망가진' : `${level}성`;
        const btnLabel = isBroken ? `수리 (🪨${nextCost})` : isMax ? 'MAX' : `강화 (🪨${nextCost})`;
        html += `<div class="guild-equip-card${isBroken ? ' broken' : ''}">
            <div class="guild-equip-icon">${def.icon}</div>
            <div class="guild-equip-name">${def.name}</div>
            <div class="guild-equip-level">${levelLabel}</div>
            <div class="guild-equip-effect">${PERSONAL_EQUIP_TYPE_DESC[def.type]} +${effect}%</div>
            <button class="guild-equip-btn" ${isMax || !canAfford ? 'disabled' : ''}
                onclick="_buyPersonalEquipment('${key}',this)">${btnLabel}</button>
        </div>`;
    });
    html += `</div>`;

    // 길드 장비
    const guildEquip = guild.guildEquipment || {};
    const guildFund = guild.guildEquipmentFund || {};
    html += `<div class="guild-section-title">🏰 길드 장비</div>`;
    html += `<div class="guild-equip-grid">`;
    Object.entries(GUILD_EQUIP_DEFS).forEach(([key, def]) => {
        const level = guildEquip[key] || 0;
        const isMax = level >= 5;
        const nextCost = isMax ? null : GUILD_EQUIP_CLAW_COST[level + 1];
        const fund = guildFund[key] || 0;
        const remaining = isMax ? 0 : nextCost - fund;
        const canContribute = !isMax && myDragonHornFragments > 0;
        const effectValues = { chain: GUILD_EQUIP_CHAIN_REDUCTION, blade: GUILD_EQUIP_BLADE_BONUS, judgment: GUILD_EQUIP_JUDGMENT_BONUS, winepress: GUILD_EQUIP_WINEPRESS_BONUS };
        const effectVal = effectValues[key][level];
        const effectUnit = key === 'winepress' ? `+${effectVal}비늘/처치` : `${key === 'chain' ? '-' : '+'}${effectVal}%`;
        const fundPct = isMax ? 100 : Math.round((fund / nextCost) * 100);
        const fundBar = isMax ? '' : `<div class="guild-equip-fund-wrap">
            <div class="guild-equip-fund-bar" style="width:${fundPct}%"></div>
            <span class="guild-equip-fund-label">🦴${fund}/${nextCost}</span>
        </div>`;
        const btnLabel = isMax ? 'MAX' : `기여하기 (🦷${Math.min(myDragonHornFragments, remaining)})`;
        html += `<div class="guild-equip-card${level === 0 ? ' broken' : ''}">
            <div class="guild-equip-icon">${def.icon}</div>
            <div class="guild-equip-name">${def.name}</div>
            <div class="guild-equip-level">${level === 0 ? '미구매' : `Lv.${level}`}</div>
            <div class="guild-equip-effect">${def.desc} ${effectUnit}</div>
            ${fundBar}
            <button class="guild-equip-btn" ${isMax || !canContribute ? 'disabled' : ''}
                onclick="_contributeGuildEquipment('${key}',this)">${btnLabel}</button>
        </div>`;
    });
    html += `</div>`;

    // 멤버 목록
    html += `<div class="guild-section-title">👤 멤버 (${guild.members.length}/${maxMembers})</div>`;
    html += `<div class="guild-member-list">`;
    const _memos = _getMemberMemos();
    guild.members.forEach(tag => {
        const nick = nicknames[tag] || tag;
        const isThisLeader = tag === guild.leaderId;
        const memo = _memos[tag] || '';
        html += `<div class="guild-member-row" style="flex-wrap:wrap;gap:2px;">
            <span class="guild-member-name">${escapeHtml(nick)}<span class="guild-member-tag"> #${tag}</span>${isThisLeader ? ' <span class="guild-leader-badge">길드장</span>' : ''}</span>
            <span style="display:flex;align-items:center;gap:4px;margin-left:auto;">
                ${tag !== myTag ? `<button class="guild-btn-gift" onclick="openGiftFruit('${tag}', ${JSON.stringify(nick || '').replace(/"/g, '&quot;')})">🎁</button>` : ''}
                ${isLeader && tag !== myTag ? `<button class="guild-btn-kick" onclick="_kickGuildMember('${tag}',this)">추방</button>` : ''}
                <button onclick="_editMemberMemo('${tag}')" style="background:none;border:1px solid #4a4a6a;border-radius:5px;color:${memo ? '#f1c40f' : '#7070a0'};font-size:11px;padding:2px 6px;cursor:pointer;" title="${escapeHtml(memo || '메모 없음')}">📝</button>
            </span>
            ${memo ? `<div style="width:100%;font-size:11px;color:#a090c0;padding:2px 2px 0;white-space:pre-wrap;word-break:break-all;">${escapeHtml(memo)}</div>` : ''}
        </div>`;
    });
    html += `</div>`;

    // 길드장: 가입 신청 목록 (초대 발송 항목 제외)
    const joinReqs = pendingReqs.filter(r => !r.invitedBy);
    const sentInvites = pendingReqs.filter(r => !!r.invitedBy);
    if (isLeader && joinReqs.length > 0) {
        html += `<div class="guild-section-title">📬 가입 신청 (${joinReqs.length})</div>`;
        joinReqs.forEach(r => {
            const elapsed = Math.floor((Date.now() - r.sentAt) / 3600000);
            const timeStr = elapsed < 1 ? '방금' : `${elapsed}시간 전`;
            html += `<div class="guild-request-row">
                <div class="guild-request-info">
                    <span class="guild-request-name">${escapeHtml(r.nickname || '순례자')}</span>
                    <span class="guild-request-meta">#${r.tag} · ${timeStr}</span>
                </div>
                <div class="guild-request-btns">
                    <button class="guild-btn-accept" onclick="_respondGuildRequest('${r.tag}', true, this)">수락</button>
                    <button class="guild-btn-reject" onclick="_respondGuildRequest('${r.tag}', false, this)">거절</button>
                </div>
            </div>`;
        });
    }
    // 대기 중인 초대 목록
    if (sentInvites.length > 0) {
        html += `<div class="guild-section-title">✉️ 초대 발송 (${sentInvites.length})</div>`;
        sentInvites.forEach(r => {
            const elapsed = Math.floor((Date.now() - r.sentAt) / 3600000);
            const timeStr = elapsed < 1 ? '방금' : `${elapsed}시간 전`;
            html += `<div class="guild-request-row">
                <div class="guild-request-info">
                    <span class="guild-request-name">${escapeHtml(r.nickname || '순례자')}</span>
                    <span class="guild-request-meta">#${r.tag} · ${timeStr} · 수락 대기 중</span>
                </div>
            </div>`;
        });
    }

    // 친구 초대 (길드장만)
    if (isLeader) {
        html += `<div class="guild-section-title" style="margin-top:18px;">친구 초대</div>`;
        html += `<div id="guild-invite-area"><button class="guild-btn-secondary" onclick="_loadGuildInviteList()">친구 목록 보기</button></div>`;
    }

    html += `<div style="margin-top:24px; text-align:center;">
        <button class="guild-btn-leave" onclick="_leaveGuild(this)">${isLeader && guild.members.length <= 1 ? '길드 해산' : isLeader ? '길드장 위임 후 탈퇴' : '길드 탈퇴'}</button>
    </div>`;

    body.innerHTML = html;
}

async function _submitCreateGuild(btn) {
    const input = document.getElementById('guild-name-input');
    if (!input) return;
    const name = input.value.trim();
    if (name.length < 2) { showGemToast(0, '길드 이름을 2자 이상 입력해주세요.', true); return; }
    input.disabled = true;
    await _withButtonLoading(btn, '생성 중…', async () => {
        try {
            const res = await _callGuildFn('createGuild', { name });
            if (res.ok) { showGemToast(0, `길드 "${name}" 생성 완료! 코드: ${res.code}`); _renderGuildScreen(); }
        } catch (e) {
            showGemToast(0, e.message || '길드 생성에 실패했습니다.', true);
            input.disabled = false;
        }
    });
}

async function _submitJoinGuild(btn) {
    const input = document.getElementById('guild-code-input');
    if (!input) return;
    const code = input.value.trim().toUpperCase();
    if (code.length !== 6) { showGemToast(0, '코드는 6자리입니다.', true); return; }
    input.disabled = true;
    await _withButtonLoading(btn, '신청 중…', async () => {
        try {
            const res = await _callGuildFn('joinGuildRequest', { code });
            if (res.ok) {
                if (res.autoAccepted) {
                    myGuildId = res.guildId || null;
                    showGemToast(0, `"${res.guildName}" 길드에 가입되었습니다! 🎉`);
                    _renderGuildScreen();
                } else {
                    showGemToast(0, `"${res.guildName}" 가입 신청 완료! 길드장의 수락을 기다려주세요.`);
                }
            }
        } catch (e) {
            showGemToast(0, e.message || '가입 신청에 실패했습니다.', true);
            input.disabled = false;
        }
    });
}

async function _respondGuildRequest(targetTag, accept, btn) {
    await _withButtonLoading(btn, '', async () => {
        try {
            await _callGuildFn('respondJoinRequest', { guildId: myGuildId, targetTag, accept });
            _renderGuildScreen();
        } catch (e) {
            showGemToast(0, e.message || '처리 실패', true);
        }
    });
}

function _getMemberMemos() {
    try { return JSON.parse(localStorage.getItem('kingsRoad_memberMemos') || '{}'); } catch(e) { return {}; }
}

function _editMemberMemo(tag) {
    // 닉네임은 인자로 받지 않고 길드 데이터에서 조회 (onclick 문맥 주입 방지)
    const nick = (typeof _guildData !== 'undefined' && _guildData && _guildData.memberNicknames && _guildData.memberNicknames[tag]) || tag;
    let overlay = document.getElementById('member-memo-overlay');
    if (overlay) overlay.remove();
    const memos = _getMemberMemos();
    const current = memos[tag] || '';
    overlay = document.createElement('div');
    overlay.id = 'member-memo-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:10000;display:flex;align-items:center;justify-content:center;';
    overlay.innerHTML = `
        <div style="background:#1e1e2e;border-radius:14px;padding:20px;max-width:300px;width:88%;box-shadow:0 8px 32px rgba(0,0,0,0.5);">
            <div style="color:#c8b8e8;font-size:14px;font-weight:700;margin-bottom:12px;">📝 ${escapeHtml(nick)} 메모</div>
            <textarea id="member-memo-input" style="width:100%;box-sizing:border-box;height:80px;background:#12121e;border:1px solid #4a4a6a;border-radius:8px;color:#e0d8f0;font-size:13px;padding:8px;resize:none;" placeholder="나만 보이는 메모">${escapeHtml(current)}</textarea>
            <div style="display:flex;gap:8px;margin-top:12px;">
                <button onclick="_saveMemberMemo('${tag}')" style="flex:1;padding:9px;border-radius:8px;border:none;background:#5040a0;color:#fff;font-size:14px;cursor:pointer;">저장</button>
                <button onclick="document.getElementById('member-memo-overlay').remove()" style="flex:1;padding:9px;border-radius:8px;border:none;background:#3a3a5c;color:#b0a8d0;font-size:14px;cursor:pointer;">취소</button>
            </div>
        </div>`;
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    document.body.appendChild(overlay);
    document.getElementById('member-memo-input').focus();
}

function _saveMemberMemo(tag) {
    const input = document.getElementById('member-memo-input');
    if (!input) return;
    const memos = _getMemberMemos();
    const text = input.value.trim();
    if (text) memos[tag] = text;
    else delete memos[tag];
    localStorage.setItem('kingsRoad_memberMemos', JSON.stringify(memos));
    document.getElementById('member-memo-overlay')?.remove();
    _renderGuildScreen();
}

function _showRaidDamageTable() {
    let overlay = document.getElementById('raid-damage-table-overlay');
    if (overlay) { overlay.remove(); return; }
    overlay = document.createElement('div');
    overlay.id = 'raid-damage-table-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:10000;display:flex;align-items:center;justify-content:center;';
    const rows = [
        ['첫 학습',     '15',       '스테이지당'],
        ['복습',         '5',       '스테이지당'],
        ['중간점검',    '5×절수',   '장당'],
        ['보스전',      '7×절수',   '장당'],
        ['주소의 고난', '2×절수',   '장당'],
        ['구절의 고난', '3×절수',   '장당'],
        ['암송의 고난', '9×절수',   '장당'],
        ['망각의 고난', '10×절수',  '장당'],
    ].map(([name, dmg, limit]) =>
        `<tr><td>${name}</td><td style="text-align:right;font-weight:700;color:#e8c060;">${dmg}</td><td style="text-align:center;color:#8888aa;font-size:11px;">일 1회/${limit}</td></tr>`
    ).join('');
    overlay.innerHTML = `
        <div style="background:#1e1e2e;border-radius:14px;padding:20px;max-width:280px;width:88%;box-shadow:0 8px 32px rgba(0,0,0,0.5);">
            <div style="color:#c8b8e8;font-size:14px;font-weight:700;margin-bottom:12px;">⚔️ 레이드 대미지</div>
            <table style="width:100%;border-collapse:collapse;font-size:13px;color:#e0d8f0;">
                <thead><tr style="color:#9080b0;font-size:11px;">
                    <th style="text-align:left;padding-bottom:6px;">액션</th>
                    <th style="text-align:right;padding-bottom:6px;">대미지</th>
                    <th style="text-align:center;padding-bottom:6px;">제한</th>
                </tr></thead>
                <tbody>${rows}</tbody>
            </table>
            <button onclick="document.getElementById('raid-damage-table-overlay').remove()" style="margin-top:16px;width:100%;padding:9px;border-radius:8px;border:none;background:#3a3a5c;color:#b0a8d0;font-size:14px;cursor:pointer;">닫기</button>
        </div>`;
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    document.body.appendChild(overlay);
}

function _guildConfirm(message, onConfirm, onCancel) {
    let overlay = document.getElementById('guild-confirm-overlay');
    if (overlay) overlay.remove();
    overlay = document.createElement('div');
    overlay.id = 'guild-confirm-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:10000;display:flex;align-items:center;justify-content:center;';
    overlay.innerHTML = `
        <div style="background:#1e1e2e;border-radius:14px;padding:24px 20px;max-width:300px;width:88%;text-align:center;box-shadow:0 8px 32px rgba(0,0,0,0.5);">
            <div style="color:#e8e0f0;font-size:15px;line-height:1.6;margin-bottom:20px;">${message}</div>
            <div style="display:flex;gap:10px;justify-content:center;">
                <button id="guild-confirm-cancel" style="flex:1;padding:10px;border-radius:8px;border:none;background:#3a3a5c;color:#b0a8d0;font-size:14px;cursor:pointer;">취소</button>
                <button id="guild-confirm-ok" style="flex:1;padding:10px;border-radius:8px;border:none;background:#c0392b;color:#fff;font-size:14px;font-weight:700;cursor:pointer;">확인</button>
            </div>
        </div>`;
    document.body.appendChild(overlay);
    overlay.querySelector('#guild-confirm-cancel').onclick = () => { overlay.remove(); if (onCancel) onCancel(); };
    overlay.querySelector('#guild-confirm-ok').onclick = () => { overlay.remove(); onConfirm(); };
}

/* 되돌릴 수 없는 동작(길드 해산)용 — 길드 이름을 그대로 쳐야 확인이 켜진다 (2026-09-17).
   한 길드가 흔적 없이 사라진 뒤에 넣었다. 혼자인 길드가 대부분이라 해산 버튼이 거의 모든 길드장에게 늘 보인다 */
function _guildConfirmTyped(message, requiredText, onConfirm) {
    let overlay = document.getElementById('guild-confirm-overlay');
    if (overlay) overlay.remove();
    overlay = document.createElement('div');
    overlay.id = 'guild-confirm-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:10000;display:flex;align-items:center;justify-content:center;';
    overlay.innerHTML = `
        <div style="background:#1e1e2e;border-radius:14px;padding:24px 20px;max-width:300px;width:88%;text-align:center;box-shadow:0 8px 32px rgba(0,0,0,0.5);">
            <div style="color:#e8e0f0;font-size:15px;line-height:1.6;margin-bottom:12px;">${message}</div>
            <div style="color:#a080c0;font-size:13px;margin-bottom:8px;">확인하려면 길드 이름 <b style="color:#f1c40f;">${escapeHtml(requiredText)}</b> 을(를) 그대로 입력하세요</div>
            <input id="guild-confirm-input" type="text" autocomplete="off" placeholder="${escapeHtml(requiredText)}" style="width:100%;box-sizing:border-box;padding:10px;border-radius:8px;border:1px solid #3a3a5c;background:#12121c;color:#fff;font-size:15px;text-align:center;margin-bottom:14px;">
            <div style="display:flex;gap:10px;justify-content:center;">
                <button id="guild-confirm-cancel" style="flex:1;padding:10px;border-radius:8px;border:none;background:#3a3a5c;color:#b0a8d0;font-size:14px;cursor:pointer;">취소</button>
                <button id="guild-confirm-ok" disabled style="flex:1;padding:10px;border-radius:8px;border:none;background:#c0392b;color:#fff;font-size:14px;font-weight:700;cursor:pointer;opacity:0.4;">해산</button>
            </div>
        </div>`;
    document.body.appendChild(overlay);
    const input = overlay.querySelector('#guild-confirm-input');
    const ok = overlay.querySelector('#guild-confirm-ok');
    input.oninput = () => { const match = input.value.trim() === String(requiredText).trim(); ok.disabled = !match; ok.style.opacity = match ? '1' : '0.4'; };
    overlay.querySelector('#guild-confirm-cancel').onclick = () => overlay.remove();
    ok.onclick = () => { if (ok.disabled) return; overlay.remove(); onConfirm(); };
    setTimeout(() => input.focus(), 50);
}

async function _kickGuildMember(targetTag, btn) {
    _guildConfirm(`정말 #${targetTag} 을(를)<br>길드에서 추방하시겠습니까?`, async () => {
        await _withButtonLoading(btn, '', async () => {
            try {
                await _callGuildFn('kickGuildMember', { targetTag });
                showGemToast(0, `#${targetTag} 을(를) 추방했습니다.`);
                _renderGuildScreen();
            } catch (e) {
                showGemToast(0, e.message || '추방 실패', true);
            }
        });
    });
}

async function _leaveGuild(btn) {
    const isLeader = _guildData && _guildData.leaderId === myTag;
    const memberCount = _guildData ? _guildData.members.length : 1;
    const msg = isLeader && memberCount > 1
        ? '정말 탈퇴하시겠습니까?<br><small style="color:#a080c0;">길드장이 다음 멤버에게 자동 위임됩니다.</small>'
        : isLeader
        ? '정말 길드를 해산하시겠습니까?<br><small style="color:#a080c0;">모든 멤버가 길드에서 제거됩니다.</small>'
        : '정말 길드를 탈퇴하시겠습니까?';
    const run = async () => {
        await _withButtonLoading(btn, '처리 중…', async () => {
            try {
                await _callGuildFn('leaveGuild', {});
                const leaveMsg = isLeader && memberCount > 1
                    ? '길드장을 위임하고 탈퇴했습니다.'
                    : isLeader
                    ? '길드를 해산했습니다.'
                    : '길드를 탈퇴했습니다.';
                myGuildId = null; _guildData = null;
                showGemToast(0, leaveMsg);
                _renderGuildScreen();
            } catch (e) {
                showGemToast(0, e.message || '탈퇴 실패', true);
            }
        });
    };
    // 해산은 되돌릴 수 없다 — 길드 이름을 직접 쳐야 한다
    if (isLeader && memberCount <= 1) _guildConfirmTyped(msg + '<br><small style="color:#e74c3c;">되돌릴 수 없습니다.</small>', _guildData.name || '', run);
    else _guildConfirm(msg, run);
}

async function _guildAttend(btn) {
    await _withButtonLoading(btn, '출석 중…', async () => {
        try {
            const res = await _callGuildFn('guildAttend', {});
            if (res.alreadyDone) { showGemToast(0, '오늘 이미 출석했습니다.', true); return; }
            if (res.levelUp) showGemToast(0, `길드 레벨 업! Lv.${res.newLevel} 🎉`);
            else showGemToast(0, `출석 완료! 길드 경험치 +${res.xpGained} XP`);
            _myGuildStatus.attendedToday = true;
            _todoSocial.attended = true; _syncSocialBadges();
            if (_guildData) { _guildData.xp = res.newXp; _guildData.level = res.newLevel; }
            const body = document.getElementById('guild-screen-body');
            if (body) _renderGuildHome(body, _guildData, _myGuildStatus);
        } catch (e) { showGemToast(0, e.message || '출석 실패', true); }
    });
}

function _guildDonate(btn) {
    // 하루 한 번 💎500 (9/30 — 100씩 다섯 번 누르던 것을 합쳤다)
    if (myGems < 500) { showGemToast(0, '보석이 부족합니다. (필요: 💎500)', true); return; }
    // 로딩 표시는 확인을 누른 뒤에 — 확인 대화상자가 떠 있는 동안 "기부 중"이 보이면 오해를 준다
    _guildConfirm('보석 500개를 기부하시겠습니까?', async () => {
        await _withButtonLoading(btn, '기부 중…', async () => {
            try {
                const res = await _callGuildFn('guildDonate', { gems: 500 });
                if (res.alreadyDone) { showGemToast(0, '오늘은 이미 기부했습니다.', true); return; }
                myGems -= 500;
                saveGameData();
                if (res.levelUp) showGemToast(0, `길드 레벨 업! Lv.${res.newLevel} 🎉`);
                else showGemToast(0, `기부 완료! 길드 경험치 +${res.xpGained} XP`);
                _myGuildStatus.donateCountToday = res.todayCount;
                if (_guildData) { _guildData.xp = res.newXp; _guildData.level = res.newLevel; }
                const body = document.getElementById('guild-screen-body');
                if (body) _renderGuildHome(body, _guildData, _myGuildStatus);
            } catch (e) { showGemToast(0, e.message || '기부 실패', true); }
        });
    });
}

async function _claimRaidReward(btn) {
    await _withButtonLoading(btn, '수령 중…', async () => {
        try {
            const res = await _callGuildFn('claimRaidReward', {});
            if (!res.ok || (!res.hornFragments && !res.headSkins && !res.scales)) { showGemToast(0, '수령할 보상이 없습니다.', true); return; }
            myDragonHornFragments += res.hornFragments || 0;
            myDragonHeadSkins     += res.headSkins     || 0;
            myDragonScales        += res.scales        || 0;
            saveGameData();
            const rewardParts = [];
            if (res.scales)        rewardParts.push(`🪨 비늘 +${res.scales}`);
            if (res.hornFragments) rewardParts.push(`🦷 뿔조각 +${res.hornFragments}`);
            if (res.headSkins)     rewardParts.push(`🐉 머릿가죽 +${res.headSkins}`);
            showGemToast(0, `보상 수령 완료! ${rewardParts.join(' · ')}`);
            _renderGuildScreen();
        } catch (e) { showGemToast(0, e.message || '수령 실패', true); }
    });
}

async function _loadGuildInviteList() {
    const area = document.getElementById('guild-invite-area');
    if (!area) return;
    area.innerHTML = '<div class="guild-loading">불러오는 중…</div>';
    try {
        const myDoc = await db.collection('leaderboard').doc(myTag).get();
        const friends = myDoc.data()?.friends || [];
        const guildMembers = new Set(_guildData?.members || []);
        const nonMemberFriends = friends.filter(f => !guildMembers.has(f));
        if (nonMemberFriends.length === 0) {
            area.innerHTML = '<div class="guild-empty-msg">초대 가능한 친구가 없습니다.</div>';
            return;
        }
        const nicknames = _guildData?.memberNicknames || {};
        let html = '';
        for (const tag of nonMemberFriends) {
            const memo = getFriendMemo(tag);
            const label = memo || `#${tag}`;
            html += `<div class="guild-invite-row">
                <span class="guild-invite-name">${label}</span>
                <button class="guild-btn-invite" onclick="_inviteToGuild('${tag}', this)">초대</button>
            </div>`;
        }
        area.innerHTML = html;
    } catch (e) {
        area.innerHTML = `<div class="guild-error">불러오기 실패</div>`;
    }
}

async function _inviteToGuild(friendTag, btn) {
    if (btn) { btn.disabled = true; btn.innerHTML = '<span class="kr-spinner-btn"></span>발송 중…'; }
    try {
        await _callGuildFn('inviteToGuild', { friendTag });
        if (btn) { btn.textContent = '✓ 발송'; }
        showGemToast(0, '초대를 발송했습니다.');
    } catch (e) {
        showGemToast(0, e.message || '초대 실패', true);
        if (btn) { btn.disabled = false; btn.textContent = '초대'; }
    }
}

function _openRenameGuildModal() {
    const currentName = _guildData ? escapeHtml(_guildData.name) : '';
    const overlay = document.createElement('div');
    overlay.id = 'guild-rename-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);display:flex;align-items:center;justify-content:center;z-index:9999;';
    overlay.innerHTML = `
        <div style="background:#1a0e2e;border:1px solid #5a3a8a;border-radius:14px;padding:24px;width:90%;max-width:340px;">
            <div style="font-size:17px;font-weight:700;color:#e0c0ff;margin-bottom:16px;">길드 이름 변경</div>
            <div style="color:#9070b0;font-size:13px;margin-bottom:10px;">현재: ${currentName}</div>
            <input id="guild-rename-input" style="width:100%;box-sizing:border-box;background:#0d0720;border:1px solid #5a3a8a;border-radius:8px;padding:10px 12px;color:#e0c0ff;font-size:15px;margin-bottom:6px;outline:none;" type="text" maxlength="10" placeholder="새 이름 (한글 10자 이하)">
            <div id="guild-rename-hint" style="font-size:12px;color:#9070b0;min-height:18px;margin-bottom:16px;">최대 10자 · 중복 불허 · 7일 쿨다운</div>
            <div style="display:flex;gap:8px;">
                <button class="guild-btn-primary" onclick="_confirmRenameGuild()">변경</button>
                <button class="guild-btn-secondary" onclick="document.getElementById('guild-rename-modal').remove()">취소</button>
            </div>
        </div>`;
    document.body.appendChild(overlay);
    const inp = overlay.querySelector('#guild-rename-input');
    if (inp) inp.focus();
}

async function _confirmRenameGuild() {
    const input = document.getElementById('guild-rename-input');
    const hint = document.getElementById('guild-rename-hint');
    const modal = document.getElementById('guild-rename-modal');
    if (!input) return;
    const newName = input.value.trim();
    if ([...newName].length < 2) { if (hint) { hint.textContent = '2자 이상 입력해주세요.'; hint.style.color = '#e05050'; } return; }
    if ([...newName].length > 10) { if (hint) { hint.textContent = '10자를 초과할 수 없습니다.'; hint.style.color = '#e05050'; } return; }
    const btns = modal ? modal.querySelectorAll('button') : [];
    btns.forEach(b => b.disabled = true);
    if (hint) { hint.textContent = '변경 중…'; hint.style.color = '#9070b0'; }
    try {
        const res = await _callGuildFn('renameGuild', { newName });
        if (modal) modal.remove();
        showGemToast(0, `길드 이름이 '${res.newName}'으로 변경되었습니다.`);
        _renderGuildScreen();
    } catch (e) {
        if (hint) { hint.textContent = e.message || '변경 실패'; hint.style.color = '#e05050'; }
        btns.forEach(b => b.disabled = false);
    }
}

// ===== 길드 시스템 끝 =====

/* [시스템] 지난주 ID 구하기 */
function getLastWeekId() {
    const today = new Date();
    const lastWeek = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 7);
    return getWeekId(lastWeek);
}

/* [시스템] 주간 마감 당일인지 확인 (일요일) */
function isLastDayOfWeek() {
    const today = new Date();
    return today.getDay() === 0; // 일요일
}

/* [시스템] 현재 월간 ID 구하기 (YYYYMM 형식) */
function getMonthId(dateObj) {
    const d = dateObj ? new Date(dateObj) : new Date();
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    return `${year}${month}`;
}

/* [시스템] 지난달 ID 구하기 */
function getLastMonthId() {
    const today = new Date();
    const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
    return getMonthId(lastMonth);
}

/* [시스템] 월간 마감 당일인지 확인 (1일) */
function isFirstDayOfMonth() {
    const today = new Date();
    return today.getDate() === 1;
}

/* [시스템] 출석 및 주간 리그 결산 (핵심 로직) */
function checkDailyLogin() {
    const today = getMemoryQuizDate(); // 오전 6시 기준
    const lastDate = localStorage.getItem('lastPlayedDate');

    // 이 스위치가 true가 되면 마지막에 무조건 저장을 실행합니다.
    let needsSave = false;

    // 1. 미션 데이터 안전장치
    if (!missionData) missionData = { weekly: { attendance: 0, claimed: [false, false, false] } };
    if (!missionData.weekly) missionData.weekly = { attendance: 0, claimed: [false, false, false] };

    // 2. 주간 초기화 (새로운 주가 시작되었는지 확인)
    const currentWeekId = getWeekId();   // ← 승점(랭킹) 주차 — 월요일 0시

    // 🌟 (1) 미션 주간 초기화 — checkMissions()와 **같은 함수·같은 6시 경계**로 (2026-09-28)
    //   예전엔 여기서 자정 기준으로 따로(그것도 일부만) 리셋해 월요일 새벽에 두 번 리셋됐다
    if (_resetWeeklyMissionsIfNeeded(today)) needsSave = true;

    // 🌟 (2) 승점 주간 초기화 (미션과 완전히 독립적으로 따로 검사!)
    if (leagueData.weekId !== currentWeekId) {
        console.log("🔄 승점 주간 리셋 (엇박자 치료 완료!)");

        // 지난주 점수를 백업 필드에 보존 (CF 아카이빙 경쟁조건 방어)
        leagueData.prevWeekId = leagueData.weekId || getLastWeekId();
        leagueData.prevWeekScore = leagueData.myScore || 0;

        // 주간 히스토리에 누적 (최근 12주 보존)
        if (!leagueData.weeklyHistory) leagueData.weeklyHistory = {};
        if (leagueData.prevWeekId && leagueData.prevWeekScore > 0) {
            leagueData.weeklyHistory[leagueData.prevWeekId] = leagueData.prevWeekScore;
            const keys = Object.keys(leagueData.weeklyHistory).sort().reverse();
            if (keys.length > 12) keys.slice(12).forEach(k => delete leagueData.weeklyHistory[k]);
        }

        leagueData.weekId = currentWeekId;
        leagueData.myScore = 0;
        leagueData.stageLog = {};
        needsSave = true;
    }

    // ✨ NEW: 3. 월간 초기화 (새로운 달이 시작되었는지 확인)
    const currentMonthId = getMonthId(); // 예: "202602"

    if (leagueData.monthId !== currentMonthId) {
        console.log("🔄 새로운 달이 시작되었습니다! (월간 리셋)");

        // (1) 지난달 점수를 백업 필드에 보존 (CF 아카이빙 경쟁조건 방어)
        leagueData.prevMonthId = leagueData.monthId || getLastMonthId();
        leagueData.prevMonthlyScore = leagueData.myMonthlyScore || 0;

        // (2) 월간 데이터 초기화
        leagueData.monthId = currentMonthId;
        leagueData.myMonthlyScore = 0; // 월간 점수 0점부터 다시 시작
        needsSave = true; // 🌟 초기화했으니 저장 필수!
    }

    // 4. 일일 출석 체크
    if (lastDate !== today) {
        // 주간 출석 체크는 반드시 updateWeeklyAttendance로 통일
        const currentWeekId = getWeekId();
        updateWeeklyAttendance(today, currentWeekId);

        localStorage.setItem('lastPlayedDate', today);
        needsSave = true;
    }
    // ★ 일일 미션 초기화 — checkMissions()와 **같은 키(missionData.lastLoginDate)** 로 판단한다. (2026-09-16 수정)
    //   예전에는 이 블록이 localStorage의 lastPlayedDate만 보고 돌아서, 부팅 때 checkMissions()가 이미 리셋하고
    //   1.2초 뒤 로그인 미션을 자동 수령(+25pt, +100젬)한 다음, Firestore 동기화가 끝나면서 여기가 **한 번 더**
    //   claimed를 전부 false로 지웠다. 포인트는 남고 미션은 '미수령'으로 돌아가 다음 진행 때 로그인 미션이
    //   두 번째로 수령됐다 — 66명 중 31명이 포인트 = 수령×25 + 25 (2026-09-16 실측). 자동 수령 전엔 드러나지 않던 이중 리셋.
    if (missionData.lastLoginDate !== today) {
        missionData.daily.loginReward = 1; // 접속 시 즉시 완료
        missionData.daily.newClear = 0;
        missionData.daily.differentStages = 0;
        missionData.daily.checkpointBoss = 0;
        missionData.daily.hardship = 0;
        missionData.daily.hardshipAddress = 0;
        missionData.daily.hardshipMemory = 0;
        missionData.daily.hardshipEndurance = 0;
        missionData.daily.hardshipVerse = 0;
        missionData.daily.backup = 0;
        missionData.daily.bibleReadClaimed = 0;
        missionData.daily.claimed = [false, false, false, false, false, false, false, false];
        missionData.lastLoginDate = today; // ★ [버그 수정] checkMissions()와 동기화
        // 심화 일일 미션 리셋
        missionData.advanced = createEmptyAdvancedMissionData(today);
        needsSave = true; // 🌟 출석했으니 저장 필수!
        // 리셋했으면 로그인 미션을 바로 수령 (checkMissions()와 같은 처리)
        setTimeout(() => { if (typeof _autoClaimMissions === 'function') _autoClaimMissions(); }, 1200);
    }

    // [버그 수정] needsSave가 true이면 반드시 저장 (자정 지킴이에서 호출 시 데이터 유실 방지)
    if (needsSave) {
        saveGameData();
    }
}

// [3] 스테이지 클리어 함수 (수정됨)
stageClear = function (type, rewardMultiplier = 1) {
    try {
        // 🌟 [핵심 수술] 훈련 모드 철벽 방어막!
        // 훈련 모드일 때는 보석 계산도, 승점 계산도, 저장도 하지 않고 그냥 함수를 조용히 끝냅니다.
        if (window.isTrainingMode) {
            console.log("⚔️ 집중 훈련 완료! (보상 지급을 스킵합니다.)");
            return; // ➔ 여기서 함수가 즉시 종료됩니다! (아래 계산 코드 무시)
        }
        // 🌟 ---------------------------------------------------------
        const _firstEver = type === 'normal' && !onboardPromise && typeof _isPreFirstClear === 'function' && _isPreFirstClear();   // 🌅 처음으로 한 절 — 지도로 돌아가면 「내일의 약속」
        markOnboardStep('cleared');
        const sId = String(window.currentStageId);
        if (_firstEver && /^\d+-\d+$/.test(sId)) onboardPromise = { at: Date.now(), id: sId };

        // 복습 소요 시간 표본 — 일반 스테이지만. 중간점검·보스전은 단위가 달라 섞으면 안 된다.
        // (집중 훈련은 위 `isTrainingMode` 방어막에서 이미 걸러졌다)
        if (type === 'normal') _recordReviewSample(sId);

        // 변수 호이스팅 문제 방지용 선언
        let verseCnt = 1;

        // ★ [v1.1.0] 직렬 복습 상태 조회
        const reviewStatus = getReviewStatus(sId);
        const isEligible = reviewStatus.isEligible;
        const isFirstClear = reviewStatus.isFirstClear;
        // 구버전 호환: calculateScore 등 내부 호환용
        const isForgotten = isEligible; // 복습 가능 타이밍 = 구 isForgotten 역할 (calculateScore 호환용)

        let baseGem = 0;
        let msg = `${t('clear_success')}\n\n`;

        const lastTime = stageLastClear[sId] || 0;
        const isAlreadyClearedToday = new Date(lastTime).setHours(0, 0, 0, 0) === new Date().setHours(0, 0, 0, 0);
        const currentWeekId = (typeof getWeekId === 'function') ? getWeekId() : null;
        const chNum = parseInt(sId.split('-')[0]);

        // [A] 보스 (챕터 전체) — 중간점검과 동일한 편의 트리거 방식
        if (type === 'boss') {
            const chData = gameData.find(c => c.id === chNum);

            // 챕터 내 모든 노멀 스테이지 일괄 처리
            let subGemTotal = 0;
            let eligibleSubCount = 0;
            let totalSubCount = 0;

            if (chData && chData.stages) {
                chData.stages.forEach(targetStage => {
                    if (targetStage.type !== 'normal') return;
                    const subId = targetStage.id;

                    // 클리어 기록 (게임 진행용 — eligible 여부 무관)
                    if (!stageMastery[subId]) stageMastery[subId] = 0;
                    if (!stageClearDate[subId]) stageClearDate[subId] = getMemoryQuizDate();
                    targetStage.cleared = true;
                    totalSubCount++;

                    // 복습 보상
                    const subStatus = getReviewStatus(subId);
                    const _hold = _bossReviewHold(subId, subStatus);   // ✍️ 3일 뒤 이후 복습은 백지로만 · 백지 판에서 막힌 절
                    if (_hold && window._midBossBlankClear) stageNextReviewTime[subId] = _next6AM();   // 막힌 절은 내일 다시
                    if (subStatus.isEligible && !_hold) {
                        const { earnedGem: earned } = advanceReviewStep(subId);
                        stageMastery[subId]++;
                        subGemTotal += earned;
                        eligibleSubCount++;
                    } else {
                        stageMastery[subId]++;
                        subGemTotal += 10; // 대기 중 최소 보상
                    }
                });
            }

            // ★ 최초 클리어 보너스: targetVerseCount × 50
            let firstClearBonus = 0;
            if (isFirstClear && chData && !bossFirstClearClaimed.has(sId)) {
                const bossStage = chData.stages.find(s => s.id === sId);
                if (bossStage) {
                    firstClearBonus = (bossStage.targetVerseCount || 0) * 50;
                    subGemTotal += firstClearBonus;
                    msg += `💎 최초 클리어 보너스 +${firstClearBonus}개\n`;
                    bossFirstClearClaimed.add(sId);
                }
            }

            baseGem = subGemTotal;
            verseCnt = totalSubCount; // 승점 계산용: 전체 서브스테이지 수 × hearts
            msg += t('msg_boss_clear', { total: totalSubCount, eligible: eligibleSubCount }) + '\n';

            // ★ 미션 업데이트: 보스 처치
            if (!isAlreadyClearedToday) {
                updateMissionProgress('checkpointBoss', sId); // 일일 미션
            }
            updateMissionProgress('advancedCheckpointBoss', sId); // 심화 미션
            updateMissionProgress('dragon', sId); // 레이드 대미지 + 주간 미션
        }
        // [B] 일반 / 중간점검
        else {
            let maxGem = 0;

            if (type === 'mid-boss') {
                const chData = gameData.find(c => c.id === chNum);

                // 서브스테이지 일괄 처리 (중간점검은 편의 트리거 — 자체 보상 없음)
                let subGemTotal = 0;
                let eligibleSubCount = 0;
                let totalSubCount = 0;

                if (chData && chData.stages) {
                    const myIndexInMap = chData.stages.findIndex(s => s.id === sId);
                    for (let i = myIndexInMap - 1; i >= 0; i--) {
                        const targetStage = chData.stages[i];
                        if (targetStage.type === 'boss' || targetStage.type === 'mid-boss') break;
                        const subId = targetStage.id;

                        // 클리어 기록 (게임 진행용 — eligible 여부 무관)
                        if (!stageMastery[subId]) stageMastery[subId] = 0;
                        if (!stageClearDate[subId]) stageClearDate[subId] = getMemoryQuizDate();
                        targetStage.cleared = true;
                        totalSubCount++;

                        // 복습 보상
                        const subStatus = getReviewStatus(subId);
                        const _hold = _bossReviewHold(subId, subStatus);   // ✍️ 3일 뒤 이후 복습은 백지로만 · 백지 판에서 막힌 절
                        if (_hold && window._midBossBlankClear) stageNextReviewTime[subId] = _next6AM();
                        if (subStatus.isEligible && !_hold) {
                            const { earnedGem: earned } = advanceReviewStep(subId);
                            stageMastery[subId]++;
                            subGemTotal += earned;
                            eligibleSubCount++;
                        } else {
                            stageMastery[subId]++;
                            subGemTotal += 10; // 대기 중 최소 보상
                        }
                    }
                }

                maxGem = subGemTotal;
                verseCnt = totalSubCount; // 승점 계산용: 전체 서브스테이지 수 × hearts
                msg += t('msg_midboss_clear', { total: totalSubCount, eligible: eligibleSubCount }) + '\n';

                // ★ 미션 업데이트: 중보 처치
                if (!isAlreadyClearedToday) {
                    updateMissionProgress('checkpointBoss', sId); // 레이드 대미지 + 일일 미션
                    updateMissionProgress('advancedMidBoss', sId); // 심화 미션 (중간점검 전용)
                }
                updateMissionProgress('dragon', sId); // 레이드 대미지 + 주간 미션
            }
            else {
                // ★ [v1.1.0] 일반 스테이지: 직렬 복습 시스템 적용
                verseCnt = 1;

                if (isEligible && window._reviewNoAdvance === sId) {   // ✍️ 백지 먼저 복습에서 막힘 — 단계 그대로, 내일 다시
                    window._reviewNoAdvance = null;
                    stageNextReviewTime[sId] = _next6AM();
                    maxGem = 10;
                    msg += `${t('clear_review_hold')}\n`;
                } else if (isEligible) {
                    const completingStep = reviewStatus.step;
                    const advResult = advanceReviewStep(sId);
                    maxGem = advResult.earnedGem;
                    window._lastClearOutcome = advResult.outcome;
                    if (completingStep === 1) {
                        msg += `${t('clear_first_study', { gem: maxGem })}\n`;
                    } else {
                        msg += `${t('clear_review_nth', { n: completingStep, gem: maxGem })}\n`;
                    }
                } else {
                    maxGem = 10;
                    const remainMin = Math.ceil(reviewStatus.remainMs / 60000);
                    const timeStr = remainMin >= 60
                        ? t(remainMin % 60 > 0 ? 'clear_wait_hours' : 'clear_wait_hours_only', { h: Math.floor(remainMin / 60), m: remainMin % 60 })
                        : t('clear_wait_mins', { m: remainMin });
                    msg += `${t('clear_review_wait', { time: timeStr })}\n`;
                }

                // ★ 미션 업데이트
                // 복습 모드, 전체 학습 모드, 신규 모드 모두 카운트
                updateMissionProgress('new', sId); // 스테이지 클리어 시 무조건 카운트

                // 다양성 미션: 오늘 처음 클리어하는 스테이지라면 (복습/전체학습/신규 모두 적용)
                if (!isAlreadyClearedToday) {
                    updateMissionProgress('differentStage');
                }
            }

            baseGem = maxGem;
        }

        // 🌟 '오늘 완료' 뱃지를 위해 클리어 시각은 무조건 갱신
        stageLastClear[sId] = Date.now();

        // ★ [보통 모드 보상 배율 적용]
        if (rewardMultiplier !== 1) {
            baseGem = Math.floor(baseGem * rewardMultiplier);
        }

        // ★ [개인 장비 젬 보너스]
        {
            const eq = myPersonalEquipment || {};
            let equipGemMult = 1 + PERSONAL_EQUIP_EFFECT[eq.sword || 0] / 100;
            if (type === 'boss' || type === 'mid-boss')
                equipGemMult += PERSONAL_EQUIP_EFFECT[eq.shield || 0] / 100;
            else if (isEligible && reviewStatus.step === 1)
                equipGemMult += PERSONAL_EQUIP_EFFECT[eq.breastplate || 0] / 100;
            else if (isEligible && reviewStatus.step > 1)
                equipGemMult += PERSONAL_EQUIP_EFFECT[eq.helmet || 0] / 100;
            if (_myGuildStatus && _myGuildStatus.attendedToday)
                equipGemMult += PERSONAL_EQUIP_EFFECT[eq.shoes || 0] / 100;
            if (equipGemMult > 1)
                baseGem = Math.floor(baseGem * equipGemMult);
        }

        // ★ [깨달음의 경지 보너스 적용]
        const collectionScore = getCurrentCollectionScore();
        const rankBuff = getCollectionRank(collectionScore);
        let buffMsg = "";

        // 보석 보너스
        if (rankBuff.gemBonus > 0) {
            baseGem = Math.floor(baseGem * (1 + rankBuff.gemBonus / 100));
            buffMsg += `${t('clear_buff_gem', { n: rankBuff.gemBonus })}\n`;
        }

        // ★ [4회 이상 클리어 시 보상 제한]
        let scoreType = (type === 'boss') ? 'boss' : (type === 'mid-boss' ? 'mid-boss' : 'normal');

        // 재도전 보너스가 자동으로 포함됨 (calculateScore 내부에서 보너스 소진)
        const scoreResult = calculateScore(sId, scoreType, verseCnt, playerHearts, isForgotten);

        // ★ 중간점검 빈칸·백지: 승점은 고난 엔진이 구절 단위로 이미 지급했다.
        // 여기서 또 주면 같은 한 번의 암송에 두 번 지급된다. 보석은 정상 지급.
        if (window._midBossBlankClear) scoreResult.score = 0;

        // ★ 빠른 복습을 백지로 해서 백지레벨이 제때 올랐다면: 복습 승점(밭 × 스텝 배율)과 백지레벨 승점(밭 × 상자 배율) 중
        //   **큰 쪽 하나만**. 같은 한 번의 시도에 두 축이 동시에 걸리는 유일한 자리라 이중 지급을 막는다 (2026-09-28)
        let _qbShown = null;
        if (window._quickBlankBonus && window._quickBlankBonus.sid === String(sId) && type === 'normal') {
            const qb = window._quickBlankBonus;
            window._quickBlankBonus = null;
            if (qb.mult > (scoreResult.reviewMultiplier || 1)) {
                checkBoosterStatus();
                scoreResult.score = Math.floor(playerHearts * qb.mult * boosterData.multiplier);
                scoreResult.seeds = qb.mult;
                _qbShown = qb;
            }
        }

        // ★ 월말 23시 이후 승점 차단 체크
        if (scoreResult.blocked) {
            msg += `\n⚠️ ${scoreResult.blockReason}\n\n`;
            msg += `${t('clear_score_blocked_gem')}\n`;
            scoreResult.score = 0;
        }

        scoreResult.score = Math.floor(scoreResult.score);

        // 승점 보너스 (차단되지 않았을 때만)
        if (!scoreResult.blocked && rankBuff.scoreBonus > 0) {
            scoreResult.score = Math.floor(scoreResult.score * (1 + rankBuff.scoreBonus / 100));
            buffMsg += `${t('clear_buff_score', { n: rankBuff.scoreBonus })}\n`;
        }
        if (_qbShown) {
            buffMsg += `${t('clear_blank_lv_mult', { lv: _qbShown.lv, n: _qbShown.mult })}
`;
        } else
        // 복습 배율 표시 — 예전 ×1.5는 어디에도 안 보였다
        if (scoreResult.reviewMultiplier > 1) {
            buffMsg += `${t('clear_review_mult', { n: (Math.round(scoreResult.reviewMultiplier * 10) / 10) })}
`;
        }
        // ★ 승점 적립은 여기서 한 번 (_addLeagueScore 주석 참고)
        _addLeagueScore(scoreResult.score);
        // 오늘 뿌린 씨 — 중간점검·보스전 빈칸·백지는 고난 엔진이 구절마다 이미 셌다
        if (!window._midBossBlankClear) _noteDailySeeds(scoreResult.seeds);

        // 정확도 보너스
        let adjustedWrongCount = Math.max(0, wrongCount - rankBuff.wrongCorrection);
        let accuracyRate = (type === 'boss' || type === 'mid-boss')
            ? Math.max(0.1, (100 - (adjustedWrongCount * 5)) / 100)
            : Math.max(0.1, (100 - (adjustedWrongCount * 10)) / 100);

        if (rankBuff.wrongCorrection > 0) {
            buffMsg += `${t('clear_buff_wrong', { n: rankBuff.wrongCorrection })}\n`;
        }

        const baseGemBeforeAccuracy = baseGem; // ★ 정확도 적용 전 값 저장
        baseGem = Math.floor(baseGem * accuracyRate);

        // 성전 보너스
        const currentCastle = castleBlueprints[myCastleLevel];
        const bonusPercent = currentCastle ? currentCastle.bonus : 0;
        let castleBonusGem = Math.floor(baseGem * (bonusPercent / 100));
        let totalGem = baseGem + castleBonusGem;

        // 퍼펙트 보너스
        let perfectBonus = 0;
        if (adjustedWrongCount === 0) {
            perfectBonus = Math.floor(baseGem * 0.1);
            totalGem += perfectBonus;
            if (typeof SoundEffect !== 'undefined') SoundEffect.playLevelUp();
            updateStats('perfect', 1);
        }

        const returnExtra = _returnBoostExtra(totalGem);   // 돌아온 순례자 — 암송 보석 2배
        totalGem += returnExtra;
        myGems += totalGem;
        updateStats('gem_get', totalGem);
        window._lastClearGem = baseGemBeforeAccuracy; // 결과 모달용 (정확도 적용 전 기본 보석 수)

        if (!stageMastery[sId]) stageMastery[sId] = 0;
        stageMastery[sId]++;
        if (!stageClearDate[sId]) stageClearDate[sId] = getMemoryQuizDate();

        const accPercent = Math.floor(accuracyRate * 100);

        // 깨달음 보너스 메시지 추가
        if (buffMsg) {
            msg += buffMsg;
        }

        // 초회 클리어 시 상세 정보 표시
        if (!isAlreadyClearedToday) {
            msg += `\n━━━━━━━━━━━━━━━━\n`;

            if (type === 'mid-boss' || type === 'boss') {
                msg += `${t('clear_base_gem_verse', { gem: baseGemBeforeAccuracy, cnt: verseCnt })}\n`;
            } else {
                msg += `${t('clear_base_gem', { gem: baseGemBeforeAccuracy })}\n`;
            }

            msg += `${t('clear_accuracy', { pct: accPercent, wrong: adjustedWrongCount, gem: baseGem })}\n`;
            msg += `${t('clear_castle_bonus', { gem: castleBonusGem })}\n`;
            if (perfectBonus > 0) {
                msg += `${t('clear_perfect_bonus', { gem: perfectBonus })}\n`;
            }
            const scoreLabel = scoreResult.boosterMultiplier > 1 ? `${scoreResult.score} ⚡×${scoreResult.boosterMultiplier}` : scoreResult.score;
            msg += `${t('clear_score', { score: scoreLabel })}\n`;
            if (returnExtra > 0) msg += `${t('clear_return_bonus', { gem: returnExtra })}\n`;
            msg += `${t('clear_total_gem', { gem: totalGem })}`;
        } else {
            msg += `${t('clear_repeat_accuracy', { pct: accPercent, wrong: adjustedWrongCount })}\n`;
            if (perfectBonus > 0) {
                msg += `${t('clear_repeat_perfect', { gem: perfectBonus })}\n`;
            }
            const scoreLabel = scoreResult.boosterMultiplier > 1 ? `${scoreResult.score} ⚡×${scoreResult.boosterMultiplier}` : scoreResult.score;
            msg += `${t('clear_score', { score: scoreLabel })}\n`;
            if (returnExtra > 0) msg += `${t('clear_return_bonus', { gem: returnExtra })}\n`;
            msg += `${t('clear_repeat_gem', { gem: totalGem, castle: castleBonusGem })}`;
        }
        if (typeof triggerConfetti === 'function') triggerConfetti();

        /* [3] 클리어 횟수 기록 (함수 맨 끝부분, alert 뜨기 전) */
        if (type === 'boss' || type === 'mid-boss') {
            updateStats('boss_kill', 1);
        } else {
            updateStats('verse_clear', 1);
        }

        // 중간점검 빈칸·백지는 고난 결과 화면이 이어서 뜨므로 클리어 alert을 겹치지 않는다
        if (!window._suppressClearAlert) alert(msg);
        updateGemDisplay();
        saveGameData();
        syncToFirestore(); // [Firestore] 스테이지 클리어
        updateKingsRoadHomeInfo();
    } catch (error) {
        console.error("클리어 처리 중 오류:", error);
        alert(t('alert_error_msg', { msg: error.message }));
        quitGame(isFocusedTrainingSession() ? 'home' : 'map');
    }
};

//[1] 구간별 보상 계산 함수 (시작/끝 지정 가능)//
function calculateProgressiveReward(chNum, count, startVerse = 1) {
    let totalGem = 0;
    let effectiveVerses = 0;
    let isReduced = false;

    const today = new Date().setHours(0, 0, 0, 0);

    // startVerse부터 count(끝번호)까지 루프
    for (let i = startVerse; i <= count; i++) {
        const subId = `${chNum}-${i}`;
        const lastTime = stageLastClear[subId] || 0;
        const clearedDate = new Date(lastTime).setHours(0, 0, 0, 0);

        if (clearedDate === today) {
            totalGem += 10;
            effectiveVerses += 0.2;
            isReduced = true;
        } else {
            totalGem += 50;
            effectiveVerses += 1.0;
        }
    }

    return { gem: totalGem, effectiveVerses: effectiveVerses, isReduced: isReduced };
}

/* =========================================
   [시스템: 뒤로가기 방지 및 종료 팝업]
   ========================================= */

// 1. 뒤로가기 키 감지 ("납치" 설정)
window.addEventListener('load', function () {
    // 페이지 로드 시 가짜 히스토리를 하나 쌓음
    history.pushState(null, null, location.href);

    window.onpopstate = function (event) {
        history.pushState(null, null, location.href);

        const gameScreen = document.getElementById('game-screen');
        const homeScreen = document.getElementById('home-screen');

        if (gameScreen.classList.contains('active')) {
            // 전투 중: 나가기 확인 팝업
            openQuitModal();
        } else if (homeScreen.classList.contains('active')) {
            // 홈 화면: 종료 안내 모달
            const exitModal = document.getElementById('exit-confirm-modal');
            if (exitModal && exitModal.classList.contains('active')) {
                cancelExitApp();
            } else {
                openExitConfirmModal();
            }
        } else {
            // 홈이 아닌 다른 화면: 홈으로 이동
            if (typeof goHome === 'function') {
                goHome();
            }
        }
    };
});

// 2. 팝업 열기
function openQuitModal() {
    const modal = document.getElementById('quit-modal');
    const title = document.getElementById('quit-modal-title');
    const message = document.getElementById('quit-modal-message');

    if (title) {
        title.innerText = getQuitModalTitleText();
    }

    if (message) {
        message.innerHTML = getQuitModalMessageHtml();
    }

    if (modal) {
        modal.classList.add('active');
    }
}

// [앱 종료 안내 모달]
function openExitConfirmModal() {
    document.getElementById('exit-confirm-modal').classList.add('active');
}

function cancelExitApp() {
    document.getElementById('exit-confirm-modal').classList.remove('active');
}

// 3. [계속하기] 버튼: 팝업 닫고 게임 계속
function cancelQuit() {
    document.getElementById('quit-modal').classList.remove('active');
}

function getQuitModalTitleText() {
    if (!window.isHardshipMode) {
        return t('quit_modal_title');
    }

    const modeMeta = getHardshipModeMeta(hardshipState.mode);
    return t('hardship_quit_title', { title: modeMeta.title });
}

function getHardshipQuitNoticeText() {
    if (!window.isHardshipMode) return '';

    // 이어하기가 걸리는 세션이면 문구가 달라진다 — '저장되지 않습니다'는 이제 거짓이다
    if (_isResumableHardshipSession()
        && Array.isArray(hardshipState.queue) && hardshipState.queue.length >= 2
        && hardshipState.cursor > 0) {
        return t('hardship_quit_notice_resume');
    }

    if (hardshipState.mode === 'endurance') {
        return t('hardship_quit_notice_endurance');
    }

    return t('hardship_quit_notice_scored');
}

function getHardshipBackQuitNoticeText() {
    if (!window.isHardshipMode) return '';

    if (hardshipState.mode === 'endurance') {
        return t('hardship_back_quit_endurance');
    }

    return t('hardship_back_quit_scored');
}

function getQuitModalMessageHtml() {
    if (window.isHardshipMode) {
        return getHardshipBackQuitNoticeText().replace(/\. /g, '.<br>');
    }

    return t('quit_modal_message');
}

/* 🌟 [통합 버그 픽스] 포기 의사를 묻고, 확인 시 자원을 청소하며 나가는 함수 */
function confirmQuit() {
    // 1. 유저에게 의사를 먼저 묻습니다. (첫 번째 함수의 심플한 알림창)
    const quitMessage = window.isHardshipMode
        ? `${getQuitModalTitleText()}\n${getHardshipQuitNoticeText()}`
        : t('quit_confirm');
    const wantsToQuit = confirm(quitMessage);

    // 2. 유저가 '확인'을 눌렀을 때만 청소 및 종료 실행!
    if (wantsToQuit) {

        // (혹시 모를 커스텀 모달이 열려있다면 닫아줍니다)
        const quitModal = document.getElementById('quit-modal');
        if (quitModal) quitModal.classList.remove('active');

        // [청소 1] 타워 게임 다음 스텝 넘어가는 예약 취소
        if (window.towerNextTimeout) {
            clearTimeout(window.towerNextTimeout);
            window.towerNextTimeout = null;
        }

        // [청소 2] 두루마리 게임 애니메이션(무한 루프) 강제 종료!
        if (typeof scrollGame !== 'undefined') {
            scrollGame.isOver = true;
            if (scrollGame.animId) {
                cancelAnimationFrame(scrollGame.animId);
                scrollGame.animId = null;
            }
        }

        // 3. 화면 초기화 및 원래 진입 화면으로 돌아가기 (진짜 종료)
        quitGame(window.isHardshipMode ? (window.hardshipOrigin || 'home') : (isFocusedTrainingSession() ? 'home' : 'map'));
    }
}

/* =========================================
   [Step 3: 바이블 타워 게임 로직 (선택형/객관식으로 완전 개편)]
   ========================================= */
let towerGame = {
    words: [],
    idx: 0,
    locked: false
};

// 타워 게임 초기화
function initTowerGame() {
    towerGame.words = [...trainingVerseData.chunks];
    towerGame.idx = 0;

    const textDisplay = document.getElementById('tower-text-display');

    if (textDisplay) {
        textDisplay.innerHTML = "";
        towerGame.words.forEach((word, index) => {
            const span = document.createElement('span');
            span.innerText = "___";
            span.className = 'tower-word-slot';
            span.id = `tower-word-${index}`;
            textDisplay.appendChild(span);
        });
    }

    document.getElementById('tower-msg').innerText = t('tower_instruction');
    document.getElementById('tower-msg').style.color = "#f0e6c0";

    // 애니메이션 초기화
    spawnTowerStars();

    // 바로 보기 블록 생성
    spawnTowerChoices();
}

// 문제 출제 (객관식 보기 생성)
function spawnTowerChoices() {
    if (!window.isGamePlaying) return; // ★ 추가: 나갔으면 중단!
    towerGame.locked = false; // 새 보기가 나타날 때 잠금 해제
    if (towerGame.idx >= towerGame.words.length) {
        document.getElementById('tower-msg').innerText = t('tower_complete');
        document.getElementById('tower-msg').style.color = "#f1c40f";
        document.getElementById('tower-choices-area').innerHTML = "";

        // ★ 3번 문제를 위한 힌트: 이 setTimeout이 원인입니다!
        window.towerNextTimeout = setTimeout(() => {
            nextStep();
        }, 1500);
        return;
    }

    // 이제 컨트롤 영역에 있는 choices-area를 찾습니다
    const choicesArea = document.getElementById('tower-choices-area');
    choicesArea.innerHTML = "";

    const correctWord = towerGame.words[towerGame.idx];
    let options = [correctWord];

    let wrongCandidates = towerGame.words.filter((w, i) => i !== towerGame.idx && w !== correctWord);
    wrongCandidates = [...new Set(wrongCandidates)];
    wrongCandidates.sort(() => Math.random() - 0.5);

    if (wrongCandidates.length > 0) options.push(wrongCandidates[0]);
    if (wrongCandidates.length > 1) options.push(wrongCandidates[1]);

    const fallbackWords = ["은혜", "말씀", "어린양", "보좌", "생명수"];
    while (options.length < 3) {
        options.push(fallbackWords[Math.floor(Math.random() * fallbackWords.length)]);
        options = [...new Set(options)];
    }

    options.sort(() => Math.random() - 0.5);

    options.forEach((word, i) => {
        const btn = document.createElement('div');
        btn.innerText = word;
        btn.className = 'tower-orb';
        btn.style.animationDelay = `${i * 80}ms`;

        btn.onclick = () => handleTowerChoice(btn, word, correctWord);
        choicesArea.appendChild(btn);
    });

    highlightCurrentBlank();
}

// 플레이어가 블록을 선택했을 때의 판정
function handleTowerChoice(btn, selectedWord, correctWord) {
    if (towerGame.locked) return; // 연타 방지
    towerGame.locked = true;
    const choicesArea = document.getElementById('tower-choices-area');

    if (selectedWord === correctWord) {
        // [정답]
        if (typeof SoundEffect !== 'undefined' && SoundEffect.playCorrect) SoundEffect.playCorrect();

        // 버튼 중심 좌표
        const bRect = btn.getBoundingClientRect();
        const cx = bRect.left + bRect.width / 2;
        const cy = bRect.top  + bRect.height / 2;

        // 버튼 플래시 (초록)
        btn.classList.remove('tower-wrong-flash', 'tower-btn-shake');
        btn.style.backgroundColor = '';
        btn.style.color = '';
        btn.style.boxShadow = '';
        void btn.offsetWidth;
        btn.classList.add('tower-correct-flash');

        // 파티클 + 글로우 링
        spawnTowerParticles(cx, cy);
        spawnGlowRing(cx, cy);

        // 단어를 상단 기록판으로 날려보내기
        flyWordToSlot(btn, correctWord, towerGame.idx);
        towerGame.idx++;
        highlightCurrentBlank();

        // 날아가는 애니메이션 이후 다음 문제 출제
        setTimeout(spawnTowerChoices, 380);

    } else {
        // [오답]
        if (typeof SoundEffect !== 'undefined' && SoundEffect.playWrong) SoundEffect.playWrong();

        // 버튼 중심 좌표
        const bRect = btn.getBoundingClientRect();
        const cx = bRect.left + bRect.width / 2;
        const cy = bRect.top  + bRect.height / 2;

        // 버튼 플래시 (빨강) + shake
        btn.classList.remove('tower-correct-flash');
        btn.style.backgroundColor = '';
        btn.style.color = '';
        btn.style.boxShadow = '';
        void btn.offsetWidth;
        btn.classList.add('tower-wrong-flash', 'tower-btn-shake');

        // 화면 shake
        const gameContainer = document.getElementById('tower-game-container');
        if (gameContainer) {
            gameContainer.classList.add('tower-screen-shake');
            setTimeout(() => gameContainer.classList.remove('tower-screen-shake'), 450);
        }

        document.getElementById('tower-msg').innerText = t('tower_wrong');
        document.getElementById('tower-msg').style.color = "#e74c3c";

        // 틀렸을 때 하트를 깎는 로직이 있다면 여기에 추가 (예: takeDamage())

        // 0.8초 뒤 버튼 원래대로 복구하고 다시 선택하게 함
        setTimeout(() => {
            btn.classList.remove('tower-wrong-flash', 'tower-btn-shake');
            btn.style.backgroundColor = '';
            btn.style.color = '';
            btn.style.boxShadow = '';

            document.getElementById('tower-msg').innerText = t('tower_pick');
            document.getElementById('tower-msg').style.color = "#f0e6c0";

            towerGame.locked = false; // 오답 후 재시도 허용
        }, 800);
    }
}

// 정답 단어를 상단 기록판 슬롯으로 날려보내는 연출
function flyWordToSlot(sourceBtn, word, idx) {
    const slot = document.getElementById(`tower-word-${idx}`);
    if (!slot) return;

    const btnRect  = sourceBtn.getBoundingClientRect();
    const slotRect = slot.getBoundingClientRect();

    // 날아갈 복사본 생성
    const fly = document.createElement('div');
    fly.className = 'flying-word';
    fly.innerText = word;
    fly.style.left = (btnRect.left + btnRect.width  / 2) + 'px';
    fly.style.top  = (btnRect.top  + btnRect.height / 2) + 'px';
    document.body.appendChild(fly);

    // 다음 프레임에서 목적지로 이동 (transition 작동을 위해 rAF 사용)
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            fly.style.left      = (slotRect.left + slotRect.width  / 2) + 'px';
            fly.style.top       = (slotRect.top  + slotRect.height / 2) + 'px';
            fly.style.transform = 'translate(-50%, -50%) scale(0.7)';
            fly.style.opacity   = '0';
        });
    });

    // 도착 직전에 슬롯 채우기, 복사본 제거
    setTimeout(() => {
        slot.innerText = word;
        slot.classList.add('active');
        slot.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        fly.remove();
    }, 220);
}

// ── Step3 애니메이션 헬퍼 함수들 ──

// 별빛 배치
function spawnTowerStars() {
    const container = document.getElementById('tower-game-container');
    if (!container) return;
    container.querySelectorAll('.tower-star').forEach(s => s.remove());
    const count = 20 + Math.floor(Math.random() * 11);
    for (let i = 0; i < count; i++) {
        const s = document.createElement('div');
        s.className = 'tower-star';
        const size = 2 + Math.random() * 3;
        s.style.cssText = `width:${size}px;height:${size}px;left:${Math.random()*100}%;top:${Math.random()*100}%;animation:twinkle ${1.5+Math.random()*2}s ${Math.random()*2}s infinite;`;
        container.appendChild(s);
    }
}

// 현재 채워야 할 빈칸 강조
function highlightCurrentBlank() {
    document.querySelectorAll('.tower-word-slot').forEach((s, i) => {
        s.classList.toggle('current-blank', i === towerGame.idx && !s.classList.contains('active'));
    });
}

// 파티클 효과
function spawnTowerParticles(x, y) {
    const colors = ['#f5c842', '#ffd700', '#ffffff'];
    const count = 10 + Math.floor(Math.random() * 5);
    for (let i = 0; i < count; i++) {
        const p = document.createElement('div');
        const color = colors[Math.floor(Math.random() * colors.length)];
        const size = 5 + Math.random() * 5;
        const angle = Math.random() * 360;
        const dist = 40 + Math.random() * 60;
        p.style.cssText = `position:fixed;border-radius:50%;width:${size}px;height:${size}px;left:${x}px;top:${y}px;background:${color};pointer-events:none;z-index:3000;transform:translate(-50%,-50%);transition:transform 0.5s ease-out,opacity 0.5s ease-out;`;
        document.body.appendChild(p);
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                const rad = (angle * Math.PI) / 180;
                p.style.transform = `translate(calc(-50% + ${dist * Math.cos(rad)}px), calc(-50% + ${dist * Math.sin(rad)}px))`;
                p.style.opacity = '0';
            });
        });
        setTimeout(() => p.remove(), 520);
    }
}

// 글로우 링
function spawnGlowRing(x, y) {
    const ring = document.createElement('div');
    ring.style.cssText = `position:fixed;left:${x}px;top:${y}px;width:40px;height:40px;border-radius:50%;border:2px solid #f5c842;pointer-events:none;z-index:3000;transform:translate(-50%,-50%) scale(0);opacity:1;transition:transform 0.5s ease-out,opacity 0.5s ease-out;`;
    document.body.appendChild(ring);
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            ring.style.transform = 'translate(-50%,-50%) scale(2.5)';
            ring.style.opacity = '0';
        });
    });
    setTimeout(() => ring.remove(), 520);
}

// [Step 4: 예언의 두루마리 게임 상태 변수]
let scrollGame = {
    animId: null,
    speed: 1.5,
    pos: 0,
    blanks: [],
    nextBlankIdx: 0,
    isOver: false,
    isColliding: false
};

/* [시스템: 성전 화면 업데이트 (과거 보기 기능 추가됨)] */
function updateCastleView() {
    // 1. 뷰어 초기화 (게임 켰을 때 한 번만 내 레벨로 동기화)
    if (viewingCastleLevel === -1) viewingCastleLevel = myCastleLevel;
    if (viewingCastleLevel > myCastleLevel) viewingCastleLevel = myCastleLevel;

    if (!document.getElementById('castle-display')) return;

    // 2. 현재 '보고 있는' 레벨의 데이터 가져오기
    const viewBP = castleBlueprints[viewingCastleLevel];

    // 3. 실제 내 레벨(myCastleLevel)의 다음 단계 데이터 (건설 버튼용)
    const currentBP = castleBlueprints[myCastleLevel];
    const nextBP = castleBlueprints[myCastleLevel + 1];

    // 방치 보상 계산 (실제 레벨 기준)
    const now = Date.now();
    const elapsedSeconds = (now - lastClaimTime) / 1000;
    let produced = Math.floor((currentBP.prod / 3600) * elapsedSeconds);
    if (produced > currentBP.cap) produced = currentBP.cap;
    if (produced < 0) produced = 0;

    const isPast = viewingCastleLevel < myCastleLevel;

    // 이미지 src만 교체 (DOM 재생성 없이)
    const imgEl = document.getElementById('castle-img');
    if (imgEl) {
        if (viewBP.img) {
            imgEl.src = `images/${viewBP.img}`;
            imgEl.alt = viewBP.name;
            imgEl.style.display = '';
        } else {
            imgEl.style.display = 'none';
        }
    }

    // 과거 필터 클래스
    const frameWrap = document.getElementById('castle-frame-wrap');
    if (frameWrap) frameWrap.className = `castle-frame${isPast ? ' memory-filter' : ''}`;

    // 과거 배지
    const pastBadgeEl = document.getElementById('castle-past-badge');
    if (pastBadgeEl) {
        if (isPast) {
            pastBadgeEl.textContent = t('castle_past_badge');
            pastBadgeEl.style.display = '';
        } else {
            pastBadgeEl.style.display = 'none';
        }
    }

    // 레벨 타이틀 (숨김 — 토스트로 표시)
    const titleText = `Lv.${viewBP.level} ${currentLang === 'en' && viewBP.nameEn ? viewBP.nameEn : viewBP.name}`;
    const titleEl = document.getElementById('castle-level-title');
    if (titleEl) titleEl.textContent = titleText;

    // 설명 (토스트용으로만 저장)
    const descEl = document.getElementById('castle-desc');
    const descText = `"${currentLang === 'en' && viewBP.descEn ? viewBP.descEn : viewBP.desc}"`;
    if (descEl) descEl.innerHTML = descText;
    const toastTitleEl = document.getElementById('castle-toast-title');
    const toastDescEl = document.getElementById('castle-toast-desc');
    if (toastTitleEl) { toastTitleEl.textContent = titleText; toastTitleEl.style.color = isPast ? '#bdc3c7' : '#f1c40f'; }
    if (toastDescEl) toastDescEl.innerHTML = descText;

    // 네비게이션 화살표 상태
    const prevBtn = document.getElementById('castle-nav-prev');
    const nextBtn = document.getElementById('castle-nav-next');
    if (prevBtn) prevBtn.disabled = viewingCastleLevel <= 0;
    if (nextBtn) nextBtn.disabled = viewingCastleLevel >= myCastleLevel;

    // ===============================================
    // [버튼 행] — LCP 무관하므로 innerHTML 유지
    // ===============================================
    let leftBtnHTML = `<div style="width:50px; height:50px;"></div>`;

    if (!isPast && currentBP.prod > 0) {
        if (produced > 0) {
            leftBtnHTML = `
                <button onclick="claimTempleSupply()" class="btn-pulse" style="width:50px; height:50px; border-radius:10px; border:none; background:#2ecc71; color:#fff; cursor:pointer; padding:0; display:flex; flex-direction:column; align-items:center; justify-content:center; box-shadow:0 3px 0 #27ae60;">
                    <div style="font-size:1.2rem;">💎</div>
                    <div style="font-size:0.6rem; font-weight:bold;">GET</div>
                </button>`;
        } else {
            leftBtnHTML = `
                <button disabled style="width:50px; height:50px; border-radius:10px; border:none; background:#34495e; color:#bdc3c7; padding:0; display:flex; flex-direction:column; align-items:center; justify-content:center;">
                    <div style="font-size:1.2rem;">⏳</div>
                </button>`;
        }
    } else if (isPast) {
        leftBtnHTML = `
            <button onclick="viewingCastleLevel = myCastleLevel; updateCastleView();" style="width:50px; height:50px; border-radius:10px; border:1px dashed rgba(255,255,255,0.3); background:rgba(0,0,0,0.2); color:#bdc3c7; cursor:pointer; display:flex; flex-direction:column; align-items:center; justify-content:center;">
                <div style="font-size:1.2rem;">🔙</div>
            </button>`;
    }

    let rightBtnHTML = `<div style="width:50px; height:50px;"></div>`;

    if (!isPast && myCastleLevel < 11) {
        if (myGems < nextBP.cost) {
            rightBtnHTML = `
                <button style="width:auto; min-width:70px; height:50px; border-radius:10px; border:none; background:#34495e; color:#7f8c8d; padding:0 10px; display:flex; flex-direction:column; align-items:center; justify-content:center; border-bottom:3px solid #2c3e50;">
                    <div style="font-size:0.9rem;">${t('castle_build_locked')}</div>
                    <div style="font-size:0.6rem; margin-top:2px; white-space:nowrap;"><span style="color:#e74c3c;">${myGems.toLocaleString()}</span> / ${nextBP.cost.toLocaleString()} 💎</div>
                </button>`;
        } else {
            rightBtnHTML = `
                <button onclick="upgradeCastle()" class="btn-pulse" style="width:auto; min-width:70px; height:50px; border-radius:10px; border:none; background:#e67e22; color:#fff; cursor:pointer; padding:0 10px; display:flex; flex-direction:column; align-items:center; justify-content:center; box-shadow:0 3px 0 #d35400;">
                    <div style="font-size:0.9rem;">${t('castle_build')}</div>
                    <div style="font-size:0.6rem; margin-top:2px; white-space:nowrap; color:#fde3c0;">${myGems.toLocaleString()} / ${nextBP.cost.toLocaleString()} 💎</div>
                </button>`;
        }
    } else if (isPast) {
        rightBtnHTML = `<div style="width:50px; height:50px; display:flex; align-items:center; justify-content:center; font-size:1.5rem; opacity:0.3;">🔒</div>`;
    }

    const btnRow = document.getElementById('castle-btn-row');
    if (btnRow) {
        btnRow.innerHTML = `
            ${leftBtnHTML}
            <div style="flex:1; background:rgba(0,0,0,0.4); border-radius:10px; border:1px solid rgba(255,255,255,0.1); height:50px; display:flex; flex-direction:column; justify-content:center; align-items:center;">
                <div style="font-size: 0.9rem; color:#fff; font-weight:bold;">
                    💎 <span style="color:#f1c40f;">${produced}</span> / ${currentBP.cap}
                </div>
                <div style="font-size: 0.7rem; color: #95a5a6;">
                    ⚡${currentBP.prod}/H <span style="color:#2ecc71;">(+${currentBP.bonus}%)</span>
                </div>
            </div>
            ${rightBtnHTML}
        `;
    }

    updateTempleUpgradeNotification();
}

// ★ 모드 선택 오버레이 - 가장 가까운 복습 대기시간 계산
function getNearestWaitingMs(nextReviewTimeMap) {
    const now = Date.now();
    let minMs = Infinity;
    Object.values(nextReviewTimeMap || {}).forEach(ts => {
        if (ts > now) {
            const diff = ts - now;
            if (diff < minMs) minMs = diff;
        }
    });
    return minMs === Infinity ? null : minMs;
}

let _castleToastTimer = null;
function showCastleDescToast() {
    const toast = document.getElementById('castle-desc-toast');
    if (!toast) return;
    if (_castleToastTimer) clearTimeout(_castleToastTimer);
    toast.style.display = 'block';
    toast.style.opacity = '1';
    _castleToastTimer = setTimeout(() => {
        toast.style.opacity = '0';
        setTimeout(() => { toast.style.display = 'none'; }, 300);
    }, 2000);
}

// [추가] 뷰어 레벨 변경 함수
function changeViewLevel(delta) {
    const nextLvl = viewingCastleLevel + delta;

    // 범위 체크 (0보다 작거나, 내가 가진 레벨보다 높으면 이동 불가)
    if (nextLvl < 0 || nextLvl > myCastleLevel) return;

    viewingCastleLevel = nextLvl;

    // 효과음 (찰칵 소리나 부드러운 클릭음 추천)
    if (typeof SoundEffect !== 'undefined') SoundEffect.playClick();

    updateCastleView();
}

/* [시스템: 성전 기능 작동 함수] */

// 1. 성전 건축하기
function upgradeCastle() {
    if (myCastleLevel >= 11) { alert(t('alert_castle_max')); return; }

    const nextLevel = myCastleLevel + 1;
    const nextBP = castleBlueprints[nextLevel];

    if (myGems >= nextBP.cost) {
        if (!confirm(`보석 ${nextBP.cost}개를 사용하여\n[Lv.${nextLevel} ${nextBP.name}]을(를) 건축하시겠습니까?`)) return;

        myGems -= nextBP.cost;
        myCastleLevel++;

        // [★추가] 업그레이드 즉시 최신 모습을 보여주기 위해 뷰어 갱신
        viewingCastleLevel = myCastleLevel;

        if (typeof SoundEffect !== 'undefined') SoundEffect.playLevelUp();

        alert(t('alert_castle_built', { lv: myCastleLevel, name: nextBP.name, desc: nextBP.desc.replace(/<br>/g, '\n') }));

        updateStats('castle_levelup', myCastleLevel);
        updateGemDisplay();
        updateCastleView(); // 화면 갱신
        saveGameData();
    } else {
        alert(t('alert_castle_no_gems', { need: nextBP.cost, have: myGems }));
    }
}

// 2. 보석 수거하기
function claimTempleSupply() {
    const currentBP = castleBlueprints[myCastleLevel];
    if (currentBP.prod === 0) return;

    const now = Date.now();
    const elapsedHours = (now - lastClaimTime) / (1000 * 60 * 60);
    let pending = Math.floor(elapsedHours * currentBP.prod);

    if (pending > currentBP.cap) pending = currentBP.cap;
    if (pending <= 0) return;

    myGems += pending;
    lastClaimTime = now;

    if (typeof SoundEffect !== 'undefined') SoundEffect.playGetGem();
    alert(t('alert_temple_collected', { count: pending }));

    updateCastleView(); // 화면 갱신
    updateResourceUI();
    saveGameData();
}

/* ========================================
   [정식 배포 버전 - 치트키 제거됨]
   ======================================== */

// [변경] 두루마리 게임 속도 3단계 조절 (기존 toggleScrollFastMode 대체)
function changeScrollSpeed(mode) {
    scrollGame.speedMode = mode;

    // 1. 버튼 3개 가져오기
    const btnSlow = document.getElementById('btn-speed-slow');
    const btnNormal = document.getElementById('btn-speed-normal');
    const btnFast = document.getElementById('btn-speed-fast');

    // 2. 모든 버튼 스타일 초기화 (비활성화 상태처럼 보이기)
    [btnSlow, btnNormal, btnFast].forEach(btn => {
        if (btn) {
            btn.style.borderColor = '#ccc';
            btn.style.color = '#7f8c8d'; // 회색 글자
            btn.style.fontWeight = 'normal';
        }
    });

    // 3. 선택된 모드에 따라 속도 적용 및 버튼 색상 강조
    if (mode === 'slow') {
        scrollGame.speed = 0.6; // 기존 어르신 모드 속도
        if (btnSlow) {
            btnSlow.style.borderColor = '#e67e22'; // 주황색
            btnSlow.style.color = '#e67e22';
            btnSlow.style.fontWeight = 'bold';
        }

    } else if (mode === 'fast') {
        scrollGame.speed = 1.5; // 기존 빠른 모드 속도
        if (btnFast) {
            btnFast.style.borderColor = '#e74c3c'; // 빨간색 (아주 빠름 강조)
            btnFast.style.color = '#e74c3c';
            btnFast.style.fontWeight = 'bold';
        }

    } else {
        // normal (보통)
        scrollGame.speed = 1.0; // 0.6과 1.5 사이의 적절한 중간 속도
        if (btnNormal) {
            btnNormal.style.borderColor = '#27ae60'; // 초록색
            btnNormal.style.color = '#27ae60';
            btnNormal.style.fontWeight = 'bold';
        }
    }
}

function skipToEnd() {
    scrollGame.speed = 15;
    const skipBtn = document.getElementById('btn-speed-skip');
    if (skipBtn) skipBtn.disabled = true;
}

/* =========================================
   [Step 4] 예언의 두루마리 게임 로직 (NEW)
   ========================================= */
function startScrollStep() {
    if (!window.isGamePlaying) return; // ★ 추가: 나갔으면 중단!
    scrollGame.isOver = false;
    scrollGame.nextBlankIdx = 0;

    // 🌟 [개선] 3단계 속도 설정 (기본값: 보통)
    if (!scrollGame.speedMode) scrollGame.speedMode = 'normal'; // 초기값이 없으면 보통으로 설정

    if (scrollGame.speedMode === 'slow') {
        scrollGame.speed = 0.4; // 1단계: 아주 느리게 (어르신, 구형 기기용)
    } else if (scrollGame.speedMode === 'fast') {
        scrollGame.speed = 1.0; // 3단계: 아주 빠르게 (고인물, 최신 기기용)
    } else {
        scrollGame.speed = 0.7; // 2단계: 보통 속도 (기본값)
    }

    const track = document.getElementById('scroll-track');
    const deck = document.getElementById('scroll-deck');
    const container = document.getElementById('scroll-game-container');

    if (!track || !container) return;

    // 1. 위치 초기화 (오른쪽 끝)
    scrollGame.pos = container.offsetWidth;
    track.style.left = scrollGame.pos + "px";

    // 2. 단어 및 빈칸 생성
    const words = trainingVerseData.chunks;
    const totalWords = words.length;

    // [개선] 전체의 최대 2/3까지만 빈칸으로 설정 (즉, 최소 1/3은 보여줌)
    const maxBlankCount = Math.floor(totalWords * (2 / 3));

    // 일단 모든 인덱스를 담은 후보 배열 생성
    let candidates = words.map((_, i) => i);

    // 긴 단어(3글자 이상)를 우선적으로 빈칸 후보로 올리기 위해 셔플
    candidates.sort(() => Math.random() - 0.5);

    const blankIndices = [];

    for (let i of candidates) {
        const word = words[i];

        // 조건 1: 빈칸 개수가 전체의 2/3를 넘지 않아야 함
        if (blankIndices.length < maxBlankCount) {
            // 조건 2: 확률(60%)이거나 단어가 길 때 (기존 로직 유지하되 한도 제한)
            if (Math.random() > 0.4 || word.length > 2) {
                blankIndices.push(i);
            }
        }
    }

    // 화면 순서대로 정렬
    blankIndices.sort((a, b) => a - b);
    scrollGame.blanks = blankIndices;

    track.innerHTML = "";
    words.forEach((word, idx) => {
        const node = document.createElement('div');
        node.className = 'scroll-node';
        node.innerText = word;
        node.dataset.idx = idx;

        if (blankIndices.includes(idx)) {
            node.classList.add('scroll-blank');

            // ★ [핵심 수정] "???" 대신 초성 함수 사용!
            node.innerText = getChosung(word);

            node.dataset.answer = word;
        }
        track.appendChild(node);
    });

    // 3. 정답 카드 생성
    deck.innerHTML = "";
    const answers = blankIndices.map(i => words[i]);
    const shuffled = [...answers].sort(() => Math.random() - 0.5);

    shuffled.forEach(word => {
        const btn = document.createElement('div');
        btn.className = 'word-block';
        btn.innerText = word;
        btn.onclick = () => handleScrollCardClick(btn, word);
        deck.appendChild(btn);
    });

    // 4. 애니메이션 시작
    if (scrollGame.animId) cancelAnimationFrame(scrollGame.animId);
    scrollGameLoop();
}

function scrollGameLoop() {
    if (!window.isGamePlaying || scrollGame.isOver) return; // ★ 2중 방어막 추가!

    // 이동
    scrollGame.pos -= scrollGame.speed;
    const track = document.getElementById('scroll-track');
    if (track) track.style.left = scrollGame.pos + "px";

    // 충돌 체크
    checkScrollCollision();

    // 반복
    scrollGame.animId = requestAnimationFrame(scrollGameLoop);
}

function checkScrollCollision() {
    const deadline = 60; // 불타는 선 위치
    const nodes = document.querySelectorAll('.scroll-node');

    // 타겟(다음 빈칸) 찾기
    const targetIdx = scrollGame.blanks[scrollGame.nextBlankIdx];

    // [상황 A] 성공 체크
    if (targetIdx === undefined) {
        const lastNode = nodes[nodes.length - 1];
        if (!lastNode) return;
        const rect = lastNode.getBoundingClientRect();
        const container = document.getElementById('scroll-game-container');

        if (rect.right < container.getBoundingClientRect().left) {
            scrollGame.isOver = true;
            cancelAnimationFrame(scrollGame.animId);
            if (typeof nextStep === 'function') nextStep();
        }
        return;
    }

    // [상황 B] 충돌 & 경고 체크
    const targetNode = nodes[targetIdx];
    const rect = targetNode.getBoundingClientRect();
    const container = document.getElementById('scroll-game-container');
    const nodeLeftRel = rect.left - container.getBoundingClientRect().left; // 화면상 빈칸의 위치

    // ★ [추가] 3초 전 경고 계산 로직 ★
    // 1프레임(약 16ms)당 scrollGame.speed 만큼 이동함.
    // 3초 = 약 180프레임. 따라서 3초 동안 이동하는 거리는 (180 * scrollGame.speed)
    const warningDistance = 180 * scrollGame.speed;
    const distanceToDeadline = nodeLeftRel - deadline;

    // 만약 선까지 남은 거리가 3초 거리 안쪽으로 들어왔다면?
    if (distanceToDeadline > 0 && distanceToDeadline <= warningDistance && !targetNode.classList.contains('filled')) {
        // 1. 단어 상자에 붉은색 경고 깜빡임 추가
        targetNode.classList.add('scroll-warning');

        // 2. (선택사항) 아래 버튼 덱에서 정답 버튼도 반짝거리게 힌트 주기
        const correctWord = targetNode.dataset.answer;
        const deckBtns = document.querySelectorAll('#scroll-deck .word-block');
        deckBtns.forEach(btn => {
            if (btn.innerText === correctWord) {
                btn.classList.add('hint-blink');
            }
        });
    } else {
        // 거리가 멀거나 이미 맞춘 경우 경고 제거
        targetNode.classList.remove('scroll-warning');
        const deckBtns = document.querySelectorAll('#scroll-deck .word-block');
        deckBtns.forEach(btn => btn.classList.remove('hint-blink'));
    }


    // 데드라인을 넘었는데 아직 정답을 못 맞췄다면? (기존 충돌 로직)
    if (nodeLeftRel < deadline && targetNode.classList.contains('scroll-blank') && !targetNode.classList.contains('filled')) {

        // 경고 클래스 떼주기
        targetNode.classList.remove('scroll-warning');
        const deckBtns = document.querySelectorAll('#scroll-deck .word-block');
        deckBtns.forEach(btn => btn.classList.remove('hint-blink'));

        if (scrollGame.isColliding) return;
        scrollGame.isColliding = true;
        wrongCount++;
        if (typeof updateBattleUI === 'function') updateBattleUI();

        // 2. 연출
        showDamageEffect();
        if (typeof SoundEffect !== 'undefined') SoundEffect.playWrong();

        // 3. 밀어내기
        const safeDistance = 250;
        const nodeOffset = targetNode.offsetLeft;

        scrollGame.pos = (deadline + safeDistance) - nodeOffset;

        const track = document.getElementById('scroll-track');
        track.style.transition = "left 0.2s cubic-bezier(0.25, 1, 0.5, 1)";
        track.style.left = scrollGame.pos + "px";

        // 4. 충돌 상태 해제 
        setTimeout(() => {
            track.style.transition = "none";
            scrollGame.isColliding = false;
        }, 500);
    }
}

function handleScrollCardClick(btn, word) {
    if (scrollGame.isOver) return;

    const targetIdx = scrollGame.blanks[scrollGame.nextBlankIdx];
    if (targetIdx === undefined) return;

    const nodes = document.querySelectorAll('.scroll-node');
    const targetNode = nodes[targetIdx];
    const correctWord = targetNode.dataset.answer;

    if (word === correctWord) {
        // 힌트 깜빡임 제거
        btn.classList.remove('hint-blink');
        targetNode.classList.remove('scroll-warning');
        // 정답 로직 (기존과 동일)
        if (typeof SoundEffect !== 'undefined') SoundEffect.playCorrect();
        targetNode.classList.add('filled');
        targetNode.innerText = correctWord;
        btn.style.visibility = 'hidden';
        scrollGame.nextBlankIdx++;

        if (scrollGame.nextBlankIdx >= scrollGame.blanks.length) {
            const skipBtn = document.getElementById('btn-speed-skip');
            if (skipBtn) skipBtn.style.display = 'inline-block';
        }

    } else {
        // [오답]
        wrongCount++;
        if (typeof updateBattleUI === 'function') updateBattleUI();
        showDamageEffect();
        if (typeof SoundEffect !== 'undefined') SoundEffect.playWrong();

        btn.style.backgroundColor = "#e74c3c";
        setTimeout(() => btn.style.backgroundColor = "#ecf0f1", 300);
    }
}

// [오답 연출 함수]
function showDamageEffect() {
    // 1. 표시 요소 생성 — 잃는 체력이 없으니 '틀렸다'만 뜻하는 ❌ (옛 💔는 없는 일을 말했다)
    const el = document.createElement('div');
    el.innerText = "❌";
    el.className = "damage-heart-effect";
    document.body.appendChild(el);

    // 2. 화면 흔들림 효과 (게임 컨테이너에)
    const container = document.getElementById('scroll-game-container');
    if (container) {
        container.classList.add('shake-screen-hard');
        setTimeout(() => container.classList.remove('shake-screen-hard'), 500);
    }

    // 3. 1.5초 뒤에 하트 요소 삭제 (메모리 정리)
    setTimeout(() => {
        if (el && el.parentNode) el.parentNode.removeChild(el);
    }, 1500);
}

