/* =========================================
   [Google 계정 연동]
   ========================================= */
function isGoogleLinked() {
    const user = typeof auth !== 'undefined' && auth ? auth.currentUser : null;
    return user ? user.providerData.some(p => p.providerId === 'google.com') : false;
}

function _isInAppBrowser() {
    return /Telegram|FBAN|FBAV|Instagram|Line|KakaoTalk/i.test(navigator.userAgent);
}

async function linkGoogleAccount() {
    if (typeof auth === 'undefined' || !auth || !auth.currentUser) {
        showGemToast(0, '서버 연결이 필요합니다.', true);
        return;
    }
    if (isGoogleLinked()) {
        showGemToast(0, '이미 Google 계정이 연결되어 있습니다.', false);
        return;
    }
    const provider = new firebase.auth.GoogleAuthProvider();
    // 텔레그램 인앱 브라우저 등 팝업 차단 환경은 처음부터 redirect
    if (_isInAppBrowser()) {
        try { await auth.currentUser.linkWithRedirect(provider); } catch (e) {
            showGemToast(0, 'Google 연결 실패: ' + (e.message || e.code), true);
        }
        return;
    }
    try {
        await auth.currentUser.linkWithPopup(provider);
        showGemToast(0, '✅ Google 계정 연결 완료! 다른 기기에서 Google로 이어할 수 있습니다.', false);
        _updateGoogleLinkUI();
    } catch (e) {
        if (e.code === 'auth/popup-blocked' || e.code === 'auth/popup-closed-by-user') {
            try {
                await auth.currentUser.linkWithRedirect(provider);
            } catch (e2) {
                showGemToast(0, 'Google 연결 실패: ' + (e2.message || e2.code), true);
            }
        } else if (e.code === 'auth/credential-already-in-use') {
            _showGoogleAlreadyUsedModal();
        } else {
            showGemToast(0, 'Google 연결 실패: ' + (e.message || e.code), true);
        }
    }
}

async function signInWithGoogleAndLoad() {
    if (typeof auth === 'undefined' || !auth) {
        showGemToast(0, '서버 연결이 필요합니다.', true);
        return;
    }
    // 케이스 1: 현재 기기에 플레이 데이터가 있으면 덮어쓰임 경고
    const localRaw = localStorage.getItem('kingsRoadSave');
    const localSave = localRaw ? (() => { try { return JSON.parse(localRaw); } catch(e) { return null; } })() : null;
    if (localSave && localSave.tag) {
        _showGoogleSignInConfirm(localSave.tag);
        return;
    }
    await _doSignInWithGoogle();
}

