/* [기능] 미리보기 텍스트 갱신 헬퍼 */
function updatePreviewText() {
    const preview = document.getElementById('preview-full');
    if (preview) {
        preview.innerHTML = `${getTribeIcon(window.tempTribe)}${getDeptTag(window.tempDept)} ${window.tempNickname}`;
    }
}

/* [기능] 프로필 확정 (저장) + 지파 이적 페널티 */
async function confirmProfile() {
    const _isFirstProfile = (myNickname === '순례자'); // 닉네임 변경 전 신규 유저 여부 캡처

    // 🌟 [핵심 방어막] 최초 가입이 아닌 유저가 지파를 바꿀 때 경고!
    if (myNickname !== "순례자" && myTribe !== window.tempTribe) {
        const warnMsg = t('profile_tribe_warn');
        if (!confirm(warnMsg)) {
            return; // 취소하면 함수 종료 (변경 취소)
        }
        // 확인을 눌렀다면 기여도를 무자비하게 0점으로 초기화!
        if (typeof leagueData !== 'undefined') {
            leagueData.yearlyScore = 0;
            console.log("🚨 지파 변경으로 인해 연간 승점이 0으로 초기화되었습니다.");
        }
    }

    if (window.tempNickname) myNickname = window.tempNickname;
    if (window.tempTribe !== undefined) myTribe = window.tempTribe;
    if (window.tempDept !== undefined) myDept = window.tempDept;

    // 신규 유저(tag 없음)에 한해 중복 없는 tag 생성.
    // ★ '0000'도 '없음'이다 — loadGameData()가 tag 없는 저장본을 '0000'으로 채우는데
    //   truthy라서 !myTag로는 걸리지 않는다. 이 한 줄 때문에 프로필을 다 채우고도
    //   번호를 못 받은 사람이 생겼다 (ensureTagAssigned 주석 참고).
    if (!myTag || myTag === '0000') myTag = await generateUniqueTag();

    markOnboardStep('profile');

    // 저장 및 갱신
    saveGameData();
    syncToFirestore(); // [Firestore] 프로필 변경
    updateProfileUI();

    // 메인 화면 갱신
    if (typeof saveMyScoreToServer === 'function') saveMyScoreToServer(); // 서버 전송

    // 팝업 닫기
    const modal = document.getElementById('nickname-modal');
    if (modal) {
        modal.classList.remove('active');
        setTimeout(() => modal.remove(), 300);
    }

    const tribeName = getTribeName(TRIBE_DATA[myTribe]);
    // 네이티브 alert 대신 토스트 — 온보딩 한복판에서 시스템 대화상자는 이질적이고,
    // 브라우저에 따라 "이 사이트가 다시 알림을 표시하지 못하게 하기" 체크박스가 붙는다.
    showToast(t('alert_welcome_tribe', { tribe: tribeName, nick: myNickname }));

    // ★ 신규 유저에게는 기존 공지를 띄우지 않는다.
    // 예전에는 여기서 checkAndShowNewNotice()를 불러 '억제됐던 공지'를 보여줬는데,
    // 그 결과 **가입 직후 두 번째 화면이 과거 패치노트와 데이터 손실 사과문**이 됐다.
    // 겪지도 않은 사고를 첫인상으로 주는 셈이라, 3일간 억제해 온보딩을 마친 뒤 보게 한다.
    if (_isFirstProfile) {
        try {
            localStorage.setItem('noticeHideUntil',
                new Date(Date.now() + 3 * 86400000).toISOString());
        } catch (e) { /* 저장 실패해도 온보딩에는 영향 없음 */ }
        // 🚪 곧바로 첫 구절로 (10/6) — 여정 고르기·하루 몇 구절·안내 3쪽·아멘은 첫 구절 뒤로
        if (typeof _isPreFirstClear === 'function' && _isPreFirstClear()) setTimeout(_startFirstVerseNow, 900);
    }
}

/* 🌅 내일의 약속 (2026-10-06) — 처음으로 한 절을 깬 직후 한 번. 실측: 10절은 둘째 날 재방문이 가르고(첫날 2~4절 깨고 다시 오지 않는 사람이 대부분),
   알림을 켠 사람(1절+ 892명 중 25명)은 다른 날에도 클리어 88% vs 58% — 다만 지금은 알림을 켜려면 지도 「알림 설정」을 찾아 시간까지 정해야 했다.
   카드: 외운 절 · 10분 뒤 첫 복습(남은 시간) · 내일 아침 6시에 다음 절 · 🔔 「내일 이 시각에 알려 주세요」(한 번에 권한 + 지금 시각) /
   알림이 없는 기기(설치 안 한 아이폰)는 「📱 홈 화면에 추가」. 본 것·누른 것·결과를 onboardPromise에 남긴다(한 주 뒤 효과 측정) */
function _promiseRefOf(id) { const [c, v] = String(id).split('-'); return currentLang === 'en' ? `Rev ${c}:${v}` : `계 ${c}:${v}` + '을을를을를를을을을를'[+String(v).slice(-1)]; }   // 끝자리 읽는 소리로 을/를(영·일·이·삼·사·오·육·칠·팔·구)
function _promiseNowHM() { const d = new Date(), m = Math.round(d.getMinutes() / 5) * 5, h = (d.getHours() + (m === 60 ? 1 : 0)) % 24; return String(h).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); }
function _showPromiseCard() {
    const P = onboardPromise; if (!P || P.shown) return;
    P.shown = Date.now(); saveGameData();
    const old = document.getElementById('promise-card'); if (old) old.remove();
    const noNotif = typeof Notification === 'undefined', iosGuide = noNotif && typeof isIOSNonPWA === 'function' && isIOSNonPWA();
    const m = document.createElement('div'); m.id = 'promise-card'; m.className = 'promise-overlay';
    m.innerHTML = `<div class="promise-card">
        <div class="promise-check">✅</div>
        <div class="promise-title">${t('promise_title', { ref: _promiseRefOf(P.id) })}</div>
        <div class="promise-rows">
            <div class="promise-row"><span>⏰</span><div><b id="promise-review">${t('promise_review_soon')}</b><small>${t('promise_review_why')}</small></div></div>
            <div class="promise-row"><span>🌅</span><div><b>${t(activeMode === 'kings' ? 'promise_next_kings' : 'promise_next_free')}</b><small>${t('promise_next_why')}</small></div></div>
        </div>
        ${iosGuide ? `<button class="promise-main" data-a="ios">${t('promise_ios_btn')}</button><div class="promise-note">${t('promise_ios_note')}</div>`
            : noNotif ? '' : `<button class="promise-main" data-a="notif">${t('promise_notif_btn', { time: _promiseNowHM() })}</button><div class="promise-note">${t('promise_notif_note')}</div>`}
        <button class="promise-later" data-a="later">${t('promise_later')}</button>
    </div>`;
    document.body.appendChild(m);
    const tick = () => {   // 첫 복습까지 남은 시간
        const el = document.getElementById('promise-review'); if (!el) { clearInterval(iv); return; }
        const st = typeof getReviewStatus === 'function' ? getReviewStatus(P.id) : null, ms = st ? st.remainMs : 0;
        el.textContent = ms > 0 ? t('promise_review_in', { m: Math.floor(ms / 60000), s: String(Math.floor(ms / 1000) % 60).padStart(2, '0') }) : t('promise_review_now');
    };
    const iv = setInterval(tick, 1000); tick();
    const close = () => { clearInterval(iv); m.remove(); };
    m.querySelectorAll('button[data-a]').forEach(b => b.onclick = async () => {
        const a = b.dataset.a;
        if (a === 'later') { if (!P.notif) P.notif = 'later'; saveGameData(); close(); return; }
        if (a === 'ios') { P.notif = 'ios-guide'; saveGameData(); close(); if (typeof showIOSInstallGuide === 'function') showIOSInstallGuide(); return; }
        b.disabled = true;
        const r = await _promiseNotifOn(); P.notif = r.state; if (r.time) P.nt = r.time; saveGameData();
        if (r.state === 'granted') { close(); showToast(t('promise_notif_ok', { time: r.time })); }
        else { b.disabled = false; showToast(t(r.state === 'unsupported' ? 'toast_notif_unsupported' : 'toast_notif_permission')); }
    });
}
/* 🔔 한 번에 — 권한을 묻고 지금 시각(5분 단위)을 매일 알림에 더한다(이미 셋이면 그대로). notifSave와 같은 길로 서버에 */
async function _promiseNotifOn() {
    if (typeof Notification === 'undefined') return { state: 'unsupported' };
    let perm = Notification.permission;
    if (perm !== 'granted') { try { perm = await Notification.requestPermission(); } catch (e) { perm = 'denied'; } }
    if (perm !== 'granted') return { state: 'denied' };
    const time = _promiseNowHM();
    let times = []; try { times = JSON.parse(localStorage.getItem('notifTimes') || '[]') || []; } catch (e) { }
    if (!times.includes(time) && times.length < 3) times.push(time);
    try { localStorage.setItem('notifTimes', JSON.stringify(times)); } catch (e) { }
    if (myTag && db) {
        try {
            await initFCM().catch(() => { }); startFCMTokenRefreshListener();
            const up = { notificationTimes: times }; if (_fcmToken) up.fcmToken = _fcmToken;
            await db.collection('leaderboard').doc(String(myTag)).set(up, { merge: true });
        } catch (e) { console.warn('약속 알림 저장 실패:', e); }
    }
    if (typeof scheduleNotifTimesViaSW === 'function') { try { scheduleNotifTimesViaSW(); } catch (e) { } }
    return { state: 'granted', time };
}

/* 🚪 가입 직후 곧바로 첫 구절 (2026-10-06) — 실측: 9/9 이후 새 가입자 68명 중 35명(51%)이 등록을 마치고 지도에 한 번도 못 갔다.
   등록 → 홈 → 「여정 시작」 → 여정 고르기(셋) → 하루 몇 구절(셋) → 안내 3쪽 → 아멘 → 지도 → 1장 → 1절, 첫 구절까지 탭 8~10번·선택 셋이었다.
   이제 「왕의 길 · 하루 1구절」로 정해 두고 지도를 한 번 보여 준 뒤 1:1을 연다. 여정·단계는 지도 칩·홈에서 언제든 바꾼다.
   안내 3쪽(kingsRoad_introSeen)은 남겨 두어 다음에 「여정 시작」을 누를 때 본다 */
function _startFirstVerseNow() {
    if (!_isPreFirstClear()) return;
    if (!kingsRoadData.stepHistory.length) setKingsRoadStep(1);
    switchMode('kings');
    try { localStorage.setItem('kingsRoad_lastAmenDate', getMemoryQuizDate()); } catch (e) { }
    window._pendingFirstStageStart = true;
    goMap();
}

/* [시스템] 데이터 경고 팝업 제어 */
function checkDataWarning() {
    // '다시 보지 않기'가 체크되어 있는지 확인
    const isHidden = localStorage.getItem("hideDataWarning");

    // 신규 유저(프로필 미설정)에게는 억제 — 온보딩 흐름 보호
    if (myNickname === '순례자') return;

    // 저장된 값이 없으면 팝업을 보여줌
    if (!isHidden) {
        document.getElementById('data-warning-modal').style.display = 'flex';
    }
}

/* 팝업 닫기 함수 */
function closeWarningModal() {
    const checkbox = document.getElementById('dont-show-again');
    const modal = document.getElementById('data-warning-modal');

    // 체크박스에 체크했으면 영구적으로 숨김 처리
    if (checkbox.checked) {
        localStorage.setItem("hideDataWarning", "true");
    }

    modal.style.display = 'none';
}

// 게임 시작 시 자동 실행 (기존 window.onload 안에 넣거나, 맨 아래에 추가)
// setTimeout을 써서 게임 로딩 0.5초 뒤에 뜨게 하면 더 자연스러움
setTimeout(checkDataWarning, 500);

/* [시스템: 게임 초기화 및 시작] */
window.onload = function () {
    // 1. 저장된 데이터 불러오기 (가장 중요)
    loadGameData();

    // 🌟 [핵심 장전] 서버에 데이터를 쏘기 전에, 방금 불러온 세이브 파일에서 토큰을 꺼내 메모리에 확실히 쥐여줍니다!
    const savedData = JSON.parse(localStorage.getItem('kingsRoadSave') || "{}");
    if (savedData.sessionToken) {
        window.currentSessionToken = savedData.sessionToken;
    }

    // 2. 복구 직후 자동 동기화는 initFirestoreSync()에서 forceSyncAfterLoad 플래그를 보고 처리

    checkMissions(); // [추가] 게임 시작 시 미션 초기화 체크
    updateStats('login');
    startKingsRoadInfoTimer();
    updateNotificationBadges();
    if (typeof updateSavedVersesBadge === 'function') updateSavedVersesBadge();

    // 4. 화면 UI 갱신
    updateGemDisplay();
    if (typeof updateResourceUI === 'function') updateResourceUI();
    if (typeof updateProfileUI === 'function') updateProfileUI();
    if (typeof updateCastleView === 'function') updateCastleView();
    ensurePlaytimeStats();
    startPlaySession();
    if (!window.playtimeTrackingInitialized) {
        window.playtimeTrackingInitialized = true;

        // 📱 1. 모바일 & 탭 이동 대응: 화면이 안 보일 때 서버에 저장
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                stopPlaySession();

                // 🌟 화면이 가려지는 순간(홈으로 나가기 등), 서버로 데이터를 툭 던져놓습니다.
                if (typeof saveMyScoreToServer === 'function') saveMyScoreToServer();
                console.log("🔒 화면 숨김 감지: 서버에 안전하게 데이터 백업 완료");
            } else {
                startPlaySession();
            }
        });

        // 💻 2. PC 대응: 브라우저 탭을 완전히 닫거나 새로고침할 때 서버에 저장
        window.addEventListener('beforeunload', (event) => {
            stopPlaySession();

            // 🌟 창이 닫히기 직전 마지막으로 서버에 기록을 남깁니다.
            if (typeof saveMyScoreToServer === 'function') saveMyScoreToServer();
        });
    }

    console.log("✅ 게임 로딩 완료!");




    // ▼▼▼ [수정] 최초 1회만 닉네임 설정창 띄우기 ▼▼▼
    if (myNickname === "순례자" && !localStorage.getItem('hasShownProfileSetup')) {
        localStorage.setItem('hasShownProfileSetup', 'true');
        // 수동 초기화는 복구 팝업 없이 바로 프로필 설정
        const isManualReset = sessionStorage.getItem('manualReset') === 'true';
        sessionStorage.removeItem('manualReset');
        if (isManualReset) {
            setTimeout(openProfileSettings, 1000);
        } else {
            // 자동 초기화(세션 충돌 등) 시에만 복구 팝업 제공
            setTimeout(_showNewUserModal, 1000);
        }
    }
};

function _showNewUserModal() {
    const overlay = document.createElement('div');
    overlay.id = 'new-user-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;z-index:9999;padding:20px;box-sizing:border-box;';
    // 케이스 4: 이미 Google 연결된 기기에서는 "Google로 이어하기" 버튼 숨김
    // (signInWithGoogleAndLoad가 forceRemoteSync를 세팅해 로컬 우선 데이터를 덮어쓸 위험 방지)
    const googleBtn = isGoogleLinked() ? '' : `
        <button onclick="document.getElementById('new-user-modal').remove();signInWithGoogleAndLoad();"
            style="background:#4285f4;border:none;border-radius:10px;padding:13px;color:white;font-size:15px;font-weight:600;cursor:pointer;">🔵 Google로 시작하기</button>`;
    overlay.innerHTML = `
        <div style="background:#1a0e2e;border:1px solid #5a3a8a;border-radius:16px;padding:28px 24px;width:100%;max-width:340px;text-align:center;">
            <div style="font-size:2rem;margin-bottom:12px;">👋</div>
            <div style="font-size:18px;font-weight:700;color:#e0c0ff;margin-bottom:10px;">처음 오셨나요?</div>
            <div style="font-size:14px;color:#9070b0;margin-bottom:24px;line-height:1.6;">이전에 플레이한 기록이 있다면<br>Google 계정으로 이어할 수 있습니다.</div>
            <div style="display:flex;flex-direction:column;gap:10px;">
                ${googleBtn}
                <button onclick="document.getElementById('new-user-modal').remove();openProfileSettings();"
                    style="background:#2a1a4a;border:1px solid #5a3a8a;border-radius:10px;padding:13px;color:#9070b0;font-size:15px;cursor:pointer;">계정 없이 시작하기</button>
            </div>
        </div>`;
    document.body.appendChild(overlay);
}


/* [시스템: 클리어 축하 폭죽 효과 (Confetti)] */
function triggerConfetti() {
    const duration = 1500; // 1.5초 동안 지속
    const end = Date.now() + duration;

    // 캔버스 생성 및 설정
    const canvas = document.createElement('canvas');
    canvas.style.position = 'fixed';
    canvas.style.top = '0';
    canvas.style.left = '0';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.pointerEvents = 'none'; // 클릭 통과 (게임 방해 X)
    canvas.style.zIndex = '9999'; // 모달보다 위에 뜨도록
    document.body.appendChild(canvas);

    const ctx = canvas.getContext('2d');
    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;

    // 리사이즈 대응
    window.addEventListener('resize', () => {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    });

    // 파티클 색상 (게임 테마색: 황금, 빨강, 초록, 파랑, 흰색)
    const colors = ['#f1c40f', '#e74c3c', '#2ecc71', '#3498db', '#ffffff'];
    const particles = [];

    // 파티클 생성 함수
    function createParticle() {
        return {
            x: Math.random() * width, // 화면 가로 랜덤 위치
            y: Math.random() * height - height, // 화면 위쪽에서 시작
            r: Math.random() * 10 + 5, // 크기
            color: colors[Math.floor(Math.random() * colors.length)],
            tilt: Math.floor(Math.random() * 10) - 10,
            tiltAngle: 0,
            tiltAngleIncr: (Math.random() * 0.07) + 0.05,
            dy: (Math.random() * 5) + 2, // 떨어지는 속도
            dx: (Math.random() * 2) - 1  // 흔들리는 정도
        };
    }

    // 초기 파티클 150개 생성
    for (let i = 0; i < 150; i++) {
        particles.push(createParticle());
    }

    // 애니메이션 루프
    (function frame() {
        const timeLeft = end - Date.now();

        // 시간이 다 되면 캔버스 지우고 종료
        if (timeLeft <= 0) {
            canvas.style.transition = 'opacity 1s';
            canvas.style.opacity = '0';
            setTimeout(() => canvas.remove(), 1000);
            return;
        }

        ctx.clearRect(0, 0, width, height);

        particles.forEach((p, i) => {
            p.tiltAngle += p.tiltAngleIncr;
            p.y += p.dy; // 아래로 떨어짐
            p.x += Math.sin(p.tiltAngle) * 2; // 좌우로 살랑살랑

            // 바닥에 닿으면 다시 위로 (시간 내에는 계속 순환)
            if (p.y > height) {
                particles[i] = createParticle();
                particles[i].y = -20; // 화면 위에서 다시 시작
            }

            // 그리기 (사각형 종이 모양)
            ctx.beginPath();
            ctx.lineWidth = p.r;
            ctx.strokeStyle = p.color;
            ctx.moveTo(p.x + p.tilt + p.r / 2, p.y);
            ctx.lineTo(p.x + p.tilt, p.y + p.tilt + p.r);
            ctx.stroke();
        });

        requestAnimationFrame(frame);
    }());
}

/* ========================================
   [정식 배포 버전 - 디버그 기능 제거됨]
   ======================================== */

/* =========================================
   [시스템: 암기 분석 리포트]
   ========================================= */

function buildChapterMemoryRows() {
    const chapterMap = {};
    gameData.forEach(ch => {
        if (!ch || !ch.stages) return;
        const chNum = ch.chapter || ch.id;
        const normals = ch.stages.filter(s => s.type === 'normal');
        if (!normals.length) return;
        let totalStep = 0, cleared = 0, totalStrength = 0;
        normals.forEach(s => {
            const step = (stageReviewStep && stageReviewStep[s.id]) || 0;
            if (step > 0) {
                totalStep += step;
                cleared++;
                totalStrength += getMemoryStrength(s.id);
            }
        });
        chapterMap[chNum] = { total: normals.length, cleared, avgStrength: cleared ? totalStrength / cleared : 0, avgStep: cleared ? totalStep / cleared : 0 };
    });

    return Object.entries(chapterMap).map(([ch, d]) => {
        const pct = Math.round(d.avgStrength * 100);
        const fillColor = pct >= 80 ? '#27ae60' : pct >= 60 ? '#f1c40f' : pct >= 40 ? '#e67e22' : '#e74c3c';
        const clearPct = d.total ? Math.round(d.cleared / d.total * 100) : 0;
        return `<div class="mr-chapter-row">
  <div class="mr-chapter-label"><span class="mr-ch-num">${ch}장</span><span class="mr-ch-stats">${d.cleared}/${d.total} 스테이지 · 기억강도 ${pct}%</span></div>
  <div class="mr-progress-bar"><div class="mr-progress-fill" style="width:${clearPct}%;background:${fillColor}"></div></div>
</div>`;
    }).join('');
}

function buildHardshipRows() {
    const types = [
        { key: 'endurance', label: '🕊️ 암송의 고난', data: hardshipEnduranceClearHistory, isEndurance: true },
        { key: 'address', label: '🎯 주소의 고난', data: hardshipAddressClearHistory },
        { key: 'verse', label: '📖 구절의 고난', data: hardshipVerseClearHistory },
        { key: 'memory', label: '⌨️ 망각의 고난', data: hardshipMemoryClearHistory }
    ];
    return types.map(type => {
        const entries = Object.entries(type.data || {});
        if (!entries.length) return `<div class="mr-hardship-box"><div class="mr-hardship-type">${type.label}</div><div class="mr-hardship-empty">기록 없음</div></div>`;
        const rows = entries.map(([ch, records]) => {
            const best = records.reduce((b, r) => (!b || r.score > b.score ? r : b), null);
            if (!best) return '';
            const sec = best.duration ? Math.round(best.duration) : 0;
            const mm = Math.floor(sec / 60), ss = String(sec % 60).padStart(2, '0');
            if (type.isEndurance) {
                return `<div class="mr-hardship-entry"><span class="mr-h-ch">${ch}장</span><span class="mr-h-score">${best.score}점</span><span class="mr-h-acc">${best.avgScore ?? 0}%</span><span class="mr-h-time">${mm}:${ss}</span></div>`;
            }
            const acc = best.total ? Math.round(best.correct / best.total * 100) : 0;
            return `<div class="mr-hardship-entry"><span class="mr-h-ch">${ch}장</span><span class="mr-h-score">${best.score}점</span><span class="mr-h-acc">${acc}%</span><span class="mr-h-time">${mm}:${ss}</span></div>`;
        }).filter(Boolean).join('');
        const header = `<div class="mr-hardship-entry mr-hardship-header"><span class="mr-h-ch">장</span><span class="mr-h-score">점수</span><span class="mr-h-acc">${type.isEndurance ? '평균' : '정확도'}</span><span class="mr-h-time">시간</span></div>`;
        return `<div class="mr-hardship-box"><div class="mr-hardship-type">${type.label}</div>${rows ? header + rows : '<div class="mr-hardship-empty">기록 없음</div>'}</div>`;
    }).join('');
}

function buildSummaryStats() {
    const totalSec = getTotalPlaySecondsNow();
    const hh = Math.floor(totalSec / 3600), mm = Math.floor((totalSec % 3600) / 60);
    const playStr = hh > 0 ? `${hh}시간 ${mm}분` : `${mm}분`;
    const streak = parseInt(localStorage.getItem('streakDays') || '0', 10);

    let clearedCount = 0, strengthSum = 0;
    gameData.forEach(ch => {
        if (!ch || !ch.stages) return;
        ch.stages.filter(s => s.type === 'normal').forEach(s => {
            const step = stageReviewStep && stageReviewStep[s.id];
            if (step > 0) { clearedCount++; strengthSum += getMemoryStrength(s.id); }
        });
    });
    const avgStr = clearedCount ? Math.round(strengthSum / clearedCount * 100) : 0;

    return `<div class="mr-summary-grid">
  <div class="mr-stat-box"><div class="mr-stat-val">${clearedCount}</div><div class="mr-stat-label">클리어 스테이지</div></div>
  <div class="mr-stat-box"><div class="mr-stat-val">${avgStr}%</div><div class="mr-stat-label">평균 기억강도</div></div>
  <div class="mr-stat-box"><div class="mr-stat-val">${playStr}</div><div class="mr-stat-label">총 플레이</div></div>
  <div class="mr-stat-box"><div class="mr-stat-val">${streak}일</div><div class="mr-stat-label">연속 학습</div></div>
</div>`;
}

function openMemoryReport() {
    const existing = document.getElementById('memory-report-overlay');
    if (existing) { existing.remove(); return; }

    const today = new Date();
    const dateStr = `${today.getFullYear()}.${String(today.getMonth()+1).padStart(2,'0')}.${String(today.getDate()).padStart(2,'0')}`;
    const nickname = myNickname || '순례자';

    const chapterRows = buildChapterMemoryRows();
    const summaryStats = buildSummaryStats();
    const hardshipRows = buildHardshipRows();

    const overlay = document.createElement('div');
    overlay.id = 'memory-report-overlay';
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `
<div class="memory-report-card" id="memory-report-card">
  <button class="mr-close-btn" onclick="document.getElementById('memory-report-overlay').remove()">✕</button>
  <div class="mr-header">
    <div class="mr-crown">👑</div>
    <div class="mr-nickname">${nickname}</div>
    <div class="mr-date">암기 리포트 · ${dateStr}</div>
  </div>
  <div class="mr-section">
    <div class="mr-section-title">📖 킹스로드 챕터별 암기 현황</div>
    ${chapterRows || '<div class="mr-empty">아직 클리어한 스테이지가 없습니다.</div>'}
  </div>
  <div class="mr-section">
    <div class="mr-section-title">📈 나의 암기 요약</div>
    ${summaryStats}
  </div>
  <div class="mr-section">
    <div class="mr-section-title">⚔️ 역경 최고 기록</div>
    <div class="mr-hardship-grid">${hardshipRows}</div>
  </div>
  <div class="mr-footer">King's Road · 말씀 암기 여정</div>
</div>`;

    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    document.body.appendChild(overlay);
}

/* =========================================
   [시스템: 업적(나의 기록실) UI 및 로직]
   ========================================= */

// 1. 업적 화면 열기 (수정됨)
function openAchievement() {
    // 다른 화면 끄기
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));

    // 화면이 없으면 생성 (최초 1회)
    let screen = document.getElementById('achievement-screen');
    if (!screen) {
        screen = document.createElement('div');
        screen.id = 'achievement-screen';
        screen.className = 'screen';
        // [유지] 방향 설정은 놔두셔도 됩니다 (CSS로 옮겨도 되지만 여기 둬도 무방)
        screen.style.flexDirection = 'column';
        screen.style.backgroundColor = '#2c3e50';

        screen.innerHTML = `
            <div class="map-header" style="justify-content: center; flex-shrink: 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
                <div style="font-weight:bold; font-size:1.3rem; color:#f1c40f;">${t('achievement_screen_title')}</div>
            </div>

            <div style="text-align:center; padding:15px; background:rgba(0,0,0,0.2); color:#bdc3c7; font-size:0.9rem; flex-shrink: 0;">
                ${t('achievement_screen_subtitle')}
            </div>

            <div id="record-summary" style="padding:15px; flex-shrink:0;">
            </div>

            <div id="achievement-list" style="flex: 1; overflow-y: auto; padding: 20px; padding-bottom: 80px;">
                </div>

            <div class="button-area-static">
                <button class="btn-gray btn-back" onclick="goMap()">${t('btn_go_back')}</button>
            </div>
        `;
        document.body.appendChild(screen);
    }

    screen.classList.add('active'); // 여기서 CSS가 display: flex를 적용해줍니다.
    renderMyPlayRecord();
    renderAchievementList(); // 목록 그리기
    // 백버튼 가시성 갱신 (기록실 화면에서는 보여야 함)
    if (typeof updateBackButtonVisibility === 'function') updateBackButtonVisibility();
}

// 2. 업적 목록 그리기 (핵심 로직)
function renderAchievementList() {
    const list = document.getElementById('achievement-list');
    if (!list) return;
    list.innerHTML = "";

    // 통계 변수 매핑 (데이터 키 -> userStats 키)
    const statsMap = {
        login: 'loginDays',
        verse: 'totalVersesCleared',
        boss: 'totalBossKilled',
        gem: 'totalGemsEarned',
        perfect: 'totalPerfects',
        castle: 'maxCastleLevel',
        earlybird: 'earlyBirdCounts'
    };

    // 아이콘 매핑
    const iconMap = {
        login: '🕯️', verse: '📖', boss: '🏆',
        gem: '💎', perfect: '✨', castle: '🏰', earlybird: '🌅'
    };

    // ACHIEVEMENT_DATA 순회
    for (let key in ACHIEVEMENT_DATA) {
        const data = ACHIEVEMENT_DATA[key];
        const currentTierIdx = achievementStatus[key] || 0; // 현재 단계 (0부터 시작)
        const maxTier = data.tiers.length;

        // 현재 내 수치 가져오기
        let myValue = 0;
        if (key === 'castle') {
            myValue = (typeof userStats !== 'undefined' && userStats.maxCastleLevel)
                ? userStats.maxCastleLevel : myCastleLevel;
        } else {
            myValue = (typeof userStats !== 'undefined') ? userStats[statsMap[key]] : 0;
        }
        if (!myValue) myValue = 0;

        // 아이템 박스 생성
        const item = document.createElement('div');

        item.style.cssText = "background:white; border-radius:15px; padding:15px; margin-bottom:15px; display:flex; align-items:center; box-shadow:0 4px 6px rgba(0,0,0,0.1);";

        // 왼쪽 아이콘
        const iconDiv = document.createElement('div');
        iconDiv.style.cssText = "font-size:2rem; margin-right:15px; width:50px; text-align:center;";
        iconDiv.innerText = iconMap[key] || '🏅';

        // 중간 정보
        const infoDiv = document.createElement('div');
        infoDiv.style.flex = "1";

        // 목표 설정
        let target = 0;
        let reward = 0;
        let isMax = false;

        if (currentTierIdx >= maxTier) {
            isMax = true; // 모든 단계 완료
            target = data.tiers[maxTier - 1]; // 마지막 목표 보여줌
        } else {
            target = data.tiers[currentTierIdx];
            reward = data.rewards[currentTierIdx];
        }

        // 진행률 계산
        let percent = Math.min(100, Math.floor((myValue / target) * 100));
        if (isMax) percent = 100;

        // 텍스트 생성
        const dataTitle = (currentLang === 'en' && data.titleEn) ? data.titleEn : data.title;
        const dataDesc = (currentLang === 'en' && data.descEn) ? data.descEn : data.desc;
        let titleHtml = `<div style="font-weight:bold; color:#2c3e50; font-size:1rem;">${dataTitle} <span style="font-size:0.8rem; color:#7f8c8d;">(Lv.${currentTierIdx + 1})</span></div>`;
        if (isMax) titleHtml = `<div style="font-weight:bold; color:#f1c40f; font-size:1rem;">${dataTitle} ${t('achievement_complete')}</div>`;

        let descHtml = `<div style="font-size:0.8rem; color:#95a5a6; margin-bottom:5px;">${dataDesc}</div>`;

        let progressHtml = `
            <div style="display:flex; justify-content:space-between; font-size:0.75rem; color:#7f8c8d; margin-bottom:2px;">
                <span>${t('achievement_progress_current', { val: myValue.toLocaleString() })}</span>
                <span>${t('achievement_progress_target', { val: target.toLocaleString() })}</span>
            </div>
            <div style="width:100%; height:8px; background:#ecf0f1; border-radius:4px; overflow:hidden;">
                <div style="width:${percent}%; height:100%; background:${isMax ? '#2ecc71' : '#f1c40f'}; transition:width 0.5s;"></div>
            </div>
        `;

        infoDiv.innerHTML = titleHtml + descHtml + progressHtml;

        // 오른쪽 버튼
        const btnDiv = document.createElement('div');
        btnDiv.style.marginLeft = "10px";

        if (isMax) {
            btnDiv.innerHTML = `<button disabled style="background:#2ecc71; color:white; border:none; padding:8px 12px; border-radius:10px; font-weight:bold; font-size:0.8rem;">${t('achievement_conquered')}</button>`;
        } else if (myValue >= target) {
            // 보상 받기 가능
            btnDiv.innerHTML = `<button onclick="claimAchievementReward('${key}')" class="btn-pulse" style="background:#f39c12; color:white; border:none; padding:8px 15px; border-radius:10px; font-weight:bold; cursor:pointer; font-size:0.85rem; box-shadow:0 3px 0 #d68910;">💎 ${reward}<br>${t('achievement_claim')}</button>`;
        } else {
            // 진행 중
            btnDiv.innerHTML = `<button disabled style="background:#ecf0f1; color:#bdc3c7; border:1px solid #bdc3c7; padding:8px 12px; border-radius:10px; font-size:0.8rem;">${t('achievement_in_progress')}</button>`;
        }

        item.appendChild(iconDiv);
        item.appendChild(infoDiv);
        item.appendChild(btnDiv);
        list.appendChild(item);
    }
}

// 3. 보상 받기 함수
function claimAchievementReward(key) {
    const data = ACHIEVEMENT_DATA[key];
    const currentTierIdx = achievementStatus[key] || 0;

    // 안전 장치
    if (currentTierIdx >= data.tiers.length) return;

    const reward = data.rewards[currentTierIdx];

    // 1. 보상 지급
    if (typeof myGems === 'undefined') myGems = 0;
    myGems += reward;

    // 2. 단계 상승 및 저장
    achievementStatus[key]++;

    // 3. 저장 및 갱신
    if (typeof updateGemDisplay === 'function') updateGemDisplay();
    if (typeof saveGameData === 'function') saveGameData();
    if (typeof syncToFirestore === 'function') syncToFirestore(); // [Firestore] 업적 보상 청구
    updateNotificationBadges();

    // 4. 효과음 및 알림
    if (typeof SoundEffect !== 'undefined') SoundEffect.playLevelUp(); // 또는 playGetGem
    if (typeof triggerConfetti === 'function') triggerConfetti();

    alert(t('alert_achievement', { title: (currentLang === 'en' && data.titleEn) ? data.titleEn : data.title, count: reward }));

    // 5. 리스트 새로고침 (다음 단계 보여주기 위해)
    renderAchievementList();
}

/* [시스템] 알림 배지 상태 업데이트 함수 */
function updateNotificationBadges() {
    // 1. 업적(기록실) 알림 체크
    let hasAchievementReward = false;

    // 모든 업적을 돌면서 '달성했으나 아직 안 받은 보상'이 있는지 확인
    for (let key in ACHIEVEMENT_DATA) {
        const data = ACHIEVEMENT_DATA[key];
        const currentTierIdx = achievementStatus[key] || 0;

        // 마지막 단계가 아니라면 체크
        if (currentTierIdx < data.tiers.length) {
            const target = data.tiers[currentTierIdx];

            // 내 수치 가져오기 (매핑 로직 재사용)
            const statsMap = { login: 'loginDays', verse: 'totalVersesCleared', boss: 'totalBossKilled', gem: 'totalGemsEarned', perfect: 'totalPerfects', castle: 'maxCastleLevel', earlybird: 'earlyBirdCounts' };
            let myValue = 0;
            if (key === 'castle') myValue = (typeof userStats !== 'undefined' && userStats.maxCastleLevel) ? userStats.maxCastleLevel : myCastleLevel;
            else myValue = (typeof userStats !== 'undefined') ? userStats[statsMap[key]] : 0;

            // 목표 달성했으면 알림 ON
            if (myValue >= target) {
                hasAchievementReward = true;
                break; // 하나라도 있으면 충분함
            }
        }
    }

    // 기록실 배지는 사용하지 않음 — 항상 숨김
    const achBadge = document.getElementById('badge-achievement');
    if (achBadge) achBadge.classList.remove('active');

    // 2. 미션 알림 체크
    let hasMissionReward = false;

    // 일일 미션 체크
    if (missionData && missionData.daily) {
        // 하드코딩된 목표치와 비교 (updateMissionUI 로직 참조)
        if ((missionData.daily.loginReward || 0) >= 1 && !missionData.daily.claimed[0]) hasMissionReward = true;
        if (missionData.daily.newClear >= 1 && !missionData.daily.claimed[1]) hasMissionReward = true;
        if (missionData.daily.checkpointBoss >= 1 && !missionData.daily.claimed[2]) hasMissionReward = true;
        const _checkMastery2 = [stageMastery, kingsRoadData && kingsRoadData.mastery].filter(Boolean);
        const _anyBossCleared = _checkMastery2.some(m => Object.keys(m).some(id => id.endsWith('-boss') && m[id] > 0));
        if (_anyBossCleared && (missionData.daily.hardshipAddress || 0) >= 1 && !missionData.daily.claimed[4]) hasMissionReward = true;
        if (_anyBossCleared && (missionData.daily.hardshipMemory || 0) >= 1 && !missionData.daily.claimed[5]) hasMissionReward = true;
        if (_anyBossCleared && (missionData.daily.hardshipEndurance || 0) >= 1 && !missionData.daily.claimed[6]) hasMissionReward = true;
        if (_anyBossCleared && (missionData.daily.hardshipVerse || 0) >= 1 && !missionData.daily.claimed[7]) hasMissionReward = true;
        // 주간 미션 고난 체크 (같은 스코프에서 _anyBossCleared 재사용)
        if (missionData.weekly && _anyBossCleared && (missionData.weekly.hardship || 0) >= 10 && !missionData.weekly.claimed[3]) hasMissionReward = true;
        // 심화 일일 미션 미수령 체크
        if (_anyBossCleared && missionData.advanced) {
            const addrClaimed = missionData.advanced.claimed[0] || 0;
            const addrClaimable = Math.max(0, (missionData.advanced.hardshipAddressChapters || []).length - 1);
            if (addrClaimable > addrClaimed) hasMissionReward = true;
            const memClaimed = missionData.advanced.claimed[1] || 0;
            const memClaimable = Math.max(0, (missionData.advanced.hardshipMemoryChapters || []).length - 1);
            if (memClaimable > memClaimed) hasMissionReward = true;
            const enduClaimed = missionData.advanced.claimed[2] || 0;
            const enduClaimable = Math.max(0, (missionData.advanced.hardshipEnduranceChapters || []).length - 1);
            if (enduClaimable > enduClaimed) hasMissionReward = true;
            const verseClaimed = missionData.advanced.claimed[3] || 0;
            const verseClaimable = Math.max(0, (missionData.advanced.hardshipVerseChapters || []).length - 1);
            if (verseClaimable > verseClaimed) hasMissionReward = true;
        }
    }
    // 주간 미션 체크
    if (missionData && missionData.weekly) {
        if (missionData.weekly.attendance >= 5 && !missionData.weekly.claimed[0]) hasMissionReward = true;
        if (missionData.weekly.dragonKill >= 5 && !missionData.weekly.claimed[1]) hasMissionReward = true;
        if (missionData.weekly.stageClear >= 15 && !missionData.weekly.claimed[2]) hasMissionReward = true;
        if ((missionData.weekly.dailyMissionClearCount || 0) >= 20 && !missionData.weekly.claimed[4]) hasMissionReward = true;
    }

    // 배지 켜기/끄기
    const misBadge = document.getElementById('badge-mission');
    if (misBadge) {
        if (hasMissionReward) misBadge.classList.add('active');
        else misBadge.classList.remove('active');
    }

    // 3. 더보기 알림 — 미션이 더보기로 들어갔으므로(2026-09-14) 미션 배지를 여기에도 비춘다. 떡은 이제 없다
    const moreBadge = document.getElementById('badge-more');
    const social = typeof _socialBadgeOn === 'function' && _socialBadgeOn();   // 친구 응원·길드 출석도 (9/30)
    if (moreBadge) {
        if (hasMissionReward || social) moreBadge.classList.add('active');
        else moreBadge.classList.remove('active');
    }
    if (typeof renderHomeTodo === 'function') renderHomeTodo();
}

/* [기능] 보스 타격 연출 함수 (흔들림 + 데미지 숫자) */
function triggerBossHitEffect() {
    const bossAvatar = document.querySelector('.boss-avatar');

    // 1. 흔들림 효과 (클래스 줬다 뺏기)
    if (bossAvatar) {
        bossAvatar.classList.remove('boss-hit-effect'); // 혹시 있으면 제거
        void bossAvatar.offsetWidth; // 리플로우 강제 (애니메이션 리셋용)
        bossAvatar.classList.add('boss-hit-effect');

        // 애니메이션 끝나면 클래스 제거 (깔끔하게)
        setTimeout(() => {
            bossAvatar.classList.remove('boss-hit-effect');
        }, 500);
    }

    // 2. 데미지 텍스트 띄우기 (머리 위에 -1)
    if (bossAvatar) {
        const damageText = document.createElement('div');
        damageText.className = 'floating-damage';
        damageText.innerText = "-1";

        // 보스 위치 기준으로 좌표 잡기
        const rect = bossAvatar.getBoundingClientRect();
        // 화면 중앙쯤에 배치 (보스 머리 위)
        damageText.style.left = (rect.left + rect.width / 2 - 10) + 'px';
        damageText.style.top = (rect.top) + 'px';

        document.body.appendChild(damageText);

        // 1초 뒤에 텍스트 삭제 (청소)
        setTimeout(() => damageText.remove(), 1000);
    }
}

/* [시스템] 마일스톤 팝업 처리기 */
function tryShowMilestone() {
    // 1. 이미 팝업이 떠 있거나, 대기열이 비었으면 중단
    if (isMilestoneShowing || milestoneQueue.length === 0) return;

    // 2. 현재 전투 화면(game-screen)이면 방해하지 않음 (단, 결과창은 제외)
    const gameScreen = document.getElementById('game-screen');
    const resultModal = document.getElementById('result-modal');

    // 게임 화면이 켜져있는데 결과창은 안 켜져있다? -> 한창 싸우는 중 -> 보류
    if (gameScreen.classList.contains('active') && !resultModal.classList.contains('active')) {
        console.log("⚔️ 전투 중이라 업적 알림을 보류합니다.");
        return;
    }

    // ★ 첫 스테이지를 깨기 전에는 보류한다.
    // 접속만 해도 '누적 출석 Lv.1'이 즉시 달성돼, 가입 직후 모달이 겹치고
    // 아무것도 안 한 상태에서 보상이 와 성취감도 약했다.
    // 첫 클리어 뒤 quitGame()의 플러시가 이 대기열을 이어받는다.
    if (_isPreFirstClear()) {
        console.log("🌱 첫 스테이지 클리어 전이라 업적 알림을 보류합니다.");
        return;
    }

    // 3. 팝업 표시 시작
    isMilestoneShowing = true;
    const item = milestoneQueue.shift(); // 대기열에서 하나 꺼냄

    // HTML 생성
    const overlay = document.getElementById('milestone-overlay') || createMilestoneOverlay();
    const iconMap = { login: '🕯️', verse: '📖', boss: '🏆', gem: '💎', perfect: '✨', castle: '🏰', earlybird: '🌅' };

    const rewardVal = item.data.rewards[item.tier];
    const milestoneTitle = (currentLang === 'en' && item.data.titleEn) ? item.data.titleEn : item.data.title;
    const milestoneDesc = (currentLang === 'en' && item.data.descEn) ? item.data.descEn : item.data.desc;

    // 내용 채우기
    overlay.innerHTML = `
        <div class="sunburst"></div>
        <div class="milestone-card">
            <div class="milestone-icon">${iconMap[item.key]}</div>
            <div class="milestone-title">LEVEL UP!</div>
            <div style="font-size:1.1rem; font-weight:bold; color:#2c3e50; margin-bottom:5px;">
                ${milestoneTitle}
            </div>
            <div class="milestone-desc">
                ${milestoneDesc}
            </div>

            <div class="milestone-reward">
                ${t('milestone_reward', { val: rewardVal })}
            </div>

            <button class="btn-get-reward" onclick="claimMilestoneReward('${item.key}', ${item.tier}, ${rewardVal})">
                ${t('milestone_btn')}
            </button>
        </div>
    `;

    overlay.style.display = 'flex';

    // 효과음: 팡파레! (기존 playClear보다 더 웅장하게)
    if (typeof SoundEffect !== 'undefined') {
        SoundEffect.playLevelUp(); // 기존 효과음 활용 (또는 새로 만들어도 됨)
    }
    if (typeof triggerConfetti === 'function') triggerConfetti(); // 폭죽 발사!
}

// 오버레이가 없으면 만드는 함수
function createMilestoneOverlay() {
    const div = document.createElement('div');
    div.id = 'milestone-overlay';
    document.body.appendChild(div);
    return div;
}

// 보상 받기 버튼 클릭 시
function claimMilestoneReward(key, tier, reward) {
    // 1. 보상 지급
    if (typeof myGems === 'undefined') myGems = 0;
    myGems += reward;

    // 2. 상태 업데이트
    achievementStatus[key] = tier + 1;

    // 3. 시각적 피드백 즉시 처리 (INP 개선)
    updateGemDisplay();
    const overlay = document.getElementById('milestone-overlay');
    overlay.style.display = 'none';
    isMilestoneShowing = false;

    // 4. 무거운 작업은 다음 태스크로 미뤄 브라우저가 먼저 페인트하게 함
    setTimeout(() => {
        saveGameData();
        syncToFirestore(); // [Firestore] 마일스톤 보상 청구
        updateNotificationBadges(); // 배지 갱신
        tryShowMilestone(); // 다음 대기열 확인 (연속 달성 시 줄줄이 사탕처럼 나옴)
    }, 0);
}

/* [시스템: 데이터 보호 시스템] */

// 페이지 종료/새로고침 직전 강제 저장
// 실수로 창을 닫거나 새로고침했을 때 마지막 순간을 기록합니다.
window.addEventListener("beforeunload", () => {
    saveGameData();
    if (typeof saveMyScoreToServer === 'function') saveMyScoreToServer();
});

// 앱 백그라운드 전환 시 저장, 포그라운드 복귀 시 미션 날짜/주차 체크
document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === 'hidden') {
        saveGameData();
    } else if (document.visibilityState === 'visible') {
        checkMissions();
        // 다른 기기에서 더 최근에 저장했는지 (1분에 한 번까지) — 있으면 「새로고침」 안내 (2026-09-29)
        //   예전엔 다른 기기가 '여정 시작'을 새로 눌렀을 때만 확인해서, 켜 둔 PC 탭은 폰 기록을 모른 채 있었다
        if (typeof checkRemoteIsNewer === 'function') checkRemoteIsNewer();
    }
});
// PC는 탭이 보이는 채로 창만 뒤로 가 있다 돌아오는 일이 많다 — 창에 초점이 올 때도 같은 확인
window.addEventListener('focus', () => { if (typeof checkRemoteIsNewer === 'function') checkRemoteIsNewer(); });

// [시스템] 스테이지 목록 강제 새로고침 (UI 갱신용)
function reloadCurrentChapterUI() {
    // 현재 선택된 스테이지 ID가 없다면 중단
    if (!window.currentStageId) return;

    // ID에서 챕터 번호 추출 (예: "1-1" -> 1)
    const chNum = parseInt(window.currentStageId.split('-')[0]);

    // 해당 챕터의 데이터를 찾음
    const chData = gameData.find(c => c.id === chNum);

    // 스테이지 시트(목록)를 다시 엽니다 (이 과정에서 버튼 상태가 갱신됨)
    if (chData) {
        openStageSheet(chData);
    }
}

// [시스템] 스테이지 ID로 해당 챕터 시트 열기 (클리어 후 자동 표시용)
function openStageSheetForStageId(stageId) {
    if (!stageId) return;
    const chNum = parseInt(String(stageId).split('-')[0]);
    if (isNaN(chNum)) return;
    const chData = gameData.find(c => c.id === chNum);
    if (chData) {
        openStageSheet(chData);
    }
}

/* =========================================
   [서버 연동] 파이어베이스 점수 저장 및 시온성 심사
   ========================================= */
let lastScorePayloadKey = null;
function saveMyScoreToServer() {
    if (typeof db === 'undefined' || !db || !myTag || myTag === '0000') return;

    const currentWeekId = leagueData.weekId || getWeekId();
    const currentScore = leagueData.myScore || 0;

    // 👉 [추가된 부분] 월간 ID와 월간 점수도 꼭 챙겨야 합니다!
    const currentMonthId = leagueData.monthId || getMonthId();
    const currentMonthlyScore = leagueData.myMonthlyScore || 0;
    // 🌟 [핵심 수술 3단계: 서버로 보낼 짐싸기]
    const currentTotalScore = leagueData.totalScore || 0;
    const currentYearlyScore = leagueData.yearlyScore || 0; // 🌟 추가

    const payload = {
        nickname: myNickname,
        score: currentScore,
        castleLv: myCastleLevel,
        tribe: myTribe,
        dept: myDept,
        tag: myTag,
        weekId: currentWeekId,
        monthId: currentMonthId,
        myMonthlyScore: currentMonthlyScore,
        totalScore: currentTotalScore, // 👉 누적 승점 항목 추가!
        yearlyScore: currentYearlyScore, // 🌟 추가 (이걸 바탕으로 서버가 지파 합산을 합니다)
        maxHearts: maxPlayerHearts,
        // 실시간 암송왕 — recallWeek이 지난 주 것이면 지난 주 id가 그대로 가서 이번 주 조회에 안 잡힌다 (의도)
        recallWeekId: recallWeek.weekId || currentWeekId,
        recallCount: recallWeek.count || 0,
        // 실시간 통독왕
        readWeekId: readWeek.weekId || currentWeekId,
        readCount: readWeek.count || 0,
        // 오늘의 암송 — ✅(오늘 마친 날짜)·📅 암송완료(주차). 없으면 빈 문자열
        dailyDoneDate: _dailyDoneToday() ? _get6AMDayStr() : '',
        weeklyDoneWeek: dailyWeekDone || ''
    };
    // 시험 준비 참여 — 대시보드 집계용 (saves를 훑지 않고 leaderboard에서 세려고). 활성 이벤트 하나만
    const _evStat = _eventStatForServer();
    if (_evStat) Object.assign(payload, _evStat);

    // 월 전환 시 이전달 백업 데이터가 있으면 함께 전송 (CF 아카이빙 경쟁조건 방어)
    if (leagueData.prevMonthId && leagueData.prevMonthlyScore > 0) {
        payload.prevMonthId = leagueData.prevMonthId;
        payload.prevMonthlyScore = leagueData.prevMonthlyScore;
    }

    // 주 전환 시 이전주 백업 데이터가 있으면 함께 전송 (CF 아카이빙 경쟁조건 방어)
    if (leagueData.prevWeekId && leagueData.prevWeekScore > 0) {
        payload.prevWeekId = leagueData.prevWeekId;
        payload.prevWeekScore = leagueData.prevWeekScore;
    }

    // 주간 히스토리 서버 전송 (수동 복구용)
    if (leagueData.weeklyHistory && Object.keys(leagueData.weeklyHistory).length > 0) {
        payload.weeklyHistory = leagueData.weeklyHistory;
    }

    if (typeof lastScorePayloadKey === 'undefined' || lastScorePayloadKey === null) {
        try {
            lastScorePayloadKey = localStorage.getItem("kingsroad_last_score_payload") || "";
        } catch (e) {
            lastScorePayloadKey = "";
        }
    }

    const nextKey = JSON.stringify(payload);

    // ★ 방어막: 데이터가 이전과 똑같다면 파이어베이스에 안 보내고 조용히 함수 종료!
    if (nextKey === lastScorePayloadKey) return;

    // ★ 진짜로 서버에 데이터를 보낼 때만 로그를 띄우도록 위치 변경
    console.log("📡 점수 변동 감지! 서버에 주간 점수 저장 중...");

    // 점수는 직접 쓰지 않고 검증 CF(submitScoreSecure)로만 제출한다 (조작 방지).
    const _submitScore = firebase.app().functions('asia-northeast3').httpsCallable('submitScoreSecure');
    _callWithSaveDocRetry(() => _submitScore({ ...payload, myTag }))
        .then(() => {
            lastScorePayloadKey = nextKey;
            try {
                localStorage.setItem("kingsroad_last_score_payload", nextKey);
            } catch (e) {
                // Ignore storage errors.
            }
            console.log(`✅ 서버 저장 완료: ${currentScore}점 (${currentWeekId})`);
            // 구형 문서(tag가 숫자로 저장된 것) 1회 자동 삭제
            if (!localStorage.getItem('kingsroad_legacy_cleanup_done') && myTag && myTag !== '0000') {
                const numericTag = parseInt(myTag, 10);
                if (!isNaN(numericTag)) {
                    db.collection('leaderboard')
                        .where('tag', '==', numericTag)
                        .get()
                        .then(snapshot => {
                            snapshot.forEach(doc => {
                                if (doc.id !== myTag) {
                                    doc.ref.delete().catch(() => {});
                                }
                            });
                            localStorage.setItem('kingsroad_legacy_cleanup_done', '1');
                        })
                        .catch(() => {});
                }
            }
        })
        .catch((error) => {
            console.error("❌ 점수 저장 실패:", error);
            // 조용히 실패하면 유저는 랭킹 점수가 안 올라간 걸 알 수 없다.
            _showSyncFailToast(error, '점수 반영 실패');
        });
}

function renderMyPlayRecord() {
    const summary = document.getElementById('record-summary');
    if (!summary) return;
    ensurePlaytimeStats();

    const totalPlaySeconds = getTotalPlaySecondsNow();
    const avgDailySeconds = getAverageDailySecondsLast7Days();
    const counts = getStageClearCounts();
    const totalMemoryLevel = getTotalMemoryLevel();
    const gems = (userStats && typeof userStats.totalGemsEarned === 'number') ? userStats.totalGemsEarned : 0;
    const score = (userStats && typeof userStats.totalScoreEarned === 'number') ? userStats.totalScoreEarned : 0;

    const tile = (icon, label, value, accent) => `
        <div style="background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.12); border-radius:12px; padding:10px; color:#ecf0f1; font-size:0.85rem; box-shadow:0 6px 12px rgba(0,0,0,0.2);">
            <div style="display:flex; align-items:center; gap:6px; color:#95a5a6; font-size:0.75rem; margin-bottom:4px;">
                <span>${icon}</span><span>${label}</span>
            </div>
            <div style="font-weight:bold; font-size:1rem; color:${accent};">${value}</div>
        </div>
    `;

    summary.innerHTML = `
        <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:15px;">
            <div style="background:rgba(241,196,15,0.15); border:1px solid rgba(241,196,15,0.4); color:#f1c40f; padding:6px 10px; border-radius:999px; font-size:0.8rem; font-weight:bold;">
                ${t('record_badge_score', { val: score.toLocaleString() })}
            </div>
            <div style="background:rgba(52,152,219,0.15); border:1px solid rgba(52,152,219,0.4); color:#7fbdf0; padding:6px 10px; border-radius:999px; font-size:0.8rem; font-weight:bold;">
                ${t('record_badge_gems', { val: gems.toLocaleString() })}
            </div>
            <div style="background:rgba(46,204,113,0.15); border:1px solid rgba(46,204,113,0.4); color:#2ecc71; padding:6px 10px; border-radius:999px; font-size:0.8rem; font-weight:bold;">
                ${t('record_badge_playtime', { val: formatDuration(totalPlaySeconds) })}
            </div>
        </div>

        <div class="record-accordion" style="width: 100%; border-radius: 15px; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); overflow: hidden;">
            <button class="accordion-header" onclick="toggleAccordion('detail-stats', this)" style="width: 100%; padding: 15px 20px; background: rgba(0,0,0,0.2); color: #f1c40f; border: none; text-align: left; font-size: 1.1rem; font-family: 'Jua', sans-serif; cursor: pointer; display: flex; justify-content: space-between; align-items: center;">
                <span>${t('record_detail_title')}</span>
                <span class="toggle-icon" style="font-size: 0.9rem; transition: transform 0.3s ease;">▼</span>
            </button>

            <div id="detail-stats" class="accordion-content" style="max-height: 0; overflow: hidden; transition: max-height 0.4s ease-out, padding 0.4s ease; background: rgba(255,255,255,0.02);">
                <div style="display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap:10px; padding: 15px 20px;">
                    ${tile("⏱️", t('record_tile_playtime'), formatDuration(totalPlaySeconds), "#f1c40f")}
                    ${tile("📆", t('record_tile_avg7d'), formatDuration(avgDailySeconds), "#7fbdf0")}
                    ${tile("📖", t('record_tile_normal'), t('record_count', { n: counts.normal.toLocaleString() }), "#ecf0f1")}
                    ${tile("🐲", t('record_tile_bossmid'), t('record_count', { n: counts.bossMid.toLocaleString() }), "#ecf0f1")}
                    ${tile("💎", t('record_tile_gems'), t('record_count', { n: gems.toLocaleString() }), "#7fbdf0")}
                    ${tile("🏅", t('record_tile_score'), `${score.toLocaleString()} pts`, "#f1c40f")}
                    ${tile("💜", t('record_tile_memory'), t('record_memory_lv', { n: totalMemoryLevel }), "#b487ff")}
                </div>
            </div>
        </div>
        `;
}

// 🌟 아코디언을 열고 닫는 스위치 함수 (game.js 맨 아래나 적당한 곳에 추가해 주세요)
function toggleAccordion(contentId, btnElement) {
    const content = document.getElementById(contentId);

    // 내용물이 열려있으면 닫고, 닫혀있으면 엽니다
    if (content.style.maxHeight && content.style.maxHeight !== '0px') {
        content.style.maxHeight = '0px';
        content.style.paddingTop = '0px';
        content.style.paddingBottom = '0px';
        btnElement.querySelector('.toggle-icon').style.transform = 'rotate(0deg)';
    } else {
        content.style.maxHeight = '800px'; // 타일들이 다 보일 만큼 넉넉한 높이
        content.style.paddingTop = '0px';
        content.style.paddingBottom = '0px';
        btnElement.querySelector('.toggle-icon').style.transform = 'rotate(180deg)';
    }
}
