let _gq = null;
function _gShuffle(a) { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
function openGuideQuiz(review) {
    _gq = { list: _gShuffle(GUIDE_QUIZ.map((_, i) => i)), pos: 0, wrong: [], round: 1, review: !!review, shown: null };
    let ov = document.getElementById('guide-quiz-overlay');
    if (!ov) {
        ov = document.createElement('div'); ov.id = 'guide-quiz-overlay'; ov.className = 'friend-overlay';
        ov.innerHTML = `<div class="friend-panel"><div class="friend-panel-header"><span class="friend-panel-title">📝 인도자 시험</span>
            <button class="friend-close-btn" onclick="document.getElementById('guide-quiz-overlay').style.display='none'">✕</button></div>
            <div id="guide-quiz-body" class="friend-screen-body guide-body"></div></div>`;
        document.body.appendChild(ov);
    }
    ov.style.display = 'flex';
    _guideQuizRender();
}
function _guideQuizRender() {
    const body = document.getElementById('guide-quiz-body'); if (!body || !_gq) return;
    if (_gq.pos >= _gq.list.length) {
        if (_gq.wrong.length) {
            body.innerHTML = `<div class="guide-quiz-end">틀린 문제 <b>${_gq.wrong.length}</b>개를 다시 풀어요.<br><span class="guide-dim">해설을 떠올리며 천천히 — 다 맞히면 끝나요.</span></div>
                <button class="guide-btn main" onclick="_gq.list=_gShuffle(_gq.wrong);_gq.wrong=[];_gq.pos=0;_gq.round++;_guideQuizRender()">다시 풀기</button>`;
        } else _guideQuizPass(body);
        return;
    }
    const Q = GUIDE_QUIZ[_gq.list[_gq.pos]], opts = _gShuffle([Q.a, ...Q.w]);
    _gq.shown = opts;
    body.innerHTML = `<div class="guide-quiz-n">${_gq.round > 1 ? `다시 풀기 ${_gq.round - 1}번째 · ` : ''}${_gq.pos + 1} / ${_gq.list.length}</div>
        <div class="guide-quiz-q">${_gEsc(Q.q)}</div>
        <div class="guide-quiz-opts">${opts.map((o, i) => `<button class="guide-quiz-opt" onclick="_guideQuizPick(${i}, this)">${_gEsc(o)}</button>`).join('')}</div>
        <div id="guide-quiz-fb"></div>`;
}
function _guideQuizPick(i, btn) {
    const Q = GUIDE_QUIZ[_gq.list[_gq.pos]], ok = _gq.shown[i] === Q.a;
    document.querySelectorAll('.guide-quiz-opt').forEach((b, k) => { b.disabled = true; if (_gq.shown[k] === Q.a) b.classList.add('right'); });
    if (!ok) { btn.classList.add('wrong'); _gq.wrong.push(_gq.list[_gq.pos]); }
    const fb = document.getElementById('guide-quiz-fb');
    if (fb) fb.innerHTML = `<div class="guide-quiz-exp ${ok ? 'ok' : 'no'}">${ok ? '⭕ 맞아요' : '❌ 아쉬워요'} — ${_gEsc(Q.e)}</div>
        <button class="guide-btn main" onclick="_gq.pos++;_guideQuizRender()">다음</button>`;
}
async function _guideQuizPass(body) {
    if (_gq.review || guideInfo.passedAt) {
        body.innerHTML = `<div class="guide-quiz-end">🎉 다 맞혔어요!</div><button class="guide-btn main" onclick="document.getElementById('guide-quiz-overlay').style.display='none'">닫기</button>`;
        return;
    }
    body.innerHTML = `<div class="guide-quiz-end">🎉 다 맞혔어요! 인도자로 등록하는 중…</div>`;
    try {
        const r = await _callGuildFn('guidePass', { nick: myNickname });
        if (r && r.ok) {
            guideInfo.passedAt = r.passedAt; guideInfo.grads = r.grads || 0; saveGameData();
            body.innerHTML = `<div class="guide-quiz-end">🧭 이제 인도자예요!<br><br>내 인도자 코드는 <b>#${_gEsc(myTag)}</b>예요.<br>
                <span class="guide-dim">새로 시작하는 친구를 만나면 이 코드를 알려 주고, 그 자리에서 함께 시작해 보세요 — 홈 화면에 추가하기, 알림 켜기, 첫 절 외우기.</span></div>
                <button class="guide-btn main" onclick="document.getElementById('guide-quiz-overlay').style.display='none';_renderGuideScreen(true)">확인</button>`;
            return;
        }
    } catch (e) { console.warn('[guide] pass', e); }
    body.innerHTML = `<div class="guide-quiz-end">등록하지 못했어요. 잠시 뒤에 다시 해 주세요.</div><button class="guide-btn main" onclick="_guideQuizPass(document.getElementById('guide-quiz-body'))">다시 등록</button>`;
}

function openFriendScreen() {
    closeMoreMenu();
    if (!myTag || myTag === '0000') { showGemToast(0, '닉네임을 먼저 설정해주세요.', true); return; }
    let overlay = document.getElementById('friend-screen-overlay');
    if (overlay) { overlay.style.display = 'flex'; _renderFriendScreen(); return; }

    overlay = document.createElement('div');
    overlay.id = 'friend-screen-overlay';
    overlay.className = 'friend-overlay';
    overlay.innerHTML = `
        <div class="friend-panel">
            <div class="friend-panel-header">
                <span class="friend-panel-title">👥 친구</span>
                <button class="friend-close-btn" onclick="closeFriendScreen()">✕</button>
            </div>
            <div class="friend-add-row">
                <input id="friend-tag-input" class="friend-tag-input" placeholder="코드 입력 (#ABCD12)" maxlength="7" />
                <button class="friend-add-btn" onclick="_submitFriendRequest()">신청</button>
            </div>
            <div id="friend-screen-body" class="friend-screen-body">
                <div style="text-align:center; color:#95a5a6; padding:30px;">불러오는 중…</div>
            </div>
        </div>
    `;
    document.body.appendChild(overlay);
    _renderFriendScreen();
}

function closeFriendScreen() {
    const overlay = document.getElementById('friend-screen-overlay');
    if (overlay) overlay.style.display = 'none';
}

async function _renderFriendScreen() {
    const body = document.getElementById('friend-screen-body');
    if (!body || !db || !myTag) return;
    body.innerHTML = '<div style="text-align:center; color:#95a5a6; padding:30px;">불러오는 중…</div>';

    const data = await _getFriendDoc(myTag);
    if (!data) { body.innerHTML = '<div style="text-align:center; color:#e74c3c; padding:20px;">데이터를 불러올 수 없습니다.</div>'; return; }

    const now = Date.now();
    const received = (data.pendingReceived || []).filter(r => (now - r.sentAt) < FRIEND_REQUEST_TTL_MS);
    const friends = data.friends || [];
    const pendingCheers = data.pendingCheers || [];

    let html = '';

    // 받은 응원 목록
    if (pendingCheers.length > 0) {
        const totalGems = pendingCheers.reduce((sum, c) => sum + (c.gems || CHEER_GEM_AMOUNT), 0);
        const bySender = new Map();   // 보낸 사람별로 묶는다 — 응원이 여러 날 쌓일 수 있다
        pendingCheers.forEach(c => {
            const k = c.fromTag || c.from || '?';
            const g = bySender.get(k) || { c, n: 0, gems: 0 };
            g.n++; g.gems += c.gems || CHEER_GEM_AMOUNT; bySender.set(k, g);
        });
        html += `<div class="friend-section-title">💛 받은 응원 (${bySender.size}명${pendingCheers.length > bySender.size ? ` · ${pendingCheers.length}번` : ''})</div>`;
        html += `<div class="friend-cheer-received-wrap">`;
        bySender.forEach(({ c, n, gems }) => {
            const memo = getFriendMemo(c.fromTag || '');
            const label = memo || c.from || '친구';
            const sub = memo ? c.from || '' : (c.fromTag ? `#${c.fromTag}` : '');
            html += `<div class="friend-cheer-received-item">
                <span class="friend-cheer-from">${label}${n > 1 ? ` ×${n}` : ''}</span>
                ${sub ? `<span class="friend-cheer-from-sub">${sub}</span>` : ''}
                <span class="friend-cheer-gem">+💎${gems}</span>
            </div>`;
        });
        html += `</div>`;
        html += `<button class="friend-claim-btn" onclick="_claimAllCheers()">💎${totalGems} 일괄 수령</button>`;
    }

    // 친구 신청 목록
    if (received.length > 0) {
        html += `<div class="friend-section-title">📬 친구 신청 (${received.length})</div>`;
        received.forEach(r => {
            const tribe = (TRIBE_DATA[r.tribe] && TRIBE_DATA[r.tribe].name) ? TRIBE_DATA[r.tribe].name : '';
            const elapsed = Math.floor((now - r.sentAt) / 3600000);
            const timeStr = elapsed < 1 ? '방금' : `${elapsed}시간 전`;
            html += `
                <div class="friend-request-item">
                    <div class="friend-req-info">
                        <span class="friend-req-name">${escapeHtml(r.nickname || '순례자')}</span>
                        <span class="friend-req-meta">${tribe ? tribe + ' · ' : ''}#${r.tag} · ${timeStr}</span>
                    </div>
                    <div class="friend-req-btns">
                        <button class="friend-btn-accept" onclick="_acceptRequest('${r.tag}')">수락</button>
                        <button class="friend-btn-reject" onclick="_rejectRequest('${r.tag}')">거절</button>
                    </div>
                </div>`;
        });
    }

    // 친구 목록
    const todayStr = _getLocalDateStr(new Date());
    const cheerMap = (typeof data.lastCheerSent === 'object' && data.lastCheerSent) ? data.lastCheerSent : {};
    const cheerableCount = friends.filter(tag => cheerMap[tag] !== todayStr).length;
    html += `<div class="friend-section-title" style="display:flex;align-items:center;justify-content:space-between;">
        <span>👤 친구 목록 (${friends.length}/${FRIEND_MAX})${friends.length > 1 ? ' <span class="friend-list-sort-hint">· 지난주 점수순</span>' : ''}</span>
        ${cheerableCount > 0 ? `<button id="friend-cheer-all-btn" class="friend-cheer-all-btn" onclick="_cheerAllFriends()">💛 모두 응원 (${cheerableCount})</button>` : ''}
    </div>`;
    if (friends.length === 0) {
        html += `<div class="friend-empty">아직 친구가 없습니다.<br>코드로 친구를 추가해보세요!</div>`;
    } else {
        // 친구별 지난주 점수를 미리 조회한다 — 목록에 표시하고 내림차순 정렬하기 위함.
        // 최대 20명(FRIEND_MAX)이라 병렬 조회로 충분하며, 실패한 친구는 0점으로 둔다.
        const _lastWeekId = getLastWeekId();
        const _docs = await Promise.all(friends.map(tag => _getFriendDoc(tag).catch(() => null)));
        const friendRows = friends.map((tag, i) => {
            const d = _docs[i];
            return {
                tag,
                nickname: (d && d.nickname) || '',
                lastWeekScore: d ? ((d.weeklyHistory && d.weeklyHistory[_lastWeekId]) || d.prevWeekScore || 0) : 0,
                dailyDoneDate: (d && d.dailyDoneDate) || '',
                weeklyDoneWeek: (d && d.weeklyDoneWeek) || ''
            };
        });
        friendRows.sort((a, b) => b.lastWeekScore - a.lastWeekScore);

        friendRows.forEach((fr) => {
            const { tag, nickname, lastWeekScore } = fr;
            const memo = getFriendMemo(tag);
            const cheered = cheerMap[tag] === todayStr;
            html += `<div class="friend-list-item" onclick="openFriendProfile('${tag}')">
                <div class="friend-list-info">
                    <span class="friend-list-name">${escapeHtml(nickname || '순례자')}${_dailyBadgeHtml(fr, { daily: true })}</span>
                    <span class="friend-list-sub">#${tag}${memo ? ` · ${escapeHtml(memo)}` : ''}</span>
                </div>
                <span class="friend-list-score">${lastWeekScore.toLocaleString()}점</span>
                <div class="friend-list-actions" onclick="event.stopPropagation()">
                    <button class="friend-cheer-list-btn${cheered ? ' done' : ''}" onclick="_cheerFriendFromList('${tag}',this)" ${cheered ? 'disabled' : ''}>${cheered ? '✓' : '💛'}</button>
                    <button class="friend-cheer-list-btn gift${njGiftSent[tag] === _get6AMDayStr() ? ' done' : ''}" onclick="openGiftFruit('${tag}', ${JSON.stringify(nickname || '').replace(/"/g, '&quot;')})" title="🎁">🎁</button>
                    <span class="friend-list-arrow">▶</span>
                </div>
            </div>`;
        });
    }

    body.innerHTML = html;

    // 내 코드 표시
    const input = document.getElementById('friend-tag-input');
    if (input && !input.dataset.hint) {
        input.dataset.hint = '1';
        const myCodeEl = document.createElement('div');
        myCodeEl.className = 'friend-my-code';
        myCodeEl.innerHTML = `내 코드: <strong>#${myTag}</strong>`;
        input.parentElement.insertAdjacentElement('afterend', myCodeEl);
    }

    updateFriendBadge();
}

async function _claimAllCheers() {
    const btn = document.querySelector('.friend-claim-btn');
    if (btn) { btn.disabled = true; btn.textContent = '수령 중…'; }
    try {
        const data = await _getFriendDoc(myTag);
        const cheers = data?.pendingCheers || [];
        if (cheers.length === 0) { _renderFriendScreen(); return; }
        const totalGems = cheers.reduce((sum, c) => sum + (c.gems || CHEER_GEM_AMOUNT), 0);
        myGems += totalGems;
        updateGemDisplay();
        saveGameData();
        await _friendRef(myTag).set({ pendingCheers: firebase.firestore.FieldValue.arrayRemove(...cheers) }, { merge: true });   // 읽은 것만 — 그 사이 온 응원은 남는다
        showGemToast(totalGems, `💛 응원 수령 완료! (+💎${totalGems})`);
        _renderFriendScreen();
    } catch (e) {
        if (btn) { btn.disabled = false; btn.textContent = '다시 시도'; }
    }
}

async function _submitFriendRequest() {
    const input = document.getElementById('friend-tag-input');
    if (!input) return;
    const raw = input.value.trim().replace(/^#/, '').toUpperCase();
    const is6Char = raw.length === 6;
    const is4Digit = raw.length === 4 && /^\d{4}$/.test(raw);
    if (!is6Char && !is4Digit) { showGemToast(0, '올바른 코드를 입력하세요.', true); return; }
    if (raw === '0000') { showGemToast(0, '존재하지 않는 코드입니다.', true); return; }

    const btn = document.querySelector('.friend-add-btn');
    if (btn) { btn.disabled = true; btn.textContent = '…'; }
    const result = await sendFriendRequest(raw);
    if (btn) { btn.disabled = false; btn.textContent = '신청'; }

    showGemToast(0, result.msg, !result.ok);
    if (result.ok) { input.value = ''; _renderFriendScreen(); }
}

async function _acceptRequest(senderTag) {
    await acceptFriendRequest(senderTag);
    _renderFriendScreen();
}

async function _rejectRequest(senderTag) {
    await rejectFriendRequest(senderTag);
    _renderFriendScreen();
}

// --- 친구 프로필 모달 ---

async function openFriendProfile(tag) {
    let modal = document.getElementById('friend-profile-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'friend-profile-modal';
        modal.className = 'friend-profile-modal';
        modal.innerHTML = `<div class="friend-profile-card" id="friend-profile-card"></div>`;
        modal.addEventListener('click', e => { if (e.target === modal) closeFriendProfile(); });
        document.body.appendChild(modal);
    }
    modal.style.display = 'flex';
    const card = document.getElementById('friend-profile-card');
    card.innerHTML = '<div style="text-align:center; padding:30px; color:#95a5a6;">불러오는 중…</div>';

    try {
        const data = await _getFriendDoc(tag);
        if (!data) { card.innerHTML = '<div style="text-align:center; padding:20px; color:#e74c3c;">정보를 불러올 수 없습니다.</div>'; return; }

        const tribe = (TRIBE_DATA[data.tribe] && TRIBE_DATA[data.tribe].name) ? TRIBE_DATA[data.tribe].name : '';
        const weeklyScore = data.score || 0;
        const lastWeekId = getLastWeekId();
        const lastWeekScore = (data.weeklyHistory && data.weeklyHistory[lastWeekId]) || data.prevWeekScore || 0;
        const totalScore = data.totalScore || 0;

        const todayStr = _getLocalDateStr(new Date());
        const myData = await _getFriendDoc(myTag);
        const cheerMap2 = (typeof myData?.lastCheerSent === 'object' && myData.lastCheerSent) ? myData.lastCheerSent : {};
        const alreadyCheered = cheerMap2[tag] === todayStr;

        card.innerHTML = `
            <button class="friend-profile-close" onclick="closeFriendProfile()">✕</button>
            <div class="friend-profile-name">${escapeHtml(data.nickname || '순례자')}</div>
            <div class="friend-profile-meta">${tribe ? tribe + ' · ' : ''}#${tag}</div>
            <div class="friend-profile-scores">
                <div class="friend-score-box">
                    <div class="friend-score-label">이번 주</div>
                    <div class="friend-score-val">${weeklyScore.toLocaleString()}점</div>
                </div>
                <div class="friend-score-box">
                    <div class="friend-score-label">지난 주</div>
                    <div class="friend-score-val">${lastWeekScore.toLocaleString()}점</div>
                </div>
                <div class="friend-score-box">
                    <div class="friend-score-label">누적</div>
                    <div class="friend-score-val">${totalScore.toLocaleString()}점</div>
                </div>
            </div>
            <button class="friend-cheer-btn${alreadyCheered ? ' cheered' : ''}" onclick="_cheerFriend('${tag}', this)" ${alreadyCheered ? 'disabled' : ''}>
                ${alreadyCheered ? '💛 오늘 응원 완료' : '💛 응원하기 (+💎50)'}
            </button>
            <div class="friend-memo-wrap">
                <input id="friend-memo-input" class="friend-memo-input" type="text"
                    placeholder="메모 (나만 보임)" maxlength="20"
                    value="${getFriendMemo(tag).replace(/"/g, '&quot;')}" />
                <button class="friend-memo-save" onclick="_saveMemo('${tag}')">저장</button>
            </div>
            <div class="friend-danger-btns">
                <button class="friend-btn-unfriend" onclick="_removeFriend('${tag}')">친구 끊기</button>
                <button class="friend-btn-block" onclick="_blockUser('${tag}')">차단</button>
            </div>
        `;
    } catch (e) {
        card.innerHTML = '<div style="text-align:center; padding:20px; color:#e74c3c;">오류가 발생했습니다.</div>';
    }
}

function closeFriendProfile() {
    const modal = document.getElementById('friend-profile-modal');
    if (modal) modal.style.display = 'none';
}

async function _cheerFriend(tag, btn) {
    if (btn) { btn.disabled = true; btn.textContent = '…'; }
    const result = await cheerFriend(tag);
    showGemToast(0, result.msg, !result.ok);
    if (result.ok && btn) { btn.textContent = '💛 오늘 응원 완료'; btn.classList.add('cheered'); }
    else if (!result.ok && btn) { btn.disabled = false; btn.textContent = '💛 응원하기 (+💎50)'; }
}

async function _cheerFriendFromList(tag, btn) {
    if (btn) { btn.disabled = true; btn.textContent = '…'; }
    const result = await cheerFriend(tag);
    if (result.ok) {
        if (btn) { btn.textContent = '✓'; btn.classList.add('done'); }
        // 모두 응원 버튼 카운트 갱신
        const allBtn = document.getElementById('friend-cheer-all-btn');
        if (allBtn) {
            const m = allBtn.textContent.match(/\((\d+)\)/);
            const n = m ? parseInt(m[1]) - 1 : 0;
            if (n <= 0) allBtn.remove();
            else allBtn.textContent = `💛 모두 응원 (${n})`;
        }
        showGemToast(CHEER_GEM_AMOUNT);
    } else {
        if (btn) { btn.disabled = false; btn.textContent = '💛'; }
        showGemToast(0, result.msg, true);
    }
}

async function _cheerAllFriends() {
    const allBtn = document.getElementById('friend-cheer-all-btn');
    if (allBtn) { allBtn.disabled = true; allBtn.textContent = '보내는 중…'; }

    const myData = await _getFriendDoc(myTag);
    if (!myData) { if (allBtn) { allBtn.disabled = false; } return; }

    const todayStr = _getLocalDateStr(new Date());
    const cheerMap = (typeof myData.lastCheerSent === 'object' && myData.lastCheerSent) ? myData.lastCheerSent : {};
    const friends = myData.friends || [];

    // 오늘 아직 응원 안 한 친구만
    const targets = friends.filter(tag => cheerMap[tag] !== todayStr);
    if (targets.length === 0) {
        showGemToast(0, '오늘은 모든 친구에게 이미 응원을 보냈습니다.', true);
        if (allBtn) allBtn.remove();
        return;
    }

    // 대상 친구 doc 병렬 읽기
    const friendDocs = await Promise.all(targets.map(tag => _getFriendDoc(tag).then(d => ({ tag, data: d }))));

    // 친구가 아직 받지 않은 응원이 있어도 쌓인다 (9/30)
    const eligible = friendDocs.filter(({ data }) => data);
    if (eligible.length === 0) {
        showGemToast(0, '친구를 찾을 수 없습니다.', true);
        if (allBtn) allBtn.disabled = false;
        return;
    }

    const newCheerMap = { ...cheerMap };
    const sentAt = Date.now();
    const writes = eligible.map(({ tag }) => {
        newCheerMap[tag] = todayStr;
        return _friendRef(tag).set({
            pendingCheers: firebase.firestore.FieldValue.arrayUnion(
                { from: myNickname, fromTag: myTag, gems: CHEER_GEM_AMOUNT, sentAt }
            )
        }, { merge: true });
    });
    writes.push(_friendRef(myTag).set({ lastCheerSent: newCheerMap }, { merge: true }));
    await Promise.all(writes);

    const totalGems = eligible.length * CHEER_GEM_AMOUNT;
    myGems += totalGems;
    updateGemDisplay();
    saveGameData();
    syncToFirestore();

    showGemToast(totalGems, `${eligible.length}명에게 응원을 보냈습니다!`);
    _renderFriendScreen();
}

function _saveMemo(tag) {
    const input = document.getElementById('friend-memo-input');
    if (!input) return;
    setFriendMemo(tag, input.value);
    showGemToast(0, '메모가 저장되었습니다.', true);
}

async function _removeFriend(tag) {
    if (!confirm('친구를 끊으시겠습니까?')) return;
    await removeFriend(tag);
    deleteFriendMemo(tag);
    closeFriendProfile();
    _renderFriendScreen();
    showGemToast(0, '친구 관계가 해제되었습니다.', true);
}

async function _blockUser(tag) {
    if (!confirm('이 사용자를 차단하시겠습니까?\n차단하면 친구 관계도 해제됩니다.')) return;
    await blockUser(tag);
    deleteFriendMemo(tag);
    closeFriendProfile();
    _renderFriendScreen();
    showGemToast(0, '차단되었습니다.', true);
}
